CREATE OR REPLACE FUNCTION "public"."_acotar_pagina"("p_pedido" integer, "p_defecto" integer, "p_maximo" integer) RETURNS integer
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  select least(greatest(coalesce(p_pedido, p_defecto), 1), p_maximo);
$$;


ALTER FUNCTION "public"."_acotar_pagina"("p_pedido" integer, "p_defecto" integer, "p_maximo" integer) OWNER TO "postgres";


