CREATE OR REPLACE FUNCTION "public"."_atributos_completar"("p_actuales" "jsonb", "p_nuevos" "jsonb", "p_activas" "text"[], "p_msg_objeto" "text", "p_msg_clave" "text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select public._atributos_fusionar('{}'::jsonb, p_nuevos, p_activas, p_msg_objeto, p_msg_clave) || p_actuales;
$$;


ALTER FUNCTION "public"."_atributos_completar"("p_actuales" "jsonb", "p_nuevos" "jsonb", "p_activas" "text"[], "p_msg_objeto" "text", "p_msg_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_atributos_fusionar"("p_actuales" "jsonb", "p_cambios" "jsonb", "p_activas" "text"[], "p_msg_objeto" "text", "p_msg_clave" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare k text; x jsonb; v jsonb := p_actuales;
begin
  if jsonb_typeof(p_cambios) <> 'object' then
    raise exception '%', p_msg_objeto using errcode = '22023';
  end if;
  for k, x in select * from jsonb_each(p_cambios) loop
    if not (k = any (p_activas)) then
      raise exception '%', format(p_msg_clave, k) using errcode = '22023', hint = 'atributos.' || k;
    end if;
    if x in ('null'::jsonb, '""'::jsonb, '[]'::jsonb) then
      v := v - k;
    else
      v := v || jsonb_build_object(k, x);
    end if;
  end loop;
  return v;
end;
$$;


ALTER FUNCTION "public"."_atributos_fusionar"("p_actuales" "jsonb", "p_cambios" "jsonb", "p_activas" "text"[], "p_msg_objeto" "text", "p_msg_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_atributos_validar"("p_atributos" "jsonb", "p_campos" "jsonb", "p_msg_objeto" "text") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare c record; v jsonb;
begin
  if jsonb_typeof(p_atributos) <> 'object' then
    raise exception '%', p_msg_objeto using errcode = '22023';
  end if;
  for c in select x.clave, x.etiqueta, x.tipo, x.requerido
           from jsonb_to_recordset(coalesce(p_campos, '[]'::jsonb)) as x (clave text, etiqueta text, tipo text, requerido boolean) loop
    v := p_atributos -> c.clave;
    if c.requerido and (v is null or v = 'null'::jsonb or (jsonb_typeof(v) = 'string' and v #>> '{}' = '') or v = '[]'::jsonb) then
      raise exception 'Falta «%».', c.etiqueta using errcode = '23502', hint = 'atributos.' || c.clave;
    end if;
    if v is not null and v <> 'null'::jsonb then
      case c.tipo
        when 'numero', 'moneda' then
          if jsonb_typeof(v) <> 'number' then raise exception '«%» tiene que ser un número.', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave; end if;
        when 'booleano' then
          if jsonb_typeof(v) <> 'boolean' then raise exception '«%» tiene que ser sí o no.', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave; end if;
        when 'multi_opcion' then
          if jsonb_typeof(v) <> 'array' then raise exception '«%» tiene que ser una lista.', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave; end if;
        else
          if jsonb_typeof(v) not in ('string', 'number') then raise exception '«%» tiene que ser un texto.', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave; end if;
      end case;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."_atributos_validar"("p_atributos" "jsonb", "p_campos" "jsonb", "p_msg_objeto" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_baja_lote"("p_usuario" "uuid", "p_lote" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not exists (select 1 from public.equipo_bajas b where b.usuario_id = p_usuario and b.terminada_en is null) then
    return true;
  end if;
  perform public._baja_lote_desde(p_usuario, p_lote, null);
  return public._baja_terminar(p_usuario);
end;
$$;


ALTER FUNCTION "public"."_baja_lote"("p_usuario" "uuid", "p_lote" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_baja_lote_desde"("p_usuario" "uuid", "p_lote" integer, "p_desde" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_baja public.equipo_bajas;
  v_ids uuid[];
  v_leads uuid[];
  v_hechos uuid[];
  v_limbo int := 0;
  v_canceladas int;
  v_n int := greatest(coalesce(p_lote, 0), 1);
begin
  select * into v_baja from public.equipo_bajas b where b.usuario_id = p_usuario and b.terminada_en is null;
  if not found then
    return null;
  end if;
  -- Los ids que siguen, por leads_asesores_usuario_vigente_idx (usuario_id, lead_id) where revocado_en is null: ordenados y
  -- con `limit`, sin unir con `leads` (unidas, con una cartera que es un tercio de la tabla, el planificador prefería
  -- recorrer las dos y ordenar: crece con la tabla, no con la persona).
  if p_desde is null then
    v_ids := array(select la.lead_id from public.leads_asesores la
                    where la.usuario_id = p_usuario and la.revocado_en is null
                    order by la.lead_id limit v_n);
  else
    v_ids := array(select la.lead_id from public.leads_asesores la
                    where la.usuario_id = p_usuario and la.revocado_en is null and la.lead_id > p_desde
                    order by la.lead_id limit v_n);
  end if;
  -- Después los leads, por su clave, en orden de id y sin esperar: uno que otra RPC tiene bloqueado lo toma la corrida
  -- siguiente (el cursor avanza igual: lo saltado no vuelve en esta corrida).
  v_leads := array(select l.id from public.leads l where l.id = any (v_ids) order by l.id for update skip locked);
  if cardinality(v_leads) > 0 then
    -- La sentencia dispara el recálculo de la cartera de esos leads (ya bloqueados: el trigger no espera).
    -- Se cuentan sólo los leads cuya fila revocó esta sentencia: uno que otra corrida de esta misma baja ya aplicó (y contó)
    -- entre leer los ids y bloquear no se cuenta dos veces.
    with hechas as (
      update public.leads_asesores la set revocado_en = now(), revocado_por = v_baja.por
       where la.lead_id = any (v_leads) and la.usuario_id = p_usuario and la.revocado_en is null
      returning la.lead_id
    )
    select coalesce(array_agg(h.lead_id), '{}') into v_hechos from hechas h;
    select count(*) into v_limbo from public.leads l
     where l.id = any (v_hechos) and l.eliminado_en is null and l.cartera = '{}';
  end if;
  -- Sus oportunidades abiertas (sólo las ve su dueña: nadie ve el estado intermedio). oportunidades_abiertas_usuario_idx.
  with lote as (
    select o.id from public.oportunidades o
     where o.usuario_id = p_usuario and o.estado = 'abierta'
     order by o.id limit v_n
       for update skip locked
  )
  update public.oportunidades o set estado = 'cancelada' from lote where o.id = lote.id;
  get diagnostics v_canceladas = row_count;

  if v_limbo > 0 or v_canceladas > 0 then
    update public.equipo_bajas
       set leads_al_limbo = leads_al_limbo + v_limbo, oportunidades_canceladas = oportunidades_canceladas + v_canceladas
     where usuario_id = p_usuario;
  end if;
  return v_ids[cardinality(v_ids)];
end;
$$;


ALTER FUNCTION "public"."_baja_lote_desde"("p_usuario" "uuid", "p_lote" integer, "p_desde" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_baja_terminar"("p_usuario" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_baja public.equipo_bajas;
begin
  if exists (select 1 from public.leads_asesores la where la.usuario_id = p_usuario and la.revocado_en is null)
     or exists (select 1 from public.oportunidades o where o.usuario_id = p_usuario and o.estado = 'abierta') then
    return false;
  end if;
  update public.equipo_bajas set terminada_en = now() where usuario_id = p_usuario and terminada_en is null
  returning * into v_baja;
  if found then
    perform public.registrar_actividad('usuario.baja_terminada', 'perfiles', p_usuario::text, null,
      jsonb_build_object('leads_al_limbo', v_baja.leads_al_limbo, 'oportunidades_canceladas', v_baja.oportunidades_canceladas));
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."_baja_terminar"("p_usuario" "uuid") OWNER TO "postgres";


