CREATE OR REPLACE FUNCTION "public"."_color_contraste"("p_a" "text", "p_b" "text") RETURNS double precision
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select (greatest(la, lb) + 0.05) / (least(la, lb) + 0.05)
    from (select public._color_luminancia(p_a) as la, public._color_luminancia(p_b) as lb) x;
$$;


ALTER FUNCTION "public"."_color_contraste"("p_a" "text", "p_b" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_color_luminancia"("p_hex" "text") RETURNS double precision
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select 0.2126 * c.r + 0.7152 * c.g + 0.0722 * c.b
    from (select
            case when v.r <= 0.04045 then v.r / 12.92 else power((v.r + 0.055) / 1.055, 2.4) end as r,
            case when v.g <= 0.04045 then v.g / 12.92 else power((v.g + 0.055) / 1.055, 2.4) end as g,
            case when v.b <= 0.04045 then v.b / 12.92 else power((v.b + 0.055) / 1.055, 2.4) end as b
            from (select ('x' || substr(lower(p_hex), 2, 2))::bit(8)::int / 255.0::float8 as r,
                         ('x' || substr(lower(p_hex), 4, 2))::bit(8)::int / 255.0::float8 as g,
                         ('x' || substr(lower(p_hex), 6, 2))::bit(8)::int / 255.0::float8 as b) v) c;
$$;


ALTER FUNCTION "public"."_color_luminancia"("p_hex" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_compilar_visibilidad"("p_def" "jsonb", "p_diseno" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with items as (
    select it.value ->> 'nodo' as nodo, it.value ? 'secundario' as con_pct,
           coalesce(it.value ->> 'nivel_ver', s.value ->> 'nivel_ver', 'todos') as ver,
           coalesce(it.value ->> 'nivel_editar', s.value ->> 'nivel_editar', 'todos') as editar
      from jsonb_array_elements(p_diseno -> 'secciones') s(value)
      cross join lateral jsonb_array_elements(s.value -> 'items') it(value)
     where it.value ->> 'tipo' in ('celda', 'subtotal', 'variante', 'interruptor')
  ), nodos as (
    select n.value ->> 'id' as id, n.value ->> 'pct' as pct, n.value ->> 'salida' as salida
      from jsonb_array_elements(p_def -> 'nodos') n(value)
  ), dibujado as (
    select nodo, ver, editar from items
    union all
    select n.pct, i.ver, i.editar from items i join nodos n on n.id = i.nodo where i.con_pct and n.pct is not null
  ), final as (
    select d.nodo, case when n.salida in ('total', 'aparte') then 'todos' else d.ver end as ver, d.editar
      from dibujado d join nodos n on n.id = d.nodo
    union all
    select n.id, 'todos', null from nodos n
     where n.salida in ('total', 'aparte') and not exists (select 1 from dibujado d where d.nodo = n.id)
  )
  select coalesce(jsonb_object_agg(f.nodo, jsonb_build_object('ver', f.ver, 'editar', f.editar)), '{}'::jsonb) from final f;
$$;


ALTER FUNCTION "public"."_compilar_visibilidad"("p_def" "jsonb", "p_diseno" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_conflicto_de_edicion"("p_tabla" "text", "p_registro" "uuid", "p_cuando" timestamp with time zone, "p_sujeto" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid; v_nombre text; v_hay boolean := false;
begin
  select a.actor_id, true into v_actor, v_hay from public.actividad a
  where a.tabla = p_tabla and a.registro_id = p_registro::text order by a.id desc limit 1;
  if v_actor is not null and v_actor = (select auth.uid()) then
    raise exception 'Cambiaste % % desde otra ventana. Recarga para seguir desde ahí.', p_sujeto, public._hace(p_cuando) using errcode = 'PT409';
  end if;
  if v_actor is not null then
    select nullif(btrim(p.nombre), '') into v_nombre from public.perfiles p where p.id = v_actor;
  end if;
  if v_nombre is null and (v_actor is not null or not coalesce(v_hay, false)) then
    v_nombre := 'Otra persona';
  end if;
  if v_nombre is null then
    raise exception '% cambió %.', upper(left(p_sujeto, 1)) || substr(p_sujeto, 2), public._hace(p_cuando) using errcode = 'PT409';
  end if;
  raise exception '% cambió % %.', v_nombre, p_sujeto, public._hace(p_cuando) using errcode = 'PT409';
end;
$$;


ALTER FUNCTION "public"."_conflicto_de_edicion"("p_tabla" "text", "p_registro" "uuid", "p_cuando" timestamp with time zone, "p_sujeto" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_contraste_aa"("p_razon" double precision) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$ select p_razon >= 4.5; $$;


ALTER FUNCTION "public"."_contraste_aa"("p_razon" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_cotizacion_abierta"("p_origen" "uuid", "p_formula" "uuid", "p_abierta_en" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_version int; v_estado text; v_siguiente timestamptz;
begin
  -- «Guardar con la N» no fija precios viejos para siempre: la hoja tiene que haberse abierto hace menos de un día y, si la versión ya no es la publicada, haber dejado de serlo hace menos de un día.
  if p_abierta_en < statement_timestamp() - interval '24 hours' then
    raise exception 'Abriste la hoja hace más de un día: ábrela de nuevo.' using errcode = '22023', detail = 'abierta_vencida', hint = 'abierta';
  end if;
  select f.version, f.estado::text into v_version, v_estado from public.formulas f where f.id = p_formula and f.origen_id = p_origen and f.estado in ('publicada', 'archivada');
  if not found then
    raise exception 'La versión de la hoja que abriste ya no está disponible: ábrela de nuevo.' using errcode = '22023', detail = 'abierta_no_disponible', hint = 'abierta';
  end if;
  if v_estado = 'archivada' then
    select min(f.publicado_en) into v_siguiente from public.formulas f where f.origen_id = p_origen and f.version > v_version and f.estado in ('publicada', 'archivada');
    if v_siguiente is null or v_siguiente < statement_timestamp() - interval '24 hours' then
      raise exception 'Esa versión de la hoja se reemplazó hace más de un día: ábrela de nuevo.' using errcode = '22023', detail = 'abierta_vencida', hint = 'abierta';
    end if;
  end if;
end $$;


ALTER FUNCTION "public"."_cotizacion_abierta"("p_origen" "uuid", "p_formula" "uuid", "p_abierta_en" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_abierta"("p_origen" "uuid", "p_formula" "uuid", "p_abierta_en" timestamp with time zone) IS 'Valida la versión de la hoja abierta para «Guardar con la N» (publicada o archivada de este origen; abierta hace menos de un día y, si ya no es la publicada, reemplazada hace menos de un día). STABLE y sin candado: el for share lo toma cotizacion_crear. De nadie; la llaman cotizacion_crear y cotizacion_evaluar. docs/COTIZADOR.md › «Cómo se guarda (4.10-3)» y «La hoja abierta (4.13-3a)».';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_abierta_firmar"("p_origen" "uuid", "p_formula" "uuid", "p_cuando" timestamp with time zone) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_clave text; v_us bigint;
begin
  if v_uid is null or p_origen is null or p_formula is null or p_cuando is null then
    raise exception 'No se puede firmar la hoja abierta sin persona, origen, versión y hora.' using errcode = '42501';
  end if;
  select s.decrypted_secret into v_clave from vault.decrypted_secrets s where s.name = 'cotizacion:abierta';
  if v_clave is null then
    raise exception 'Falta la clave que firma la hoja abierta: avisa a quien administra el sistema.' using errcode = 'XX000';
  end if;
  v_us := round(extract(epoch from p_cuando) * 1000000)::bigint;
  return p_formula::text || '.' || v_us::text || '.'
         || encode(extensions.hmac(convert_to(format('cotizacion_abierta|%s|%s|%s|%s', v_uid, p_origen, p_formula, v_us), 'UTF8'), decode(v_clave, 'hex'), 'sha256'), 'hex');
end $$;


ALTER FUNCTION "public"."_cotizacion_abierta_firmar"("p_origen" "uuid", "p_formula" "uuid", "p_cuando" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_abierta_firmar"("p_origen" "uuid", "p_formula" "uuid", "p_cuando" timestamp with time zone) IS 'Firma (HMAC con la clave de Vault cotizacion:abierta) la hoja abierta de quien llama: fórmula, origen y hora. De nadie; la llama cotizacion_hoja. docs/COTIZADOR.md › «La hoja abierta (4.13-3a)».';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_abierta_leer"("p_abierta" "text", "p_origen" "uuid") RETURNS TABLE("formula_id" "uuid", "abierta_en" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  c_forma constant text := '^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\.([0-9]{1,16})\.([0-9a-f]{64})$';
  v_uid uuid := (select auth.uid());
  v_partes text[]; v_clave text; v_firma text;
begin
  if p_abierta is null then
    raise exception 'Falta la hoja que abriste: ábrela de nuevo.' using errcode = '22023', hint = 'abierta';
  end if;
  v_partes := regexp_match(p_abierta, c_forma);
  select s.decrypted_secret into v_clave from vault.decrypted_secrets s where s.name = 'cotizacion:abierta';
  if v_partes is null or v_uid is null or p_origen is null or v_clave is null then
    raise exception 'La hoja que abriste ya no es válida: ábrela de nuevo.' using errcode = '22023', detail = 'abierta_invalida', hint = 'abierta';
  end if;
  v_firma := encode(extensions.hmac(convert_to(format('cotizacion_abierta|%s|%s|%s|%s', v_uid, p_origen, v_partes[1], v_partes[2]::bigint), 'UTF8'), decode(v_clave, 'hex'), 'sha256'), 'hex');
  if v_firma <> v_partes[3] then
    raise exception 'La hoja que abriste ya no es válida: ábrela de nuevo.' using errcode = '22023', detail = 'abierta_invalida', hint = 'abierta';
  end if;
  return query select v_partes[1]::uuid, 'epoch'::timestamptz + v_partes[2]::bigint * interval '1 microsecond';
end $_$;


ALTER FUNCTION "public"."_cotizacion_abierta_leer"("p_abierta" "text", "p_origen" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_abierta_leer"("p_abierta" "text", "p_origen" "uuid") IS 'Verifica la hoja abierta de quien llama en ese origen y devuelve la versión de la fórmula y la hora de la apertura; 22023 abierta_invalida si no es la que firmó la base. De nadie; la llaman cotizacion_crear y cotizacion_evaluar. docs/COTIZADOR.md › «La hoja abierta (4.13-3a)».';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_armar"("p_entradas" "jsonb", "p_cotizacion" "uuid", "p_origen" "uuid", "p_vehiculo" "uuid", "p_formula" "uuid" DEFAULT NULL::"uuid", "p_abierta_en" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_con_la_abierta" boolean DEFAULT false) RETURNS TABLE("definicion" "jsonb", "params" "jsonb", "entrada" "jsonb", "formula_id" "uuid", "origen_id" "uuid", "visibilidad" "jsonb", "tc_cambiado" boolean, "guardado" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_origen uuid;
  v_formula uuid;
  v_vehiculo uuid;
  v_tc_cot jsonb;
  v_valores jsonb; v_fuentes jsonb; v_clase public.clase_cotizacion;
  v_def jsonb;
  v_par jsonb;
  v_visib jsonb;
  v_cong jsonb;
  v_ids text[];
  v_tablas text[];
  v_tcs text[];
  v_campos text[];
  v_match text[];
  v_vivas text[];
  v_extra text;
  v_tc jsonb;
  v_tc_cambiado boolean := false;
  v_tab jsonb;
  v_veh jsonb := '{}'::jsonb;
  v_v_origen uuid;
  v_anio smallint; v_marca text; v_modelo text; v_km int; v_precio numeric; v_attr jsonb;
begin
  perform public.assert_activo();

  -- La llamada: uno de los dos, y el vehículo sólo con un origen (la cotización trae el suyo).
  if (p_cotizacion is null) = (p_origen is null) then
    perform public._motor_fallar('llamada_invalida', null, 'Evaluar pide una cotización o un origen, y no los dos ni ninguno.');
  end if;
  -- La versión de la hoja que se abrió y cuándo (D2) son de un alta: una cotización ya trae su versión y sus tipos de cambio.
  if p_cotizacion is not null and (p_formula is not null or p_abierta_en is not null or p_con_la_abierta) then
    perform public._motor_fallar('llamada_invalida', 'p_formula', 'Una cotización ya trae su versión de la hoja y sus tipos de cambio.');
  end if;
  -- Las entradas: un objeto y sólo lo que la persona puede tipear. Lo demás lo pone la base.
  if p_entradas is null or jsonb_typeof(p_entradas) <> 'object' then
    perform public._motor_fallar('entradas_invalidas', null, 'Las entradas son un objeto con inputs, banderas, overrides y variante.');
  end if;
  select min(k collate "C") into v_extra from jsonb_object_keys(p_entradas) k where k not in ('inputs', 'banderas', 'overrides', 'variante');
  if v_extra is not null then
    perform public._motor_fallar('entradas_invalidas', v_extra, 'Las entradas no llevan «' || v_extra || '»: la base lo pone.');
  end if;

  -- Quién puede, y de dónde sale la fórmula.
  if p_cotizacion is not null then
    -- Una cotización que no existe y una que no se ve dan el mismo error.
    if not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
      raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
    end if;
    select c.origen_id, c.formula_id, c.vehiculo_id, c.tipos_cambio, c.valores, c.fuentes, c.clase into v_origen, v_formula, v_vehiculo, v_tc_cot, v_valores, v_fuentes, v_clase
      from public.cotizaciones c where c.id = p_cotizacion;                                    -- cotizaciones_pkey
    -- Otro vehículo para ese cálculo (lo que daría cambiarlo, antes de guardar): una final no cambia de vehículo.
    if p_vehiculo is not null then
      if v_clase = 'final' and p_vehiculo is distinct from v_vehiculo then
        perform public._motor_fallar('llamada_invalida', 'p_vehiculo', 'Una cotización final no cambia de vehículo.');
      end if;
      v_vehiculo := p_vehiculo;
    end if;
    select f.definicion, f.params, f.visibilidad into v_def, v_par, v_visib from public.formulas f where f.id = v_formula;  -- formulas_pkey
  else
    perform public.assert_permiso('cotizaciones.crear', p_origen);
    v_origen := p_origen;
    v_vehiculo := p_vehiculo;
    if p_formula is not null then
      -- La versión que se abrió (D2, «Guardar con la N»): una publicada o archivada de este origen.
      select f.id, f.definicion, f.params, f.visibilidad into v_formula, v_def, v_par, v_visib
        from public.formulas f where f.id = p_formula and f.origen_id = p_origen and f.estado in ('publicada', 'archivada');   -- formulas_pkey
      if not found then
        perform public._motor_fallar('llamada_invalida', 'p_formula', 'La versión de la hoja no es de este origen.');
      end if;
    else
      select f.id, f.definicion, f.params, f.visibilidad into v_formula, v_def, v_par, v_visib
        from public.formulas f where f.origen_id = p_origen and f.estado = 'publicada';          -- formulas_publicada_unica
      if not found then
        perform public._motor_fallar('origen_sin_formula', null, 'Este origen no tiene una fórmula publicada.');
      end if;
    end if;
  end if;

  -- El vehículo: sólo si quien llama lo ve (esto corre con los derechos de la base y no puede devolver lo que él no vería).
  if v_vehiculo is not null then
    if not public.puede_vehiculo(v_vehiculo, 'vehiculos.ver') then
      raise exception 'No tienes acceso a este vehículo.' using errcode = '42501';
    end if;
    select v.origen_id, v.anio, v.marca, v.modelo, v.kilometraje, v.precio, v.atributos
      into v_v_origen, v_anio, v_marca, v_modelo, v_km, v_precio, v_attr
      from public.vehiculos v where v.id = v_vehiculo;                                         -- vehiculos_pkey
    if p_vehiculo is not null and v_v_origen <> v_origen then
      perform public._motor_fallar('vehiculo_de_otro_origen', 'p_vehiculo', 'El vehículo no es de este origen.');
    end if;
  end if;

  -- Lo que la fórmula nombra, en una sola pasada por sus nodos (`definicion` se desarma una vez: un jsonb que llega de una columna
  -- comprimida se descomprime entero en cada `->`). Los campos del vehículo son los de `campo_vehiculo` y los valores de un `match` que
  -- no son el id de un nodo.
  select array_agg(distinct n ->> 'id'),
         coalesce(array_agg(distinct n ->> 'tabla') filter (where n ->> 'tabla' is not null), '{}'),
         coalesce(array_agg(distinct n ->> 'clave') filter (where n ->> 'tipo' = 'tipo_cambio'), '{}'),
         coalesce(array_agg(distinct n ->> 'campo') filter (where n ->> 'tipo' = 'campo_vehiculo'), '{}'),
         coalesce(array_agg(distinct m.value) filter (where m.value is not null), '{}')
    into v_ids, v_tablas, v_tcs, v_campos, v_match
    from jsonb_array_elements(v_def -> 'nodos') n
    left join lateral jsonb_each_text(case when jsonb_typeof(n -> 'match') = 'object' then n -> 'match' end) m on true;
  v_campos := array(select distinct c from unnest(v_campos || array(select r from unnest(v_match) r where r <> all (coalesce(v_ids, '{}')))) c);

  -- Las tablas vivas: las que un nodo nombra y la fórmula no congeló.
  v_cong := v_par -> 'tablas';
  v_vivas := array(select t from unnest(v_tablas) t where jsonb_typeof(v_cong) is distinct from 'object' or not (v_cong ? t));
  select coalesce(jsonb_object_agg(x.clave, x.filas), '{}'::jsonb) into v_tab
    from (
      select c.clave,
             -- tablas_referencia_filas_tabla_orden_idx: sus filas activas, en su orden.
             (select coalesce(jsonb_agg(f.valores order by f.orden, f.id), '[]'::jsonb)
                from public.tablas_referencia_filas f where f.tabla_id = t.id and f.activa) as filas
        from unnest(v_vivas) c (clave)
        -- tablas_referencia_origen_id_clave_key: la del origen y, si no hay una activa, la compartida.
        cross join lateral (
          select coalesce(
                   (select r.id from public.tablas_referencia r where r.origen_id = v_origen and r.clave = c.clave and r.activa),
                   (select r.id from public.tablas_referencia r where r.origen_id is null and r.clave = c.clave and r.activa)
                 ) as id
        ) t
       where t.id is not null
    ) x;

  -- Los tipos de cambio: los congelados de la cotización o los vigentes de la empresa, sólo los que un nodo nombra.
  if p_cotizacion is not null then
    select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) into v_tc
      from jsonb_each(case when jsonb_typeof(v_tc_cot) = 'object' then v_tc_cot else '{}'::jsonb end) e
     where e.key = any (v_tcs) and case when jsonb_typeof(e.value) = 'number' then (e.value)::numeric > 0 else false end;
  else
    -- Los vigentes de hoy, los que valían cuando se abrió la hoja (`tipos_cambio_historial_tipo_idx`: el último cambio hasta `p_abierta_en`) y si alguno cambió desde entonces (D2), todo en
    -- una sola lectura: una foto. Uno que no tenía valor entonces (nació después) cuenta como cambiado. «Guardar con la N» congela los de entonces.
    select coalesce(jsonb_object_agg(x.clave, case when p_con_la_abierta and x.entonces is not null then x.entonces else x.valor end), '{}'::jsonb),
           coalesce(bool_or(p_abierta_en is not null and x.entonces is distinct from x.valor), false)
      into v_tc, v_tc_cambiado
      from (select t.clave, t.valor,
                   case when p_abierta_en is not null then
                     (select h.valor_nuevo from public.tipos_cambio_historial h where h.tipo_cambio_id = t.id and h.cambiado_en <= p_abierta_en order by h.cambiado_en desc, h.id desc limit 1)
                   end as entonces
              from public.tipos_cambio t where t.clave = any (v_tcs) and t.activo) x;          -- tipos_cambio_clave_key
  end if;

  -- Los campos del vehículo.
  if v_vehiculo is not null then
    select coalesce(jsonb_object_agg(n.campo, n.valor) filter (where n.valor is not null), '{}'::jsonb) into v_veh
      from (
        select s.campo,
               case when jsonb_typeof(s.x) = 'number' and abs((s.x #>> '{}')::numeric) < 1e308 then s.x
                    when jsonb_typeof(s.x) = 'string' and char_length(s.x #>> '{}') <= 200 then s.x end as valor
          from (
            select k.campo,
                   case k.campo
                     when 'anio' then to_jsonb(v_anio)
                     when 'marca' then to_jsonb(v_marca)
                     when 'modelo' then to_jsonb(v_modelo)
                     when 'kilometraje' then to_jsonb(v_km)
                     when 'precio' then to_jsonb(v_precio)
                     -- origenes_campos_origen_id_clave_key: sólo un campo activo del origen del vehículo.
                     else case when exists (select 1 from public.origenes_campos oc
                                             where oc.origen_id = v_v_origen and oc.clave = k.campo and oc.activo)
                               then v_attr -> k.campo end
                   end as x
              from unnest(v_campos) k (campo)
          ) s
      ) n;
  end if;

  return query select
    v_def,
    v_par,
    jsonb_build_object(
      'inputs', case when p_entradas ? 'inputs' then p_entradas -> 'inputs' else '{}'::jsonb end,
      'banderas', case when p_entradas ? 'banderas' then p_entradas -> 'banderas' else '{}'::jsonb end,
      'tipos_cambio', v_tc,
      'vehiculo', v_veh,
      'tablas', v_tab,
      'overrides', case when p_entradas ? 'overrides' then p_entradas -> 'overrides' else '{}'::jsonb end)
    || case when p_entradas ? 'variante' then jsonb_build_object('variante', p_entradas -> 'variante') else '{}'::jsonb end,
    v_formula,
    v_origen,
    coalesce(v_visib, '{}'::jsonb),
    v_tc_cambiado,
    -- Lo guardado, para completar lo que quien llama no ve o no edita (cotizacion_conservar): sólo con una cotización.
    case when p_cotizacion is not null then jsonb_build_object('valores', v_valores, 'fuentes', v_fuentes) end;
end $$;


ALTER FUNCTION "public"."_cotizacion_armar"("p_entradas" "jsonb", "p_cotizacion" "uuid", "p_origen" "uuid", "p_vehiculo" "uuid", "p_formula" "uuid", "p_abierta_en" timestamp with time zone, "p_con_la_abierta" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_armar"("p_entradas" "jsonb", "p_cotizacion" "uuid", "p_origen" "uuid", "p_vehiculo" "uuid", "p_formula" "uuid", "p_abierta_en" timestamp with time zone, "p_con_la_abierta" boolean) IS 'Arma la fórmula (con su id, su origen y su visibilidad; con p_formula, esa versión), las tablas vivas que ella nombra y no congeló, los tipos de cambio (con p_abierta_en, si alguno cambió desde entonces), los campos del vehículo (con una cotización, el suyo o el p_vehiculo que se pase) y, con una cotización, lo guardado, para evaluar_formula(). Comprueba los permisos como la policy. La llaman cotizacion_evaluar y cotizacion_crear; docs/COTIZADOR.md › «En la base (4.06-2)», «(4.10-1)» y «Cómo se guarda (4.10-3)».';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_conservar"("p_def" "jsonb", "p_entrada" "jsonb", "p_editables" "jsonb", "p_guardado" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_r jsonb := public._cotizacion_entradas_de(p_def, p_guardado -> 'valores', p_guardado -> 'fuentes');
  v_k text; v_opc text; v_out jsonb; v_nuevo jsonb; v_ids jsonb; v_parts jsonb;
  v_e_in jsonb := p_entrada -> 'inputs'; v_e_ba jsonb := p_entrada -> 'banderas'; v_e_ov jsonb := p_entrada -> 'overrides';
  v_r_in jsonb; v_r_ba jsonb; v_r_ov jsonb;
begin
  -- Cada subobjeto una sola vez: `p_entrada -> 'inputs' -> k` copia el subobjeto entero en cada fila (cuadrático en los nodos).
  v_r_in := v_r -> 'inputs'; v_r_ba := v_r -> 'banderas'; v_r_ov := v_r -> 'overrides';
  v_ids := coalesce((select jsonb_object_agg(n ->> 'id', true) from jsonb_array_elements(coalesce(p_def -> 'nodos', '[]'::jsonb)) n), '{}'::jsonb);
  select n ->> 'id' into v_opc from jsonb_array_elements(coalesce(p_def -> 'nodos', '[]'::jsonb)) n where n ->> 'tipo' = 'opcion' limit 1;
  -- Un valor para un nodo que se ve y no se edita, distinto de lo guardado: el primero por id, en bytes (como en `cotizacion_crear`). Igual a lo guardado no es un cambio. Una clave que no es un nodo no se juzga
  -- acá: un input o una bandera así ya lo rechazó `_cotizacion_tipeado()` y un override así vuelve del motor como `nodo_inexistente`.
  select min(t.k collate "C") into v_k
    from (select k from jsonb_object_keys(v_e_in) k where v_ids ? k and not p_editables ? k and (v_r_in -> k) is distinct from (v_e_in -> k)
          union all select k from jsonb_object_keys(v_e_ba) k where v_ids ? k and not p_editables ? k and (v_r_ba -> k) is distinct from (v_e_ba -> k)
          union all select k from jsonb_object_keys(v_e_ov) k where v_ids ? k and not p_editables ? k and (v_r_ov -> k) is distinct from (v_e_ov -> k)
          union all select v_opc where v_opc is not null and p_entrada ? 'variante' and not p_editables ? v_opc and (v_r -> 'variante') is distinct from (p_entrada -> 'variante')) t;
  if v_k is not null then
    raise exception 'No puedes cambiar «%» en esta hoja.', v_k using errcode = '42501', detail = 'nodo_no_editable', hint = v_k;
  end if;
  -- Lo que no edita, de lo guardado; lo que edita, lo que mandó (y lo que no mandó, sin tipear). Las tres partes se arman chicas y se pegan UNA vez a la entrada: reescribirla tres veces
  -- (con `jsonb_set`) copiaba cada vez sus tablas (4.000 filas en la sintética) y costaba más que todo lo demás.
  v_parts := jsonb_build_object(
    'inputs', coalesce((select jsonb_object_agg(e.key, e.value) from jsonb_each(v_r_in) e where not p_editables ? e.key), '{}'::jsonb) || v_e_in,
    'banderas', coalesce((select jsonb_object_agg(e.key, e.value) from jsonb_each(v_r_ba) e where not p_editables ? e.key), '{}'::jsonb) || v_e_ba,
    'overrides', coalesce((select jsonb_object_agg(e.key, e.value) from jsonb_each(v_r_ov) e where not p_editables ? e.key), '{}'::jsonb) || v_e_ov);
  -- La variante no tiene «sin tipear»: sin mandarla, la guardada.
  if v_opc is not null then
    v_nuevo := case when p_editables ? v_opc and p_entrada ? 'variante' then p_entrada -> 'variante' else v_r -> 'variante' end;
    if v_nuevo is not null then v_parts := v_parts || jsonb_build_object('variante', v_nuevo); end if;
  end if;
  v_out := p_entrada || v_parts;
  return v_out;
end $$;


ALTER FUNCTION "public"."_cotizacion_conservar"("p_def" "jsonb", "p_entrada" "jsonb", "p_editables" "jsonb", "p_guardado" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_conservar"("p_def" "jsonb", "p_entrada" "jsonb", "p_editables" "jsonb", "p_guardado" "jsonb") IS 'Completa la entrada de quien llama con lo guardado de lo que no edita (oculto o no editable) y rechaza (42501 nodo_no_editable) un valor distinto para un nodo que se ve y no se edita. De nadie. docs/COTIZADOR.md › «Cómo se guarda (4.10-3)».';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_contexto"("p_visibles" "text"[], "p_def" "jsonb", "p_visibilidad" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_nodos jsonb := coalesce(p_def -> 'nodos', '[]'::jsonb);
  v_vis jsonb; v_ocultos jsonb; v_ok jsonb; v_ids jsonb; v_grupos_ocultos jsonb; v_grupos jsonb; v_tc jsonb;
begin
  v_vis := coalesce((select jsonb_object_agg(x, true) from unnest(coalesce(p_visibles, '{}'::text[])) x), '{}'::jsonb);
  v_ocultos := coalesce((select jsonb_object_agg(k, true) from jsonb_object_keys(coalesce(p_visibilidad, '{}'::jsonb)) k where not v_vis ? k), '{}'::jsonb);
  v_ids := coalesce((select jsonb_object_agg(n ->> 'id', true) from jsonb_array_elements(v_nodos) n), '{}'::jsonb);
  v_ok := v_vis || coalesce((select jsonb_object_agg(n ->> 'id', true) from jsonb_array_elements(v_nodos) n where n ->> 'salida' in ('total', 'aparte')), '{}'::jsonb);
  v_grupos_ocultos := coalesce((select jsonb_object_agg(n ->> 'grupo', true) from jsonb_array_elements(v_nodos) n where (n ->> 'grupo') is not null and not v_ok ? (n ->> 'id')), '{}'::jsonb);
  v_grupos := coalesce((select jsonb_object_agg(gr ->> 'id', true) from jsonb_array_elements(coalesce(p_def -> 'grupos', '[]'::jsonb)) gr where not v_grupos_ocultos ? (gr ->> 'id')), '{}'::jsonb);
  v_tc := coalesce((select jsonb_object_agg(n ->> 'clave', true) from jsonb_array_elements(v_nodos) n where n ->> 'tipo' = 'tipo_cambio' and (n ->> 'clave') is not null and v_ocultos ? (n ->> 'id')), '{}'::jsonb);
  return jsonb_build_object('ok', v_ok, 'ids', v_ids, 'grupos', v_grupos, 'tc_ocultas', v_tc, 'tc_oculto', v_tc <> '{}'::jsonb);
end $$;


ALTER FUNCTION "public"."_cotizacion_contexto"("p_visibles" "text"[], "p_def" "jsonb", "p_visibilidad" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_contexto"("p_visibles" "text"[], "p_def" "jsonb", "p_visibilidad" "jsonb") IS 'Lo que el recorte necesita, armado una vez por llamada (conjuntos jsonb): los nodos que viajan, todos los nodos, los grupos que se ven enteros y los tipos de cambio que un nivel esconde. De nadie. docs/COTIZADOR.md › «En la base (4.10-1)».';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_diff_recortado"("p_diff" "jsonb", "p_ctx" "jsonb", "p_legibles" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_out jsonb := '{}'::jsonb; e record; v_de jsonb; v_a jsonb;
begin
  if jsonb_typeof(p_diff) is distinct from 'object' then return '{}'::jsonb; end if;
  for e in select d.key, d.value from jsonb_each(p_diff) d loop
    if e.key = any (p_legibles) then
      v_out := v_out || jsonb_build_object(e.key, e.value);
    elsif e.key in ('valores', 'fuentes', 'totales', 'tipos_cambio') and jsonb_typeof(e.value) = 'object' then
      v_de := public._cotizacion_recorte(jsonb_build_object(e.key, e.value -> 'de'), p_ctx) -> e.key;
      v_a := public._cotizacion_recorte(jsonb_build_object(e.key, e.value -> 'a'), p_ctx) -> e.key;
      if v_de is distinct from v_a then
        v_out := v_out || jsonb_build_object(e.key, jsonb_build_object('de', v_de, 'a', v_a));
      end if;
    end if;
  end loop;
  return v_out;
end $$;


ALTER FUNCTION "public"."_cotizacion_diff_recortado"("p_diff" "jsonb", "p_ctx" "jsonb", "p_legibles" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_diff_recortado"("p_diff" "jsonb", "p_ctx" "jsonb", "p_legibles" "text"[]) IS 'El diff de una revisión sin lo que quien lee no ve (las columnas legibles tal cual; valores, fuentes, totales y tipos_cambio por _cotizacion_recorte; si sólo cambió lo oculto, la columna no figura). De nadie.';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_entradas_de"("p_def" "jsonb", "p_valores" "jsonb", "p_fuentes" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_nodos jsonb := coalesce(p_def -> 'nodos', '[]'::jsonb);
  v_valores jsonb := case when jsonb_typeof(p_valores) = 'object' then p_valores else '{}'::jsonb end;
  v_fuentes jsonb := case when jsonb_typeof(p_fuentes) = 'object' then p_fuentes else '{}'::jsonb end;
  v_pisados jsonb; v_in jsonb; v_ba jsonb; v_ov jsonb; v_var jsonb;
begin
  select coalesce(jsonb_object_agg(m ->> 'pct', true), '{}'::jsonb) into v_pisados
    from jsonb_array_elements(v_nodos) m
   where m ->> 'tipo' = 'calculo' and m ->> 'op' = 'porcentaje_de' and (m -> 'sobrescribible') = 'true'::jsonb and (m ->> 'pct') is not null and v_fuentes ->> (m ->> 'id') = 'override';
  select coalesce(jsonb_object_agg(n ->> 'id', v_valores -> (n ->> 'id')), '{}'::jsonb) into v_in
    from jsonb_array_elements(v_nodos) n
   where n ->> 'tipo' = 'input' and not v_pisados ? (n ->> 'id') and v_fuentes ->> (n ->> 'id') in ('input', 'override') and jsonb_typeof(v_valores -> (n ->> 'id')) = 'number';
  select coalesce(jsonb_object_agg(n ->> 'id', case when jsonb_typeof(v_valores -> (n ->> 'id')) = 'number' then v_valores -> (n ->> 'id') else '0'::jsonb end), '{}'::jsonb) into v_ov
    from jsonb_array_elements(v_nodos) n
   where n ->> 'tipo' in ('constante', 'tipo_cambio', 'tabla', 'tramo', 'calculo') and not v_pisados ? (n ->> 'id') and v_fuentes ->> (n ->> 'id') = 'override'
     and (jsonb_typeof(v_valores -> (n ->> 'id')) = 'number' or n ->> 'tipo' = 'tipo_cambio');
  select coalesce(jsonb_object_agg(n ->> 'id', (v_valores -> (n ->> 'id')) = '1'::jsonb), '{}'::jsonb) into v_ba
    from jsonb_array_elements(v_nodos) n where n ->> 'tipo' = 'bandera' and jsonb_typeof(v_valores -> (n ->> 'id')) = 'number';
  select v_valores -> (n ->> 'id') into v_var from jsonb_array_elements(v_nodos) n where n ->> 'tipo' = 'opcion' limit 1;
  return jsonb_build_object('inputs', v_in, 'banderas', v_ba, 'overrides', v_ov) || case when jsonb_typeof(v_var) = 'string' then jsonb_build_object('variante', v_var) else '{}'::jsonb end;
end $$;


ALTER FUNCTION "public"."_cotizacion_entradas_de"("p_def" "jsonb", "p_valores" "jsonb", "p_fuentes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_entradas_de"("p_def" "jsonb", "p_valores" "jsonb", "p_fuentes" "jsonb") IS 'Lo guardado de una cotización (valores y fuentes) como lo tipeó la persona: inputs, banderas, overrides y variante. Lo derivado (sugerido, default, el pct pisado, lo apagado) no está. Puro; de nadie. docs/COTIZADOR.md › «Cómo se guarda (4.10-3)».';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_guardable"("p_res" "jsonb", "p_mandados" "jsonb") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_d jsonb; v_moneda text; v_total jsonb;
begin
  -- Lo que el motor descarta de un nodo que la persona mandó no se guarda en silencio: lo guardado es lo que se mandó.
  select e into v_d from jsonb_array_elements(coalesce(p_res -> 'overrides_descartados', '[]'::jsonb)) e where p_mandados ? (e ->> 'id') limit 1;
  if v_d is not null then
    raise exception 'No puedes sobrescribir «%»: %.', v_d ->> 'id',
      case v_d ->> 'motivo' when 'no_sobrescribible' then 'ese valor no se sobrescribe'
                            when 'fuera_de_variante' then 'no vale en esta variante'
                            when 'condicion_apagada' then 'su condición está apagada'
                            else v_d ->> 'motivo' end
      using errcode = '22023', detail = v_d ->> 'motivo', hint = v_d ->> 'id';
  end if;
  -- El total en la moneda base de la empresa.
  select e.moneda_base::text into v_moneda from public.ajustes_empresa e where e.id = 1;
  v_total := case v_moneda when 'USD' then p_res #> '{totales,usd}' when 'BOB' then p_res #> '{totales,bs}' end;
  if v_total is null and v_moneda not in ('USD', 'BOB') then
    raise exception 'La moneda base de la empresa es %: el cotizador sólo calcula en USD o en BOB.', v_moneda using errcode = '22023', hint = 'total';
  end if;
  if v_total is null or jsonb_typeof(v_total) <> 'number' then
    perform public._motor_fallar('total_sin_valor', 'total', 'No se pudo calcular el total: faltan datos de la hoja.');
  end if;
  if abs((v_total #>> '{}')::numeric) >= 1e15 then
    perform public._motor_fallar('fuera_de_rango', 'total', 'El total no cabe: revisa los montos de la hoja.');
  end if;
  return round((v_total #>> '{}')::numeric, 2);
end $$;


ALTER FUNCTION "public"."_cotizacion_guardable"("p_res" "jsonb", "p_mandados" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_guardable"("p_res" "jsonb", "p_mandados" "jsonb") IS 'Lo que se puede guardar del resultado del motor: rechaza un override mandado que el motor descartó, un total sin valor o que no cabe, y devuelve total_base en la moneda base de la empresa. De nadie; la llaman cotizacion_crear y cotizacion_guardar.';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_hoja"("p_formula" "uuid", "p_origen" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  fo public.formulas;
  v_cfg boolean; v_tc boolean; v_arr text[]; v_editables jsonb; v_ctx jsonb; v_ok jsonb;
  v_nodos jsonb; v_grupos jsonb; v_niveles jsonb; v_visib jsonb; v_lee jsonb; v_vivas jsonb; v_opcion text; v_opcion_ok boolean;
  v_secciones jsonb; v_claves text[]; v_tarjeta jsonb; v_tonos jsonb;
begin
  select * into fo from public.formulas x where x.id = p_formula;
  v_cfg := public.tiene_permiso('cotizaciones.configurar', p_origen);
  v_tc := public.tiene_permiso('empresa.tipos_cambio.gestionar');
  select coalesce(array_agg(n.nodo), '{}'), coalesce(jsonb_object_agg(n.nodo, true) filter (where n.editar), '{}'::jsonb) into v_arr, v_editables from public._nodos_visibles(p_formula) n;
  v_ctx := public._cotizacion_contexto(v_arr, fo.definicion, fo.visibilidad);
  v_ok := v_ctx -> 'ok';
  -- Copias en memoria de lo que se busca por nodo (un jsonb que viene de la tabla se vuelve a leer entero en cada operador).
  v_nodos := coalesce((select jsonb_object_agg(n ->> 'id', n) from jsonb_array_elements(coalesce(fo.definicion -> 'nodos', '[]'::jsonb)) n), '{}'::jsonb);
  v_grupos := coalesce((select jsonb_object_agg(g ->> 'id', g ->> 'tono') from jsonb_array_elements(coalesce(fo.definicion -> 'grupos', '[]'::jsonb)) g where (g ->> 'tono') is not null), '{}'::jsonb);
  v_niveles := coalesce((select jsonb_object_agg(l.clave, l.nombre) from public.cotizaciones_niveles l), '{}'::jsonb);
  v_visib := coalesce((select jsonb_object_agg(e.key, e.value) from jsonb_each(coalesce(fo.visibilidad, '{}'::jsonb)) e), '{}'::jsonb);
  -- Las tablas que lee algún nodo que quien llama ve (la regla de `cotizacion_tabla()`) y las que existen vivas para este origen.
  v_lee := coalesce((select jsonb_object_agg(t.nombre, true)
                       from (select distinct n ->> 'tabla' as nombre from jsonb_array_elements(coalesce(fo.definicion -> 'nodos', '[]'::jsonb)) n
                              where (n ->> 'tabla') is not null and n ->> 'id' = any (v_arr)) t), '{}'::jsonb);
  v_vivas := coalesce((select jsonb_object_agg(r.clave, true) from public.tablas_referencia r where r.activa and (r.origen_id = p_origen or r.origen_id is null)), '{}'::jsonb);
  select n ->> 'id' into v_opcion from jsonb_array_elements(coalesce(fo.definicion -> 'nodos', '[]'::jsonb)) n where n ->> 'tipo' = 'opcion' limit 1;
  v_opcion_ok := v_opcion is not null and v_ok ? v_opcion;

  with it as (
    select s.ord as so, i.ord as io, s.value as sec, i.value as item, i.value ->> 'tipo' as t, i.value ->> 'nodo' as nid
      from jsonb_array_elements(fo.diseno -> 'secciones') with ordinality s (value, ord)
     cross join lateral jsonb_array_elements(s.value -> 'items') with ordinality i (value, ord)
  ), vis as (
    -- Sólo viaja lo que su nodo (y, en un par, su porcentaje) permite.
    select it.*, v_nodos -> it.nid as n
      from it
     where v_ok ? it.nid and v_nodos ? it.nid
       and (it.t <> 'celda' or not (it.item ? 'secundario') or v_ok ? (v_nodos -> it.nid ->> 'pct'))
  ), obj as (
    select vis.so, vis.io, vis.sec,
           case when vis.t in ('celda', 'subtotal') then v_grupos ->> (vis.n ->> 'grupo') end as tono,
           case vis.t
             when 'celda' then jsonb_strip_nulls(jsonb_build_object(
                 'tipo', 'celda', 'nodo', vis.nid, 'etiqueta', vis.n ->> 'etiqueta', 'tipo_nodo', vis.n ->> 'tipo',
                 'formato', coalesce(vis.n ->> 'formato', 'usd'), 'ancho', vis.item ->> 'ancho',
                 'tono', v_grupos ->> (vis.n ->> 'grupo'),
                 'ayuda', case
                            when (vis.item -> 'ayuda') ? 'texto' then jsonb_build_object('texto', vis.item -> 'ayuda' ->> 'texto')
                            when (vis.item -> 'ayuda') ? 'tabla'
                                 and (v_cfg or v_lee ? (vis.item -> 'ayuda' ->> 'tabla'))
                                 and ((jsonb_typeof(fo.params -> 'tablas') = 'object' and (fo.params -> 'tablas') ? (vis.item -> 'ayuda' ->> 'tabla'))
                                      or v_vivas ? (vis.item -> 'ayuda' ->> 'tabla'))
                              then jsonb_build_object('tabla', vis.item -> 'ayuda' ->> 'tabla') end,
                 'solo_en', case when v_opcion_ok then vis.n -> 'solo_en' end,
                 'condicion', case when v_ok ? (vis.n ->> 'condicion') then vis.n ->> 'condicion' end,
                 'requerido_si', case when v_ok ? (vis.n ->> 'requerido_si') then vis.n ->> 'requerido_si' end,
                 'secundario', case when vis.item ? 'secundario' then
                     jsonb_build_object('nodo', vis.n ->> 'pct', 'como', vis.item ->> 'secundario', 'tipo_nodo', v_nodos -> (vis.n ->> 'pct') ->> 'tipo',
                                        'formato', coalesce(v_nodos -> (vis.n ->> 'pct') ->> 'formato', 'usd'))
                     || public._hoja_estado(v_nodos -> (vis.n ->> 'pct'), true, v_editables ? (vis.n ->> 'pct'),
                                            v_visib -> (vis.n ->> 'pct') ->> 'editar', v_niveles ->> (v_visib -> (vis.n ->> 'pct') ->> 'editar'), v_cfg, v_tc) end))
               || public._hoja_estado(vis.n, true, v_editables ? vis.nid, v_visib -> vis.nid ->> 'editar', v_niveles ->> (v_visib -> vis.nid ->> 'editar'), v_cfg, v_tc)
             when 'atajos' then jsonb_build_object('tipo', 'atajos', 'nodo', vis.nid,
                 'chips', public._hoja_chips(p_origen, fo.params, vis.n, vis.item ->> 'columna', (vis.item ->> 'filas')::int))
             when 'variante' then jsonb_strip_nulls(jsonb_build_object(
                 'tipo', 'variante', 'nodo', vis.nid, 'etiqueta', vis.n ->> 'etiqueta',
                 'opciones', coalesce((select jsonb_agg(jsonb_build_object('clave', o ->> 'clave', 'etiqueta', o ->> 'etiqueta', 'titulo', o ->> 'titulo'))
                                         from jsonb_array_elements(vis.n -> 'opciones') o), '[]'::jsonb),
                 'por_defecto', vis.n ->> 'por_defecto'))
               || public._hoja_estado(vis.n, false, v_editables ? vis.nid, v_visib -> vis.nid ->> 'editar', v_niveles ->> (v_visib -> vis.nid ->> 'editar'), v_cfg, v_tc)
             when 'interruptor' then jsonb_strip_nulls(jsonb_build_object(
                 'tipo', 'interruptor', 'nodo', vis.nid, 'etiqueta', vis.n ->> 'etiqueta', 'efecto', vis.item ->> 'efecto',
                 'solo_en', case when v_opcion_ok then vis.n -> 'solo_en' end))
               || public._hoja_estado(vis.n, false, v_editables ? vis.nid, v_visib -> vis.nid ->> 'editar', v_niveles ->> (v_visib -> vis.nid ->> 'editar'), v_cfg, v_tc)
             when 'subtotal' then jsonb_strip_nulls(jsonb_build_object(
                 'tipo', 'subtotal', 'nodo', vis.nid, 'etiqueta', vis.n ->> 'etiqueta', 'formato', coalesce(vis.n ->> 'formato', 'usd'),
                 'tono', v_grupos ->> (vis.n ->> 'grupo')))
           end as o
      from vis
  ), secs as (
    select o.so, jsonb_strip_nulls(jsonb_build_object('id', o.sec ->> 'id', 'titulo', o.sec ->> 'titulo', 'presentacion', o.sec ->> 'presentacion'))
                 || jsonb_build_object('items', jsonb_agg(o.o order by o.io)) as sec
      from obj o
     where o.o is not null
     group by o.so, o.sec ->> 'id', o.sec ->> 'titulo', o.sec ->> 'presentacion'
  )
  select coalesce((select jsonb_agg(s.sec order by s.so) from secs s), '[]'::jsonb),
         coalesce((select array_agg(distinct x.tono) from obj x where x.tono is not null), '{}'::text[])
    into v_secciones, v_claves;

  select coalesce(jsonb_agg(jsonb_build_object('clave', t.clave,
                                               'claro', jsonb_build_object('fondo', t.claro_fondo, 'borde', t.claro_borde, 'tinta', t.claro_tinta),
                                               'oscuro', jsonb_build_object('fondo', t.oscuro_fondo, 'borde', t.oscuro_borde, 'tinta', t.oscuro_tinta)) order by t.clave), '[]'::jsonb)
    into v_tonos from public.tonos t where t.clave = any (v_claves);

  v_tarjeta := jsonb_build_object('nodo', fo.diseno -> 'tarjeta_total' ->> 'nodo',
                                  'etiqueta', v_nodos -> (fo.diseno -> 'tarjeta_total' ->> 'nodo') ->> 'etiqueta',
                                  'formato', coalesce(v_nodos -> (fo.diseno -> 'tarjeta_total' ->> 'nodo') ->> 'formato', 'usd'),
                                  'secundarios', coalesce((select jsonb_agg(jsonb_build_object('nodo', x.s, 'etiqueta', v_nodos -> x.s ->> 'etiqueta',
                                                                                              'formato', coalesce(v_nodos -> x.s ->> 'formato', 'usd')) order by x.o)
                                                             from jsonb_array_elements_text(coalesce(fo.diseno -> 'tarjeta_total' -> 'secundarios', '[]'::jsonb)) with ordinality x (s, o)
                                                            where v_ok ? x.s), '[]'::jsonb));

  return jsonb_build_object(
    'formula', jsonb_build_object('id', fo.id, 'version', fo.version),
    'cabecera', jsonb_build_object(
      'modos', coalesce((select jsonb_agg(jsonb_build_object('clave', m ->> 'clave', 'nombre', m ->> 'nombre'))
                           from jsonb_array_elements(coalesce(fo.diseno -> 'cabecera' -> 'modos', '[]'::jsonb)) m), '[]'::jsonb),
      'ver_total_bs', coalesce((fo.diseno -> 'cabecera' ->> 'ver_total_bs')::boolean, false)),
    'secciones', v_secciones,
    'tarjeta_total', v_tarjeta,
    'tonos', v_tonos);
end $$;


ALTER FUNCTION "public"."_cotizacion_hoja"("p_formula" "uuid", "p_origen" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_hoja"("p_formula" "uuid", "p_origen" "uuid") IS 'El diseño de una versión de la fórmula recortado al nivel de quien llama: ítems cuyo nodo se ve, con su candado y su motivo, ayudas, atajos, modos (clave y nombre), tarjeta y tonos. De nadie; la llama cotizacion_hoja. docs/COTIZADOR.md › «La lectura que abre la hoja (4.13-1)».';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_modo"("p_formula" "uuid", "p_modo_tc" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_modo jsonb;
begin
  if p_modo_tc is null then return null; end if;
  select jsonb_build_object('buckets', coalesce((select jsonb_object_agg(b ->> 'bucket', b ->> 'nodo') from jsonb_array_elements(m -> 'buckets') b), '{}'::jsonb),
                            'total_en', m ->> 'total_en')
    into v_modo
    from public.formulas f, jsonb_array_elements(coalesce(f.diseno -> 'cabecera' -> 'modos', '[]'::jsonb)) m
   where f.id = p_formula and m ->> 'clave' = p_modo_tc;
  if v_modo is null then
    perform public._motor_fallar('modo_invalido', 'modo_tc', 'El modo no es uno de los que ofrece la hoja.');
  end if;
  return v_modo;
end $$;


ALTER FUNCTION "public"."_cotizacion_modo"("p_formula" "uuid", "p_modo_tc" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_modo"("p_formula" "uuid", "p_modo_tc" "text") IS 'La clave de un modo de diseno.cabecera.modos de esa versión de la fórmula, en la forma del motor (nulo si no se pide); modo_invalido si no es uno de los de la hoja. De nadie; la llaman cotizacion_crear y cotizacion_guardar.';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_recorte"("p_res" "jsonb", "p_ctx" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_ok jsonb := p_ctx -> 'ok'; v_ids jsonb := p_ctx -> 'ids'; v_grupos jsonb := p_ctx -> 'grupos'; v_tc jsonb := p_ctx -> 'tc_ocultas'; v_tc_oculto boolean := (p_ctx ->> 'tc_oculto')::boolean;
  v_out jsonb := '{}'::jsonb; v_t jsonb; v_hay boolean := false; k text;
begin
  foreach k in array array['valores', 'estados', 'fuentes'] loop
    if jsonb_typeof(p_res -> k) = 'object' then
      v_out := v_out || jsonb_build_object(k, coalesce((select jsonb_object_agg(e.key, e.value) from jsonb_each(p_res -> k) e where v_ok ? e.key), '{}'::jsonb));
    end if;
  end loop;

  if jsonb_typeof(p_res -> 'tipos_cambio') = 'object' then
    v_out := v_out || jsonb_build_object('tipos_cambio', coalesce((select jsonb_object_agg(e.key, e.value) from jsonb_each(p_res -> 'tipos_cambio') e where not v_tc ? e.key), '{}'::jsonb));
  end if;

  if jsonb_typeof(p_res -> 'totales') = 'object' then
    v_t := '{}'::jsonb;
    if jsonb_typeof(p_res -> 'totales' -> 'grupos') = 'object' then
      v_t := jsonb_build_object('grupos', coalesce((
        select jsonb_object_agg(e.key,
                 case when jsonb_typeof(e.value) = 'object'
                      then coalesce((select jsonb_object_agg(f.key, f.value) from jsonb_each(e.value) f where f.key in ('usd', 'se_dibuja') or (f.key = 'bs' and not v_tc_oculto)), '{}'::jsonb)
                      else e.value end)
          from jsonb_each(p_res -> 'totales' -> 'grupos') e where v_grupos ? e.key), '{}'::jsonb));
    end if;
    foreach k in array array['bs', 'usd', 'suma_usd'] loop
      if p_res -> 'totales' ? k then v_t := v_t || jsonb_build_object(k, p_res -> 'totales' -> k); end if;
    end loop;
    v_out := v_out || jsonb_build_object('totales', v_t);
  end if;

  if jsonb_typeof(p_res -> 'faltantes') = 'array' then
    select coalesce(jsonb_agg(e.value order by e.ord) filter (where e.viaja), '[]'::jsonb), coalesce(bool_or(not e.viaja), false) into v_t, v_hay
      from (select f.value, f.ord,
                   coalesce(v_ok ? (f.value ->> 'donde') or (f.value ->> 'donde') = 'total' or v_grupos ? (f.value ->> 'donde'), false)
                   and ((f.value ->> 'ref') is null or not v_ids ? (f.value ->> 'ref') or v_ok ? (f.value ->> 'ref')) as viaja
              from jsonb_array_elements(p_res -> 'faltantes') with ordinality f (value, ord)) e;
    v_out := v_out || jsonb_build_object('faltantes', v_t);
    if v_hay then v_out := v_out || jsonb_build_object('hay_faltantes_ocultos', true); end if;
  end if;

  if jsonb_typeof(p_res -> 'overrides_descartados') = 'array' then
    v_out := v_out || jsonb_build_object('overrides_descartados', coalesce((
      select jsonb_agg(e.value order by e.ord) from jsonb_array_elements(p_res -> 'overrides_descartados') with ordinality e (value, ord)
       where v_ok ? (e.value ->> 'id') or not v_ids ? (e.value ->> 'id')), '[]'::jsonb));
  end if;
  return v_out;
end $$;


ALTER FUNCTION "public"."_cotizacion_recorte"("p_res" "jsonb", "p_ctx" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_recorte"("p_res" "jsonb", "p_ctx" "jsonb") IS 'El recorte por nivel de lo que tiene una cotización o calcula evaluar_formula(), con el contexto de _cotizacion_contexto(): sólo lo visible, el total y lo aparte, y los subtotales de los grupos que se ven enteros. De nadie; la llaman cotizacion_leer, cotizacion_evaluar y cotizacion_revisiones. docs/COTIZADOR.md › «En la base (4.10-1)».';



CREATE TABLE IF NOT EXISTS "public"."cotizaciones" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "numero" bigint NOT NULL,
    "origen_id" "uuid" NOT NULL,
    "lead_id" "uuid",
    "vehiculo_id" "uuid",
    "creado_por" "uuid" NOT NULL,
    "clase" "public"."clase_cotizacion" DEFAULT 'preventa'::"public"."clase_cotizacion" NOT NULL,
    "estado" "public"."estado_cotizacion" DEFAULT 'activa'::"public"."estado_cotizacion" NOT NULL,
    "titulo" "text",
    "formula_id" "uuid" NOT NULL,
    "plantilla_id" "uuid",
    "valores" "jsonb" NOT NULL,
    "fuentes" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "tipos_cambio" "jsonb" NOT NULL,
    "totales" "jsonb" NOT NULL,
    "total_base" numeric(18,2) NOT NULL,
    "moneda_mostrar" character(3),
    "modo_tc" "text",
    "notas" "text",
    "version" integer DEFAULT 1 NOT NULL,
    "cotizacion_padre_id" "uuid",
    "reportes_count" integer DEFAULT 0 NOT NULL,
    "favoritos_count" integer DEFAULT 0 NOT NULL,
    "eliminado_en" timestamp with time zone,
    "eliminado_por" "uuid",
    "lote_papelera_id" "uuid",
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."cotizaciones" OWNER TO "postgres";


COMMENT ON TABLE "public"."cotizaciones" IS 'Una cotización = fórmula (de qué versión salieron los defaults) + valores (lo que realmente se usó) + tipos de cambio congelados. Recalcular usa SU versión, nunca la vigente. Un vehículo tiene a lo sumo una final activa; al entrar a logística la final queda como dato y las preventas de ese vehículo se envían a la papelera.';



COMMENT ON COLUMN "public"."cotizaciones"."valores" IS 'Oculta a authenticated: se lee por cotizacion_leer(), recortada por nivel (docs/COTIZADOR.md › «Niveles de acceso»).';



COMMENT ON COLUMN "public"."cotizaciones"."fuentes" IS 'Oculta a authenticated: se lee por cotizacion_leer(), recortada por nivel.';



COMMENT ON COLUMN "public"."cotizaciones"."tipos_cambio" IS 'Oculta a authenticated: se lee por cotizacion_leer(); un tipo de cambio de un nodo restringido no viaja.';



COMMENT ON COLUMN "public"."cotizaciones"."totales" IS 'Oculta a authenticated: se lee por cotizacion_leer(), recortada por nivel (los subtotales por grupo viajan sólo si se ve todo el grupo).';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_respuesta"("c" "public"."cotizaciones", "p_ctx" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb := p_ctx; v_def jsonb; v_vis jsonb; v_cols jsonb;
begin
  if v_ctx is null then
    select f.definicion, coalesce(f.visibilidad, '{}'::jsonb) into v_def, v_vis from public.formulas f where f.id = c.formula_id;
    v_ctx := public._cotizacion_contexto(coalesce(array(select n.nodo from public._nodos_visibles(c.formula_id) n), '{}'), v_def, v_vis);
  end if;
  -- Las columnas que se devuelven son las que `authenticated` lee: el grant de columnas es la única fuente (una columna nueva sin grant no viaja).
  select coalesce(jsonb_object_agg(a.attname, to_jsonb(c) -> a.attname), '{}'::jsonb) into v_cols
    from pg_attribute a
   where a.attrelid = 'public.cotizaciones'::regclass and a.attnum > 0 and not a.attisdropped and has_column_privilege('authenticated', a.attrelid, a.attnum, 'select');
  return jsonb_build_object('cotizacion', v_cols)
      || public._cotizacion_recorte(jsonb_build_object('valores', c.valores, 'fuentes', c.fuentes, 'totales', c.totales, 'tipos_cambio', c.tipos_cambio), v_ctx);
end $$;


ALTER FUNCTION "public"."_cotizacion_respuesta"("c" "public"."cotizaciones", "p_ctx" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_respuesta"("c" "public"."cotizaciones", "p_ctx" "jsonb") IS 'La fila de una cotización (las columnas que lee authenticated) con su snapshot recortado por nivel. De nadie; la llaman cotizacion_leer y cotizacion_crear. docs/COTIZADOR.md › «Quién escribe una cotización y cómo (4.10-2)».';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_tipeado"("p_def" "jsonb", "p_entrada" "jsonb", "p_modo" "jsonb", "p_ok" "jsonb", "p_tiene_variante" boolean DEFAULT false) RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_hint text;
  v_tipos jsonb;
  v_k text;
  v_opc2 text;
  v_opc text;
  v_opc_por_defecto text;
  v_ov_ocultos text[] := '{}'::text[];
begin
  -- La forma de lo que llega, antes que cualquier otra cosa y con el texto del motor (así lo que es de forma da el mismo error aunque el nodo no se vea). Sólo lo que tipea la
  -- persona: las tablas las arma la base y el motor las revisa después (revisar las 4.000 filas de cuatro tablas costaba 11 ms, el doble de lo que cuesta el recorte entero).
  v_hint := public._motor_forma_entrada(p_entrada || jsonb_build_object('tablas', '{}'::jsonb));
  if v_hint is not null then
    perform public._motor_fallar('entrada_invalida', nullif(v_hint, ''),
      case when v_hint = '' then 'La entrada no tiene la forma esperada.' else format('La entrada no tiene la forma esperada en «%s».', v_hint) end);
  end if;
  if p_modo is not null then
    v_hint := public._motor_forma_modo(p_modo);
    if v_hint is not null then
      perform public._motor_fallar('modo_invalido', nullif(v_hint, ''),
        case when v_hint = '' then 'El modo no tiene la forma esperada.' else format('El modo no tiene la forma esperada en «%s».', v_hint) end);
    end if;
  end if;

  if jsonb_typeof(p_def -> 'nodos') <> 'array' then
    return v_ov_ocultos;
  end if;
  -- Una fórmula que el motor rechaza antes de mirar lo tipeado (dos variantes, o sin total) lo dice primero, como en el motor.
  v_opc2 := (array(select n ->> 'id' from jsonb_array_elements(p_def -> 'nodos') n where n ->> 'tipo' = 'opcion'))[2];
  if v_opc2 is not null then perform public._motor_sin_validar(v_opc2, 'tiene dos variantes'); end if;
  if not exists (select 1 from jsonb_array_elements(p_def -> 'nodos') n where n ->> 'salida' = 'total') then
    perform public._motor_sin_validar(null, 'no tiene un nodo con salida «total»');
  end if;

  -- Lo tipeado sólo nombra lo que se ve: un input o una bandera que no se ve da el error del que no existe (el orden y el texto son los de `evaluar_formula()`).
  if p_entrada -> 'inputs' <> '{}'::jsonb or p_entrada -> 'banderas' <> '{}'::jsonb or p_entrada -> 'overrides' <> '{}'::jsonb then
    select coalesce(jsonb_object_agg(n ->> 'id', n ->> 'tipo'), '{}'::jsonb) into v_tipos from jsonb_array_elements(p_def -> 'nodos') n;
    for v_k in select jsonb_object_keys(p_entrada -> 'inputs') loop
      if v_tipos ->> v_k is distinct from 'input' or not p_ok ? v_k then
        perform public._motor_fallar('entrada_invalida', v_k, format('La entrada nombra «%s», que no es un input de la fórmula.', v_k));
      end if;
    end loop;
    for v_k in select jsonb_object_keys(p_entrada -> 'banderas') loop
      if v_tipos ->> v_k is distinct from 'bandera' or not p_ok ? v_k then
        perform public._motor_fallar('entrada_invalida', v_k, format('La entrada nombra «%s», que no es un bandera de la fórmula.', v_k));
      end if;
    end loop;
  end if;

  -- 4-18: la variante que no se ve es, para quien llama, una fórmula sin variante. El motor la nombraría (en el texto y en el `hint`).
  select n ->> 'id', n ->> 'por_defecto' into v_opc, v_opc_por_defecto
    from jsonb_array_elements(p_def -> 'nodos') n where n ->> 'tipo' = 'opcion' limit 1;
  if v_opc is not null and not p_ok ? v_opc then
    if p_entrada ? 'variante' then
      perform public._motor_fallar('entrada_invalida', null,
        format('La entrada elige la variante «%s», y la fórmula no tiene variante.', p_entrada ->> 'variante'));
    elsif v_opc_por_defecto is null and not p_tiene_variante then
      perform public._motor_fallar('variante_sin_eleccion', null,
        'La hoja necesita una variante que no puedes ver: avisa a quien configura el cotizador.');
    end if;
  end if;

  -- Un override de un nodo que existe y no se ve se quita antes del motor; vuelve como `nodo_inexistente` (lo hace quien llama, después de recortar).
  if p_entrada -> 'overrides' <> '{}'::jsonb then
    v_ov_ocultos := coalesce(array(select k from jsonb_object_keys(p_entrada -> 'overrides') k where v_tipos ? k and not p_ok ? k), '{}');
  end if;
  return v_ov_ocultos;
end $$;


ALTER FUNCTION "public"."_cotizacion_tipeado"("p_def" "jsonb", "p_entrada" "jsonb", "p_modo" "jsonb", "p_ok" "jsonb", "p_tiene_variante" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_tipeado"("p_def" "jsonb", "p_entrada" "jsonb", "p_modo" "jsonb", "p_ok" "jsonb", "p_tiene_variante" boolean) IS 'Revisa lo que tipeó la persona (forma, fórmula inválida, inputs, banderas y variante sólo de nodos que ve) con el texto y el orden del motor, y devuelve los overrides de nodos que no ve; con p_tiene_variante (una cotización guardada), una opción oculta sin por_defecto no es un error. De nadie; la llaman cotizacion_evaluar, cotizacion_crear y cotizacion_guardar.';



CREATE OR REPLACE FUNCTION "public"."_cotizacion_vehiculo"("p_vehiculo" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then
    raise exception 'No tienes acceso a este vehículo.' using errcode = '42501';
  end if;
  perform 1 from public.vehiculos v where v.id = p_vehiculo and v.eliminado_en is null for key share;
  if not found or not public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then
    raise exception 'No tienes acceso a este vehículo.' using errcode = '42501';
  end if;
end $$;


ALTER FUNCTION "public"."_cotizacion_vehiculo"("p_vehiculo" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cotizacion_vehiculo"("p_vehiculo" "uuid") IS 'Comprueba que quien llama ve el vehículo, lo toma for key share y vuelve a comprobar: 42501 para el que no existe, está en la papelera o no se ve. De nadie; la llaman cotizacion_crear y cotizacion_guardar.';



CREATE OR REPLACE FUNCTION "public"."_diseno_forma"("p_diseno" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  c_id constant text := '^[a-z][a-z0-9_]{0,40}$';
  c_forma constant text := 'El diseño no tiene la forma esperada en «%s».';
  v_cab jsonb;
  v_modos jsonb;
  v_m jsonb;
  v_bs jsonb;
  v_b jsonb;
  v_secs jsonb;
  v_s jsonb;
  v_its jsonb;
  v_t jsonb;
  v_donde text;
begin
  if jsonb_typeof(p_diseno) is distinct from 'object' then
    /*D01*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno'));
  end if;

  -- La cabecera: los modos y si se ofrece «Ver total Bs».
  v_cab := p_diseno -> 'cabecera';
  if jsonb_typeof(v_cab) is distinct from 'object' then
    /*D02*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera'));
  end if;
  if (v_cab - array['modos', 'ver_total_bs']) <> '{}'::jsonb then
    /*D03*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera'));
  end if;
  if jsonb_typeof(v_cab -> 'ver_total_bs') is distinct from 'boolean' then
    /*D04*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera.ver_total_bs'));
  end if;
  v_modos := v_cab -> 'modos';
  if jsonb_typeof(v_modos) is distinct from 'array' then
    /*D05*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera.modos'));
  end if;
  for i in 0 .. jsonb_array_length(v_modos) - 1 loop
    v_m := v_modos -> i;
    if jsonb_typeof(v_m) is distinct from 'object' then
      /*D06*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera.modos.' || i));
    end if;
    if (v_m - array['clave', 'nombre', 'buckets', 'total_en']) <> '{}'::jsonb then
      /*D07*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera.modos.' || i));
    end if;
    if (jsonb_typeof(v_m -> 'clave') = 'string' and (v_m ->> 'clave') ~ c_id) is not true then
      /*D08*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera.modos.' || i || '.clave'));
    end if;
    if (jsonb_typeof(v_m -> 'nombre') = 'string' and char_length(v_m ->> 'nombre') between 1 and 40) is not true then
      /*D09*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera.modos.' || i || '.nombre'));
    end if;
    if (jsonb_typeof(v_m -> 'total_en') = 'string' and (v_m ->> 'total_en') ~ c_id) is not true then
      /*D10*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera.modos.' || i || '.total_en'));
    end if;
    v_bs := v_m -> 'buckets';
    if jsonb_typeof(v_bs) is distinct from 'array' then
      /*D11*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera.modos.' || i || '.buckets'));
    end if;
    if jsonb_array_length(v_bs) < 1 then
      /*D32*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera.modos.' || i || '.buckets'));
    end if;
    for k in 0 .. jsonb_array_length(v_bs) - 1 loop
      v_b := v_bs -> k;
      if jsonb_typeof(v_b) is distinct from 'object' then
        /*D12*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera.modos.' || i || '.buckets.' || k));
      end if;
      if (v_b - array['bucket', 'nodo']) <> '{}'::jsonb then
        /*D13*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera.modos.' || i || '.buckets.' || k));
      end if;
      if (jsonb_typeof(v_b -> 'bucket') = 'string' and (v_b ->> 'bucket') ~ c_id) is not true then
        /*D14*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera.modos.' || i || '.buckets.' || k || '.bucket'));
      end if;
      if (jsonb_typeof(v_b -> 'nodo') = 'string' and (v_b ->> 'nodo') ~ c_id) is not true then
        /*D15*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.cabecera.modos.' || i || '.buckets.' || k || '.nodo'));
      end if;
    end loop;
  end loop;

  -- Las secciones, en orden. Cualquier problema bajo una sección se nombra con su id.
  v_secs := p_diseno -> 'secciones';
  if jsonb_typeof(v_secs) is distinct from 'array' then
    /*D16*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.secciones'));
  end if;
  if jsonb_array_length(v_secs) < 1 then
    /*D33*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.secciones'));
  end if;
  for i in 0 .. jsonb_array_length(v_secs) - 1 loop
    v_s := v_secs -> i;
    v_donde := case when jsonb_typeof(v_s -> 'id') = 'string' then v_s ->> 'id' end;
    if jsonb_typeof(v_s) is distinct from 'object' then
      /*D17*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'diseno.secciones.' || i));
    end if;
    if (v_s - array['id', 'titulo', 'presentacion', 'nivel_ver', 'nivel_editar', 'items']) <> '{}'::jsonb then
      /*D18*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'diseno.secciones.' || i));
    end if;
    if (jsonb_typeof(v_s -> 'id') = 'string' and (v_s ->> 'id') ~ c_id) is not true then
      /*D19*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'diseno.secciones.' || i || '.id'));
    end if;
    if v_s ? 'titulo' and (jsonb_typeof(v_s -> 'titulo') = 'string' and char_length(v_s ->> 'titulo') between 1 and 80) is not true then
      /*D20*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'diseno.secciones.' || i || '.titulo'));
    end if;
    if (jsonb_typeof(v_s -> 'presentacion') = 'string' and (v_s ->> 'presentacion') in ('principal', 'avanzado')) is not true then
      /*D21*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'diseno.secciones.' || i || '.presentacion'));
    end if;
    if v_s ? 'nivel_ver' and (jsonb_typeof(v_s -> 'nivel_ver') = 'string' and (v_s ->> 'nivel_ver') ~ c_id) is not true then
      /*D22*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'diseno.secciones.' || i || '.nivel_ver'));
    end if;
    if v_s ? 'nivel_editar' and (jsonb_typeof(v_s -> 'nivel_editar') = 'string' and (v_s ->> 'nivel_editar') ~ c_id) is not true then
      /*D23*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'diseno.secciones.' || i || '.nivel_editar'));
    end if;
    v_its := v_s -> 'items';
    if jsonb_typeof(v_its) is distinct from 'array' then
      /*D24*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'diseno.secciones.' || i || '.items'));
    end if;
    if jsonb_array_length(v_its) < 1 then
      /*D34*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'diseno.secciones.' || i || '.items'));
    end if;
    for k in 0 .. jsonb_array_length(v_its) - 1 loop
      if not public._diseno_forma_item(v_its -> k) then
        /*D25*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'diseno.secciones.' || i || '.items.' || k));
      end if;
    end loop;
  end loop;

  -- La tarjeta del total: el nodo y sus secundarios.
  v_t := p_diseno -> 'tarjeta_total';
  if jsonb_typeof(v_t) is distinct from 'object' then
    /*D26*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.tarjeta_total'));
  end if;
  if (v_t - array['nodo', 'secundarios']) <> '{}'::jsonb then
    /*D27*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.tarjeta_total'));
  end if;
  if (jsonb_typeof(v_t -> 'nodo') = 'string' and (v_t ->> 'nodo') ~ c_id) is not true then
    /*D28*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.tarjeta_total.nodo'));
  end if;
  v_its := v_t -> 'secundarios';
  if jsonb_typeof(v_its) is distinct from 'array' then
    /*D29*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.tarjeta_total.secundarios'));
  end if;
  for k in 0 .. jsonb_array_length(v_its) - 1 loop
    if (jsonb_typeof(v_its -> k) = 'string' and (v_its ->> k) ~ c_id) is not true then
      /*D30*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno.tarjeta_total.secundarios.' || k));
    end if;
  end loop;

  if (p_diseno - array['cabecera', 'secciones', 'tarjeta_total']) <> '{}'::jsonb then
    /*D31*/ perform public._formula_rechazar('forma', null, format(c_forma, 'diseno'));
  end if;
end;
$_$;


ALTER FUNCTION "public"."_diseno_forma"("p_diseno" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_diseno_forma_item"("p_i" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  c_id constant text := '^[a-z][a-z0-9_]{0,40}$';
  v_tipo text;
  v_permitidas text[];
  v_a jsonb;
  v_num numeric;
  v_f float8;
begin
  if jsonb_typeof(p_i) is distinct from 'object' then /*D40*/ return false; end if;
  v_tipo := case when jsonb_typeof(p_i -> 'tipo') = 'string' then p_i ->> 'tipo' end;
  v_permitidas := case v_tipo
    when 'celda' then array['tipo', 'nodo', 'ancho', 'secundario', 'ayuda', 'nivel_ver', 'nivel_editar']
    when 'atajos' then array['tipo', 'nodo', 'columna', 'filas']
    when 'variante' then array['tipo', 'nodo']
    when 'interruptor' then array['tipo', 'nodo', 'efecto']
    when 'subtotal' then array['tipo', 'nodo']
  end;
  if v_permitidas is null then /*D41*/ return false; end if;
  -- Una clave que el tipo no lleva (también «__proto__», «clase» o «color») es un error, no se ignora.
  if (p_i - v_permitidas) <> '{}'::jsonb then /*D42*/ return false; end if;
  if (jsonb_typeof(p_i -> 'nodo') = 'string' and (p_i ->> 'nodo') ~ c_id) is not true then /*D43*/ return false; end if;

  if v_tipo = 'celda' then
    if (jsonb_typeof(p_i -> 'ancho') = 'string' and (p_i ->> 'ancho') in ('completo', 'mitad', 'tercio')) is not true then
      /*D44*/ return false;
    end if;
    if p_i ? 'secundario'
       and (jsonb_typeof(p_i -> 'secundario') = 'string' and (p_i ->> 'secundario') in ('porcentaje', 'monto')) is not true then
      /*D45*/ return false;
    end if;
    if p_i ? 'nivel_ver' and (jsonb_typeof(p_i -> 'nivel_ver') = 'string' and (p_i ->> 'nivel_ver') ~ c_id) is not true then
      /*D46*/ return false;
    end if;
    if p_i ? 'nivel_editar' and (jsonb_typeof(p_i -> 'nivel_editar') = 'string' and (p_i ->> 'nivel_editar') ~ c_id) is not true then
      /*D47*/ return false;
    end if;
    -- La ayuda es la tabla que se abre o un texto, no las dos.
    if p_i ? 'ayuda' then
      v_a := p_i -> 'ayuda';
      if jsonb_typeof(v_a) is distinct from 'object' then /*D48*/ return false; end if;
      if v_a ? 'tabla' then
        if (v_a - 'tabla') <> '{}'::jsonb then /*D49*/ return false; end if;
        if (jsonb_typeof(v_a -> 'tabla') = 'string' and (v_a ->> 'tabla') ~ c_id) is not true then /*D50*/ return false; end if;
      elsif v_a ? 'texto' then
        if (v_a - 'texto') <> '{}'::jsonb then /*D51*/ return false; end if;
        if (jsonb_typeof(v_a -> 'texto') = 'string' and char_length(v_a ->> 'texto') between 1 and 300) is not true then
          /*D52*/ return false;
        end if;
      else
        /*D53*/ return false;
      end if;
    end if;
  elsif v_tipo = 'atajos' then
    if (jsonb_typeof(p_i -> 'columna') = 'string' and (p_i ->> 'columna') ~ c_id) is not true then /*D54*/ return false; end if;
    -- `z.int().min(1).max(12)` sobre el número como lo lee JS: 1.0 y 0.99999999999999999 valen 1; lo que JS redondea a 0, no. Un
    -- entero menor que 1 sólo puede ser 0 (D56), y uno de 13 o más lo corta D57: sólo queda lo que el doble redondea a 13.
    if jsonb_typeof(p_i -> 'filas') is distinct from 'number' then /*D55*/ return false; end if;
    v_num := (p_i -> 'filas')::numeric;
    if abs(v_num) < 1e-300 then
      /*D56*/ return false;
    elsif abs(v_num) >= 13 then
      /*D57*/ return false;
    else
      v_f := v_num::float8;
      if v_f <> trunc(v_f) or v_f > 12 then /*D58*/ return false; end if;
    end if;
  elsif v_tipo = 'interruptor' then
    if (jsonb_typeof(p_i -> 'efecto') = 'string' and (p_i ->> 'efecto') in ('habilita', 'muestra')) is not true then
      /*D59*/ return false;
    end if;
  end if;
  return true;
end;
$_$;


ALTER FUNCTION "public"."_diseno_forma_item"("p_i" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_diseno_modos"("p_modos" "jsonb", "p_buckets" "jsonb", "p_nb" integer, "p_total_en" "text", "p_pos" "jsonb", "p_tipos" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_dup boolean[];
  v_m jsonb;
  v_clave text;
  v_regla text;
  v_ref text;
  v_total text;
begin
  -- Un modo repite la clave de uno anterior.
  select coalesce(array_agg(d.rn > 1 order by d.ord), '{}')
    into v_dup
    from (select x.ord, row_number() over (partition by x.value ->> 'clave' order by x.ord) as rn
            from jsonb_array_elements(p_modos) with ordinality as x(value, ord)) d;
  for i in 1 .. coalesce(array_length(v_dup, 1), 0) loop
    v_m := p_modos -> (i - 1);
    v_clave := v_m ->> 'clave';
    if v_dup[i] then
      perform public._formula_rechazar('modo_duplicado', v_clave,
        format('Hay dos modos de tipo de cambio con la clave «%s».', v_clave));
    end if;
    if p_total_en is null then
      perform public._formula_rechazar('modo_sin_total_en', v_clave,
        format('El modo «%s» trae su propio «total_en», y la fórmula no tiene uno: con un modo el total cambiaría de cuenta.', v_clave));
    end if;
    -- La primera entrada que falla, y qué le pasa: bucket inexistente, repetido o un nodo que no es un tipo de cambio.
    select q.regla, q.ref
      into v_regla, v_ref
      from (select case when not coalesce(p_buckets ? e.bucket, false) then 'modo_bucket_inexistente'
                        when e.rep then 'modo_bucket_repetido'
                        when p_tipos[(p_pos ->> e.nodo)::int] is distinct from 'tipo_cambio' then 'modo_tipo_de_cambio_inexistente'
                   end as regla,
                   case when not coalesce(p_buckets ? e.bucket, false) or e.rep then e.bucket else e.nodo end as ref,
                   e.ord
              from (select x.ord, x.value ->> 'bucket' as bucket, x.value ->> 'nodo' as nodo,
                           row_number() over (partition by x.value ->> 'bucket' order by x.ord) > 1 as rep
                      from jsonb_array_elements(v_m -> 'buckets') with ordinality as x(value, ord)) e) q
     where q.regla is not null
     order by q.ord
     limit 1;
    if v_regla = 'modo_bucket_inexistente' then
      perform public._formula_rechazar('modo_bucket_inexistente', v_clave,
        format('El modo «%s» usa el bucket «%s», que la fórmula no tiene.', v_clave, v_ref));
    elsif v_regla = 'modo_bucket_repetido' then
      perform public._formula_rechazar('modo_bucket_repetido', v_clave,
        format('El modo «%s» llena dos veces el bucket «%s».', v_clave, v_ref));
    elsif v_regla = 'modo_tipo_de_cambio_inexistente' then
      perform public._formula_rechazar('modo_tipo_de_cambio_inexistente', v_clave,
        format('El modo «%s» nombra «%s», que no es un tipo de cambio de la fórmula.', v_clave, v_ref));
    end if;
    v_total := v_m ->> 'total_en';
    if p_tipos[(p_pos ->> v_total)::int] is distinct from 'tipo_cambio' then
      perform public._formula_rechazar('modo_tipo_de_cambio_inexistente', v_clave,
        format('El modo «%s» nombra «%s», que no es un tipo de cambio de la fórmula.', v_clave, v_total));
    end if;
    -- Cada bucket del modo existe en la fórmula y no se repite: llena todos si tiene tantos como ella.
    if jsonb_array_length(v_m -> 'buckets') < p_nb then
      perform public._formula_rechazar('modo_incompleto', v_clave,
        format('El modo «%s» tiene que llenar todos los buckets de la fórmula y le falta alguno.', v_clave));
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."_diseno_modos"("p_modos" "jsonb", "p_buckets" "jsonb", "p_nb" integer, "p_total_en" "text", "p_pos" "jsonb", "p_tipos" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_diseno_nivel"("p_nivel" "text", "p_donde" "text", "p_niveles" "jsonb", "p_retirados" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_nivel is null or p_nivel = 'todos' then return; end if;
  if not coalesce(p_niveles ? p_nivel, false) then
    perform public._formula_rechazar('nivel_inexistente', p_donde,
      format('«%s» usa el nivel «%s», que no existe.', p_donde, p_nivel));
  end if;
  if coalesce(p_retirados ? p_nivel, false) then
    perform public._formula_rechazar('nivel_retirado', p_donde,
      format('«%s» usa el nivel «%s», que está retirado: elige otro para esta celda o sección.', p_donde, p_nivel));
  end if;
end;
$$;


ALTER FUNCTION "public"."_diseno_nivel"("p_nivel" "text", "p_donde" "text", "p_niveles" "jsonb", "p_retirados" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_diseno_secciones"("p_secs" "jsonb", "p_tarjeta" "jsonb", "p_ids" "text"[], "p_tipos" "text"[], "p_ops" "text"[], "p_salidas" "text"[], "p_sobres" boolean[], "p_pcts" "text"[], "p_pos" "jsonb", "p_cond" "jsonb", "p_req" "jsonb", "p_niveles" "jsonb", "p_retirados" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_n int := coalesce(array_length(p_ids, 1), 0);
  v_aver text[] := array_fill(null::text, array[v_n]);     -- con qué nivel de ver se dibuja el nodo (nulo: no se dibuja)
  v_aedit text[] := array_fill(null::text, array[v_n]);    -- con qué nivel de editar
  v_atajo boolean[] := array_fill(false, array[v_n]);      -- ya tiene unos atajos
  v_visto boolean[] := array_fill(false, array[v_n]);      -- ya es un secundario de la tarjeta
  v_a_nodo int[] := '{}'::int[];                           -- los atajos, en el orden del diseño: nodo, niveles de su sección
  v_a_ver text[] := '{}'::text[];
  v_a_edit text[] := '{}'::text[];
  v_dup boolean[];
  v_s jsonb;
  v_its jsonb;
  v_it jsonb;
  v_sid text;
  v_hver text;
  v_hedit text;
  v_ver text;
  v_edit text;
  v_tipo text;
  v_nodo text;
  v_ntipo text;
  v_efecto text;
  v_pct text;
  v_esp boolean;
  j int;
  l int;
begin
  -- §2 las secciones, en orden. Una sección repite el id de una anterior.
  select coalesce(array_agg(d.rn > 1 order by d.ord), '{}')
    into v_dup
    from (select x.ord, row_number() over (partition by x.value ->> 'id' order by x.ord) as rn
            from jsonb_array_elements(p_secs) with ordinality as x(value, ord)) d;
  for i in 1 .. coalesce(array_length(v_dup, 1), 0) loop
    v_s := p_secs -> (i - 1);
    v_sid := v_s ->> 'id';
    if v_dup[i] then
      perform public._formula_rechazar('seccion_duplicada', v_sid, format('Hay dos secciones con el id «%s».', v_sid));
    end if;
    perform public._diseno_nivel(v_s ->> 'nivel_ver', v_sid, p_niveles, p_retirados);
    perform public._diseno_nivel(v_s ->> 'nivel_editar', v_sid, p_niveles, p_retirados);
    v_hver := coalesce(v_s ->> 'nivel_ver', 'todos');
    v_hedit := coalesce(v_s ->> 'nivel_editar', 'todos');
    -- Lo lo que no se ve no se edita: ver restringido con editar abierto se rechaza (ver abierto con editar restringido vale).
    if v_hver <> 'todos' and v_hedit = 'todos' then
      perform public._formula_rechazar('editar_sin_ver', v_sid, format('«%s» se ve sólo con un nivel y se edita sin él: lo que no se ve no se edita. Ponle también un nivel de edición.', v_sid));
    end if;
    v_its := v_s -> 'items';

    for k in 0 .. jsonb_array_length(v_its) - 1 loop
      v_it := v_its -> k;
      v_tipo := v_it ->> 'tipo';
      v_nodo := v_it ->> 'nodo';
      j := (p_pos ->> v_nodo)::int;
      if j is null then
        perform public._formula_rechazar('nodo_inexistente', v_nodo,
          format('El diseño nombra «%s», que no es un nodo de la fórmula.', v_nodo));
      end if;
      v_ntipo := p_tipos[j];
      v_esp := v_ntipo = 'calculo' and p_ops[j] = 'porcentaje_de';
      v_ver := v_hver;
      v_edit := v_hedit;

      if v_tipo = 'celda' then
        if v_ntipo in ('opcion', 'bandera') then
          perform public._formula_rechazar('celda_no_es_valor', v_nodo,
            format('«%s» no se dibuja como celda: la variante va como chips y una bandera como interruptor.', v_nodo));
        end if;
        if v_it ? 'secundario' and not v_esp then
          perform public._formula_rechazar('secundario_sin_porcentaje', v_nodo,
            format('«%s» lleva un secundario y no es un porcentaje de otro monto.', v_nodo));
        end if;
        if v_esp and p_sobres[j] and not (v_it ? 'secundario') then
          perform public._formula_rechazar('par_sin_secundario', v_nodo,
            format('«%s» es un monto con su porcentaje y se sobrescribe: el par es una sola celda con su secundario.', v_nodo));
        end if;
        perform public._diseno_nivel(v_it ->> 'nivel_ver', v_nodo, p_niveles, p_retirados);
        perform public._diseno_nivel(v_it ->> 'nivel_editar', v_nodo, p_niveles, p_retirados);
        v_ver := coalesce(v_it ->> 'nivel_ver', v_hver);
        v_edit := coalesce(v_it ->> 'nivel_editar', v_hedit);
      elsif v_tipo = 'atajos' then
        if v_ntipo <> 'tabla' then
          perform public._formula_rechazar('atajos_no_es_tabla', v_nodo,
            format('Los atajos de «%s» van sobre un nodo de tabla, y ese nodo no lo es.', v_nodo));
        end if;
        if not p_sobres[j] then
          perform public._formula_rechazar('atajos_no_sobrescribible', v_nodo,
            format('Los atajos de «%s» eligen una fila y dejan su valor como sugerido: la tabla tiene que poder sobrescribirse.', v_nodo));
        end if;
      elsif v_tipo = 'variante' then
        if v_ntipo <> 'opcion' then
          perform public._formula_rechazar('variante_no_es_opcion', v_nodo,
            format('«%s» no es la variante de la fórmula.', v_nodo));
        end if;
      elsif v_tipo = 'interruptor' then
        if v_ntipo <> 'bandera' then
          perform public._formula_rechazar('interruptor_no_es_bandera', v_nodo,
            format('«%s» no es una bandera: un interruptor la enciende.', v_nodo));
        end if;
        -- «Habilita» apaga lo que la bandera condiciona o pide; «muestra», sólo lo que condiciona.
        v_efecto := v_it ->> 'efecto';
        if not (p_cond ? v_nodo) and not (v_efecto = 'habilita' and p_req ? v_nodo) then
          perform public._formula_rechazar('interruptor_sin_efecto', v_nodo,
            format('La bandera «%s» no condiciona ningún nodo: su interruptor no haría nada.', v_nodo));
        end if;
      elsif v_tipo = 'subtotal' then
        if v_ntipo <> 'calculo' then
          perform public._formula_rechazar('subtotal_no_es_calculo', v_nodo,
            format('«%s» no es un cálculo: un subtotal se dibuja desde uno.', v_nodo));
        end if;
      end if;

      -- El total, lo que va aparte y la variante los recibe todo el mundo (D7). «Lo que va aparte» incluye el porcentaje que muestra una celda con
      -- secundario y la bandera de un interruptor (4-9): se dibujan con el nivel de su ítem y la base los manda igual.
      if v_ver <> 'todos'
         and (v_tipo = 'variante' or (v_tipo in ('celda', 'subtotal') and p_salidas[j] in ('total', 'aparte'))) then
        perform public._formula_rechazar('nivel_no_admitido', v_nodo,
          format('«%s» se muestra a todos: el total, lo que va aparte y la variante no se pueden restringir a un nivel.', v_nodo));
      end if;
      if v_ver <> 'todos' and v_tipo = 'celda' and v_it ? 'secundario' and p_salidas[(p_pos ->> p_pcts[j])::int] in ('total', 'aparte') then
        perform public._formula_rechazar('nivel_no_admitido', p_pcts[j],
          format('«%s» se muestra a todos: el total, lo que va aparte y la variante no se pueden restringir a un nivel.', p_pcts[j]));
      end if;
      if v_ver <> 'todos' and v_tipo = 'interruptor' and p_salidas[j] in ('total', 'aparte') then
        perform public._formula_rechazar('nivel_no_admitido', v_nodo,
          format('«%s» se muestra a todos: el total, lo que va aparte y la variante no se pueden restringir a un nivel.', v_nodo));
      end if;
      -- Una celda con su nivel de ver restringido y el de editar abierto (la sección ya revisada no lo tiene: sólo lo rompe el nivel propio de la celda).
      if v_tipo = 'celda' and v_ver <> 'todos' and v_edit = 'todos' then
        perform public._formula_rechazar('editar_sin_ver', v_nodo, format('«%s» se ve sólo con un nivel y se edita sin él: lo que no se ve no se edita. Ponle también un nivel de edición.', v_nodo));
      end if;

      -- Dónde se dibuja el valor del nodo (y el del porcentaje de un par); un segundo dibujo es `nodo_repetido`.
      if v_tipo = 'atajos' then
        if v_atajo[j] then
          perform public._formula_rechazar('nodo_repetido', v_nodo, format('«%s» aparece dos veces en el diseño.', v_nodo));
        end if;
        v_atajo[j] := true;
        v_a_nodo := array_append(v_a_nodo, j);
        v_a_ver := array_append(v_a_ver, v_hver);
        v_a_edit := array_append(v_a_edit, v_hedit);
      else
        if v_aver[j] is not null then
          perform public._formula_rechazar('nodo_repetido', v_nodo, format('«%s» aparece dos veces en el diseño.', v_nodo));
        end if;
        v_aver[j] := v_ver;
        v_aedit[j] := v_edit;
        if v_tipo = 'celda' and v_it ? 'secundario' then
          v_pct := p_pcts[j];
          l := (p_pos ->> v_pct)::int;
          if v_aver[l] is not null then
            perform public._formula_rechazar('nodo_repetido', v_pct, format('«%s» aparece dos veces en el diseño.', v_pct));
          end if;
          v_aver[l] := v_ver;
          v_aedit[l] := v_edit;
        end if;
      end if;
    end loop;
  end loop;

  -- §3 la tarjeta: el total y sus secundarios (la garantía), que repiten lo que la hoja ya dibuja.
  v_nodo := p_tarjeta ->> 'nodo';
  j := (p_pos ->> v_nodo)::int;
  if j is null then
    perform public._formula_rechazar('nodo_inexistente', v_nodo,
      format('El diseño nombra «%s», que no es un nodo de la fórmula.', v_nodo));
  end if;
  if p_salidas[j] is distinct from 'total' then
    perform public._formula_rechazar('tarjeta_no_es_el_total', v_nodo,
      format('La tarjeta nombra «%s», que no es el total de la fórmula.', v_nodo));
  end if;
  v_its := p_tarjeta -> 'secundarios';
  for k in 0 .. jsonb_array_length(v_its) - 1 loop
    v_nodo := v_its ->> k;
    j := (p_pos ->> v_nodo)::int;
    if j is null then
      perform public._formula_rechazar('nodo_inexistente', v_nodo,
        format('El diseño nombra «%s», que no es un nodo de la fórmula.', v_nodo));
    end if;
    if p_salidas[j] is distinct from 'aparte' then
      perform public._formula_rechazar('tarjeta_secundario_no_es_aparte', v_nodo,
        format('«%s» es un secundario de la tarjeta y no es una salida «aparte».', v_nodo));
    end if;
    if v_visto[j] then
      perform public._formula_rechazar('nodo_repetido', v_nodo, format('«%s» aparece dos veces en el diseño.', v_nodo));
    end if;
    v_visto[j] := true;
  end loop;

  -- §4 un atajos va sobre la celda de su nodo (o el porcentaje que ella muestra) y con sus mismos niveles.
  for i in 1 .. coalesce(array_length(v_a_nodo, 1), 0) loop
    j := v_a_nodo[i];
    if v_aver[j] is null then
      perform public._formula_rechazar('atajos_sin_celda', p_ids[j],
        format('Los atajos de «%s» necesitan la celda de ese nodo en el diseño.', p_ids[j]));
    end if;
    if v_aver[j] <> v_a_ver[i] or v_aedit[j] <> v_a_edit[i] then
      perform public._formula_rechazar('nodo_con_dos_niveles', p_ids[j],
        format('Los atajos de «%s» y su celda tienen niveles distintos: tienen que ser los mismos.', p_ids[j]));
    end if;
  end loop;

  -- §5 lo que la hoja tiene que dibujar sí o sí, en el orden de la fórmula: todo input y constante, la variante y las banderas que
  -- condicionan algo o piden un dato.
  for n in 1 .. v_n loop
    if v_aver[n] is null
       and (p_tipos[n] in ('input', 'constante', 'opcion')
            or (p_tipos[n] = 'bandera' and (p_cond ? p_ids[n] or p_req ? p_ids[n]))) then
      perform public._formula_rechazar('nodo_sin_seccion', p_ids[n],
        format('«%s» no está en ninguna sección del diseño.', p_ids[n]));
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."_diseno_secciones"("p_secs" "jsonb", "p_tarjeta" "jsonb", "p_ids" "text"[], "p_tipos" "text"[], "p_ops" "text"[], "p_salidas" "text"[], "p_sobres" boolean[], "p_pcts" "text"[], "p_pos" "jsonb", "p_cond" "jsonb", "p_req" "jsonb", "p_niveles" "jsonb", "p_retirados" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_embudo_conflicto"("p_cuando" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  raise exception 'Cambiaste este embudo % desde otra ventana. Recarga para seguir desde ahí.', public._hace(p_cuando)
    using errcode = 'PT409';
end;
$$;


ALTER FUNCTION "public"."_embudo_conflicto"("p_cuando" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_embudo_defecto_de"("p_usuario" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  perform public._embudos_candado(p_usuario);
  select e.id into v_id from public.embudos e where e.usuario_id = p_usuario and e.es_default;
  if found then
    return v_id;
  end if;
  select e.id into v_id from public.embudos e where e.usuario_id = p_usuario order by e.creado_en, e.id limit 1;
  if found then
    update public.embudos e set es_default = true where e.id = v_id;
    return v_id;
  end if;
  return public._embudo_insertar(p_usuario, null, 'Ventas', true, jsonb_build_array(
    jsonb_build_object('nombre', 'Nuevo', 'color', 'gris', 'es_inicial', true),
    jsonb_build_object('nombre', 'Contactado', 'color', 'azul'),
    jsonb_build_object('nombre', 'Cotizado', 'color', 'violeta'),
    jsonb_build_object('nombre', 'Negociación', 'color', 'ambar'),
    jsonb_build_object('nombre', 'Ganado', 'color', 'verde', 'es_ganada', true),
    jsonb_build_object('nombre', 'Perdido', 'color', 'rojo', 'es_perdida', true)));
end;
$$;


ALTER FUNCTION "public"."_embudo_defecto_de"("p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_embudo_insertar"("p_usuario" "uuid", "p_id" "uuid", "p_nombre" "text", "p_default" boolean, "p_etapas" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  insert into public.embudos (id, usuario_id, nombre, es_default, actualizado_en)
  values (coalesce(p_id, gen_random_uuid()), p_usuario, p_nombre, p_default, clock_timestamp())
  returning id into v_id;
  insert into public.embudos_etapas (embudo_id, nombre, color, es_inicial, es_ganada, es_perdida, orden)
  select v_id, x ->> 'nombre', x ->> 'color', coalesce((x ->> 'es_inicial')::boolean, false),
         coalesce((x ->> 'es_ganada')::boolean, false), coalesce((x ->> 'es_perdida')::boolean, false), (o * 10)::smallint
    from jsonb_array_elements(p_etapas) with ordinality t (x, o);
  return v_id;
end;
$$;


ALTER FUNCTION "public"."_embudo_insertar"("p_usuario" "uuid", "p_id" "uuid", "p_nombre" "text", "p_default" boolean, "p_etapas" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_embudo_json"("p_embudo" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', e.id, 'nombre', e.nombre, 'es_default', e.es_default, 'actualizado_en', e.actualizado_en,
    'etapas', coalesce((select jsonb_agg(jsonb_build_object(
        'id', s.id, 'nombre', s.nombre, 'color', s.color,
        'es_inicial', s.es_inicial, 'es_ganada', s.es_ganada, 'es_perdida', s.es_perdida)
        order by s.orden, s.id)
      from public.embudos_etapas s where s.embudo_id = e.id), '[]'::jsonb))
  from public.embudos e where e.id = p_embudo;
$$;


ALTER FUNCTION "public"."_embudo_json"("p_embudo" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."embudos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "nombre" "text" NOT NULL,
    "es_default" boolean DEFAULT false NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "embudos_nombre_largo" CHECK ((("char_length"("nombre") >= 1) AND ("char_length"("nombre") <= 40)))
);


ALTER TABLE "public"."embudos" OWNER TO "postgres";


COMMENT ON TABLE "public"."embudos" IS 'Embudos de oportunidades de cada persona: sólo los ve y los toca su dueña, y se escriben sólo por RPC (embudo_*). El de por defecto lo crea embudo_por_defecto() la primera vez que hace falta.';



CREATE OR REPLACE FUNCTION "public"."_embudo_mio"("p_embudo" "uuid") RETURNS "public"."embudos"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare e public.embudos;
begin
  select * into e from public.embudos x where x.id = p_embudo and x.usuario_id = (select auth.uid()) for update;
  if not found then
    raise exception 'No encontramos este embudo. Recarga para ver los tuyos.' using errcode = '42501';
  end if;
  return e;
end;
$$;


ALTER FUNCTION "public"."_embudo_mio"("p_embudo" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_embudo_nombre"("p_nombre" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v text := btrim(coalesce(p_nombre, ''));
begin
  if char_length(v) not between 1 and 40 then
    raise exception 'El nombre de un embudo lleva entre 1 y 40 caracteres.' using errcode = '22023', hint = 'nombre';
  end if;
  return v;
end;
$$;


ALTER FUNCTION "public"."_embudo_nombre"("p_nombre" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_embudo_nombre_libre"("p_usuario" "uuid", "p_nombre" "text", "p_excepto" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v text;
begin
  select e.nombre into v from public.embudos e
   where e.usuario_id = p_usuario and lower(e.nombre) = lower(p_nombre) and e.id is distinct from p_excepto;
  if found then
    raise exception 'Ya tienes un embudo «%».', v using errcode = '22023', hint = 'nombre';
  end if;
end;
$$;


ALTER FUNCTION "public"."_embudo_nombre_libre"("p_usuario" "uuid", "p_nombre" "text", "p_excepto" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_embudo_patron"("p_texto" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  select case when char_length(btrim(coalesce(p_texto, ''))) < 2 then null
              else '%' || replace(replace(replace(btrim(left(p_texto, 60)), '\', '\\'), '%', '\%'), '_', '\_') || '%' end
$$;


ALTER FUNCTION "public"."_embudo_patron"("p_texto" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_embudos_candado"("p_usuario" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform pg_advisory_xact_lock(hashtextextended('embudos:' || p_usuario::text, 0));
end;
$$;


ALTER FUNCTION "public"."_embudos_candado"("p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_embudos_puedo"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_activo();
  if public.alcance_de('leads.ver') is null then
    raise exception 'No tienes permiso para ver leads.' using errcode = '42501';
  end if;
  return (select auth.uid());
end;
$$;


ALTER FUNCTION "public"."_embudos_puedo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_encolar_para_limpiar"("p_bucket" "text", "p_rutas" "text"[], "p_ya" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int;
begin
  insert into public.cola_gc_storage as c (bucket, ruta, encolado_en)
  select distinct p_bucket, r, case when p_ya then now() - public._gracia_de_storage() - interval '1 second' else now() end
  from unnest(p_rutas) as r
  where r is not null and public.storage_refcount(p_bucket, r) = 0
  on conflict (bucket, ruta) do update set encolado_en = least(c.encolado_en, excluded.encolado_en) where c.reclamado_en is null;
  get diagnostics n = row_count;
  return n;
end;
$$;


ALTER FUNCTION "public"."_encolar_para_limpiar"("p_bucket" "text", "p_rutas" "text"[], "p_ya" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_equipo_busqueda_patron"("p_texto" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  select '%' || replace(replace(replace(public._sin_tildes(p_texto), '\', '\\'), '%', '\%'), '_', '\_') || '%'
$$;


ALTER FUNCTION "public"."_equipo_busqueda_patron"("p_texto" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_equipo_lista_indexable"("p_texto" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  select coalesce(public._sin_tildes(p_texto) ~ '[[:alnum:]]{3}', false)
$$;


ALTER FUNCTION "public"."_equipo_lista_indexable"("p_texto" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_equipo_lista_recorrido"() RETURNS integer
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$ select 2000 $$;


ALTER FUNCTION "public"."_equipo_lista_recorrido"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_equipo_lista_sql"("p_texto" "text", "p_estado" "text", "p_limite" integer, "p_etapa" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_texto text := left(btrim(coalesce(p_texto, '')), 100);
  v_estado text := coalesce(p_estado, 'vigentes');
  v_estado_donde text;
  v_texto_donde text := 'true';
  v_texto_de_w text := 'true';
begin
  if v_estado = 'vigentes' then
    v_estado_donde := 'p.activo';
  elsif v_estado in ('activa', 'invitacion_pendiente', 'bloqueada', 'baja') then
    v_estado_donde := format('public._estado_de_persona(p.activo, p.bloqueado, p.invitado_en, p.invitacion_aceptada_en) = %L', v_estado);
  else
    raise exception 'El estado «%» no existe.', v_estado using errcode = '22023';
  end if;
  if v_texto <> '' then
    v_texto_donde := format('public._sin_tildes(p.nombre || %L || coalesce(p.email::text, %L)) like %L', ' ', '', public._equipo_busqueda_patron(v_texto));
    v_texto_de_w := format('public._sin_tildes(w.nombre || %L || coalesce(w.email::text, %L)) like %L', ' ', '', public._equipo_busqueda_patron(v_texto));
  end if;
  if p_etapa = 'recorrer' then
    -- Sin `materialized`: la subconsulta se lee de a una fila y el `limit` de afuera corta en cuanto junta lo que pide. El `order by` de afuera lo cumple el de adentro
    -- (el planificador lo sabe y no ordena otra vez).
    return format('select array(select w.id from (select p.id, p.nombre, p.email from public.perfiles p where %s order by p.nombre, p.email, p.id limit %s) w '
                  'where %s order by w.nombre, w.email, w.id limit %s) as ids',
                  v_estado_donde, public._equipo_lista_recorrido(), v_texto_de_w, p_limite);
  elsif p_etapa = 'indice' then
    -- `materialized` cierra la subconsulta: sin él el planificador la deshace y camina el índice del orden (el plan de «maria»).
    return format('with m as materialized (select p.id, p.nombre, p.email from public.perfiles p where %s and %s) '
                  'select m.id from m order by m.nombre, m.email, m.id limit %s',
                  v_estado_donde, v_texto_donde, p_limite);
  elsif p_etapa = 'todo' then
    return format('select p.id from public.perfiles p where %s and %s order by p.nombre, p.email, p.id limit %s', v_estado_donde, v_texto_donde, p_limite);
  end if;
  raise exception 'La etapa «%» no existe.', p_etapa;
end;
$$;


ALTER FUNCTION "public"."_equipo_lista_sql"("p_texto" "text", "p_estado" "text", "p_limite" integer, "p_etapa" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_estado_de_persona"("p_activo" boolean, "p_bloqueado" boolean, "p_invitado_en" timestamp with time zone, "p_aceptada_en" timestamp with time zone) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  select case when not p_activo then 'baja'
              when p_bloqueado then 'bloqueada'
              when p_invitado_en is not null and p_aceptada_en is null then 'invitacion_pendiente'
              else 'activa' end
$$;


ALTER FUNCTION "public"."_estado_de_persona"("p_activo" boolean, "p_bloqueado" boolean, "p_invitado_en" timestamp with time zone, "p_aceptada_en" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_etiqueta_color"("p_color" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_color is null or not (p_color = any (public._etiquetas_paleta())) then
    raise exception 'Elige un color de la paleta.' using errcode = '22023', hint = 'color';
  end if;
  return p_color;
end;
$$;


