CREATE OR REPLACE FUNCTION "public"."_lead_conflicto"("p_lead" "uuid", "p_cuando" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid; v_nombre text; v_hay boolean := false;
begin
  select a.actor_id, true into v_actor, v_hay from public.actividad a
   where a.tabla = 'leads' and a.registro_id = p_lead::text and a.accion = 'leads.update'
   order by a.id desc limit 1;
  if v_actor is not null and v_actor = (select auth.uid()) then
    raise exception 'Cambiaste este lead % desde otra ventana. Recarga para seguir desde ahí.', public._hace(p_cuando)
      using errcode = 'PT409';
  end if;
  if v_actor is not null then
    select nullif(btrim(p.nombre), '') into v_nombre from public.perfiles p where p.id = v_actor;
  end if;
  if v_nombre is null and (v_actor is not null or not coalesce(v_hay, false)) then
    v_nombre := 'Otra persona';
  end if;
  if v_nombre is null then
    raise exception 'Este lead cambió %.', public._hace(p_cuando) using errcode = 'PT409';
  end if;
  raise exception '% cambió este lead %.', v_nombre, public._hace(p_cuando) using errcode = 'PT409';
end;
$$;


ALTER FUNCTION "public"."_lead_conflicto"("p_lead" "uuid", "p_cuando" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_crear"("p_id" "uuid", "p_lead" "jsonb", "p_seguimiento" "jsonb", "p_recordatorio" "jsonb", "p_recordar_origen" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_permitidas constant text[] := array['nombre', 'telefono_cc', 'telefono_principal', 'tipo_lead_id', 'origen_lead_id', 'atributos', 'adoptar'];
  v_k text;
  v_cc text;
  v_cc_digitos text;
  v_tel text;
  v_nombre text;
  v_tipo uuid;
  v_origen uuid;
  v_activos text[];
  v_atributos jsonb := '{}'::jsonb;
  v_verif jsonb;
  v_estado text;
  v_id uuid;
  v_adoptado boolean := false;
  v_tipo_seg uuid;
  v_titulo text;
  v_detalle text;
  v_doc jsonb;
  v_id_previo uuid;
  v_ocurrido timestamptz := now();
  v_k2 text;
  v_msg text;
  v_recordar timestamptz;
  v_titulo_rec text;
begin
  if p_id is null then
    raise exception 'Falta el identificador del intento.' using errcode = '22023';
  end if;
  if p_lead is null or jsonb_typeof(p_lead) <> 'object' then
    raise exception 'Los datos del lead tienen que ser un objeto.' using errcode = '22023';
  end if;
  for v_k in select jsonb_object_keys(p_lead) loop
    if not (v_k = any (v_permitidas)) then
      raise exception 'El dato «%» no va suelto: los campos del lead se mandan dentro de «atributos».', v_k
        using errcode = '22023', hint = v_k;
    end if;
  end loop;

  -- ¿Ya entró este intento? Una respuesta perdida y un reintento: devuelve lo mismo, no duplica.
  select l.id into v_id from public.leads l where l.id = p_id and l.creado_por = v_yo;
  if found then
    return jsonb_build_object('resultado', 'creado', 'id', v_id, 'repetido', true) || public._lead_numeros_de(v_id);
  end if;
  -- ¿Ya entró por una adopción del limbo? Sólo un alta que adopta (`adoptar`) puede haber escrito ese intento, y la
  -- importación nunca adopta: sin `adoptar` no se busca. Buscarlo siempre costaba 0,15 µs por fila de `actividad` por cada
  -- alta (con `leads` grande el planificador recorría `actividad_pkey` entera en vez de `actividad_intento_adopcion_idx`):
  -- importar 500 filas con 126.000 de `actividad` tardaba 10,5 s. `docs/DECISIONES.md`, «Cierre 5a-fix-2».
  if (p_lead ->> 'adoptar') = 'true' then
    select l.id into v_id
      from public.actividad a join public.leads l on l.id::text = a.registro_id
     where a.accion = 'lead.adoptado_del_limbo' and a.actor_id = v_yo and a.detalle ->> 'intento' = p_id::text
     order by a.id desc limit 1;
    if found then
      return jsonb_build_object('resultado', 'adoptado', 'id', v_id, 'repetido', true) || public._lead_numeros_de(v_id);
    end if;
  end if;

  -- El teléfono, y lo que ya se sabe de él.
  v_cc := coalesce(nullif(btrim(p_lead ->> 'telefono_cc'), ''), (select e.telefono_cc from public.ajustes_empresa e where e.id = 1));
  v_tel := public.normalizar_telefono(v_cc, p_lead ->> 'telefono_principal');
  v_verif := public._lead_verificar(v_tel);
  v_estado := v_verif ->> 'estado';
  if v_estado in ('existe', 'de_otro') or (v_estado = 'limbo' and (p_lead ->> 'adoptar') is distinct from 'true') then
    return jsonb_build_object('resultado', v_estado, 'verificacion', v_verif);
  end if;

  -- Lo demás que tiene que pasar, antes de escribir nada.
  v_nombre := btrim(coalesce(p_lead ->> 'nombre', ''));
  if v_nombre = '' then
    raise exception 'Escribe el nombre.' using errcode = '22023', hint = 'nombre';
  end if;
  if char_length(v_nombre) > 120 then
    raise exception 'El nombre admite hasta 120 caracteres.' using errcode = '22023', hint = 'nombre';
  end if;
  begin
    v_tipo := coalesce(nullif(p_lead ->> 'tipo_lead_id', '')::uuid, public._tipo_lead_por_defecto());
  exception when invalid_text_representation then
    raise exception 'Ese tipo de lead no existe.' using errcode = '22023', hint = 'tipo_lead_id';
  end;
  if v_tipo is null then
    raise exception 'Elige el tipo de lead.' using errcode = '22023', hint = 'tipo_lead_id';
  end if;
  perform public._tipo_lead_exigir_activo(v_tipo);
  begin
    v_origen := nullif(p_lead ->> 'origen_lead_id', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'Ese origen del lead no existe.' using errcode = '22023', hint = 'origen_lead_id';
  end;
  if v_origen is not null then
    if not exists (select 1 from public.origenes_lead o where o.id = v_origen and o.activo) then
      raise exception 'Ese origen del lead está desactivado o ya no existe.' using errcode = '22023', hint = 'origen_lead_id';
    end if;
  elsif exists (select 1 from public.origenes_lead o where o.activo) then
    raise exception 'Elige de dónde viene el lead.' using errcode = '22023', hint = 'origen_lead_id';
  end if;

  select coalesce(array_agg(c.clave), '{}') into v_activos from public.leads_campos c where c.activo;
  if p_lead ? 'atributos' then
    v_atributos := public._atributos_fusionar('{}'::jsonb, p_lead -> 'atributos', v_activos,
      'Los atributos de un lead tienen que ser un objeto.',
      'El campo «%s» no es un campo de los leads o está desactivado.');
  end if;

  if p_seguimiento is not null then
    if jsonb_typeof(p_seguimiento) <> 'object' then
      raise exception 'El seguimiento tiene que ser un objeto.' using errcode = '22023', hint = 'seguimiento.titulo';
    end if;
    -- Las mismas claves que `seguimiento_crear`, menos las que el alta no ofrece (la visibilidad y el
    -- vehículo): una de más se rechaza con su nombre, no pasa callada.
    for v_k2 in select jsonb_object_keys(p_seguimiento) loop
      if v_k2 not in ('tipo_id', 'titulo', 'detalle', 'ocurrido_en') then
        raise exception 'El dato «%» no es del primer seguimiento.', v_k2
          using errcode = '22023', hint = 'seguimiento.' || v_k2;
      end if;
    end loop;
    begin
      v_tipo_seg := nullif(p_seguimiento ->> 'tipo_id', '')::uuid;
    exception when invalid_text_representation then
      v_tipo_seg := null;
    end;
    if v_tipo_seg is null or not exists (select 1 from public.tipos_seguimiento t where t.id = v_tipo_seg and t.activo) then
      raise exception 'Elige un tipo de seguimiento que esté activo.' using errcode = '22023', hint = 'seguimiento.tipo_id';
    end if;
    -- El resumen, el detalle y la fecha se validan con las funciones de `seguimiento_crear`: una sola
    -- regla. El resumen recibe su hint; el detalle y la fecha levantan el de la ficha («detalle»,
    -- «ocurrido_en») y acá se les pone el campo del alta.
    v_titulo := public._seguimiento_titulo(p_seguimiento -> 'titulo', 'seguimiento.titulo');
    begin
      v_doc := p_seguimiento -> 'detalle';
      v_detalle := public._seguimiento_detalle(v_doc);
      if v_detalle is null then
        v_doc := null;
      end if;
    exception when sqlstate '22023' then
      get stacked diagnostics v_msg = message_text;
      raise exception '%', v_msg using errcode = '22023', hint = 'seguimiento.detalle';
    end;
    if p_seguimiento ? 'ocurrido_en' and p_seguimiento -> 'ocurrido_en' <> 'null'::jsonb then
      begin
        v_ocurrido := public._seguimiento_fecha(p_seguimiento -> 'ocurrido_en');
      exception when sqlstate '22023' then
        get stacked diagnostics v_msg = message_text;
        raise exception '%', v_msg using errcode = '22023', hint = 'seguimiento.ocurrido_en';
      end;
    end if;
  end if;
  if p_recordatorio is not null then
    if jsonb_typeof(p_recordatorio) <> 'object' then
      raise exception 'El recordatorio tiene que ser un objeto.' using errcode = '22023', hint = 'recordatorio.recordar_en';
    end if;
    begin
      v_recordar := nullif(p_recordatorio ->> 'recordar_en', '')::timestamptz;
    exception when others then
      v_recordar := null;
    end;
    if v_recordar is null then
      raise exception 'Elige cuándo recordarlo.' using errcode = '22023', hint = 'recordatorio.recordar_en';
    end if;
    if v_recordar <= now() then
      raise exception 'El recordatorio tiene que ser en el futuro.' using errcode = '22023', hint = 'recordatorio.recordar_en';
    end if;
    v_titulo_rec := coalesce(nullif(btrim(p_recordatorio ->> 'titulo'), ''), v_titulo);
    if v_titulo_rec is null then
      raise exception 'Escribe de qué es el recordatorio.' using errcode = '22023', hint = 'recordatorio.titulo';
    end if;
  end if;

  if v_estado = 'limbo' then
    -- «Tomar lead»: queda de dueño y lo que el lead ya tiene no se pisa; lo vacío se completa.
    select l.id into v_id from public.leads l
     where l.telefono_principal = v_tel and l.eliminado_en is null for update;
    -- Otra llamada del MISMO intento pudo adoptarlo mientras esta esperaba el candado (un doble envío):
    -- ya se ve confirmado, y adoptar de nuevo duplicaría el seguimiento y el recordatorio. (Otro intento
    -- de otra persona sobre el mismo lead sigue siendo la carrera de siempre, fuera de esta parte.)
    select l.id into v_id_previo
      from public.actividad a join public.leads l on l.id::text = a.registro_id
     where a.accion = 'lead.adoptado_del_limbo' and a.actor_id = v_yo and a.detalle ->> 'intento' = p_id::text
     order by a.id desc limit 1;
    if found then
      return jsonb_build_object('resultado', 'adoptado', 'id', v_id_previo, 'repetido', true) || public._lead_numeros_de(v_id_previo);
    end if;
    -- Una baja en curso de quien lo tenía se aplica a este lead antes de tomarlo (cierre 1); y si otra persona lo tomó
    -- mientras se esperaba el candado, se dice como al verificar, en vez de chocar con el dueño único.
    perform public._lead_aplicar_bajas(v_id);
    if not public.lead_en_limbo(v_id) then
      v_verif := public._lead_verificar(v_tel);
      return jsonb_build_object('resultado', v_verif ->> 'estado', 'verificacion', v_verif);
    end if;
    insert into public.leads_asesores (lead_id, usuario_id, tipo_acceso)
    values (v_id, v_yo, 'dueno')
    on conflict (lead_id, usuario_id) do update
      set tipo_acceso = 'dueno', desde = now(), revocado_en = null, revocado_por = null, compartido_por = null;
    update public.leads l set
      origen_lead_id = coalesce(l.origen_lead_id, v_origen),
      atributos = public._atributos_completar(l.atributos, v_atributos, v_activos,
        'Los atributos de un lead tienen que ser un objeto.',
        'El campo «%s» no es un campo de los leads o está desactivado.')
     where l.id = v_id;
    v_adoptado := true;
    perform public.registrar_actividad('lead.adoptado_del_limbo', 'leads', v_id::text, null,
      jsonb_build_object('telefono', public.enmascarar_telefono(v_tel)), jsonb_build_object('intento', p_id));
  else
    v_cc_digitos := regexp_replace(coalesce(v_cc, ''), '\D', '', 'g');
    begin
      insert into public.leads (id, nombre, telefono_cc, telefono_principal, tipo_lead_id, origen_lead_id, atributos, creado_por)
      values (p_id, v_nombre,
              case when v_cc_digitos <> '' and v_tel like v_cc_digitos || '%' then '+' || v_cc_digitos end,
              v_tel, v_tipo, v_origen, v_atributos, v_yo)
      returning id into v_id;
    exception when unique_violation then
      -- Dos personas guardaron el mismo teléfono a la vez (o este mismo intento, dos veces): el que
      -- llegó segundo ve su estado «existe», no un error.
      select l.id into v_id from public.leads l where l.id = p_id and l.creado_por = v_yo;
      if found then
        return jsonb_build_object('resultado', 'creado', 'id', v_id, 'repetido', true) || public._lead_numeros_de(v_id);
      end if;
      v_verif := public._lead_verificar(v_tel);
      if (v_verif ->> 'estado') in ('existe', 'de_otro', 'limbo') then
        return jsonb_build_object('resultado', v_verif ->> 'estado', 'verificacion', v_verif);
      end if;
      raise exception 'Ese teléfono cambió mientras guardabas. Vuelve a intentarlo.' using errcode = 'PT409';
    end;
    perform public.registrar_actividad('lead.creado', 'leads', v_id::text, null,
      jsonb_build_object('nombre', v_nombre), jsonb_build_object('intento', p_id));
  end if;

  if p_seguimiento is not null then
    insert into public.seguimientos (lead_id, usuario_id, tipo_id, titulo, detalle_doc, detalle_texto, ocurrido_en, actualizado_en)
    values (v_id, v_yo, v_tipo_seg, v_titulo, v_doc, v_detalle, v_ocurrido, clock_timestamp());
  end if;
  if p_recordatorio is not null then
    insert into public.recordatorios (usuario_id, lead_id, titulo, recordar_en)
    values (v_yo, v_id, v_titulo_rec, v_recordar);
  end if;
  if p_recordar_origen and v_origen is not null then
    insert into public.preferencias_usuario (usuario_id, clave, valor)
    values (v_yo, 'leads.ultimo_origen_lead', to_jsonb(v_origen::text))
    on conflict (usuario_id, clave) do update set valor = excluded.valor, actualizado_en = now();
  end if;

  return jsonb_build_object('resultado', case when v_adoptado then 'adoptado' else 'creado' end,
                            'id', v_id, 'repetido', false) || public._lead_numeros_de(v_id);
end;
$$;


ALTER FUNCTION "public"."_lead_crear"("p_id" "uuid", "p_lead" "jsonb", "p_seguimiento" "jsonb", "p_recordatorio" "jsonb", "p_recordar_origen" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_defecto_empresa"("p_tipo" "public"."tipo_campo", "p_defecto" "jsonb", "p_empresa" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_empresa is null or p_empresa = '' then return null; end if;
  if p_empresa not in ('ciudad', 'pais') then
    raise exception 'De la empresa sólo se toma la ciudad o el país.' using errcode = '22023';
  end if;
  if p_tipo <> 'texto' then
    raise exception 'El dato de la empresa sólo se usa en un campo de texto.' using errcode = '22023';
  end if;
  if p_defecto is not null then
    raise exception 'Un campo lleva un valor por defecto o el de la empresa, no los dos.' using errcode = '22023';
  end if;
  return p_empresa;
end;
$$;


ALTER FUNCTION "public"."_lead_defecto_empresa"("p_tipo" "public"."tipo_campo", "p_defecto" "jsonb", "p_empresa" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_destino_validar"("p_usuario" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_usuario is null then
    raise exception 'No encontramos a esa persona.' using errcode = '22023', hint = 'usuario';
  end if;
  perform 1 from public.perfiles p where p.id = p_usuario for share;
  if not found then
    raise exception 'No encontramos a esa persona.' using errcode = '22023', hint = 'usuario';
  end if;
  if not exists (select 1 from public.perfiles p where p.id = p_usuario and p.activo and not p.bloqueado) then
    raise exception 'Esa persona no está activa en el equipo.' using errcode = '22023', hint = 'usuario';
  end if;
  if not public.usuario_tiene_permiso(p_usuario, 'leads.ver') then
    raise exception 'Esa persona no puede ver leads.' using errcode = '22023', hint = 'usuario';
  end if;
end;
$$;


ALTER FUNCTION "public"."_lead_destino_validar"("p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_dueno"("p_lead" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select a.usuario_id from public.leads_asesores a
  where a.lead_id = p_lead and a.tipo_acceso = 'dueno' and a.revocado_en is null
    and a.usuario_id <> all ((select public._bajas_en_curso())::uuid[]);
$$;


ALTER FUNCTION "public"."_lead_dueno"("p_lead" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."leads" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "numero" bigint NOT NULL,
    "nombre" "text" NOT NULL,
    "telefono_cc" "text",
    "telefono_principal" "text" NOT NULL,
    "tipo_lead_id" "uuid" NOT NULL,
    "origen_lead_id" "uuid",
    "atributos" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "creado_por" "uuid",
    "numero_propio" integer,
    "ultimo_seguimiento_en" timestamp with time zone,
    "cartera" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "atributos_publicos" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "eliminado_en" timestamp with time zone,
    "eliminado_por" "uuid",
    "lote_papelera_id" "uuid",
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "leads_atributos_check" CHECK (("jsonb_typeof"("atributos") = 'object'::"text")),
    CONSTRAINT "leads_numero_propio_check" CHECK (("numero_propio" > 0)),
    CONSTRAINT "leads_telefono_principal_check" CHECK (("telefono_principal" ~ '^[0-9]{7,15}$'::"text"))
);


ALTER TABLE "public"."leads" OWNER TO "postgres";


COMMENT ON TABLE "public"."leads" IS 'Prospectos y clientes. El teléfono principal es único entre leads vivos y sólo lo ve completo quien está en la cartera (leads_asesores): la app lee leads_vista y lead_ficha, no esta tabla. Se escribe sólo por RPC (crear_lead, lead_guardar, cambiar_telefono_lead). actualizado_en es la versión de edición: la mueve un cambio de nombre, tipo, origen, atributos, teléfono o papelera; un seguimiento, compartir o transferir no. Un lead sin asesores vigentes está en el LIMBO: invisible hasta que alguien lo adopta registrando su teléfono. Fijos: nombre, teléfono, tipo y origen; el resto son campos configurables (leads_campos) y viven en atributos.';



COMMENT ON COLUMN "public"."leads"."telefono_cc" IS 'El código de país del número, cuando es el de la empresa; nulo si el número vino con otro. El número completo está en telefono_principal.';



CREATE OR REPLACE FUNCTION "public"."_lead_mio"("p_lead" "uuid", "p_clave" "text" DEFAULT 'leads.editar'::"text", "p_bloquear" boolean DEFAULT true) RETURNS "public"."leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l public.leads;
begin
  perform public.assert_activo();
  if not public.puede_actuar_lead(p_lead, p_clave) then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  if p_bloquear then
    select * into l from public.leads x where x.id = p_lead and x.eliminado_en is null for update;
  else
    select * into l from public.leads x where x.id = p_lead and x.eliminado_en is null;
  end if;
  if not found then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  -- Quien esperaba el lock pudo perder el acceso mientras tanto (le quitaron la cartera, lo
  -- transfirieron): se vuelve a mirar ya con el lead bloqueado, sobre lo que quedó confirmado.
  if p_bloquear and not public.puede_actuar_lead(p_lead, p_clave) then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  return l;
end;
$$;


ALTER FUNCTION "public"."_lead_mio"("p_lead" "uuid", "p_clave" "text", "p_bloquear" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_mis_etiquetas"("p_lead" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(le.etiqueta_id order by le.etiqueta_id), '[]'::jsonb)
    from public.leads_etiquetas le join public.etiquetas e on e.id = le.etiqueta_id
   where le.lead_id = p_lead and e.usuario_id = (select auth.uid());
$$;


ALTER FUNCTION "public"."_lead_mis_etiquetas"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_motivo_de_bloqueo"("l" "public"."leads", "p_al_enviar" boolean) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.vehiculos v where v.lead_id = l.id and (not p_al_enviar or v.eliminado_en is null)) then
    if not p_al_enviar then
      return 'Tiene un vehículo vinculado: desvincúlalo antes de purgarlo.';
    end if;
    if exists (select 1 from public.vehiculos v where v.lead_id = l.id and v.eliminado_en is null
                and not public.puede_vehiculo(v.id, 'vehiculos.ver')) then
      return 'Tiene un vehículo vinculado que no ves: quien lo gestiona tiene que desvincularlo antes.';
    end if;
    return 'Tiene un vehículo vinculado: desvincúlalo en «Vehículos» antes de enviarlo.';
  end if;
  if not p_al_enviar then
    if exists (select 1 from public.pagos p where p.lead_id = l.id) then
      return 'Tiene pagos registrados.';
    end if;
    if exists (select 1 from public.accesos_portal a where a.lead_id = l.id and a.habilitado) then
      return 'Tiene el acceso al portal vigente.';
    end if;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."_lead_motivo_de_bloqueo"("l" "public"."leads", "p_al_enviar" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_motivo_de_restaurar"("l" "public"."leads") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  v := public._lead_verificar(l.telefono_principal, l.id);
  return case v ->> 'estado'
    when 'existe' then format('«%s»%s ya tiene este teléfono.', v ->> 'nombre',
      case when v ->> 'numero' is not null then ' (#' || (v ->> 'numero') || ')'
           when v ->> 'numero_propio' is not null then ' (tu n.º ' || (v ->> 'numero_propio') || ')'
           else '' end)
    when 'de_otro' then format('Ese teléfono ya lo tiene un lead de %s.', coalesce(v ->> 'dueno', 'otra persona'))
    when 'limbo' then 'Ese teléfono ya lo tiene un lead sin dueño.'
    else null end;
end;
$$;


ALTER FUNCTION "public"."_lead_motivo_de_restaurar"("l" "public"."leads") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_motivo_para_deshacer"("p_lead" "uuid", "p_yo" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l public.leads;
begin
  select * into l from public.leads x where x.id = p_lead;
  if not found or l.eliminado_en is not null then
    return 'papelera';
  end if;
  if not exists (select 1 from public.leads_asesores a
                  where a.lead_id = l.id and a.usuario_id = p_yo and a.tipo_acceso = 'dueno' and a.revocado_en is null) then
    return 'otra_persona';
  end if;
  if exists (select 1 from public.leads_asesores a where a.lead_id = l.id and a.usuario_id <> p_yo) then
    return 'compartido';
  end if;
  if l.actualizado_en is distinct from l.creado_en then
    return 'editado';
  end if;
  if exists (select 1 from public.seguimientos s where s.lead_id = l.id) then
    return 'seguimientos';
  end if;
  if exists (select 1 from public.recordatorios r where r.lead_id = l.id) then
    return 'recordatorios';
  end if;
  if exists (select 1 from public.leads_telefonos t where t.lead_id = l.id) then
    return 'telefonos';
  end if;
  if exists (select 1 from public.vehiculos v where v.lead_id = l.id)
     or exists (select 1 from public.vehiculos_interesados v where v.lead_id = l.id)
     or exists (select 1 from public.vehiculos_vinculos v where v.lead_id = l.id) then
    return 'vehiculos';
  end if;
  if exists (select 1 from public.oportunidades o where o.lead_id = l.id) then
    return 'oportunidades';
  end if;
  if exists (select 1 from public.accesos_portal a where a.lead_id = l.id) then
    return 'portal';
  end if;
  if exists (select 1 from public.cotizaciones c where c.lead_id = l.id)
     or exists (select 1 from public.pagos c where c.lead_id = l.id)
     or exists (select 1 from public.eventos c where c.lead_id = l.id)
     or exists (select 1 from public.tareas c where c.lead_id = l.id)
     or exists (select 1 from public.mensajes c where c.lead_id = l.id)
     or exists (select 1 from public.repuestos_proyectos c where c.lead_id = l.id)
     or exists (select 1 from public.web_testimonios c where c.lead_id = l.id)
     or exists (select 1 from public.solicitudes_contacto_web c where c.lead_id = l.id) then
    return 'otros';
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."_lead_motivo_para_deshacer"("p_lead" "uuid", "p_yo" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_numeros"("p_lead" "public"."leads", "p_ve" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'numero', case when p_ve then p_lead.numero end,
    'numero_propio', case when p_ve or p_lead.creado_por = (select auth.uid()) then p_lead.numero_propio end);
$$;


ALTER FUNCTION "public"."_lead_numeros"("p_lead" "public"."leads", "p_ve" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_numeros_de"("p_lead" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((select public._lead_numeros(l, public.tiene_permiso('leads.numero_global.ver'))
                     from public.leads l where l.id = p_lead), '{}'::jsonb);
$$;


ALTER FUNCTION "public"."_lead_numeros_de"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_para_mover"("p_lead" "uuid") RETURNS "public"."leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l public.leads;
begin
  perform public.assert_activo();
  if p_lead is null or not public.puede_lead(p_lead, 'leads.ver') then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  select * into l from public.leads x where x.id = p_lead and x.eliminado_en is null for update;
  if not found or not public.puede_lead(p_lead, 'leads.ver') then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  -- Compartir, transferir y quitar acceso deciden sobre el estado final: sin quien está en baja.
  perform public._lead_aplicar_bajas(l.id);
  select * into l from public.leads x where x.id = p_lead;
  return l;
end;
$$;


ALTER FUNCTION "public"."_lead_para_mover"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_telefonos_estado"("p_lead" "uuid", "p_resultado" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'resultado', p_resultado,
    'actualizado_en', l.actualizado_en,
    'telefono_cc', l.telefono_cc,
    'telefono', l.telefono_principal,
    'telefonos', coalesce((
      select jsonb_agg(jsonb_build_object('id', t.id, 'telefono', t.telefono, 'etiqueta', t.etiqueta,
                                          'creado_en', t.creado_en) order by t.creado_en, t.id)
        from public.leads_telefonos t where t.lead_id = l.id), '[]'::jsonb))
  from public.leads l where l.id = p_lead;
$$;


ALTER FUNCTION "public"."_lead_telefonos_estado"("p_lead" "uuid", "p_resultado" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_verificar"("p_tel" "text", "p_excluir" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l record; d record; a record;
  -- El permiso del número se pregunta sólo cuando hay un lead que nombrar («existe»): la papelera llama a esta función una vez
  -- por lead y casi nunca llega acá, y `tiene_permiso` cuesta ~0,25 ms.
  v_ve boolean;
  v_yo uuid := (select auth.uid());
begin
  select x.id, x.numero, x.numero_propio, x.creado_por, x.nombre into l
    from public.leads x
   where x.telefono_principal = p_tel and x.eliminado_en is null and x.id is distinct from p_excluir;
  if not found then
    select x.id, x.numero, x.numero_propio, x.creado_por, x.nombre into a
      from public.leads_telefonos t join public.leads x on x.id = t.lead_id
     where t.telefono = p_tel and x.eliminado_en is null and x.id is distinct from p_excluir
       and not public.lead_en_limbo(x.id)
     order by public.puede_lead(x.id, 'leads.ver') desc, public.en_cartera(x.id) desc, t.creado_en, t.id
     limit 1;
    if not found then
      return jsonb_build_object('estado', 'libre');
    end if;
    if public.puede_lead(a.id, 'leads.ver') then
      v_ve := public.tiene_permiso('leads.numero_global.ver');
      return jsonb_build_object('estado', 'libre', 'alterno', jsonb_build_object(
        'estado', 'existe', 'lead_id', a.id, 'numero', case when v_ve then a.numero end,
        'numero_propio', case when v_ve or a.creado_por = v_yo then a.numero_propio end, 'nombre', a.nombre,
        'es_mio', public.en_cartera(a.id)));
    end if;
    select p.nombre into d
      from public.leads_asesores la join public.perfiles p on p.id = la.usuario_id
     where la.lead_id = a.id and la.revocado_en is null and la.usuario_id <> all ((select public._bajas_en_curso())::uuid[])
     order by (la.tipo_acceso = 'dueno') desc, la.desde
     limit 1;
    return jsonb_build_object('estado', 'libre', 'alterno', jsonb_build_object('estado', 'de_otro', 'dueno', d.nombre));
  end if;
  if public.lead_en_limbo(l.id) then
    return jsonb_build_object('estado', 'limbo');
  end if;
  if public.puede_lead(l.id, 'leads.ver') then
    v_ve := public.tiene_permiso('leads.numero_global.ver');
    return jsonb_build_object('estado', 'existe', 'lead_id', l.id, 'numero', case when v_ve then l.numero end,
                              'numero_propio', case when v_ve or l.creado_por = v_yo then l.numero_propio end, 'nombre', l.nombre,
                              'es_mio', public.en_cartera(l.id));
  end if;
  select p.id, p.nombre into d
    from public.leads_asesores la join public.perfiles p on p.id = la.usuario_id
   where la.lead_id = l.id and la.revocado_en is null and la.usuario_id <> all ((select public._bajas_en_curso())::uuid[])
   order by (la.tipo_acceso = 'dueno') desc, la.desde
   limit 1;
  return jsonb_build_object('estado', 'de_otro', 'dueno', d.nombre, 'dueno_id', d.id);
end;
$$;


ALTER FUNCTION "public"."_lead_verificar"("p_tel" "text", "p_excluir" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_visible"("p_lead" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_activo();
  if p_lead is null or not public.puede_lead(p_lead, 'leads.ver') then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  return p_lead;
end;
$$;


ALTER FUNCTION "public"."_lead_visible"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_visible_para"("p_eliminado_en" timestamp with time zone, "p_cartera" "uuid"[], "p_alcance" "public"."alcance_permiso", "p_yo" "uuid", "p_fuera" "uuid"[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  select p_eliminado_en is null
     and not (p_cartera <@ p_fuera)
     and nullif(case p_alcance when 'todos' then true when 'propios' then p_yo = any (p_cartera) end, false) is not null
$$;


ALTER FUNCTION "public"."_lead_visible_para"("p_eliminado_en" timestamp with time zone, "p_cartera" "uuid"[], "p_alcance" "public"."alcance_permiso", "p_yo" "uuid", "p_fuera" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_lead_visible_para"("p_eliminado_en" timestamp with time zone, "p_cartera" "uuid"[], "p_alcance" "public"."alcance_permiso", "p_yo" "uuid", "p_fuera" "uuid"[]) IS 'La regla de quién ve un lead (9h; cierre 1): vivo, con alguien en la cartera que no está en baja (p_fuera = _bajas_en_curso()) y con «todos», o con «propios» y en la cartera. Se inlinea en la policy de leads; la usan también puede_lead() y atributos_lead(). La forma con nullif … is not null es para que el planificador la estime en ~1 (docs/DECISIONES.md, 9h).';



CREATE OR REPLACE FUNCTION "public"."_lead_vivo_en_mi_cartera"("p_lead" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from public.leads_asesores la join public.leads l on l.id = la.lead_id
                  where la.lead_id = p_lead and la.usuario_id = (select auth.uid()) and la.revocado_en is null and l.eliminado_en is null)
$$;


ALTER FUNCTION "public"."_lead_vivo_en_mi_cartera"("p_lead" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_lead_vivo_en_mi_cartera"("p_lead" "uuid") IS 'Si el lead está vivo y en la cartera vigente de quien llama. Es la mitad de la policy de oportunidades (la otra es que la oportunidad sea suya); se pregunta por fila para que el planificador pueda caminar oportunidades_tablero_idx y cortar (5a-6).';



CREATE OR REPLACE FUNCTION "public"."_leads_al_limbo_de"("p_usuario" "uuid", "p_tope" integer) RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select count(*)::int from (
    select 1 from public.leads_asesores a join public.leads l on l.id = a.lead_id
     where a.usuario_id = p_usuario and a.revocado_en is null and l.eliminado_en is null
       and not exists (select 1 from public.leads_asesores b
                        where b.lead_id = a.lead_id and b.usuario_id <> p_usuario and b.revocado_en is null
                          and b.usuario_id <> all ((select public._bajas_en_curso())::uuid[]))
     limit p_tope + 1
  ) x;
$$;


ALTER FUNCTION "public"."_leads_al_limbo_de"("p_usuario" "uuid", "p_tope" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_leads_candidatos_etiquetas"("p_filtros" "jsonb", "p_yo" "uuid") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  select coalesce(array(select e.id from public.etiquetas e
                         where e.usuario_id = p_yo
                           and e.id = any (array(select u::uuid from jsonb_array_elements_text(case when jsonb_typeof(p_filtros -> 'etiquetas') = 'array' then p_filtros -> 'etiquetas' else '[]'::jsonb end) u
                                                  where u ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'))), '{}'::uuid[])
$_$;


ALTER FUNCTION "public"."_leads_candidatos_etiquetas"("p_filtros" "jsonb", "p_yo" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_leads_candidatos_indexable"("p_filtros" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $_$
  select coalesce(nullif(p_filtros ->> 'texto', '') ~ '[[:alnum:]]{3}', false)
      or coalesce(jsonb_array_length(case when jsonb_typeof(p_filtros -> 'atributos') = 'array' then p_filtros -> 'atributos' end), 0) > 0
      or coalesce(jsonb_array_length(case when jsonb_typeof(p_filtros -> 'etiquetas') = 'array' then p_filtros -> 'etiquetas' end), 0) > 0
      or coalesce(jsonb_array_length(case when jsonb_typeof(p_filtros -> 'privados') = 'array' then p_filtros -> 'privados' end), 0) > 0
      or coalesce(p_filtros -> 'tachados' = 'true'::jsonb, false)
      or exists (select 1 from jsonb_array_elements(case when jsonb_typeof(p_filtros -> 'comparaciones') = 'array' then p_filtros -> 'comparaciones' else '[]'::jsonb end) e
                  where jsonb_typeof(e) = 'object' and jsonb_typeof(e -> 'clave') = 'string' and (e ->> 'clave') ~ '^[a-z][a-z0-9_]{1,40}$'
         and case e ->> 'tipo'
               when 'texto' then jsonb_typeof(e -> 'texto') = 'string' and (e ->> 'texto') ~ '[[:alnum:]]{3}'
               when 'rango_numero' then jsonb_typeof(e -> 'min') = 'number' or jsonb_typeof(e -> 'max') = 'number'
               when 'rango_texto' then jsonb_typeof(e -> 'desde') = 'string' or jsonb_typeof(e -> 'antes_de') = 'string'
               else false end)
      or exists (select 1 from jsonb_array_elements(case when jsonb_typeof(p_filtros -> 'comparaciones_privadas') = 'array' then p_filtros -> 'comparaciones_privadas' else '[]'::jsonb end) e
                  where jsonb_typeof(e) = 'object' and jsonb_typeof(e -> 'clave') = 'string' and (e ->> 'clave') ~ '^[a-z][a-z0-9_]{1,40}$'
         and case e ->> 'tipo'
               when 'texto' then jsonb_typeof(e -> 'texto') = 'string' and (e ->> 'texto') ~ '[[:alnum:]]{3}'
               when 'rango_numero' then jsonb_typeof(e -> 'min') = 'number' or jsonb_typeof(e -> 'max') = 'number'
               when 'rango_texto' then jsonb_typeof(e -> 'desde') = 'string' or jsonb_typeof(e -> 'antes_de') = 'string'
               else false end)
$_$;


ALTER FUNCTION "public"."_leads_candidatos_indexable"("p_filtros" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_leads_candidatos_recorrido"() RETURNS integer
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$ select 4000 $$;


ALTER FUNCTION "public"."_leads_candidatos_recorrido"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_leads_candidatos_sql"("p_etapa" "text", "p_filtros" "jsonb", "p_yo" "uuid", "p_alcance" "public"."alcance_permiso", "p_fuera" "uuid"[]) RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_k int := public._leads_candidatos_tope();
  v_s int := public._leads_candidatos_recorrido();
  v_texto text := nullif(p_filtros ->> 'texto', '');
  v_patron text;
  -- Un campo privado sólo lo tiene la cartera de quien llama (`atributos_lead()` no le entrega ese dato a nadie más): filtrar por uno es leer «míos», lo pida o no el cliente.
  v_con_privados boolean := coalesce(jsonb_array_length(case when jsonb_typeof(p_filtros -> 'privados') = 'array' then p_filtros -> 'privados' end), 0) > 0;
  -- Un texto o un rango sobre un campo privado también se lee sólo de la cartera de quien llama (`atributos_lead()` no le entrega ese dato a nadie más): cuenta sólo si el elemento es válido.
  v_con_comp_privadas boolean := exists (select 1 from jsonb_array_elements(case when jsonb_typeof(p_filtros -> 'comparaciones_privadas') = 'array' then p_filtros -> 'comparaciones_privadas' else '[]'::jsonb end) e
                                          where jsonb_typeof(e) = 'object' and jsonb_typeof(e -> 'clave') = 'string' and (e ->> 'clave') ~ '^[a-z][a-z0-9_]{1,40}$'
         and case e ->> 'tipo'
               when 'texto' then jsonb_typeof(e -> 'texto') = 'string' and (e ->> 'texto') ~ '[[:alnum:]]{3}'
               when 'rango_numero' then jsonb_typeof(e -> 'min') = 'number' or jsonb_typeof(e -> 'max') = 'number'
               when 'rango_texto' then jsonb_typeof(e -> 'desde') = 'string' or jsonb_typeof(e -> 'antes_de') = 'string'
               else false end);
  v_mios boolean := coalesce((p_filtros ->> 'mios')::boolean, false) or p_alcance = 'propios' or v_con_privados or v_con_comp_privadas;
  v_atras boolean := (p_filtros ->> 'sentido') = 'anterior';
  v_dir text := case when v_atras then 'asc' else 'desc' end;
  v_cmp text := case when v_atras then '>' else '<' end;
  v_en timestamptz := nullif(p_filtros #>> '{cursor,creado_en}', '')::timestamptz;
  v_id uuid := nullif(p_filtros #>> '{cursor,id}', '')::uuid;
  v_visible text;
  v_cursor_l text := 'true';
  v_cursor_la text := 'true';
  v_m text[] := '{}'::text[];
  v_con_etiquetas boolean := coalesce(jsonb_typeof(p_filtros -> 'etiquetas') = 'array', false);
  v_etiquetas uuid[] := public._leads_candidatos_etiquetas(p_filtros, p_yo);
  v_grupo jsonb; v_alt jsonb; v_alts text[];
  v_clave_de_comparaciones text; v_ref text; v_comp jsonb; v_hay_comparacion boolean := false;
  v_con_tachados boolean := coalesce(p_filtros -> 'tachados' = 'true'::jsonb, false);
  v_etapa text := p_etapa;
  -- `recorrido` es interno: `leads_candidatos()` lo usa para seguir un recorrido acotado (cuántas filas mirar, no más de 2,5 veces la ventana). Un valor que no es un entero cuenta como ausente.
  v_limite int := case when coalesce(p_filtros ->> 'recorrido', '') ~ '^[0-9]{1,7}$'
                       then least(greatest((p_filtros ->> 'recorrido')::int, 1), (v_s * 5) / 2) else v_s end;
begin
  -- Etiquetas pedidas y ninguna es de quien mira (una que nadie tiene, una ajena, un id que no existe): no hay candidatos, y no se recorre nada. Lo mismo que «ninguna»: nadie
  -- sabe, por el tiempo ni por lo que vuelve, si la etiqueta existe o es de otra persona.
  if v_con_etiquetas and cardinality(v_etiquetas) = 0 then
    return 'select ''{}''::uuid[], 0, null::uuid';
  end if;
  -- La segunda etapa sin nada que buscarle al índice es el mismo recorrido por el orden del listado, sin tope: por la cartera de quien mira o por `leads_listado_idx`.
  -- Con el GIN de la cartera era peor (Ana, 8.000 leads: 97 ms contra 43 de antes): cada lead de la cartera es una lectura al azar del heap, y el recorrido ordenado
  -- lee `leads` por su clave en ~2,5 µs.
  -- Quien ve «todos» no necesita el `lateral` ni en «míos»: su cartera es de un 40 % de la tabla, y el planificador camina `leads_listado_idx` con el filtro y corta en K + 1
  -- (la dueña, «míos» sin resultados: 133 ms hoy y con esta forma; con el `lateral`, 272).
  if p_etapa = 'indice' and v_mios and p_alcance = 'propios' and not public._leads_candidatos_indexable(p_filtros) then
    v_etapa := 'recorrer';
    v_limite := 2147483647;
  end if;
  v_visible := format('l.eliminado_en is null and l.cartera <> %L::uuid[] and public._lead_visible_para(l.eliminado_en, l.cartera, %L::public.alcance_permiso, %L::uuid, %L::uuid[])',
                      '{}', p_alcance, p_yo, p_fuera);
  if v_en is not null and v_id is not null then
    v_cursor_l := format('l.creado_en %s= %L and (l.creado_en %s %L or l.id %s %L)', v_cmp, v_en, v_cmp, v_en, v_cmp, v_id);
    v_cursor_la := format('la.lead_creado_en %s= %L and (la.lead_creado_en %s %L or la.lead_id %s %L)', v_cmp, v_en, v_cmp, v_en, v_cmp, v_id);
  end if;
  if v_texto is not null and p_etapa <> 'extra' then
    v_patron := public._lead_busqueda_patron(v_texto);
    -- Con un tramo de 3 letras o dígitos, el patrón entero va al índice trigram (sus trigramas se cruzan solos). Sin él el índice no tiene
    -- nada que buscar y recorrería la columna entera: `(nombre || '')` no es una columna indexada y el filtro queda para quien ya recorre.
    v_m := v_m || case when p_etapa = 'indice' and v_texto ~ '[[:alnum:]]{3}'
                       then format('l.nombre ilike %L', v_patron) else format('(l.nombre || %L) ilike %L', '', v_patron) end;
  end if;
  if jsonb_typeof(p_filtros -> 'tipos') = 'array' then
    v_m := v_m || format('l.tipo_lead_id = any (%L::uuid[])', array(select jsonb_array_elements_text(p_filtros -> 'tipos'))::uuid[]);
  end if;
  if jsonb_typeof(p_filtros -> 'origenes') = 'array' then
    v_m := v_m || format('l.origen_lead_id = any (%L::uuid[])', array(select jsonb_array_elements_text(p_filtros -> 'origenes'))::uuid[]);
  end if;
  if v_con_etiquetas then
    v_m := v_m || format('exists (select 1 from public.leads_etiquetas le where le.lead_id = l.id and le.etiqueta_id = any (%L::uuid[]))', v_etiquetas);
  end if;
  -- Sólo los tachados de quien llama (5a-34): la marca es suya, no del pedido.
  if v_con_tachados then
    v_m := v_m || format('exists (select 1 from public.leads_tachados t where t.lead_id = l.id and t.usuario_id = %L::uuid)', p_yo);
  end if;
  if jsonb_typeof(p_filtros -> 'atributos') = 'array' then
    for v_grupo in select * from jsonb_array_elements(p_filtros -> 'atributos') loop
      v_alts := '{}';
      for v_alt in select * from jsonb_array_elements(v_grupo) loop
        v_alts := v_alts || format('l.atributos_publicos @> %L::jsonb', v_alt);
      end loop;
      if cardinality(v_alts) > 0 then v_m := v_m || ('(' || array_to_string(v_alts, ' or ') || ')'); end if;
    end loop;
  end if;
  -- Un campo privado (5a-10): la misma forma que un público, sobre `atributos` (lo que `atributos_lead()` le daría a quien llama, porque es de su cartera) y sólo en su
  -- cartera (`v_mios`). Un grupo vacío o que no es un arreglo no filtra, como en un campo público.
  if v_con_privados then
    for v_grupo in select * from jsonb_array_elements(p_filtros -> 'privados') loop
      v_alts := '{}';
      for v_alt in select * from jsonb_array_elements(case when jsonb_typeof(v_grupo) = 'array' then v_grupo else '[]'::jsonb end) loop
        v_alts := v_alts || format('l.atributos @> %L::jsonb', v_alt);
      end loop;
      if cardinality(v_alts) > 0 then v_m := v_m || ('(' || array_to_string(v_alts, ' or ') || ')'); end if;
    end loop;
  end if;
  -- Un texto o un rango sobre un campo (4.03, 5a-9 y 5a-34): `comparaciones` sobre la copia de lo público y `comparaciones_privadas` sobre `atributos`, sólo de la cartera (`v_mios`). Lo mal formado se ignora.
  foreach v_clave_de_comparaciones in array array['comparaciones', 'comparaciones_privadas'] loop
    v_ref := case v_clave_de_comparaciones when 'comparaciones' then 'l.atributos_publicos' else 'l.atributos' end;
    for v_comp in select e from jsonb_array_elements(case when jsonb_typeof(p_filtros -> v_clave_de_comparaciones) = 'array' then p_filtros -> v_clave_de_comparaciones else '[]'::jsonb end) e loop
      continue when jsonb_typeof(v_comp) <> 'object' or jsonb_typeof(v_comp -> 'clave') <> 'string' or (v_comp ->> 'clave') !~ '^[a-z][a-z0-9_]{1,40}$';
      case v_comp ->> 'tipo'
        when 'texto' then
          if jsonb_typeof(v_comp -> 'texto') = 'string' and (v_comp ->> 'texto') ~ '[[:alnum:]]{3}' then
            v_m := v_m || format('(%s ->> %L) ilike %L', v_ref, v_comp ->> 'clave', public._lead_busqueda_patron(v_comp ->> 'texto'));
            v_hay_comparacion := true;
          end if;
        when 'rango_numero' then
          -- jsonb contra jsonb, como PostgREST con `->`: un valor de texto ordena antes que cualquier número.
          if jsonb_typeof(v_comp -> 'min') = 'number' then v_m := v_m || format('(%s -> %L) >= %L::jsonb', v_ref, v_comp ->> 'clave', v_comp -> 'min'); v_hay_comparacion := true; end if;
          if jsonb_typeof(v_comp -> 'max') = 'number' then v_m := v_m || format('(%s -> %L) <= %L::jsonb', v_ref, v_comp ->> 'clave', v_comp -> 'max'); v_hay_comparacion := true; end if;
        when 'rango_texto' then
          if jsonb_typeof(v_comp -> 'desde') = 'string' then v_m := v_m || format('(%s ->> %L) >= %L', v_ref, v_comp ->> 'clave', v_comp ->> 'desde'); v_hay_comparacion := true; end if;
          if jsonb_typeof(v_comp -> 'antes_de') = 'string' then v_m := v_m || format('(%s ->> %L) < %L', v_ref, v_comp ->> 'clave', v_comp ->> 'antes_de'); v_hay_comparacion := true; end if;
        else null;
      end case;
    end loop;
  end loop;
  -- El lead del número (`extra`): las mismas condiciones que la ventana, sin la del nombre. $1 los ids, $2 si esta ventana es la última, $3 y $4 hasta dónde llegó.
  if p_etapa = 'extra' then
    return format($q$select coalesce(array_agg(l.id), '{}'::uuid[]), count(*)::int, null::uuid from public.leads l
        where l.id = any ($1) and %s and %s %s %s and ($2 or (l.creado_en, l.id) %s ($3, $4))$q$,
      v_visible, v_cursor_l, case when v_mios then format('and l.cartera @> array[%L]::uuid[]', p_yo) else '' end,
      case when cardinality(v_m) > 0 then 'and ' || array_to_string(v_m, ' and ') else '' end, case when v_atras then '<=' else '>=' end);
  end if;
  if v_etapa = 'recorrer' then
    -- Hasta S filas visibles en el orden del listado, y de ellas las que cumplen. «Míos» y «propios» por la cartera de quien mira
    -- (`leads_asesores_listado_idx`, como `leads_cartera_vista`); «todos» por `leads_listado_idx`. Dice cuántas recorrió (menos de S = recorrió todo).
    if v_mios and v_limite = 2147483647 then
      -- Sin tope (un término sin nada que buscarle al índice): los primeros K + 1 que cumplen, **cortando al juntarlos**. Si la unión se agregara entera (el `array_agg … filter` de abajo), un
      -- término denso de 1 o 2 caracteres recorrería toda la cartera de la dueña (212 ms con 212.000 leads) en vez de parar en la primera página.
      return format($q$select coalesce(array_agg(w.id order by w.creado_en %s, w.id %s), '{}'::uuid[]), count(*)::int, null::uuid
          from (select x.lead_id as id, x.lead_creado_en as creado_en
                  from public.leads_asesores x
                  join lateral (select 1 from public.leads l where l.id = x.lead_id and %s and %s limit 1) l on true
                 where x.usuario_id = %L::uuid and x.revocado_en is null and %s
                 order by x.lead_creado_en %s, x.lead_id %s limit %s) w$q$,
        v_dir, v_dir, v_visible, coalesce(nullif(array_to_string(v_m, ' and '), ''), 'true'), p_yo, replace(replace(v_cursor_la, 'la.', 'x.'), 'x.lead_creado_en', 'x.lead_creado_en'),
        v_dir, v_dir, v_k + 1);
    end if;
    if v_mios then
      -- `lateral … limit 1` (el id es único, da lo mismo): sin la valla, el planificador aplana la unión y lee `leads` entera (un `Hash Join`, 24 ms con 62.000) en vez de buscar cada fila de la cartera por su clave.
      return format($q$select coalesce((array_agg(w.id order by w.creado_en %s, w.id %s) filter (where w.m))[1:%s], '{}'::uuid[]), count(*)::int,
                (array_agg(w.id order by w.creado_en %s, w.id %s))[count(*)::int]
          from (select x.lead_id as id, x.lead_creado_en as creado_en, l.m
                  from (select la.lead_id, la.lead_creado_en from public.leads_asesores la
                         where la.usuario_id = %L::uuid and la.revocado_en is null and %s
                         order by la.lead_creado_en %s, la.lead_id %s limit %s) x
                  left join lateral (select (%s) as m from public.leads l where l.id = x.lead_id and %s limit 1) l on true) w$q$,
        v_dir, v_dir, v_k + 1, v_dir, v_dir, p_yo, v_cursor_la, v_dir, v_dir, v_limite, coalesce(nullif(array_to_string(v_m, ' and '), ''), 'true'), v_visible);
    end if;
    return format($q$select coalesce((array_agg(w.id order by w.creado_en %s, w.id %s) filter (where w.m))[1:%s], '{}'::uuid[]), count(*)::int,
              (array_agg(w.id order by w.creado_en %s, w.id %s))[count(*)::int]
        from (select l.id, l.creado_en, (%s) as m from public.leads l where %s and %s
               order by l.creado_en %s, l.id %s limit %s) w$q$,
      v_dir, v_dir, v_k + 1, v_dir, v_dir, coalesce(nullif(array_to_string(v_m, ' and '), ''), 'true'), v_visible, v_cursor_l, v_dir, v_dir, v_limite);
  end if;
  -- Un texto o un rango con «míos»: el planificador no tiene estadísticas de `->`/`->>` y estima un rango de un lado en un tercio de la cartera, así que camina `leads_listado_idx` entero (Berta, 28.000
  -- leads, rango de número sin resultados: 88 ms y 172.737 buffers con 212.000). Con la valla (`materialized`) elige por la cartera: 14 ms y 925 buffers. Sólo con «míos»: la consulta de quien ve
  -- «todos» no tiene cartera que la acote.
  if v_mios and v_hay_comparacion then
    return format($q$with c as materialized (select l.id, l.creado_en from public.leads l where %s and %s %s %s)
        select coalesce(array_agg(x.id order by x.creado_en %s, x.id %s), '{}'::uuid[]), count(*)::int, null::uuid
          from (select * from c order by creado_en %s, id %s limit %s) x$q$,
      v_visible, v_cursor_l,
    case when v_mios then format('and l.cartera @> array[%L]::uuid[]', p_yo) else '' end
    -- Con etiquetas, el índice de `leads_etiquetas` (por `etiqueta_id`) dice cuáles son: sin esto el planificador camina `leads_listado_idx` y calcula las etiquetas de cada fila (368 ms).
    || case when v_con_etiquetas then format('and l.id = any (array(select le.lead_id from public.leads_etiquetas le where le.etiqueta_id = any (%L::uuid[])))', v_etiquetas) else '' end
    || case when v_con_tachados then format('and l.id = any (array(select t.lead_id from public.leads_tachados t where t.usuario_id = %L::uuid))', p_yo) else '' end,
    case when cardinality(v_m) > 0 then 'and ' || array_to_string(v_m, ' and ') else '' end,
      v_dir, v_dir, v_dir, v_dir, v_k + 1);
  end if;
  -- El índice: los primeros K + 1 que cumplen, en el orden. Con «míos» la cartera entra al índice y las filas ajenas no se leen.
  return format($q$select coalesce(array_agg(x.id order by x.creado_en %s, x.id %s), '{}'::uuid[]), count(*)::int, null::uuid
      from (select l.id, l.creado_en from public.leads l where %s and %s %s %s
             order by l.creado_en %s, l.id %s limit %s) x$q$,
    v_dir, v_dir, v_visible, v_cursor_l,
    case when v_mios then format('and l.cartera @> array[%L]::uuid[]', p_yo) else '' end
    -- Con etiquetas, el índice de `leads_etiquetas` (por `etiqueta_id`) dice cuáles son: sin esto el planificador camina `leads_listado_idx` y calcula las etiquetas de cada fila (368 ms).
    || case when v_con_etiquetas then format('and l.id = any (array(select le.lead_id from public.leads_etiquetas le where le.etiqueta_id = any (%L::uuid[])))', v_etiquetas) else '' end
    || case when v_con_tachados then format('and l.id = any (array(select t.lead_id from public.leads_tachados t where t.usuario_id = %L::uuid))', p_yo) else '' end,
    case when cardinality(v_m) > 0 then 'and ' || array_to_string(v_m, ' and ') else '' end,
    v_dir, v_dir, v_k + 1);
end $_$;


ALTER FUNCTION "public"."_leads_candidatos_sql"("p_etapa" "text", "p_filtros" "jsonb", "p_yo" "uuid", "p_alcance" "public"."alcance_permiso", "p_fuera" "uuid"[]) OWNER TO "postgres";


