    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "vehiculos_anio_check" CHECK ((("anio" IS NULL) OR (("anio" >= 1900) AND ("anio" <= 2100)))),
    CONSTRAINT "vehiculos_vin_check" CHECK ((("vin" IS NULL) OR ("vin" ~ '^[A-HJ-NPR-Z0-9]{11,17}$'::"text")))
);


ALTER TABLE "public"."vehiculos" OWNER TO "postgres";


COMMENT ON TABLE "public"."vehiculos" IS 'Inventario. De sólo lectura para la app: se escribe por vehiculo_crear() y vehiculo_guardar(). fase_id lo escriben cambiar_fase() y, sólo al nacer, vehiculo_crear() (entrada a la única fase inicial). publicado_web lo escribe vehiculo_vitrina(); que además se vea en la web lo decide interno.vitrina_vehiculos (fase activa que publica, origen activo y visible, integración web activa). Papelera: eliminado_en + lote; una policy RESTRICTIVE esconde lo borrado a todos.';



COMMENT ON COLUMN "public"."vehiculos"."estado_subasta" IS 'abierta | en_vivo | terminada | vendida. Lo deriva _vehiculo_subasta_desde() de apibara_raw: nadie lo escribe a mano.';



COMMENT ON COLUMN "public"."vehiculos"."apibara_raw" IS 'La última respuesta de apibara, entera. La copia la base desde apibara_consultas: nunca llega del navegador.';



COMMENT ON COLUMN "public"."vehiculos"."importado_apibara" IS 'Nació de una consulta a apibara (vehiculo_crear con p_consulta). No cambia nunca: la limpieza automática sólo mira a estos.';



CREATE OR REPLACE FUNCTION "public"."_limpieza_ancla"("v" "public"."vehiculos") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.vehiculos_conservados c where c.vehiculo_id = v.id) then return 'conservar'; end if;
  if v.lead_id is not null then return 'vinculo'; end if;
  if v.fase_id is not null and exists (select 1 from public.fases f where f.id = v.fase_id and not f.es_inicial) then
    return 'fase';
  end if;
  -- Cuentan todas las filas, también las borradas: la purga las llevaría en cascada.
  if exists (select 1 from public.documentos d where d.vehiculo_id = v.id) then return 'documentos'; end if;
  if exists (select 1 from public.gastos g where g.vehiculo_id = v.id) then return 'gastos'; end if;
  if exists (select 1 from public.pagos p where p.vehiculo_id = v.id) then return 'pagos'; end if;
  if v.publicado_web then return 'vitrina'; end if;
  -- Fase 4: una cotización final activa también es ancla ('cotizacion_final'); se suma acá.
  -- Lo demás que la papelera manual rechaza (comprobante, declaración aduanera, repuestos): la
  -- limpieza nunca intenta lo que la puerta de siempre cerraría.
  if public._vehiculo_motivo_de_bloqueo(v, true) is not null then return 'bloqueo'; end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."_limpieza_ancla"("v" "public"."vehiculos") OWNER TO "postgres";


