    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  return a * b;
exception when numeric_value_out_of_range then
  if abs(a) >= 1 then
    return case when (a > 0) = (b > 0) then 'Infinity'::float8 else '-Infinity'::float8 end;
  end if;
  return case when (a > 0) = (b > 0) then 0::float8 else '-0'::float8 end;
end;
$$;


