CREATE OR REPLACE FUNCTION "public"."_vehiculo_de_nota_json"("p_vehiculo" "uuid", "p_es_mio" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when p_vehiculo is null then jsonb_build_object('vehiculo', null, 'vehiculo_oculto', false)
    when public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then jsonb_build_object(
      'vehiculo', (select jsonb_build_object('id', v.id, 'titulo', v.titulo, 'numero', v.numero)
                     from public.vehiculos v where v.id = p_vehiculo),
      'vehiculo_oculto', false)
    else jsonb_build_object('vehiculo', null, 'vehiculo_oculto', coalesce(p_es_mio, false))
  end;
$$;


ALTER FUNCTION "public"."_vehiculo_de_nota_json"("p_vehiculo" "uuid", "p_es_mio" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_fase_de_entrada"("p_vehiculo" "uuid", "p_origen" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_iniciales uuid[]; f public.fases;
begin
  select array_agg(fa.id) into v_iniciales
  from public.fases fa join public.flujos fl on fl.id = fa.flujo_id
  where fl.origen_id = p_origen and fl.ambito = 'vehiculos' and fa.es_inicial and fa.activa;
  if coalesce(cardinality(v_iniciales), 0) <> 1 then return null; end if;
  select * into f from public.fases where id = v_iniciales[1];
  if f.nota_obligatoria then return null; end if;
  if exists (select 1 from public.evaluar_requisitos(p_vehiculo, null, f.id) e where e.bloqueante and not e.cumplido) then return null; end if;
  if exists (select 1 from public.fases_roles fr where fr.fase_id = f.id)
     and not exists (
       select 1 from public.fases_roles fr join public.usuarios_roles ur on ur.rol_id = fr.rol_id
       where fr.fase_id = f.id and ur.usuario_id = (select auth.uid())) then
    return null;
  end if;
  return f.id;
end;
$$;


ALTER FUNCTION "public"."_vehiculo_fase_de_entrada"("p_vehiculo" "uuid", "p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_motivo_de_bloqueo"("v" "public"."vehiculos", "p_al_enviar" boolean) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_fase public.fases;
begin
  if v.lead_id is not null then
    return 'Está vinculado a un lead. Quita el vínculo antes.';
  end if;
  if p_al_enviar and v.fase_id is not null then
    select * into v_fase from public.fases f where f.id = v.fase_id;
    if not v_fase.es_inicial then
      return format('Está en «%s». Sólo va a la papelera lo que sigue en su fase inicial.', v_fase.nombre);
    end if;
  end if;
  if exists (select 1 from public.comprobantes cp join public.cotizaciones c on c.id = cp.cotizacion_id where c.vehiculo_id = v.id) then
    return 'Tiene un comprobante emitido.';
  end if;
  if exists (select 1 from public.pagos p where p.vehiculo_id = v.id) or exists (select 1 from public.gastos g where g.vehiculo_id = v.id) then
    return 'Tiene pagos o gastos registrados.';
  end if;
  if exists (select 1 from public.declaraciones_vehiculos d where d.vehiculo_id = v.id and d.removido_en is null) then
    return 'Está en una declaración aduanera.';
  end if;
  if exists (select 1 from public.repuestos_proyectos r where r.vehiculo_id = v.id and r.eliminado_en is null) then
    return 'Tiene un proyecto de repuestos.';
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."_vehiculo_motivo_de_bloqueo"("v" "public"."vehiculos", "p_al_enviar" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_numero"("p_datos" "jsonb", "p_clave" "text", "p_nombre" "text", "p_minimo" numeric, "p_maximo" numeric, "p_entero" boolean) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v jsonb := p_datos -> p_clave; n numeric;
begin
  if v is null or v = 'null'::jsonb then return null; end if;
  if jsonb_typeof(v) <> 'number' then
    raise exception '% tiene que ser un número.', p_nombre using errcode = '22023', hint = p_clave;
  end if;
  n := (v #>> '{}')::numeric;
  if (p_entero and n <> trunc(n)) or n < p_minimo or n > p_maximo then
    raise exception '% tiene que estar entre % y %.', p_nombre, p_minimo, p_maximo using errcode = '22023', hint = p_clave;
  end if;
  return n;
end;
$$;


ALTER FUNCTION "public"."_vehiculo_numero"("p_datos" "jsonb", "p_clave" "text", "p_nombre" "text", "p_minimo" numeric, "p_maximo" numeric, "p_entero" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_para_nota"("p_vehiculo" "uuid", "p_hint" "text" DEFAULT 'vehiculo_id'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_vehiculo is null then
    return null;
  end if;
  if not public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then
    raise exception 'Ese vehículo no existe o no tienes acceso.' using errcode = '42501', hint = p_hint;
  end if;
  return p_vehiculo;
end;
$$;


