CREATE OR REPLACE FUNCTION "public"."_vehiculo_sin_repetidos"("v" "public"."vehiculos") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if v.vin is not null and exists (select 1 from public.vehiculos o where o.vin = v.vin and o.id <> v.id and o.eliminado_en is null) then
    raise exception 'Ya hay un vehículo con el VIN %.', v.vin using errcode = '23505', hint = 'vin';
  end if;
  if v.lote is not null and exists (
    select 1 from public.vehiculos o
    where o.origen_id = v.origen_id and o.lote = v.lote and o.plataforma is not distinct from v.plataforma
      and o.id <> v.id and o.eliminado_en is null) then
    raise exception 'Ya hay un vehículo con el lote % en este origen.', v.lote using errcode = '23505', hint = 'lote';
  end if;
end;
$$;


ALTER FUNCTION "public"."_vehiculo_sin_repetidos"("v" "public"."vehiculos") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_subasta_desde"("p_raw" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  a jsonb := coalesce(p_raw -> 'auction', '{}'::jsonb);
  v_en timestamptz; v_fin timestamptz; v_estado public.estado_subasta; v_sub text;
  v_resultado text := lower(coalesce(a ->> 'outcome_status', ''));
  v_state text := lower(coalesce(a ->> 'state', ''));
begin
  begin v_en := nullif(a ->> 'auction_at', '')::timestamptz; exception when others then v_en := null; end;
  begin v_fin := coalesce(nullif(a ->> 'timed_end_at', '')::timestamptz, nullif(a ->> 'auction_ended_at', '')::timestamptz);
  exception when others then v_fin := null; end;
  v_sub := lower(coalesce(a ->> 'lot_sub_status', ''));
  if v_resultado in ('sold', 'sold on approval') or coalesce((a ->> 'sold_buy_now')::boolean, false)
     or coalesce((a ->> 'sold_timed')::boolean, false) then
    v_estado := 'vendida';
  elsif v_resultado in ('not sold', 'removed') or coalesce((a ->> 'lot_removed')::boolean, false)
        or nullif(a ->> 'auction_ended_at', '') is not null or v_sub = 'ended'
        or (v_state <> '' and v_state not in ('open', 'live', 'future', 'pre_bid', 'upcoming')) then
    v_estado := 'terminada';
  elsif v_sub = 'live' or v_state = 'live' then
    v_estado := 'en_vivo';
  elsif v_en is not null or v_state <> '' then
    v_estado := 'abierta';
  end if;
  return jsonb_build_object('subasta_en', v_en, 'subasta_fin_en', v_fin, 'estado_subasta', v_estado);
end;
$$;


ALTER FUNCTION "public"."_vehiculo_subasta_desde"("p_raw" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_texto"("p_datos" "jsonb", "p_clave" "text", "p_nombre" "text", "p_largo" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v jsonb := p_datos -> p_clave; t text;
begin
  if v is null or v = 'null'::jsonb then return null; end if;
  if jsonb_typeof(v) <> 'string' then
    raise exception '% tiene que ser un texto.', p_nombre using errcode = '22023', hint = p_clave;
  end if;
  t := nullif(btrim(v #>> '{}'), '');
  if char_length(t) > p_largo then
    raise exception '% admite hasta % caracteres.', p_nombre, p_largo using errcode = '22023', hint = p_clave;
  end if;
  return t;
end;
$$;


ALTER FUNCTION "public"."_vehiculo_texto"("p_datos" "jsonb", "p_clave" "text", "p_nombre" "text", "p_largo" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculos_papelera_lote_json"("p_lote" "public"."lotes_papelera", "p_dias" integer, "p_yo" "uuid", "p_primeros" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', p_lote.id, 'actualizado_en', p_lote.actualizado_en, 'creado_en', p_lote.creado_en,
    'creado_por_nombre', (select nullif(btrim(p.nombre), '') from public.perfiles p where p.id = p_lote.creado_por),
    'es_mio', p_lote.creado_por is not distinct from p_yo,
    'es_limpieza', p_lote.es_limpieza,
    'purga_el', p_lote.creado_en + make_interval(days => p_dias),
    'enviados', coalesce((p_lote.resumen ->> 'cantidad')::int, 0),
    -- Un lote tiene a lo sumo 200; las fotos de un vehículo, a lo sumo 24 (`vehiculo_imagenes_tope`).
    'vehiculos', (
      select jsonb_agg(jsonb_build_object(
        'id', v.id, 'numero', v.numero, 'titulo', v.titulo, 'origen_id', v.origen_id,
        'miniatura', (select i.ruta_miniatura from public.vehiculos_imagenes i where i.vehiculo_id = v.id and i.es_portada),
        'fotos', (select count(*) from public.vehiculos_imagenes i where i.vehiculo_id = v.id),
        'motivo_de_bloqueo', public._vehiculo_motivo_de_bloqueo(v, false)) order by v.numero)
      from public.vehiculos v
      where v.id = any (array(select v0.id from public.vehiculos v0
                                where v0.lote_papelera_id = p_lote.id and v0.eliminado_en is not null
                                order by v0.numero limit p_primeros))),
    -- Cuántos quedan en la papelera, exacto: un lote tiene a lo sumo 200 (contado sobre 201 para la guarda de escala).
    'en_papelera', (select count(*) from (select 1 from public.vehiculos v where v.lote_papelera_id = p_lote.id
                                           and v.eliminado_en is not null limit 201) c));
$$;


ALTER FUNCTION "public"."_vehiculos_papelera_lote_json"("p_lote" "public"."lotes_papelera", "p_dias" integer, "p_yo" "uuid", "p_primeros" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."actividad_purgar"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d int; n int;
begin
  select actividad_dias into d from public.ajustes_empresa where id = 1;
  delete from public.actividad where creado_en < now() - make_interval(days => d);
  get diagnostics n = row_count;
  delete from public.eventos_web where creado_en < now() - interval '12 months';
  delete from public.visitados where visto_en < now() - interval '30 days';
  delete from public.notificaciones where creado_en < now() - interval '90 days' and (leida_en is not null or accionada_en is not null);
  return n;
end;
$$;


ALTER FUNCTION "public"."actividad_purgar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."alcance_de"("p_clave" "text", "p_origen" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."alcance_permiso"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when bool_or(rp.alcance = 'todos') then 'todos'::public.alcance_permiso
              when count(*) > 0 then 'propios'::public.alcance_permiso
         end
  from public.usuarios_roles ur
  join public.roles_permisos rp on rp.rol_id = ur.rol_id
  join public.perfiles p on p.id = ur.usuario_id
  where ur.usuario_id = (select auth.uid())
    and p.activo and not p.bloqueado
    and rp.permiso_clave = p_clave
    and (rp.origen_id is null or p_origen is null or rp.origen_id = p_origen);
$$;


ALTER FUNCTION "public"."alcance_de"("p_clave" "text", "p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."alertas_demora"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; n int := 0; dflt int;
begin
  select demora_dias_default into dflt from public.ajustes_empresa where id = 1;
  for r in
    select v.id, v.titulo, v.origen_id, f.nombre as fase, f.id as fase_id, coalesce(f.demora_dias, dflt) as dias, v.fase_desde
    from public.vehiculos v join public.fases f on f.id = v.fase_id join public.flujos fl on fl.id = f.flujo_id
    where v.eliminado_en is null and f.es_logistica and not f.es_final and coalesce(f.demora_dias, dflt) > 0
      and v.fase_desde < now() - make_interval(days => coalesce(f.demora_dias, dflt))
      and public.flujo_regla_activa(fl.id, 'alerta_demora')
  loop
    insert into public.notificaciones (usuario_id, tipo, titulo, cuerpo, referencia_tipo, referencia_id, ruta, requiere_accion)
    select distinct ur.usuario_id, 'demora_fase', 'Vehículo demorado en «' || r.fase || '»', r.titulo || ' lleva más de ' || r.dias || ' días', 'vehiculo', r.id, '/logistica/vehiculo/' || r.id, true
    from public.usuarios_roles ur join public.roles_permisos rp on rp.rol_id = ur.rol_id join public.perfiles p on p.id = ur.usuario_id
    where rp.permiso_clave = 'flujos.mover' and (rp.origen_id is null or rp.origen_id = r.origen_id) and p.activo and not p.bloqueado
    on conflict do nothing;
    n := n + 1;
  end loop;
  return n;
end;
$$;


ALTER FUNCTION "public"."alertas_demora"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apibara_consulta_guardar"("p_usuario" "uuid", "p_origen" "uuid", "p_raw" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  if p_usuario is null or not exists (select 1 from public.perfiles p where p.id = p_usuario) then
    raise exception 'Falta quién consultó.' using errcode = '22023';
  end if;
  if not exists (select 1 from public.origenes o where o.id = p_origen and o.tipo = 'subasta') then
    raise exception 'Sólo un origen de subasta consulta apibara.' using errcode = '22023';
  end if;
  perform public._vehiculo_apibara_valido(p_raw);
  insert into public.apibara_consultas (origen_id, creado_por, raw) values (p_origen, p_usuario, p_raw)
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."apibara_consulta_guardar"("p_usuario" "uuid", "p_origen" "uuid", "p_raw" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apibara_consulta_leer"("p_consulta" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_raw jsonb;
begin
  perform public.assert_activo();
  select c.raw into v_raw from public.apibara_consultas c
  where c.id = p_consulta and c.creado_por = (select auth.uid()) and c.creado_en >= now() - interval '24 hours';
  if not found then
    raise exception 'Esa consulta a la subasta ya no existe. Vuelve a consultar.' using errcode = '22023';
  end if;
  return v_raw;
end;
$$;


ALTER FUNCTION "public"."apibara_consulta_leer"("p_consulta" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apibara_consultas_purgar"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n integer; v_total integer := 0; i integer;
begin
  for i in 1..10 loop
    delete from public.apibara_consultas c
     where c.id in (select x.id from public.apibara_consultas x
                     where x.creado_en < now() - interval '48 hours' order by x.creado_en limit 10000);
    get diagnostics v_n = row_count;
    v_total := v_total + v_n;
    exit when v_n < 10000;
  end loop;
  return v_total;
end;
$$;


ALTER FUNCTION "public"."apibara_consultas_purgar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apibara_contexto"("p_origen" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_int public.integraciones; v_origen public.origenes; v_plat text[]; v_config text[]; v_uso boolean;
begin
  if (select auth.uid()) is null then
    return jsonb_build_object('aplica', false, 'puede_ver_uso', false);
  end if;
  v_uso := public.tiene_permiso('empresa.ajustes.gestionar');
  select * into v_int from public.integraciones i where i.clave = 'apibara';
  select * into v_origen from public.origenes o where o.id = p_origen;
  if p_origen is null or not found or v_origen.tipo <> 'subasta' then
    return jsonb_build_object('aplica', false, 'puede_ver_uso', v_uso);
  end if;
  select coalesce(array_agg(x), '{}') into v_config from jsonb_array_elements_text(coalesce(v_int.config -> 'plataformas', '[]'::jsonb)) x;
  v_plat := case when cardinality(v_origen.apibara_plataformas) = 0 then v_config
                 else (select coalesce(array_agg(p), '{}') from unnest(v_origen.apibara_plataformas) p where p = any (v_config)) end;
  return jsonb_build_object(
    'aplica', true,
    'usuario', (select auth.uid()),
    'activa', coalesce(v_int.activa, false) and v_int.secreto_guardado_en is not null,
    'endpoint', v_int.config ->> 'endpoint',
    'plataformas', to_jsonb(v_plat),
    'puede_crear', public.tiene_permiso('vehiculos.crear', p_origen),
    'puede_editar', public.tiene_permiso('vehiculos.editar', p_origen),
    'puede_ver_uso', v_uso);
end;
$$;


ALTER FUNCTION "public"."apibara_contexto"("p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_activo"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.es_usuario_activo() then
    raise exception 'Tu cuenta está bloqueada o dada de baja.' using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "public"."assert_activo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_permiso"("p_clave" "text", "p_origen" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_activo();
  if not public.tiene_permiso(p_clave, p_origen) then
    raise exception 'No tienes el permiso «%».', p_clave using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "public"."assert_permiso"("p_clave" "text", "p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."atributos_lead"("p_lead" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER COST 20000
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  -- Fuera de la consulta: llamada desde adentro, la función SQL se vuelve a planificar en cada llamada (265 µs contra 66).
  v_alcance public.alcance_permiso := public.alcance_de('leads.ver');
  v_fuera uuid[] := public._bajas_en_curso();
  v_atributos jsonb;
  v_cartera boolean;
  v_visible boolean;
begin
  select l.atributos, v_yo = any (l.cartera), public._lead_visible_para(l.eliminado_en, l.cartera, v_alcance, v_yo, v_fuera)
    into v_atributos, v_cartera, v_visible
  from public.leads l
  where l.id = p_lead;
  if not found or not v_visible then
    return null;
  end if;
  if v_cartera then
    return v_atributos;
  end if;
  return coalesce((
    select jsonb_object_agg(e.key, e.value)
    from jsonb_each(v_atributos) e
    where exists (select 1 from public.leads_campos c where c.clave = e.key and not c.solo_cartera)
  ), '{}'::jsonb);
end;
$$;


ALTER FUNCTION "public"."atributos_lead"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auditar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id text;
begin
  v_id := coalesce((to_jsonb(coalesce(new, old)) ->> 'id'), (to_jsonb(coalesce(new, old)) ->> 'usuario_id'));
  insert into public.actividad (accion, actor_id, tabla, registro_id, antes, despues)
  values (tg_table_name || '.' || lower(tg_op), (select auth.uid()), tg_table_name, v_id,
          case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) - 'clave_hash' - 'apibara_raw' end,
          case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) - 'clave_hash' - 'apibara_raw' end);
  return null;
end;
$$;


ALTER FUNCTION "public"."auditar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auth_crear_perfil"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  rol_dueno uuid;
  es_primero boolean;
begin
  select not exists (select 1 from public.perfiles) into es_primero;
  begin
    insert into public.perfiles (id, nombre, email, handle)
    values (new.id,
            coalesce(new.raw_user_meta_data ->> 'nombre', new.raw_user_meta_data ->> 'full_name', split_part(coalesce(new.email, ''), '@', 1)),
            new.email,
            null);
  exception when others then
    -- nunca bloquear el signup por un dato opcional
    insert into public.perfiles (id, nombre, email) values (new.id, '', new.email) on conflict do nothing;
  end;
  if es_primero then
    select id into rol_dueno from public.roles where clave = 'dueno';
    if rol_dueno is not null then
      insert into public.usuarios_roles (usuario_id, rol_id, es_principal) values (new.id, rol_dueno, true);
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."auth_crear_perfil"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auth_registro_permitido"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  abierto boolean;
  hay_otros boolean;
  invitado boolean;
begin
  select coalesce((u.raw_app_meta_data ->> 'invitado')::boolean, false) into invitado
  from auth.users u where u.id = new.id;
  -- La cuenta se creó y se borró en la misma transacción: no hay nada que permitir.
  if not found then return null; end if;
  select registro_abierto into abierto from public.ajustes_empresa where id = 1;
  -- A esta altura el perfil de esta cuenta ya existe: se cuentan los demás.
  select exists (select 1 from public.perfiles p where p.id <> new.id) into hay_otros;
  -- La primera cuenta siempre puede nacer (es la dueña). A las invitadas las crea
  -- `auth.admin.createUser` con `app_metadata.invitado = true`: esa marca sólo la escribe quien
  -- tiene la secret key, nunca un registro público.
  if hay_otros and not coalesce(abierto, false) and not invitado then
    raise exception 'El registro de cuentas nuevas está cerrado.' using errcode = '42501';
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."auth_registro_permitido"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auth_sellar_invitacion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if coalesce((new.raw_app_meta_data ->> 'invitado')::boolean, false) then
    update public.perfiles set invitado_en = now() where id = new.id and invitado_en is null;
  end if;
  return new;
end;
$$;


