CREATE OR REPLACE FUNCTION "public"."cambiar_fase"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_fase_destino" "uuid", "p_nota" "text" DEFAULT NULL::"text", "p_fase_esperada" "uuid" DEFAULT NULL::"uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare pre jsonb; v_actual uuid; v_flujo uuid; v_hist bigint; v_nota_oblig boolean;
begin
  perform public.assert_activo();
  pre := public.previsualizar_cambio_fase(p_vehiculo, p_repuesto, p_fase_destino);
  v_actual := (pre ->> 'fase_actual')::uuid;
  if p_fase_esperada is not null and v_actual is distinct from p_fase_esperada then
    raise exception 'Alguien movió esta unidad hace un momento. Recargá para ver la fase actual.' using errcode = 'PT409';
  end if;
  if not (pre ->> 'ok')::boolean then
    raise exception 'No se puede mover: %', array_to_string(array(select jsonb_array_elements_text(pre -> 'motivos')), ' ') using errcode = '23514';
  end if;
  v_nota_oblig := (pre ->> 'nota_obligatoria')::boolean or exists (select 1 from public.fases_transiciones t where t.de_fase_id = v_actual and t.a_fase_id = p_fase_destino and t.nota_obligatoria);
  if v_nota_oblig and coalesce(trim(p_nota), '') = '' then raise exception 'Esta fase pide una nota interna.' using errcode = '23514'; end if;
  select flujo_id into v_flujo from public.fases where id = p_fase_destino;
  -- lock de la fila para que dos cambios concurrentes se serialicen
  if p_vehiculo is not null then
    perform 1 from public.vehiculos where id = p_vehiculo for update;
    update public.vehiculos set fase_id = p_fase_destino, fase_desde = now() where id = p_vehiculo;
  else
    perform 1 from public.repuestos_items where id = p_repuesto for update;
    update public.repuestos_items set fase_id = p_fase_destino, fase_desde = now() where id = p_repuesto;
  end if;
  insert into public.historial_fases (flujo_id, vehiculo_id, repuesto_id, de_fase_id, a_fase_id, nota, usuario_id)
  values (v_flujo, p_vehiculo, p_repuesto, v_actual, p_fase_destino, nullif(trim(p_nota), ''), (select auth.uid())) returning id into v_hist;
  if nullif(trim(p_nota), '') is not null then
    insert into public.notas (vehiculo_id, repuesto_id, historial_fase_id, cuerpo, autor_id) values (p_vehiculo, p_repuesto, v_hist, trim(p_nota), (select auth.uid()));
  end if;
  perform public.registrar_actividad('unidad.fase_cambiada', case when p_vehiculo is not null then 'vehiculos' else 'repuestos_items' end, coalesce(p_vehiculo, p_repuesto)::text,
    jsonb_build_object('fase', v_actual), jsonb_build_object('fase', p_fase_destino, 'historial', v_hist));
  return v_hist;
end;
$$;


ALTER FUNCTION "public"."cambiar_fase"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_fase_destino" "uuid", "p_nota" "text", "p_fase_esperada" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cambiar_fase_lote"("p_vehiculos" "uuid"[], "p_fase_destino" "uuid", "p_nota" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v uuid; res jsonb := '[]'::jsonb; h bigint;
begin
  if coalesce(array_length(p_vehiculos, 1), 0) > 200 then raise exception 'Máximo 200 por lote.' using errcode = '22023'; end if;
  foreach v in array p_vehiculos loop
    begin
      h := public.cambiar_fase(v, null, p_fase_destino, p_nota, null);
      res := res || jsonb_build_object('vehiculo_id', v, 'ok', true, 'historial_id', h);
    exception when others then
      res := res || jsonb_build_object('vehiculo_id', v, 'ok', false, 'motivo', sqlerrm);
    end;
  end loop;
  return res;
end;
$$;


ALTER FUNCTION "public"."cambiar_fase_lote"("p_vehiculos" "uuid"[], "p_fase_destino" "uuid", "p_nota" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cambiar_telefono_lead"("p_lead" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cc" "text", "p_tel" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  l public.leads;
  v_cc text;
  v_cc_digitos text;
  v_tel text;
  v_verif jsonb;
  v_estado text;
begin
  l := public._lead_mio(p_lead, 'leads.editar', true);
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  v_cc := coalesce(nullif(btrim(p_cc), ''), (select e.telefono_cc from public.ajustes_empresa e where e.id = 1));
  v_tel := public.normalizar_telefono(v_cc, p_tel);
  -- El mismo número no es un conflicto aunque la versión sea otra: un reintento no choca consigo mismo.
  if v_tel = l.telefono_principal then
    return public._lead_telefonos_estado(l.id, 'sin_cambios');
  end if;
  v_verif := public._lead_verificar(v_tel, l.id);
  v_estado := v_verif ->> 'estado';
  if v_estado in ('existe', 'de_otro', 'limbo') then
    return jsonb_build_object('resultado', v_estado, 'verificacion', v_verif);
  end if;
  if l.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._lead_conflicto(l.id, l.actualizado_en);
  end if;

  v_cc_digitos := regexp_replace(coalesce(v_cc, ''), '\D', '', 'g');
  begin
    update public.leads x set
      telefono_cc = case when v_cc_digitos <> '' and v_tel like v_cc_digitos || '%' then '+' || v_cc_digitos end,
      telefono_principal = v_tel
    where x.id = l.id;
  exception when unique_violation then
    -- Otra persona tomó ese número justo ahora: se dice como valor, no como error.
    v_verif := public._lead_verificar(v_tel, l.id);
    v_estado := v_verif ->> 'estado';
    if v_estado in ('existe', 'de_otro', 'limbo') then
      return jsonb_build_object('resultado', v_estado, 'verificacion', v_verif);
    end if;
    raise exception 'Ese teléfono cambió mientras guardabas. Vuelve a intentarlo.' using errcode = 'PT409';
  end;

  delete from public.leads_telefonos t where t.lead_id = l.id and t.telefono = v_tel;
  insert into public.leads_telefonos (lead_id, telefono, etiqueta)
  values (l.id, l.telefono_principal, 'Anterior')
  on conflict (lead_id, telefono) do nothing;

  perform public.registrar_actividad('lead.telefono_cambiado', 'leads', l.id::text, null, null,
    jsonb_build_object('anterior', public.enmascarar_telefono(l.telefono_principal),
                       'nuevo', public.enmascarar_telefono(v_tel)));
  return public._lead_telefonos_estado(l.id, 'cambiado');
end;
$$;


ALTER FUNCTION "public"."cambiar_telefono_lead"("p_lead" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cc" "text", "p_tel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."categoria_crear"("p_origen" "uuid", "p_nombre" "text", "p_padre" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_nombre text; v_id uuid; v_version timestamptz;
begin
  perform public.assert_permiso('origenes.gestionar');
  perform 1 from public.origenes o where o.id = p_origen for update;
  if not found then raise exception 'Ese origen ya no existe.' using errcode = 'PT409'; end if;
  v_nombre := public._origen_nombre_valido(p_nombre, 'el nombre de la categoría', 60);
  if p_padre is not null then
    if not exists (select 1 from public.categorias x where x.id = p_padre and x.origen_id = p_origen) then
      raise exception 'La categoría padre ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
    end if;
    if exists (select 1 from public.categorias x where x.id = p_padre and x.padre_id is not null) then
      raise exception 'Las categorías tienen un solo nivel de anidado.';
    end if;
  end if;
  begin
    insert into public.categorias (origen_id, padre_id, nombre, orden)
    values (p_origen, p_padre, v_nombre,
            coalesce((select max(x.orden) + 10 from public.categorias x where x.origen_id = p_origen and x.padre_id is not distinct from p_padre), 10))
    returning id, actualizado_en into v_id, v_version;
  exception when unique_violation then
    raise exception 'Ya hay una categoría «%» en este lugar.', v_nombre using errcode = '23505';
  end;
  return jsonb_build_object('id', v_id, 'actualizado_en', v_version);
end;
$$;


ALTER FUNCTION "public"."categoria_crear"("p_origen" "uuid", "p_nombre" "text", "p_padre" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."categoria_eliminar"("p_categoria" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.categorias; v_vehiculos int; v_hijas int;
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into c from public.categorias x where x.id = p_categoria for update;
  if not found then raise exception 'Esa categoría ya no existe.' using errcode = 'PT409'; end if;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió esta categoría mientras la editabas.');
  select count(*) into v_hijas from public.categorias x where x.padre_id = p_categoria;
  if v_hijas > 0 then
    raise exception '«%» tiene subcategorías: elimínalas primero.', c.nombre using errcode = '23503';
  end if;
  select count(*) into v_vehiculos from public.vehiculos v where v.categoria_id = p_categoria;
  if v_vehiculos > 0 then
    raise exception '% % están en «%». Desactívala para conservarlos agrupados.',
      v_vehiculos, case when v_vehiculos = 1 then 'vehículo' else 'vehículos' end, c.nombre using errcode = '23503';
  end if;
  delete from public.categorias where id = p_categoria;
end;
$$;


ALTER FUNCTION "public"."categoria_eliminar"("p_categoria" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."categoria_guardar"("p_categoria" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text" DEFAULT NULL::"text", "p_activa" boolean DEFAULT NULL::boolean) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.categorias; v_nombre text; v_nueva timestamptz;
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into c from public.categorias x where x.id = p_categoria for update;
  if not found then raise exception 'Esa categoría ya no existe.' using errcode = 'PT409'; end if;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió esta categoría mientras la editabas.');
  v_nombre := case when p_nombre is null then c.nombre else public._origen_nombre_valido(p_nombre, 'el nombre de la categoría', 60) end;
  if p_activa is false and exists (select 1 from public.categorias x where x.padre_id = p_categoria and x.activa) then
    raise exception 'Desactiva primero las subcategorías de «%».', c.nombre;
  end if;
  begin
    update public.categorias x set nombre = v_nombre, activa = coalesce(p_activa, x.activa)
    where x.id = p_categoria returning x.actualizado_en into v_nueva;
  exception when unique_violation then
    raise exception 'Ya hay una categoría «%» en este lugar.', v_nombre using errcode = '23505';
  end;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."categoria_guardar"("p_categoria" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text", "p_activa" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."categoria_mover"("p_categoria" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid" DEFAULT NULL::"uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.categorias; v_nueva timestamptz;
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into c from public.categorias x where x.id = p_categoria;
  if not found then raise exception 'Esa categoría ya no existe.' using errcode = 'PT409'; end if;
  perform 1 from public.origenes o where o.id = c.origen_id for update;
  select * into c from public.categorias x where x.id = p_categoria for update;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió esta categoría mientras la editabas.');
  if p_despues_de is not null then
    if p_despues_de = p_categoria then raise exception 'Una categoría no puede ir después de sí misma.'; end if;
    if not exists (select 1 from public.categorias x where x.id = p_despues_de and x.origen_id = c.origen_id and x.padre_id is not distinct from c.padre_id) then
      raise exception 'Esa categoría ya no está en este lugar. Recarga e intenta de nuevo.' using errcode = 'PT409';
    end if;
  end if;

  update public.categorias x set orden = n.nuevo
  from (
    select id, (row_number() over (order by posicion, nombre) * 10)::smallint as nuevo from (
      select x.id, x.nombre,
        case
          when x.id = p_categoria then (case when p_despues_de is null then -1.0
                                             else (select y.orden from public.categorias y where y.id = p_despues_de) + 0.5 end)
          else x.orden::numeric
        end as posicion
      from public.categorias x where x.origen_id = c.origen_id and x.padre_id is not distinct from c.padre_id
    ) q
  ) n
  where x.id = n.id and x.orden <> n.nuevo;

  select x.actualizado_en into v_nueva from public.categorias x where x.id = p_categoria;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."categoria_mover"("p_categoria" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."categorias_con_uso"("p_origen" "uuid") RETURNS TABLE("categoria_id" "uuid", "vehiculos" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('origenes.gestionar');
  return query
  select k.id, (select count(*)::int from public.vehiculos v where v.categoria_id = k.id)
  from public.categorias k where k.origen_id = p_origen;
end;
$$;


ALTER FUNCTION "public"."categorias_con_uso"("p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claves_dato_requisito"("p_ambito" "public"."ambito_flujo") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case p_ambito
    when 'vehiculos' then array['vehiculo.vin', 'vehiculo.lead', 'vehiculo.cotizacion_final', 'transporte.naviera', 'transporte.contenedor', 'transporte.booking', 'transporte.zarpe', 'transporte.eta', 'transporte.arribo', 'aduana.declaracion', 'aduana.canal', 'aduana.tributos_pagados', 'pagos.umbral_pct', 'pagos.confirmado']
    else array['repuesto.tracking', 'repuesto.precio', 'proyecto.pago_cliente', 'transporte.contenedor', 'transporte.arribo'] end;
$$;


ALTER FUNCTION "public"."claves_dato_requisito"("p_ambito" "public"."ambito_flujo") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."codigo_dictable"("p_largo" integer DEFAULT 5) RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  alfabeto constant text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  b bytea := extensions.gen_random_bytes(p_largo);
  r text := '';
begin
  for i in 0..p_largo - 1 loop
    r := r || substr(alfabeto, 1 + get_byte(b, i) % 32, 1);
  end loop;
  return r;
end;
$$;


ALTER FUNCTION "public"."codigo_dictable"("p_largo" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cola_web_configurar"("p_usuario" "uuid", "p_habilitado" boolean, "p_max_abiertas" integer DEFAULT NULL::integer, "p_prioridad" smallint DEFAULT 0, "p_orden" smallint DEFAULT 0) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('web.cola.gestionar');
  insert into public.cola_web_asesores (usuario_id, habilitado, max_abiertas, prioridad, orden) values (p_usuario, p_habilitado, p_max_abiertas, p_prioridad, p_orden)
  on conflict (usuario_id) do update set habilitado = excluded.habilitado, max_abiertas = excluded.max_abiertas, prioridad = excluded.prioridad, orden = excluded.orden;
end;
$$;


ALTER FUNCTION "public"."cola_web_configurar"("p_usuario" "uuid", "p_habilitado" boolean, "p_max_abiertas" integer, "p_prioridad" smallint, "p_orden" smallint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comprobante_anular"("p_comprobante" "uuid", "p_motivo" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('cotizaciones.comprobantes.emitir');
  if coalesce(trim(p_motivo), '') = '' then raise exception 'Anular pide motivo.' using errcode = '22023'; end if;
  update public.comprobantes set anulado_por = (select auth.uid()), anulado_en = now(), motivo_anulacion = p_motivo where id = p_comprobante and anulado_en is null;
end;
$$;


ALTER FUNCTION "public"."comprobante_anular"("p_comprobante" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comprobante_emitir"("p_cotizacion" "uuid", "p_serie" "text", "p_datos" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_num bigint; v_id uuid;
begin
  perform public.assert_permiso('cotizaciones.comprobantes.emitir');
  if not exists (select 1 from public.cotizaciones where id = p_cotizacion and clase = 'final' and estado = 'activa' and eliminado_en is null) then
    raise exception 'Sólo se emite comprobante de una cotización final activa.' using errcode = '23514';
  end if;
  insert into public.comprobantes_contadores (serie, ultimo) values (p_serie, 0) on conflict do nothing;
  update public.comprobantes_contadores set ultimo = ultimo + 1 where serie = p_serie returning ultimo into v_num;
  insert into public.comprobantes (cotizacion_id, serie, numero, datos, emitido_por) values (p_cotizacion, p_serie, v_num, p_datos, (select auth.uid())) returning id into v_id;
  perform public.registrar_actividad('comprobante.emitido', 'comprobantes', v_id::text, null, jsonb_build_object('serie', p_serie, 'numero', v_num));
  return jsonb_build_object('id', v_id, 'serie', p_serie, 'numero', v_num);
end;
$$;


ALTER FUNCTION "public"."comprobante_emitir"("p_cotizacion" "uuid", "p_serie" "text", "p_datos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."concesion_dominada"("p_clave" "text", "p_origen" "uuid", "p_alcance" "public"."alcance_permiso") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from public.mis_permisos() m
    where m.clave = p_clave
      and (m.origen_id is null or m.origen_id = p_origen)
      and (m.alcance = 'todos' or p_alcance = 'propios')
  );
$$;


ALTER FUNCTION "public"."concesion_dominada"("p_clave" "text", "p_origen" "uuid", "p_alcance" "public"."alcance_permiso") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cotizacion_auditar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id text; v public.cotizaciones;
begin
  -- Un cambio sólo de los contadores de reportes o favoritos no es un cambio de la cotización.
  if tg_op = 'UPDATE' then
    v := new;
    v.actualizado_en := old.actualizado_en;
    v.reportes_count := old.reportes_count;
    v.favoritos_count := old.favoritos_count;
    if v is not distinct from old then return null; end if;
  end if;
  v_id := coalesce(to_jsonb(coalesce(new, old)) ->> 'id', '');
  insert into public.actividad (accion, actor_id, tabla, registro_id, antes, despues)
  values (tg_table_name || '.' || lower(tg_op), (select auth.uid()), tg_table_name, v_id,
          case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) - 'valores' - 'fuentes' - 'totales' - 'tipos_cambio' end,
          case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) - 'valores' - 'fuentes' - 'totales' - 'tipos_cambio' end);
  return null;
end;
$$;


ALTER FUNCTION "public"."cotizacion_auditar"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_auditar"() IS 'Trigger de auditoría de cotizaciones: la fila sin valores, fuentes, totales ni tipos_cambio (el snapshot lo ven las revisiones, recortado por nivel); no registra un cambio sólo de contadores. Pasos 4.10-1 y 4.10-3.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_contadores"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_table_name = 'cotizaciones_reportes' then
    update public.cotizaciones set reportes_count = (select count(*) from public.cotizaciones_reportes r where r.cotizacion_id = coalesce(new.cotizacion_id, old.cotizacion_id)) where id = coalesce(new.cotizacion_id, old.cotizacion_id);
  else
    update public.cotizaciones set favoritos_count = (select count(*) from public.cotizaciones_favoritos r where r.cotizacion_id = coalesce(new.cotizacion_id, old.cotizacion_id)) where id = coalesce(new.cotizacion_id, old.cotizacion_id);
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."cotizacion_contadores"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cotizacion_crear"("p_id" "uuid", "p_origen" "uuid", "p_lead" "uuid", "p_entradas" "jsonb", "p_abierta" "text", "p_vehiculo" "uuid" DEFAULT NULL::"uuid", "p_vehiculo_nuevo" "jsonb" DEFAULT NULL::"jsonb", "p_modo_tc" "text" DEFAULT NULL::"text", "p_clase" "public"."clase_cotizacion" DEFAULT 'preventa'::"public"."clase_cotizacion", "p_con_la_abierta" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  c_uuid constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_yo uuid := (select auth.uid());
  c public.cotizaciones;
  a record;
  v_formula uuid; v_uso uuid; v_vuelta int := 0; v_version int;
  v_ab_formula uuid; v_ab_en timestamptz;
  v_veh uuid := p_vehiculo;
  v_obligatorio boolean;
  v_modo jsonb;
  v_visibles text[]; v_editables jsonb; v_ctx jsonb;
  v_k text; v_opc text;
  v_res jsonb;
  v_total_base numeric;
  v_constraint text;
begin
  perform public.assert_activo();
  if p_id is null or p_origen is null then
    raise exception 'Faltan el identificador y el origen de la cotización.' using errcode = '22023';
  end if;
  perform public.assert_permiso('cotizaciones.crear', p_origen);
  -- Cotizar pide también ver: con sólo `crear` la hoja no tiene nada que mostrar (4-32). Después de `crear`: quien no cotiza ahí sigue recibiendo ese permiso en el error.
  perform public.assert_permiso('cotizaciones.ver', p_origen);
  -- D2: la hoja que se abrió. La firma la base (`cotizacion_hoja()`): trae la versión de la fórmula y la hora de la apertura, y no se puede inventar (4-27).
  if p_abierta is null then
    raise exception 'Falta la hoja que abriste: ábrela de nuevo.' using errcode = '22023', hint = 'abierta';
  end if;
  if p_clase = 'final' then
    perform public.assert_permiso('cotizaciones.final.gestionar', p_origen);
  end if;

  -- El intento: dos llamadas con el mismo id se ordenan acá (la segunda espera a que la primera confirme). Sólo una cotización MÍA, de este origen y viva se devuelve; un id ajeno
  -- no se mira (sería una sonda barata de ids): sigue y choca con la clave en el `insert`.
  perform pg_advisory_xact_lock(hashtextextended('cotizacion_crear:' || p_id::text, 0));
  select * into c from public.cotizaciones x where x.id = p_id and x.creado_por = v_yo and x.origen_id = p_origen and x.eliminado_en is null;
  if found then
    return public._cotizacion_respuesta(c) || jsonb_build_object('repetido', true);
  end if;

  -- La hoja abierta: su firma, su versión y su hora. Después del intento: un reintento vuelve lo guardado aunque la clave haya rotado o la hoja sea vieja.
  select l.formula_id, l.abierta_en into v_ab_formula, v_ab_en from public._cotizacion_abierta_leer(p_abierta, p_origen) l;

  -- El lead (comprobar, bloquear y volver a comprobar: nadie bloquea un lead que no ve).
  if p_lead is null then
    raise exception 'Elige el lead de la cotización.' using errcode = '22023', hint = 'lead';
  end if;
  if not public.puede_lead(p_lead, 'leads.ver') then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  perform 1 from public.leads l where l.id = p_lead and l.eliminado_en is null for key share;
  if not found or not public.puede_lead(p_lead, 'leads.ver') then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;

  -- El vehículo.
  if p_vehiculo is not null and p_vehiculo_nuevo is not null then
    raise exception 'Elige un vehículo del inventario o carga uno a mano, no los dos.' using errcode = '22023', hint = 'vehiculo';
  end if;
  select coalesce((select e.vehiculo_obligatorio_al_cotizar from public.ajustes_empresa e where e.id = 1), true) into v_obligatorio;
  if p_vehiculo_nuevo is not null then
    if jsonb_typeof(p_vehiculo_nuevo) <> 'object' or (p_vehiculo_nuevo - array['id', 'datos', 'consulta']) <> '{}'::jsonb
       or coalesce(p_vehiculo_nuevo ->> 'id', '') !~ c_uuid
       or (p_vehiculo_nuevo ? 'consulta' and coalesce(p_vehiculo_nuevo ->> 'consulta', '') !~ c_uuid)
       or (p_vehiculo_nuevo ? 'datos' and jsonb_typeof(p_vehiculo_nuevo -> 'datos') <> 'object') then
      raise exception 'El vehículo a mano lleva su identificador y sus datos.' using errcode = '22023', hint = 'vehiculo';
    end if;
    v_veh := (p_vehiculo_nuevo ->> 'id')::uuid;
    -- En su propia sentencia y antes de armar: `_cotizacion_armar()` es STABLE y ve lo que esta transacción ya escribió.
    perform public.vehiculo_crear(v_veh, p_origen, coalesce(p_vehiculo_nuevo -> 'datos', '{}'::jsonb), (p_vehiculo_nuevo ->> 'consulta')::uuid);
  elsif p_vehiculo is not null then
    perform public._cotizacion_vehiculo(p_vehiculo);
  elsif v_obligatorio or p_clase = 'final' then
    raise exception 'Elige el vehículo de la cotización.' using errcode = '22023', hint = 'vehiculo';
  end if;

  -- La fórmula publicada, `for share` por su id: si publicaron mientras esperábamos, READ COMMITTED descarta la fila que ya se archivó y se vuelve a leer la nueva.
  loop
    v_vuelta := v_vuelta + 1;
    select f.id into v_formula from public.formulas f where f.origen_id = p_origen and f.estado = 'publicada';
    if v_formula is null then
      perform public._motor_fallar('origen_sin_formula', null, 'Este origen no tiene una fórmula publicada.');
    end if;
    perform 1 from public.formulas f where f.id = v_formula and f.estado = 'publicada' for share;
    exit when found;
    if v_vuelta >= 3 then
      raise exception 'La fórmula cambió mientras cotizabas. Vuelve a intentarlo.' using errcode = 'PT409';
    end if;
  end loop;

  -- D2: la hoja se abrió sobre otra versión que la publicada. Sin «Guardar con la N», se avisa y no se guarda; con ella, se usa esa versión (publicada o archivada de este origen, y reciente).
  -- «Con la abierta» vale siempre dentro de las 24 h de la apertura (4-27): con la versión vigente sólo cambia algo si una tarifa cambió desde entonces, y la hora ya no la elige el cliente.
  v_uso := v_formula;
  if v_ab_formula is distinct from v_formula then
    select f.version into v_version from public.formulas f where f.id = v_formula;
    if not p_con_la_abierta then
      raise exception 'Se publicó la versión % de la hoja mientras cotizabas.', v_version using errcode = 'PT409', detail = 'desactualizada', hint = 'formula';
    end if;
    perform public._cotizacion_abierta(p_origen, v_ab_formula, v_ab_en);
    -- `for share`, como la publicada: archivada ya no cambia, pero el candado ordena esta alta con quien la borre (un origen que se elimina).
    perform 1 from public.formulas f where f.id = v_ab_formula and f.estado in ('publicada', 'archivada') for share;
    if not found then
      raise exception 'La versión de la hoja que abriste ya no está disponible: ábrela de nuevo.' using errcode = '22023', detail = 'abierta_no_disponible', hint = 'abierta';
    end if;
    v_uso := v_ab_formula;
  elsif p_con_la_abierta then
    perform public._cotizacion_abierta(p_origen, v_ab_formula, v_ab_en);
  end if;

  select * into a from public._cotizacion_armar(p_entradas, null, p_origen, v_veh, v_uso, v_ab_en, p_con_la_abierta);
  if a.formula_id is distinct from v_uso then
    raise exception 'La fórmula cambió mientras cotizabas. Vuelve a intentarlo.' using errcode = 'PT409';
  end if;
  -- D2: algún tipo de cambio que la hoja usa cambió desde que se abrió (ARMAR lo lee en una sola foto con los de hoy).
  if a.tc_cambiado and not p_con_la_abierta then
    raise exception 'Cambió un tipo de cambio de la hoja mientras cotizabas.' using errcode = 'PT409', detail = 'desactualizada', hint = 'tipo_cambio';
  end if;

  -- El modo de cambio: la clave de uno de los modos del diseño de esa versión, convertido a la forma del motor.
  v_modo := public._cotizacion_modo(a.formula_id, p_modo_tc);

  -- Lo que se ve y lo que se edita (una sola lectura de los niveles) y la revisión de lo tipeado, la misma que hace `cotizacion_evaluar()`.
  select coalesce(array_agg(n.nodo), '{}'), coalesce(jsonb_object_agg(n.nodo, true) filter (where n.editar), '{}'::jsonb)
    into v_visibles, v_editables from public._nodos_visibles(a.formula_id) n;
  v_ctx := public._cotizacion_contexto(v_visibles, a.definicion, a.visibilidad);
  perform public._cotizacion_tipeado(a.definicion, a.entrada, v_modo, v_ctx -> 'ok');

  -- Un override de un nodo que no se ve y uno de un nodo que no existe: el mismo error (el primero por id, en bytes).
  select min(k collate "C") into v_k from jsonb_object_keys(a.entrada -> 'overrides') k where not (v_ctx -> 'ok') ? k;
  if v_k is not null then
    raise exception 'La hoja no tiene un nodo «%».', v_k using errcode = '22023', detail = 'nodo_inexistente', hint = v_k;
  end if;
  -- Un valor para un nodo que se ve y no se edita.
  select min(t.k collate "C") into v_k
    from (select jsonb_object_keys(a.entrada -> 'inputs') as k
          union all select jsonb_object_keys(a.entrada -> 'banderas')
          union all select jsonb_object_keys(a.entrada -> 'overrides')) t
   where not v_editables ? t.k;
  if v_k is null and a.entrada ? 'variante' then
    select n ->> 'id' into v_opc from jsonb_array_elements(a.definicion -> 'nodos') n where n ->> 'tipo' = 'opcion' limit 1;
    if v_opc is not null and not v_editables ? v_opc then v_k := v_opc; end if;
  end if;
  if v_k is not null then
    raise exception 'No puedes cambiar «%» en esta hoja.', v_k using errcode = '42501', detail = 'nodo_no_editable', hint = v_k;
  end if;

  -- El cálculo, entero (los nodos que quien llama no ve toman el valor de la fórmula y se guardan igual).
  v_res := public.evaluar_formula(a.definicion, a.params, a.entrada, v_modo);
  -- Lo que el motor descarta de un nodo visible no se guarda en silencio; el total tiene que tener valor, caber y estar en la moneda base: `_cotizacion_guardable()`.
  v_total_base := public._cotizacion_guardable(v_res, a.entrada -> 'overrides');

  begin
    insert into public.cotizaciones (id, origen_id, lead_id, vehiculo_id, creado_por, clase, formula_id, valores, fuentes, tipos_cambio, totales, total_base, modo_tc)
    values (p_id, p_origen, p_lead, v_veh, v_yo, p_clase, a.formula_id, v_res -> 'valores', coalesce(v_res -> 'fuentes', '{}'::jsonb), a.entrada -> 'tipos_cambio',
            v_res -> 'totales', v_total_base, p_modo_tc)
    returning * into c;
  exception when unique_violation then
    get stacked diagnostics v_constraint = constraint_name;
    if v_constraint = 'cotizaciones_pkey' then
      raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
    elsif v_constraint = 'cotizaciones_final_por_vehiculo' then
      raise exception 'Este vehículo ya tiene una cotización final activa.' using errcode = '23505', hint = 'vehiculo';
    end if;
    raise;
  end;

  return public._cotizacion_respuesta(c, v_ctx) || jsonb_build_object('repetido', false);
end $_$;


ALTER FUNCTION "public"."cotizacion_crear"("p_id" "uuid", "p_origen" "uuid", "p_lead" "uuid", "p_entradas" "jsonb", "p_abierta" "text", "p_vehiculo" "uuid", "p_vehiculo_nuevo" "jsonb", "p_modo_tc" "text", "p_clase" "public"."clase_cotizacion", "p_con_la_abierta" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_crear"("p_id" "uuid", "p_origen" "uuid", "p_lead" "uuid", "p_entradas" "jsonb", "p_abierta" "text", "p_vehiculo" "uuid", "p_vehiculo_nuevo" "jsonb", "p_modo_tc" "text", "p_clase" "public"."clase_cotizacion", "p_con_la_abierta" boolean) IS 'Crea una cotización calculada en la base (evaluar_formula sobre la fórmula publicada del origen, o sobre la abierta con p_con_la_abierta) y devuelve lo que quien llama ve (_cotizacion_respuesta). Pide cotizaciones.crear y cotizaciones.ver. Idempotente por el id del intento. D2: PT409 desactualizada si la hoja que se abrió (p_abierta, la de cotizacion_hoja) ya no es la vigente. docs/COTIZADOR.md › «Quién escribe una cotización y cómo (4.10-2)», «Cómo se guarda (4.10-3)» y «La hoja abierta (4.13-3a)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_evaluar"("p_entradas" "jsonb", "p_cotizacion" "uuid" DEFAULT NULL::"uuid", "p_origen" "uuid" DEFAULT NULL::"uuid", "p_vehiculo" "uuid" DEFAULT NULL::"uuid", "p_modo" "jsonb" DEFAULT NULL::"jsonb", "p_modo_tc" "text" DEFAULT NULL::"text", "p_abierta" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  a record;
  v_visibles text[]; v_editables jsonb; v_ctx jsonb; v_ok jsonb;
  v_cfg boolean;
  v_ent jsonb; v_ov_ocultos text[];
  v_modo jsonb := p_modo;
  v_formula uuid; v_abierta_en timestamptz; v_publicada uuid;
  v_res jsonb;
begin
  -- La hoja abierta es de una hoja nueva (por origen): una cotización ya trae su versión y sus tipos de cambio.
  if p_abierta is not null and p_cotizacion is not null then
    perform public.assert_activo();
    perform public._motor_fallar('llamada_invalida', 'p_abierta', 'Una cotización ya trae su versión de la hoja y sus tipos de cambio.');
  end if;
  -- Por origen se cotiza con `crear` y `ver` del origen (4-32), antes de leer la hoja abierta y de mirar nada más.
  if p_cotizacion is null and p_origen is not null then
    perform public.assert_permiso('cotizaciones.crear', p_origen);
    perform public.assert_permiso('cotizaciones.ver', p_origen);
    if p_abierta is not null then
      select l.formula_id, l.abierta_en into v_formula, v_abierta_en from public._cotizacion_abierta_leer(p_abierta, p_origen) l;
      select f.id into v_publicada from public.formulas f where f.origen_id = p_origen and f.estado = 'publicada';       -- formulas_publicada_unica
      -- Una versión que ya no es la publicada: ¿todavía se podría guardar con ella? Si no, «abierta_vencida» y la hoja pide recargar.
      if v_formula is distinct from v_publicada then
        perform public._cotizacion_abierta(p_origen, v_formula, v_abierta_en);
      end if;
    end if;
  end if;
  -- Con la hoja abierta (4-28): la versión Y las tarifas de la apertura, lo mismo que verá D2 al guardar «con la N»; sin ella, la publicada y las tarifas de hoy.
  if v_formula is not null then
    select * into a from public._cotizacion_armar(p_entradas, p_cotizacion, p_origen, p_vehiculo, v_formula, v_abierta_en, true);
  else
    select * into a from public._cotizacion_armar(p_entradas, p_cotizacion, p_origen, p_vehiculo);
  end if;
  -- El modo por su clave (de esa versión) se vuelve la forma del motor antes de revisar lo tipeado.
  if p_modo_tc is not null then
    if p_modo is not null then
      perform public._motor_fallar('llamada_invalida', null, 'Pide el modo por su clave o completo, no los dos.');
    end if;
    v_modo := public._cotizacion_modo(a.formula_id, p_modo_tc);
  end if;
  v_cfg := public.tiene_permiso('cotizaciones.configurar', a.origen_id);
  select coalesce(array_agg(n.nodo), '{}'), coalesce(jsonb_object_agg(n.nodo, true) filter (where n.editar), '{}'::jsonb) into v_visibles, v_editables from public._nodos_visibles(a.formula_id) n;
  v_ctx := public._cotizacion_contexto(v_visibles, a.definicion, a.visibilidad);
  v_ok := v_ctx -> 'ok';
  v_ent := a.entrada;

  -- Lo tipeado (la forma, la fórmula inválida, inputs, banderas y variante que se ven): `_cotizacion_tipeado()`, la misma que revisa `cotizacion_crear()`.
  v_ov_ocultos := public._cotizacion_tipeado(a.definicion, a.entrada, v_modo, v_ok, p_cotizacion is not null);
  -- Un override de un nodo que existe y no se ve se quita antes del motor; vuelve como `nodo_inexistente` (abajo).
  if cardinality(v_ov_ocultos) > 0 then
    v_ent := jsonb_set(a.entrada, '{overrides}', (a.entrada -> 'overrides') - v_ov_ocultos);
  end if;
  -- Con una cotización, lo que quien llama no ve o no edita es lo GUARDADO (D7: guardar conserva lo que quien guarda no ve), y un valor distinto para un nodo que se ve y no se edita es un
  -- error. Con un origen no hay nada guardado.
  if p_cotizacion is not null then
    v_ent := public._cotizacion_conservar(a.definicion, v_ent, v_editables, a.guardado);
  end if;

  -- El modo: quien no configura sólo elige uno de los del diseño de esa versión (convertido a la forma del motor).
  if v_modo is not null and not v_cfg and not exists (
       select 1 from public.formulas f, jsonb_array_elements(coalesce(f.diseno -> 'cabecera' -> 'modos', '[]'::jsonb)) m
        where f.id = a.formula_id
          and jsonb_build_object('buckets', coalesce((select jsonb_object_agg(b ->> 'bucket', b ->> 'nodo') from jsonb_array_elements(m -> 'buckets') b), '{}'::jsonb),
                                 'total_en', m ->> 'total_en') = v_modo) then
    perform public._motor_fallar('modo_invalido', null, 'El modo no es uno de los que ofrece la hoja.');
  end if;

  v_res := public.evaluar_formula(a.definicion, a.params, v_ent, v_modo);
  v_res := public._cotizacion_recorte(v_res, v_ctx);

  -- Los overrides que se quitaron vuelven como inexistentes, entre los inexistentes y en su orden (por id, en bytes), después de los descartados de nodos que existen: es lo que el
  -- motor habría dicho si el nodo no estuviera. (Se agregan después de recortar: el recorte descarta, con razón, todo lo de un nodo que existe y no se ve.)
  if cardinality(v_ov_ocultos) > 0 then
    v_res := jsonb_set(v_res, '{overrides_descartados}', (
      select coalesce(jsonb_agg(x.e order by x.grupo, x.id collate "C", x.ord), '[]'::jsonb)
        from (select d.e, case when d.e ->> 'motivo' = 'nodo_inexistente' then 1 else 0 end as grupo, d.e ->> 'id' as id, d.ord
                from jsonb_array_elements(coalesce(v_res -> 'overrides_descartados', '[]'::jsonb)) with ordinality d (e, ord)
              union all
              select jsonb_build_object('id', k, 'motivo', 'nodo_inexistente'), 1, k, 0 from unnest(v_ov_ocultos) k) x));
  end if;
  return v_res;
end $$;


ALTER FUNCTION "public"."cotizacion_evaluar"("p_entradas" "jsonb", "p_cotizacion" "uuid", "p_origen" "uuid", "p_vehiculo" "uuid", "p_modo" "jsonb", "p_modo_tc" "text", "p_abierta" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_evaluar"("p_entradas" "jsonb", "p_cotizacion" "uuid", "p_origen" "uuid", "p_vehiculo" "uuid", "p_modo" "jsonb", "p_modo_tc" "text", "p_abierta" "text") IS 'Calcula una hoja y devuelve sólo lo que quien llama ve. El modo, completo (p_modo, el editor de la fórmula) o por su clave (p_modo_tc, la hoja), no los dos. Por origen pide cotizaciones.crear y cotizaciones.ver; con p_abierta (la de cotizacion_hoja) calcula con la versión y las tarifas de esa apertura. docs/COTIZADOR.md › «En la base (4.06-2)» y «La hoja abierta (4.13-3a)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_guardar"("p_id" "uuid", "p_intento" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_entradas" "jsonb", "p_modo_tc" "text", "p_titulo" "text", "p_notas" "text", "p_vehiculo" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  c0 record;
  c public.cotizaciones;
  r public.cotizaciones_revisiones;
  a record;
  v_ids uuid[]; v_v uuid; v_puede boolean;
  v_huella text;
  v_titulo text := nullif(btrim(p_titulo), '');
  v_notas text := nullif(btrim(p_notas), '');
  v_nuevo_veh uuid;
  v_modo jsonb;
  v_visibles text[]; v_editables jsonb; v_ctx jsonb;
  v_k text; v_ent jsonb; v_res jsonb; v_total_base numeric;
begin
  perform public.assert_activo();
  if p_id is null or p_intento is null then
    raise exception 'Faltan el identificador de la cotización y el del guardado.' using errcode = '22023';
  end if;

  -- Sin candado: sólo para saber qué vehículo hay que tomar antes que la cotización.
  select x.origen_id, x.clase, x.vehiculo_id into c0 from public.cotizaciones x where x.id = p_id and x.eliminado_en is null;
  if not found then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  -- (La condición va aparte: un `if` de plpgsql termina en el primer `then`, también en el de un `case`.)
  v_puede := case c0.clase
    when 'preventa' then public.puede_cotizacion(p_id, 'cotizaciones.editar')
    else public.puede_cotizacion(p_id, 'cotizaciones.ver') and public.tiene_permiso('cotizaciones.final.gestionar', c0.origen_id) end;
  if not v_puede then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;

  -- El vehículo: sólo cambia el de una preventa y nunca se quita. Lo que se pide se valida antes de tomar nada.
  if p_vehiculo is distinct from c0.vehiculo_id then
    if c0.clase = 'final' then
      raise exception 'Una cotización final no cambia de vehículo.' using errcode = '22023', hint = 'vehiculo';
    end if;
    if p_vehiculo is null then
      raise exception 'No se quita el vehículo de una cotización: elige otro.' using errcode = '22023', hint = 'vehiculo';
    end if;
    if not public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then
      raise exception 'No tienes acceso a este vehículo.' using errcode = '42501';
    end if;
    -- El actual y el nuevo, en orden de id (como la papelera por lotes), antes que la cotización.
    v_ids := array(select distinct x from unnest(array[c0.vehiculo_id, p_vehiculo]) x where x is not null order by 1);
    foreach v_v in array v_ids loop
      perform 1 from public.vehiculos v where v.id = v_v for key share;
    end loop;
    perform 1 from public.vehiculos v where v.id = p_vehiculo and v.eliminado_en is null;
    if not found or not public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then
      raise exception 'No tienes acceso a este vehículo.' using errcode = '42501';
    end if;
  end if;

  select * into c from public.cotizaciones x where x.id = p_id and x.eliminado_en is null for no key update;
  if not found then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  -- Si mientras esperaba le cambiaron el vehículo, los candados de arriba son de otro vehículo. No hace falta una comprobación aparte: cualquier cambio de la fila mueve su versión
  -- (`cotizacion_version()`), así que quien la tenía en pantalla recibe el conflicto de la versión más abajo, y el repetido de un intento ya guardado no mira candados.

  -- El permiso con la fila tomada (la clase o el alcance pudieron cambiar mientras esperaba).
  v_puede := case c.clase
    when 'preventa' then public.puede_cotizacion(p_id, 'cotizaciones.editar')
    else public.puede_cotizacion(p_id, 'cotizaciones.ver') and public.tiene_permiso('cotizaciones.final.gestionar', c.origen_id) end;
  if not v_puede then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;

  -- El intento: la misma persona con los mismos datos recibe lo guardado; otros datos, un error claro.
  v_huella := md5(jsonb_build_object('version', to_char(p_actualizado_en_esperado at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'), 'entradas', p_entradas, 'modo', p_modo_tc,
                                     'titulo', p_titulo, 'notas', p_notas, 'vehiculo', p_vehiculo)::text);
  select * into r from public.cotizaciones_revisiones x where x.cotizacion_id = p_id and x.intento = p_intento;
  if found then
    if r.usuario_id is distinct from v_yo or r.huella is distinct from v_huella then
      raise exception 'Ese guardado ya se hizo con otros datos. Recarga la cotización.' using errcode = '22023', detail = 'intento_reusado', hint = 'intento';
    end if;
    return public._cotizacion_respuesta(c) || jsonb_build_object('repetido', true);
  end if;

  -- La versión.
  if p_actualizado_en_esperado is null then
    perform public._exigir_version(c.actualizado_en, null, '');
  elsif c.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('cotizaciones', c.id, c.actualizado_en, 'esta cotización');
  end if;

  -- Título y notas.
  if char_length(v_titulo) > 120 then
    raise exception 'El título tiene como máximo 120 caracteres.' using errcode = '22023', hint = 'titulo';
  end if;
  if char_length(v_notas) > 2000 then
    raise exception 'Las notas tienen como máximo 2.000 caracteres.' using errcode = '22023', hint = 'notas';
  end if;

  -- SU versión de la fórmula, SUS tipos de cambio y (si cambia) el vehículo nuevo; el modo de esa versión.
  v_nuevo_veh := case when p_vehiculo is distinct from c.vehiculo_id then p_vehiculo end;
  select * into a from public._cotizacion_armar(p_entradas, p_id, null, v_nuevo_veh);
  v_modo := public._cotizacion_modo(c.formula_id, p_modo_tc);

  -- Lo que se ve y lo que se edita, y la revisión de lo tipeado (la misma de `cotizacion_evaluar()` y `cotizacion_crear()`).
  select coalesce(array_agg(n.nodo), '{}'), coalesce(jsonb_object_agg(n.nodo, true) filter (where n.editar), '{}'::jsonb) into v_visibles, v_editables from public._nodos_visibles(a.formula_id) n;
  v_ctx := public._cotizacion_contexto(v_visibles, a.definicion, a.visibilidad);
  perform public._cotizacion_tipeado(a.definicion, a.entrada, v_modo, v_ctx -> 'ok', true);
  -- Un override de un nodo que no se ve y uno de un nodo que no existe: el mismo error (el primero por id, en bytes).
  select min(k collate "C") into v_k from jsonb_object_keys(a.entrada -> 'overrides') k where not (v_ctx -> 'ok') ? k;
  if v_k is not null then
    raise exception 'La hoja no tiene un nodo «%».', v_k using errcode = '22023', detail = 'nodo_inexistente', hint = v_k;
  end if;

  -- Lo que no se edita sale de lo guardado; el motor; y lo guardable.
  v_ent := public._cotizacion_conservar(a.definicion, a.entrada, v_editables, a.guardado);
  v_res := public.evaluar_formula(a.definicion, a.params, v_ent, v_modo);
  v_total_base := public._cotizacion_guardable(v_res, a.entrada -> 'overrides');

  -- Nada cambió: no se escribe (ni la versión ni la revisión).
  if c.valores is not distinct from (v_res -> 'valores') and c.fuentes is not distinct from coalesce(v_res -> 'fuentes', '{}'::jsonb) and c.totales is not distinct from (v_res -> 'totales')
     and c.total_base = v_total_base and c.modo_tc is not distinct from p_modo_tc and c.titulo is not distinct from v_titulo and c.notas is not distinct from v_notas
     and c.vehiculo_id is not distinct from p_vehiculo then
    return public._cotizacion_respuesta(c, v_ctx) || jsonb_build_object('repetido', false);
  end if;

  perform set_config('importadora.guardado', jsonb_build_object('intento', p_intento, 'huella', v_huella)::text, true);
  update public.cotizaciones x
     set valores = v_res -> 'valores', fuentes = coalesce(v_res -> 'fuentes', '{}'::jsonb), totales = v_res -> 'totales', total_base = v_total_base,
         modo_tc = p_modo_tc, titulo = v_titulo, notas = v_notas, vehiculo_id = p_vehiculo
   where x.id = p_id
   returning * into c;
  perform set_config('importadora.guardado', '', true);

  return public._cotizacion_respuesta(c, v_ctx) || jsonb_build_object('repetido', false);
end $$;


ALTER FUNCTION "public"."cotizacion_guardar"("p_id" "uuid", "p_intento" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_entradas" "jsonb", "p_modo_tc" "text", "p_titulo" "text", "p_notas" "text", "p_vehiculo" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_guardar"("p_id" "uuid", "p_intento" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_entradas" "jsonb", "p_modo_tc" "text", "p_titulo" "text", "p_notas" "text", "p_vehiculo" "uuid") IS 'Guarda una cotización calculada en la base con SU versión de la fórmula y SUS tipos de cambio; lo que quien guarda no ve ni edita se conserva de lo guardado. Versión esperada (PT409), intento idempotente y devuelve lo que quien llama ve (_cotizacion_respuesta) con repetido. docs/COTIZADOR.md › «Cómo se guarda (4.10-3)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_hoja"("p_origen" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_nombre text; v_formula uuid; v_obligatorio boolean;
begin
  -- Los permisos, antes de mirar si el origen existe: con cualquier uuid, quien no cotiza ahí recibe el mismo 42501. Cotizar pide ver (4-32): con sólo `crear` la hoja iba vacía.
  perform public.assert_permiso('cotizaciones.crear', p_origen);
  perform public.assert_permiso('cotizaciones.ver', p_origen);
  if p_origen is null then
    raise exception 'Falta el origen.' using errcode = '22023';
  end if;
  select o.nombre into v_nombre from public.origenes o where o.id = p_origen;
  if v_nombre is null then
    raise exception 'No encontramos ese origen.' using errcode = '22023';
  end if;
  select x.id into v_formula from public.formulas x where x.origen_id = p_origen and x.estado = 'publicada';   -- formulas_publicada_unica
  if v_formula is null then
    return jsonb_build_object('estado', 'sin_publicar', 'origen', jsonb_build_object('id', p_origen, 'nombre', v_nombre),
                              'puede_configurar', public.tiene_permiso('cotizaciones.configurar', p_origen));
  end if;
  select a.vehiculo_obligatorio_al_cotizar into v_obligatorio from public.ajustes_empresa a where a.id = 1;
  -- `abierta` es lo que `cotizacion_crear()` y `cotizacion_evaluar()` reciben como `p_abierta`: la versión y la hora, firmadas para esta persona y este origen (4-27 y 4-28).
  return jsonb_build_object('estado', 'lista', 'origen', jsonb_build_object('id', p_origen, 'nombre', v_nombre),
                            'abierta_en', now(), 'abierta', public._cotizacion_abierta_firmar(p_origen, v_formula, now()), 'vehiculo_obligatorio', coalesce(v_obligatorio, true))
         || public._cotizacion_hoja(v_formula, p_origen);
end $$;


ALTER FUNCTION "public"."cotizacion_hoja"("p_origen" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_hoja"("p_origen" "uuid") IS 'La lectura que abre la hoja de cotizar de un origen: el diseño publicado recortado al nivel de quien llama, la versión de la fórmula, la hora y la hoja abierta firmada (p_abierta de cotizacion_crear y cotizacion_evaluar) o «sin_publicar». Con cotizaciones.crear y cotizaciones.ver del origen. docs/COTIZADOR.md › «La lectura que abre la hoja (4.13-1)» y «La hoja abierta (4.13-3a)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_leer"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.cotizaciones;
begin
  perform public.assert_activo();
  -- Una que no existe, una en la papelera y una que no se ve dan el mismo error.
  if not public.puede_cotizacion(p_id, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  select * into c from public.cotizaciones x where x.id = p_id;
  return public._cotizacion_respuesta(c);
end $$;


ALTER FUNCTION "public"."cotizacion_leer"("p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_leer"("p_id" "uuid") IS 'Una cotización con su snapshot recortado por nivel (_nodos_visibles de SU versión de la fórmula): siempre el total y lo aparte; los subtotales por grupo sólo si se ve el grupo entero. docs/COTIZADOR.md › «En la base (4.10-1)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_marcar_final"("p_cotizacion" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.cotizaciones; v_ids uuid[];
begin
  select * into c from public.cotizaciones where id = p_cotizacion and eliminado_en is null for no key update;
  if c.id is null then raise exception 'Cotización inexistente.' using errcode = '22023'; end if;
  perform public.assert_permiso('cotizaciones.final.gestionar', c.origen_id);
  if c.vehiculo_id is null then raise exception 'Una final exige vehículo vinculado.' using errcode = '23514'; end if;
  update public.cotizaciones set clase = 'preventa' where vehiculo_id = c.vehiculo_id and clase = 'final' and id <> c.id and eliminado_en is null;
  update public.cotizaciones set clase = 'final' where id = c.id;
  select array_agg(x.id) into v_ids
    from (select z.id from public.cotizaciones z where z.vehiculo_id = c.vehiculo_id and z.clase = 'preventa' and z.eliminado_en is null order by z.id for no key update) x;
  if v_ids is not null then perform public.papelera_enviar('cotizaciones', v_ids); end if;
  if c.lead_id is not null then update public.vehiculos set lead_id = c.lead_id where id = c.vehiculo_id and lead_id is null; end if;
  perform public.registrar_actividad('cotizacion.final', 'cotizaciones', c.id::text, null, jsonb_build_object('vehiculo', c.vehiculo_id, 'preventas_a_papelera', coalesce(array_length(v_ids, 1), 0)));
end;
$$;


ALTER FUNCTION "public"."cotizacion_marcar_final"("p_cotizacion" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cotizacion_moderar"("p_cotizacion" "uuid", "p_estado" "public"."estado_cotizacion") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('cotizaciones.moderar');
  update public.cotizaciones set estado = p_estado where id = p_cotizacion;
  perform public.registrar_actividad('cotizacion.moderada', 'cotizaciones', p_cotizacion::text, null, jsonb_build_object('estado', p_estado));
end;
$$;


ALTER FUNCTION "public"."cotizacion_moderar"("p_cotizacion" "uuid", "p_estado" "public"."estado_cotizacion") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cotizacion_revision"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  d jsonb := '{}'::jsonb; k text; a jsonb := to_jsonb(old); b jsonb := to_jsonb(new);
  v_de jsonb; v_a jsonb; v_g jsonb;
begin
  for k in select jsonb_object_keys(b) loop
    if k in ('actualizado_en', 'reportes_count', 'favoritos_count') or a -> k is not distinct from b -> k then continue; end if;
    if k in ('valores', 'fuentes') and jsonb_typeof(a -> k) = 'object' and jsonb_typeof(b -> k) = 'object' then
      -- Sólo los nodos que cambiaron (`-> clave` da el jsonb null de un valor nulo y el SQL null de una clave que no está).
      select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) into v_de from jsonb_each(a -> k) e where (b -> k) -> e.key is distinct from e.value;
      select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) into v_a from jsonb_each(b -> k) e where (a -> k) -> e.key is distinct from e.value;
      d := d || jsonb_build_object(k, jsonb_build_object('de', v_de, 'a', v_a));
    else
      d := d || jsonb_build_object(k, jsonb_build_object('de', a -> k, 'a', b -> k));
    end if;
  end loop;
  if d <> '{}'::jsonb then
    -- Lo deja `cotizacion_guardar()`; un ajuste que alguna vez se fijó en la sesión vuelve como texto vacío, no como nulo.
    v_g := nullif(current_setting('importadora.guardado', true), '')::jsonb;
    insert into public.cotizaciones_revisiones (cotizacion_id, usuario_id, diff, intento, huella)
    values (new.id, (select auth.uid()), d, (v_g ->> 'intento')::uuid, v_g ->> 'huella');
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."cotizacion_revision"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_revision"() IS 'Trigger de cotizaciones: una revisión por cambio, con el diff por columna ({de, a}; en valores y fuentes sólo los nodos que cambiaron) y el intento y la huella de cotizacion_guardar. docs/COTIZADOR.md › «Cómo se guarda (4.10-3)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_revisiones"("p_cotizacion" "uuid", "p_antes" bigint DEFAULT NULL::bigint, "p_tamano" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_formula uuid; v_def jsonb; v_vis jsonb; v_visibles text[]; v_ctx jsonb; v_legibles text[];
  v_n int := public._acotar_pagina(p_tamano, 20, 100);
  v_filas jsonb; v_hay boolean;
begin
  perform public.assert_activo();
  if not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  select c.formula_id into v_formula from public.cotizaciones c where c.id = p_cotizacion;
  select f.definicion, coalesce(f.visibilidad, '{}'::jsonb) into v_def, v_vis from public.formulas f where f.id = v_formula;
  v_visibles := coalesce(array(select n.nodo from public._nodos_visibles(v_formula) n), '{}');
  v_ctx := public._cotizacion_contexto(v_visibles, v_def, v_vis);
  v_legibles := coalesce(array(select a.attname::text from pg_attribute a
                                where a.attrelid = 'public.cotizaciones'::regclass and a.attnum > 0 and not a.attisdropped and has_column_privilege('authenticated', a.attrelid, a.attnum, 'select')), '{}');
  -- Una página y una de más, para saber si hay otra (cotizaciones_revisiones_cotizacion_idx). Con cursor y sin cursor son dos consultas.
  if p_antes is null then
    select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'usuario_id', r.usuario_id, 'creado_en', r.creado_en,
                                                 'diff', public._cotizacion_diff_recortado(r.diff, v_ctx, v_legibles)) order by r.id desc), '[]'::jsonb),
           coalesce(count(*) > v_n, false)
      into v_filas, v_hay
      from (select x.id, x.usuario_id, x.creado_en, x.diff from public.cotizaciones_revisiones x where x.cotizacion_id = p_cotizacion order by x.id desc limit v_n + 1) r;
  else
    select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'usuario_id', r.usuario_id, 'creado_en', r.creado_en,
                                                 'diff', public._cotizacion_diff_recortado(r.diff, v_ctx, v_legibles)) order by r.id desc), '[]'::jsonb),
           coalesce(count(*) > v_n, false)
      into v_filas, v_hay
      from (select x.id, x.usuario_id, x.creado_en, x.diff from public.cotizaciones_revisiones x where x.cotizacion_id = p_cotizacion and x.id < p_antes order by x.id desc limit v_n + 1) r;
  end if;
  -- La de más no viaja: es sólo el aviso de que hay otra página.
  if v_hay then v_filas := v_filas - v_n; end if;
  return jsonb_build_object('revisiones', v_filas, 'hay_mas', v_hay,
                            'siguiente', case when v_hay then (v_filas -> (jsonb_array_length(v_filas) - 1) ->> 'id')::bigint end);
end $$;


ALTER FUNCTION "public"."cotizacion_revisiones"("p_cotizacion" "uuid", "p_antes" bigint, "p_tamano" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_revisiones"("p_cotizacion" "uuid", "p_antes" bigint, "p_tamano" integer) IS 'Una página de revisiones de una cotización, de la más nueva a la más vieja, con cada diff recortado por nodo (la visibilidad de SU versión). El cursor es el id de la última de la página anterior. docs/COTIZADOR.md › «En la base (4.10-1)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_tabla"("p_tabla" "text", "p_cotizacion" "uuid" DEFAULT NULL::"uuid", "p_origen" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_formula uuid; v_origen uuid; v_def jsonb; v_par jsonb; v_diseno jsonb; v_cfg boolean; v_visibles text[]; v_vis jsonb;
  v_tabla public.tablas_referencia; v_congelada jsonb; v_permitidas jsonb; v_filas jsonb; v_cols jsonb; v_hay boolean := false; v_nodos jsonb;
begin
  perform public.assert_activo();
  if (p_cotizacion is null) = (p_origen is null) then
    raise exception 'Pide una cotización o un origen, y no los dos ni ninguno.' using errcode = '22023';
  end if;
  if p_cotizacion is not null then
    if not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
      raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
    end if;
    select c.formula_id, c.origen_id into v_formula, v_origen from public.cotizaciones c where c.id = p_cotizacion;
  else
    perform public.assert_permiso('cotizaciones.crear', p_origen);
    v_origen := p_origen;
    select f.id into v_formula from public.formulas f where f.origen_id = p_origen and f.estado = 'publicada';
  end if;
  select f.definicion, f.params, f.diseno into v_def, v_par, v_diseno from public.formulas f where f.id = v_formula;
  v_nodos := coalesce(v_def -> 'nodos', '[]'::jsonb);
  v_cfg := public.tiene_permiso('cotizaciones.configurar', v_origen);

  -- Las columnas que leen los nodos que quien llama ve (sin configurar). Si ninguno la lee, la tabla es como si no existiera.
  if not v_cfg then
    v_visibles := coalesce(array(select n.nodo from public._nodos_visibles(v_formula) n), '{}');
    v_vis := coalesce((select jsonb_object_agg(x, true) from unnest(v_visibles) x), '{}'::jsonb);
    select jsonb_object_agg(c, true) into v_permitidas from (
      select jsonb_object_keys(case when jsonb_typeof(n -> 'match') = 'object' then n -> 'match' else '{}'::jsonb end) as c
        from jsonb_array_elements(v_nodos) n where n ->> 'tipo' = 'tabla' and n ->> 'tabla' = p_tabla and v_vis ? (n ->> 'id')
      union select n ->> 'columna' from jsonb_array_elements(v_nodos) n where n ->> 'tabla' = p_tabla and v_vis ? (n ->> 'id') and (n ->> 'columna') is not null
      union select 'desde' from jsonb_array_elements(v_nodos) n where n ->> 'tabla' = p_tabla and v_vis ? (n ->> 'id') and (n ->> 'tipo' = 'tramo' or n ->> 'op' = 'depreciar')
      union select 'hasta' from jsonb_array_elements(v_nodos) n where n ->> 'tabla' = p_tabla and v_vis ? (n ->> 'id') and (n ->> 'tipo' = 'tramo' or n ->> 'op' = 'depreciar')
      -- La columna que etiqueta unos atajos que se ven.
      union select it ->> 'columna'
        from jsonb_array_elements(coalesce(v_diseno -> 'secciones', '[]'::jsonb)) s, jsonb_array_elements(coalesce(s -> 'items', '[]'::jsonb)) it,
             jsonb_array_elements(v_nodos) n
       where it ->> 'tipo' = 'atajos' and n ->> 'id' = it ->> 'nodo' and n ->> 'tabla' = p_tabla and v_vis ? (n ->> 'id') and (it ->> 'columna') is not null
    ) x where c is not null;
    if v_permitidas is null then
      raise exception 'No tienes acceso a esa tabla.' using errcode = '42501';
    end if;
  end if;

  -- La congelada de esa versión manda, aunque esté vacía; si no, la viva del origen y, si no hay una activa, la compartida.
  v_congelada := case when jsonb_typeof(v_par -> 'tablas') = 'object' and v_par -> 'tablas' ? p_tabla then v_par -> 'tablas' -> p_tabla end;
  select r.* into v_tabla from public.tablas_referencia r where r.origen_id = v_origen and r.clave = p_tabla and r.activa;
  if v_tabla.id is null then
    select r.* into v_tabla from public.tablas_referencia r where r.origen_id is null and r.clave = p_tabla and r.activa;
  end if;
  if v_congelada is null and v_tabla.id is null then
    raise exception 'No tienes acceso a esa tabla.' using errcode = '42501';
  end if;
  if v_congelada is not null and jsonb_typeof(v_congelada) = 'array' then
    v_filas := coalesce((select jsonb_agg(f.value order by f.ord) from jsonb_array_elements(v_congelada) with ordinality f (value, ord) where f.ord <= 1000), '[]'::jsonb);
    v_hay := jsonb_array_length(v_congelada) > 1000;
  else
    select coalesce(jsonb_agg(x.valores order by x.orden, x.id), '[]'::jsonb), coalesce(count(*) > 1000, false) into v_filas, v_hay
      from (select f.valores, f.orden, f.id from public.tablas_referencia_filas f where f.tabla_id = v_tabla.id and f.activa order by f.orden, f.id limit 1001) x;
    if v_hay then v_filas := v_filas - 1000; end if;
  end if;
  v_cols := coalesce(v_tabla.columnas, '[]'::jsonb);
  if not v_cfg then
    v_filas := coalesce((select jsonb_agg((select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) from jsonb_each(case when jsonb_typeof(f.value) = 'object' then f.value else '{}'::jsonb end) e where v_permitidas ? e.key) order by f.ord)
                           from jsonb_array_elements(v_filas) with ordinality f (value, ord)), '[]'::jsonb);
    v_cols := coalesce((select jsonb_agg(c order by o) from jsonb_array_elements(v_cols) with ordinality t (c, o) where v_permitidas ? (c ->> 'clave')), '[]'::jsonb);
  end if;
  return jsonb_build_object('clave', p_tabla, 'nombre', coalesce(v_tabla.nombre, p_tabla), 'columnas', v_cols, 'filas', v_filas, 'hay_mas', v_hay, 'congelada', v_congelada is not null);
end $$;


ALTER FUNCTION "public"."cotizacion_tabla"("p_tabla" "text", "p_cotizacion" "uuid", "p_origen" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_tabla"("p_tabla" "text", "p_cotizacion" "uuid", "p_origen" "uuid") IS 'Una tabla de referencia con sólo las columnas que leen los nodos que quien llama ve (la entera, a quien configura el origen); la copia congelada de la versión manda. Sin acceso, el error de una tabla que no existe. docs/COTIZADOR.md › «En la base (4.10-1)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_validar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' and not exists (select 1 from public.formulas f where f.id = new.formula_id and f.origen_id = new.origen_id and f.estado in ('publicada', 'archivada')) then
    raise exception 'La cotización debe nacer de una versión publicada de la fórmula de su origen.' using errcode = '23514';
  end if;
  if new.clase = 'final' and new.vehiculo_id is null then
    raise exception 'Una cotización final exige un vehículo vinculado.' using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."cotizacion_validar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cotizacion_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v public.cotizaciones;
begin
  -- Una copia de la fila nueva con lo que no cuenta puesto como estaba: si queda igual a la vieja, sólo cambiaron los contadores.
  v := new;
  v.actualizado_en := old.actualizado_en;
  v.reportes_count := old.reportes_count;
  v.favoritos_count := old.favoritos_count;
  if v is not distinct from old then
    new.actualizado_en := old.actualizado_en;
    return new;
  end if;
  new.actualizado_en := greatest(clock_timestamp(), old.actualizado_en + interval '1 microsecond');
  return new;
end $$;


ALTER FUNCTION "public"."cotizacion_version"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_version"() IS 'Trigger de cotizaciones: sella la versión (actualizado_en) con greatest(clock_timestamp(), anterior + 1 µs) y no la mueve si sólo cambian los contadores de reportes o favoritos. docs/COTIZADOR.md › «Cómo se guarda (4.10-3)».';



CREATE OR REPLACE FUNCTION "public"."crear_lead"("p_id" "uuid", "p_lead" "jsonb", "p_seguimiento" "jsonb" DEFAULT NULL::"jsonb", "p_recordatorio" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('leads.crear');
  return public._lead_crear(p_id, p_lead, p_seguimiento, p_recordatorio, true);
end;
$$;


ALTER FUNCTION "public"."crear_lead"("p_id" "uuid", "p_lead" "jsonb", "p_seguimiento" "jsonb", "p_recordatorio" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."documento_sellos"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    new.subido_por := (select auth.uid());
    if new.estado = 'aprobado' then new.estado := 'subido'; end if;   -- nadie nace aprobado
  elsif new.estado is distinct from old.estado and new.estado in ('aprobado', 'rechazado') then
    new.revisado_por := (select auth.uid()); new.revisado_en := now();
    if new.estado = 'rechazado' and coalesce(new.motivo_rechazo, '') = '' then
      raise exception 'Rechazar pide motivo.' using errcode = '23514';
    end if;
  end if;
  if new.visible_portal and not exists (select 1 from public.tipos_documento td where td.id = new.tipo_documento_id and td.visible_portal_permitido) then
    raise exception 'Este tipo de documento no puede mostrarse en el portal.' using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."documento_sellos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."embudo_crear"("p_id" "uuid", "p_nombre" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_yo uuid := public._embudos_puedo(); e public.embudos; v_nombre text;
begin
  if p_id is null then
    raise exception 'Falta el identificador del embudo.' using errcode = '22023';
  end if;
  perform public._embudos_candado(v_yo);
  select * into e from public.embudos x where x.id = p_id;
  if found then
    if e.usuario_id = v_yo then
      return jsonb_build_object('resultado', 'repetido', 'embudo', public._embudo_json(e.id));
    end if;
    raise exception 'No pudimos crear este embudo. Vuelve a intentarlo.' using errcode = '22023';
  end if;
  v_nombre := public._embudo_nombre(p_nombre);
  perform public._embudo_nombre_libre(v_yo, v_nombre, null);
  if (select count(*) from public.embudos x where x.usuario_id = v_yo) >= 10 then
    raise exception 'Puedes tener hasta 10 embudos. Elimina uno para crear otro.' using errcode = '22023', hint = 'nombre';
  end if;
  begin
    perform public._embudo_insertar(v_yo, p_id, v_nombre,
      not exists (select 1 from public.embudos x where x.usuario_id = v_yo),
      jsonb_build_array(
        jsonb_build_object('nombre', 'Nueva', 'color', 'gris', 'es_inicial', true),
        jsonb_build_object('nombre', 'Ganada', 'color', 'verde', 'es_ganada', true),
        jsonb_build_object('nombre', 'Perdida', 'color', 'rojo', 'es_perdida', true)));
  exception when unique_violation then
    raise exception 'No pudimos crear este embudo. Vuelve a intentarlo.' using errcode = '22023';
  end;
  return jsonb_build_object('resultado', 'creado', 'embudo', public._embudo_json(p_id));
end;
$$;


ALTER FUNCTION "public"."embudo_crear"("p_id" "uuid", "p_nombre" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."embudo_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_yo uuid := public._embudos_puedo(); e public.embudos; n int;
begin
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  perform public._embudos_candado(v_yo);
  select * into e from public.embudos x where x.id = p_id and x.usuario_id = v_yo for update;
  if not found then
    return jsonb_build_object('resultado', 'sin_cambios');
  end if;
  if e.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._embudo_conflicto(e.actualizado_en);
  end if;
  if e.es_default then
    raise exception 'El embudo por defecto no se elimina: puedes renombrarlo.' using errcode = '23514';
  end if;
  select count(*) into n from public.oportunidades o where o.embudo_id = e.id and o.eliminado_en is null;
  if n > 0 then
    raise exception 'Este embudo tiene % %. Elimínalas antes de eliminarlo.', n,
      case when n = 1 then 'oportunidad' else 'oportunidades' end using errcode = '23514';
  end if;
  delete from public.oportunidades o where o.embudo_id = e.id;
  delete from public.embudos x where x.id = e.id;
  return jsonb_build_object('resultado', 'eliminado');
end;
$$;


ALTER FUNCTION "public"."embudo_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."embudo_etapa_pagina"("p_etapa" "uuid", "p_antes_en" timestamp with time zone, "p_antes_id" "uuid", "p_tope" integer DEFAULT 50, "p_buscar" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_n int := public._acotar_pagina(p_tope, 50, 100);
  v_patron text := public._embudo_patron(p_buscar);
  v_tarjetas jsonb;
  v_hay_mas boolean;
begin
  if p_antes_en is null then
    select coalesce(jsonb_agg(p.tarjeta order by p.en desc, p.id desc) filter (where p.k <= v_n), '[]'::jsonb),
           coalesce(bool_or(p.k > v_n), false)
      into v_tarjetas, v_hay_mas
      from (select public._tarjeta_json(o, jsonb_build_object('id', l.id,
                                         'numero', (select g.numero from public.leads_numeros_globales g where g.lead_id = l.id),
                                         'numero_propio', (select np.numero from public.leads_numeros_propios np where np.lead_id = l.id),
                                         'nombre', l.nombre),
                                           case when v.id is not null then jsonb_build_object('id', v.id, 'titulo', v.titulo, 'numero', v.numero) end) as tarjeta,
                   o.ultima_actividad_en as en, o.id,
                   row_number() over (order by o.ultima_actividad_en desc, o.id desc) as k
              from public.oportunidades o
              join public.leads l on l.id = o.lead_id
              left join public.vehiculos v on v.id = o.vehiculo_id
             where o.etapa_id = p_etapa
               and (v_patron is null or o.titulo ilike v_patron or l.nombre ilike v_patron)
             order by o.ultima_actividad_en desc, o.id desc
             limit v_n + 1) p;
  else
    select coalesce(jsonb_agg(p.tarjeta order by p.en desc, p.id desc) filter (where p.k <= v_n), '[]'::jsonb),
           coalesce(bool_or(p.k > v_n), false)
      into v_tarjetas, v_hay_mas
      from (select public._tarjeta_json(o, jsonb_build_object('id', l.id,
                                         'numero', (select g.numero from public.leads_numeros_globales g where g.lead_id = l.id),
                                         'numero_propio', (select np.numero from public.leads_numeros_propios np where np.lead_id = l.id),
                                         'nombre', l.nombre),
                                           case when v.id is not null then jsonb_build_object('id', v.id, 'titulo', v.titulo, 'numero', v.numero) end) as tarjeta,
                   o.ultima_actividad_en as en, o.id,
                   row_number() over (order by o.ultima_actividad_en desc, o.id desc) as k
              from public.oportunidades o
              join public.leads l on l.id = o.lead_id
              left join public.vehiculos v on v.id = o.vehiculo_id
             where o.etapa_id = p_etapa
               and (o.ultima_actividad_en, o.id) < (p_antes_en, p_antes_id)
               and (v_patron is null or o.titulo ilike v_patron or l.nombre ilike v_patron)
             order by o.ultima_actividad_en desc, o.id desc
             limit v_n + 1) p;
  end if;
  return jsonb_build_object('tarjetas', v_tarjetas, 'hay_mas', v_hay_mas);
end;
$$;


ALTER FUNCTION "public"."embudo_etapa_pagina"("p_etapa" "uuid", "p_antes_en" timestamp with time zone, "p_antes_id" "uuid", "p_tope" integer, "p_buscar" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."embudo_etapas_guardar"("p_embudo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_etapas" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e public.embudos; x jsonb; v_n int; v_ids uuid[] := '{}'::uuid[]; v_id uuid; v_nombres text[] := '{}'::text[]; v_nombre text;
  v_color text; v_ini int := 0; v_gan int := 0; v_per int := 0; v_nueva jsonb := '[]'::jsonb;
  v_quitada record;
begin
  perform public._embudos_puedo();
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  e := public._embudo_mio(p_embudo);
  if p_etapas is null or jsonb_typeof(p_etapas) <> 'array' then
    raise exception 'Las etapas tienen que ser una lista.' using errcode = '22023', hint = 'etapas';
  end if;
  v_n := jsonb_array_length(p_etapas);
  if v_n < 3 or v_n > 12 then
    raise exception 'Un embudo lleva entre 3 y 12 etapas.' using errcode = '22023', hint = 'etapas';
  end if;
  for x in select * from jsonb_array_elements(p_etapas) loop
    if jsonb_typeof(x) <> 'object' then
      raise exception 'Una de las etapas llegó incompleta. Recarga e intenta de nuevo.' using errcode = '22023', hint = 'etapas';
    end if;
    v_id := coalesce(public._uuid_de(x -> 'id', 'etapas'), gen_random_uuid());
    if v_id = any (v_ids) then
      raise exception 'Una etapa llegó dos veces. Recarga e intenta de nuevo.' using errcode = '22023', hint = 'etapas';
    end if;
    if exists (select 1 from public.embudos_etapas s where s.id = v_id and s.embudo_id <> e.id) then
      raise exception 'Una de las etapas no es de este embudo. Recarga e intenta de nuevo.' using errcode = '22023', hint = 'etapas';
    end if;
    v_nombre := btrim(coalesce(x ->> 'nombre', ''));
    if char_length(v_nombre) not between 1 and 30 then
      raise exception 'El nombre de una etapa lleva entre 1 y 30 caracteres.' using errcode = '22023', hint = 'etapas';
    end if;
    if exists (select 1 from unnest(v_nombres) n where lower(n) = lower(v_nombre)) then
      raise exception 'Hay dos etapas «%». Cámbiale el nombre a una.', v_nombre using errcode = '22023', hint = 'etapas';
    end if;
    v_color := x ->> 'color';
    if v_color is null or not (v_color = any (public._etiquetas_paleta())) then
      raise exception 'Elige un color de la paleta para «%».', v_nombre using errcode = '22023', hint = 'etapas';
    end if;
    if coalesce((x ->> 'es_ganada')::boolean, false) and coalesce((x ->> 'es_perdida')::boolean, false) then
      raise exception '«%» no puede ser ganada y perdida a la vez.', v_nombre using errcode = '22023', hint = 'etapas';
    end if;
    if coalesce((x ->> 'es_inicial')::boolean, false)
       and (coalesce((x ->> 'es_ganada')::boolean, false) or coalesce((x ->> 'es_perdida')::boolean, false)) then
      raise exception 'La etapa inicial no puede ser ganada ni perdida.' using errcode = '22023', hint = 'etapas';
    end if;
    v_ini := v_ini + case when coalesce((x ->> 'es_inicial')::boolean, false) then 1 else 0 end;
    v_gan := v_gan + case when coalesce((x ->> 'es_ganada')::boolean, false) then 1 else 0 end;
    v_per := v_per + case when coalesce((x ->> 'es_perdida')::boolean, false) then 1 else 0 end;
    v_ids := v_ids || v_id;
    v_nombres := v_nombres || v_nombre;
    v_nueva := v_nueva || jsonb_build_object('id', v_id, 'nombre', v_nombre, 'color', v_color,
      'es_inicial', coalesce((x ->> 'es_inicial')::boolean, false),
      'es_ganada', coalesce((x ->> 'es_ganada')::boolean, false),
      'es_perdida', coalesce((x ->> 'es_perdida')::boolean, false));
  end loop;
  if v_ini <> 1 then
    raise exception 'Marca una sola etapa como inicial.' using errcode = '22023', hint = 'etapas';
  end if;
  if v_gan < 1 then
    raise exception 'Hace falta al menos una etapa ganada.' using errcode = '22023', hint = 'etapas';
  end if;
  if v_per < 1 then
    raise exception 'Hace falta al menos una etapa perdida.' using errcode = '22023', hint = 'etapas';
  end if;

  if v_nueva = (public._embudo_json(e.id) -> 'etapas') then
    return jsonb_build_object('resultado', 'sin_cambios', 'embudo', public._embudo_json(e.id));
  end if;
  if e.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._embudo_conflicto(e.actualizado_en);
  end if;

  -- Una etapa que se quita no puede llevarse oportunidades vivas; las eliminadas se van con ella.
  for v_quitada in
    select s.id, s.nombre, (select count(*) from public.oportunidades o where o.etapa_id = s.id and o.eliminado_en is null) as n
      from public.embudos_etapas s where s.embudo_id = e.id and not (s.id = any (v_ids)) order by s.orden, s.id
  loop
    if v_quitada.n > 0 then
      raise exception '«%» tiene % %: muévelas antes de quitarla.', v_quitada.nombre, v_quitada.n,
        case when v_quitada.n = 1 then 'oportunidad' else 'oportunidades' end using errcode = '23514', hint = 'etapas';
    end if;
    delete from public.oportunidades o where o.etapa_id = v_quitada.id;
    delete from public.embudos_etapas s where s.id = v_quitada.id;
  end loop;

  -- Primero se liberan los nombres y la inicial (un intercambio de nombres no choca con el índice),
  -- después se escriben los valores finales.
  update public.embudos_etapas s set nombre = '~' || left(replace(s.id::text, '-', ''), 29), es_inicial = false
   where s.embudo_id = e.id;
  insert into public.embudos_etapas (id, embudo_id, nombre, color, es_inicial, es_ganada, es_perdida, orden)
  select (y ->> 'id')::uuid, e.id, '~' || left(replace(y ->> 'id', '-', ''), 29), y ->> 'color', false, false, false, 0
    from jsonb_array_elements(v_nueva) y
   where not exists (select 1 from public.embudos_etapas s where s.id = (y ->> 'id')::uuid);
  update public.embudos_etapas s set
    nombre = y ->> 'nombre', color = y ->> 'color', es_inicial = (y ->> 'es_inicial')::boolean,
    es_ganada = (y ->> 'es_ganada')::boolean, es_perdida = (y ->> 'es_perdida')::boolean, orden = (o * 10)::smallint
    from jsonb_array_elements(v_nueva) with ordinality t (y, o)
   where s.id = (y ->> 'id')::uuid;

  -- Una etapa que cambió de final a abierta (o al revés) cambia el estado de lo que tiene.
  update public.oportunidades o set
    estado = case when s.es_ganada then 'ganada' when s.es_perdida then 'perdida' else 'abierta' end::public.estado_oportunidad,
    motivo_perdida = case when s.es_perdida then o.motivo_perdida end
    from public.embudos_etapas s
   where s.id = o.etapa_id and s.embudo_id = e.id and o.estado <> 'cancelada'
     and o.estado <> case when s.es_ganada then 'ganada' when s.es_perdida then 'perdida' else 'abierta' end::public.estado_oportunidad;

  update public.embudos x set actualizado_en = greatest(clock_timestamp(), e.actualizado_en + interval '1 microsecond')
   where x.id = e.id;
  return jsonb_build_object('resultado', 'guardado', 'embudo', public._embudo_json(e.id));
end;
$$;


ALTER FUNCTION "public"."embudo_etapas_guardar"("p_embudo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_etapas" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."embudo_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_yo uuid := public._embudos_puedo(); e public.embudos; v_nombre text;
begin
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  e := public._embudo_mio(p_id);
  v_nombre := public._embudo_nombre(p_nombre);
  if v_nombre = e.nombre then
    return jsonb_build_object('resultado', 'sin_cambios', 'embudo', public._embudo_json(e.id));
  end if;
  if e.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._embudo_conflicto(e.actualizado_en);
  end if;
  perform public._embudo_nombre_libre(v_yo, v_nombre, e.id);
  update public.embudos x set nombre = v_nombre,
    actualizado_en = greatest(clock_timestamp(), e.actualizado_en + interval '1 microsecond')
  where x.id = e.id;
  return jsonb_build_object('resultado', 'guardado', 'embudo', public._embudo_json(e.id));
end;
$$;


ALTER FUNCTION "public"."embudo_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."embudo_por_defecto"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_yo uuid := public._embudos_puedo(); v_habia boolean; v_id uuid;
begin
  v_habia := exists (select 1 from public.embudos e where e.usuario_id = v_yo);
  -- En su propia sentencia: `_embudo_json` (STABLE) lee con la foto de la sentencia que la llama, y
  -- en la misma no vería el embudo recién creado.
  v_id := public._embudo_defecto_de(v_yo);
  return jsonb_build_object('resultado', case when v_habia then 'existente' else 'creado' end,
    'embudo', public._embudo_json(v_id));
end;
$$;


ALTER FUNCTION "public"."embudo_por_defecto"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."embudo_tablero"("p_embudo" "uuid", "p_tope" integer DEFAULT 50, "p_tope_total" integer DEFAULT 500, "p_buscar" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with tope as (select public._acotar_pagina(p_tope, 50, 100) as n,
                       public._acotar_pagina(p_tope_total, 500, 1000) as total,
                       public._embudo_patron(p_buscar) as patron)
  select jsonb_build_object(
    'embudo', jsonb_build_object('id', x.id, 'nombre', x.nombre, 'es_default', x.es_default, 'actualizado_en', x.actualizado_en),
    'columnas', coalesce((
      select jsonb_agg(jsonb_build_object(
        'etapa', jsonb_build_object('id', s.id, 'nombre', s.nombre, 'color', s.color,
                   'es_inicial', s.es_inicial, 'es_ganada', s.es_ganada, 'es_perdida', s.es_perdida),
        'total', least(c.leidas, (select total from tope)),
        'total_hay_mas', c.leidas > (select total from tope),
        'hay_mas', c.leidas > (select n from tope),
        'tarjetas', coalesce((
          select jsonb_agg(t.tarjeta order by t.en desc, t.id desc)
            from (select public._tarjeta_json(o, jsonb_build_object('id', l.id,
                                         'numero', (select g.numero from public.leads_numeros_globales g where g.lead_id = l.id),
                                         'numero_propio', (select np.numero from public.leads_numeros_propios np where np.lead_id = l.id),
                                         'nombre', l.nombre),
                                         case when v.id is not null then jsonb_build_object('id', v.id, 'titulo', v.titulo, 'numero', v.numero) end) as tarjeta, o.ultima_actividad_en as en, o.id
                    from public.oportunidades o
                    join public.leads l on l.id = o.lead_id
                    left join public.vehiculos v on v.id = o.vehiculo_id
                   where o.etapa_id = s.id
                     and ((select patron from tope) is null
                          or o.titulo ilike (select patron from tope) or l.nombre ilike (select patron from tope))
                   order by o.ultima_actividad_en desc, o.id desc
                   limit (select n from tope)) t), '[]'::jsonb))
        order by s.orden, s.id)
      from public.embudos_etapas s
      cross join lateral (select count(*)::int as leidas
                            from (select 1 from public.oportunidades o2 join public.leads l2 on l2.id = o2.lead_id
                                   where o2.etapa_id = s.id
                                     and ((select patron from tope) is null
                                          or o2.titulo ilike (select patron from tope) or l2.nombre ilike (select patron from tope))
                                  limit (select total from tope) + 1) q) c
      where s.embudo_id = x.id), '[]'::jsonb))
  from public.embudos x where x.id = p_embudo;
$$;


ALTER FUNCTION "public"."embudo_tablero"("p_embudo" "uuid", "p_tope" integer, "p_tope_total" integer, "p_buscar" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."empresa_con_datos_cargados"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from public.vehiculos)
      or exists (select 1 from public.oportunidades o where o.monto_estimado is not null)
      or exists (select 1 from public.cotizaciones)
      or exists (select 1 from public.gastos)
      or exists (select 1 from public.pagos)
      or exists (select 1 from public.repuestos_compras)
      or exists (select 1 from public.repuestos_cotizaciones);
$$;


ALTER FUNCTION "public"."empresa_con_datos_cargados"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."empresa_guardar_ajustes"("p_cambios" "jsonb", "p_actualizado_en_esperado" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v public.ajustes_empresa;
  v_clave text;
  v_nueva timestamptz;
  v_editables constant text[] := array['nombre', 'razon_social', 'nit', 'direccion', 'ciudad', 'pais', 'telefono', 'whatsapp', 'email',
    'logo_ruta', 'color_acento', 'iconos', 'locale', 'zona_horaria', 'moneda_base', 'registro_abierto', 'papelera_dias', 'actividad_dias',
    'limpieza_automatica', 'limpieza_dias_gracia', 'telefono_cc'];
  v_obligatorias constant text[] := array['nombre', 'pais', 'locale', 'zona_horaria', 'moneda_base', 'registro_abierto', 'papelera_dias', 'actividad_dias',
    'limpieza_automatica', 'limpieza_dias_gracia'];
begin
  perform public.assert_permiso('empresa.ajustes.gestionar');
  if p_cambios is null or jsonb_typeof(p_cambios) <> 'object' then
    raise exception 'Faltan los cambios a guardar.';
  end if;
  for v_clave in select jsonb_object_keys(p_cambios) loop
    if not (v_clave = any (v_editables)) then
      raise exception 'El dato «%» no se cambia desde los ajustes de la empresa.', v_clave;
    end if;
    if v_clave = any (v_obligatorias) and nullif(btrim(p_cambios ->> v_clave), '') is null then
      raise exception 'El dato «%» no puede quedar vacío.', v_clave;
    end if;
  end loop;

  select * into v from public.ajustes_empresa where id = 1 for update;
  perform public._exigir_version(v.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió los ajustes de la empresa mientras los editabas.');

  if p_cambios ? 'zona_horaria' then
    begin
      perform now() at time zone (p_cambios ->> 'zona_horaria');
    exception when others then
      raise exception 'La zona horaria «%» no existe.', p_cambios ->> 'zona_horaria';
    end;
  end if;
  -- Con el locale se formatea cada número de la app: uno con otra forma rompería todas las pantallas.
  if p_cambios ? 'locale' and btrim(p_cambios ->> 'locale') !~ '^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$' then
    raise exception 'El formato regional «%» no tiene la forma esperada, como es-BO.', p_cambios ->> 'locale';
  end if;
  if p_cambios ? 'iconos' and jsonb_typeof(p_cambios -> 'iconos') not in ('object', 'null') then
    raise exception 'Los íconos no tienen la forma esperada.';
  end if;
  if p_cambios ? 'telefono_cc' and nullif(btrim(p_cambios ->> 'telefono_cc'), '') is not null
     and btrim(p_cambios ->> 'telefono_cc') !~ '^\+[1-9][0-9]{0,2}$' then
    raise exception 'El código de país lleva un «+» y de 1 a 3 dígitos.' using errcode = '22023', hint = 'telefono_cc';
  end if;
  if p_cambios ? 'limpieza_dias_gracia'
     and (btrim(p_cambios ->> 'limpieza_dias_gracia') !~ '^[0-9]{1,3}$' or (p_cambios ->> 'limpieza_dias_gracia')::int not between 1 and 90) then
    raise exception 'Los días de gracia de la limpieza van de 1 a 90.' using errcode = '22023', hint = 'limpieza_dias_gracia';
  end if;
  if p_cambios ? 'limpieza_automatica' and (p_cambios ->> 'limpieza_automatica') not in ('true', 'false') then
    raise exception 'La limpieza automática se enciende o se apaga.' using errcode = '22023', hint = 'limpieza_automatica';
  end if;
  if p_cambios ? 'moneda_base' and (p_cambios ->> 'moneda_base') is distinct from v.moneda_base::text then
    if not exists (select 1 from public.monedas m where m.codigo::text = p_cambios ->> 'moneda_base' and m.activa) then
      raise exception 'La moneda base tiene que ser una de las monedas activas.';
    end if;
    if public.empresa_con_datos_cargados() then
      raise exception 'La moneda base no se cambia con datos cargados: los montos ya están guardados en %.', v.moneda_base;
    end if;
  end if;

  update public.ajustes_empresa e set
    nombre = case when p_cambios ? 'nombre' then btrim(p_cambios ->> 'nombre') else e.nombre end,
    razon_social = case when p_cambios ? 'razon_social' then nullif(btrim(p_cambios ->> 'razon_social'), '') else e.razon_social end,
    nit = case when p_cambios ? 'nit' then nullif(btrim(p_cambios ->> 'nit'), '') else e.nit end,
    direccion = case when p_cambios ? 'direccion' then nullif(btrim(p_cambios ->> 'direccion'), '') else e.direccion end,
    ciudad = case when p_cambios ? 'ciudad' then nullif(btrim(p_cambios ->> 'ciudad'), '') else e.ciudad end,
    pais = case when p_cambios ? 'pais' then btrim(p_cambios ->> 'pais') else e.pais end,
    telefono = case when p_cambios ? 'telefono' then nullif(btrim(p_cambios ->> 'telefono'), '') else e.telefono end,
    telefono_cc = case when p_cambios ? 'telefono_cc' then nullif(btrim(p_cambios ->> 'telefono_cc'), '') else e.telefono_cc end,
    whatsapp = case when p_cambios ? 'whatsapp' then nullif(btrim(p_cambios ->> 'whatsapp'), '') else e.whatsapp end,
    email = case when p_cambios ? 'email' then nullif(btrim(p_cambios ->> 'email'), '') else e.email end,
    logo_ruta = case when p_cambios ? 'logo_ruta' then nullif(p_cambios ->> 'logo_ruta', '') else e.logo_ruta end,
    color_acento = case when p_cambios ? 'color_acento' then nullif(lower(p_cambios ->> 'color_acento'), '') else e.color_acento end,
    iconos = case when p_cambios ? 'iconos' then nullif(p_cambios -> 'iconos', 'null'::jsonb) else e.iconos end,
    locale = case when p_cambios ? 'locale' then btrim(p_cambios ->> 'locale') else e.locale end,
    zona_horaria = case when p_cambios ? 'zona_horaria' then btrim(p_cambios ->> 'zona_horaria') else e.zona_horaria end,
    moneda_base = case when p_cambios ? 'moneda_base' then (p_cambios ->> 'moneda_base')::char(3) else e.moneda_base end,
    registro_abierto = case when p_cambios ? 'registro_abierto' then (p_cambios ->> 'registro_abierto')::boolean else e.registro_abierto end,
    papelera_dias = case when p_cambios ? 'papelera_dias' then (p_cambios ->> 'papelera_dias')::int else e.papelera_dias end,
    actividad_dias = case when p_cambios ? 'actividad_dias' then (p_cambios ->> 'actividad_dias')::int else e.actividad_dias end,
    limpieza_automatica = case when p_cambios ? 'limpieza_automatica' then (p_cambios ->> 'limpieza_automatica')::boolean else e.limpieza_automatica end,
    limpieza_dias_gracia = case when p_cambios ? 'limpieza_dias_gracia' then (p_cambios ->> 'limpieza_dias_gracia')::int else e.limpieza_dias_gracia end,
    actualizado_por = (select auth.uid())
  where e.id = 1
  returning e.actualizado_en into v_nueva;
  return v_nueva;
end;
$_$;


ALTER FUNCTION "public"."empresa_guardar_ajustes"("p_cambios" "jsonb", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."en_cartera"("p_lead" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from public.leads_asesores la where la.lead_id = p_lead and la.usuario_id = (select auth.uid()) and la.revocado_en is null);
$$;


ALTER FUNCTION "public"."en_cartera"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enmascarar_telefono"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when p is null or length(p) < 6 then '•••••'
              else left(p, 3) || repeat('•', greatest(length(p) - 5, 2)) || right(p, 2) end;
$$;


ALTER FUNCTION "public"."enmascarar_telefono"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equipo_aceptar_invitacion"() RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.perfiles set invitacion_aceptada_en = now()
  where id = (select auth.uid()) and invitado_en is not null and invitacion_aceptada_en is null;
$$;


ALTER FUNCTION "public"."equipo_aceptar_invitacion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equipo_bajas_continuar"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_lotes int := 0; v_terminadas int := 0; v_persona uuid; v_desde uuid; v_ultimo uuid;
        v_inicio timestamptz := clock_timestamp();
begin
  for v_persona in select b.usuario_id from public.equipo_bajas b where b.terminada_en is null order by b.empezada_en, b.usuario_id loop
    v_desde := null;
    loop
      exit when v_lotes >= 10 or clock_timestamp() - v_inicio > interval '1.5 seconds';
      v_lotes := v_lotes + 1;
      v_ultimo := public._baja_lote_desde(v_persona, 5000, v_desde);
      if v_ultimo is null then
        -- Nada más adelante: termina si no quedó nada saltado.
        if public._baja_terminar(v_persona) then
          v_terminadas := v_terminadas + 1;
        end if;
        exit;
      end if;
      v_desde := v_ultimo;
    end loop;
    exit when v_lotes >= 10 or clock_timestamp() - v_inicio > interval '1.5 seconds';
  end loop;
  return jsonb_build_object('lotes', v_lotes, 'terminadas', v_terminadas);
end;
$$;


ALTER FUNCTION "public"."equipo_bajas_continuar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equipo_bloquear"("p_usuario" "uuid", "p_bloquear" boolean, "p_motivo" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_activo boolean; v_bloqueado boolean; v_nombre text;
begin
  perform public.assert_permiso('equipo.usuarios.gestionar');
  if p_usuario = (select auth.uid()) then raise exception 'No puedes bloquearte a ti mismo.' using errcode = '42501'; end if;
  select activo, bloqueado, coalesce(nullif(nombre, ''), email::text) into v_activo, v_bloqueado, v_nombre
  from public.perfiles where id = p_usuario for update;
  if not found then raise exception 'Esa persona ya no está en el equipo.' using errcode = 'PT409'; end if;
  if not v_activo then raise exception '% ya no forma parte del equipo.', v_nombre using errcode = 'PT409'; end if;
  if v_bloqueado = p_bloquear then
    raise exception 'La cuenta de % ya estaba %.', v_nombre, case when p_bloquear then 'bloqueada' else 'desbloqueada' end using errcode = 'PT409';
  end if;
  update public.perfiles set bloqueado = p_bloquear,
    bloqueado_en = case when p_bloquear then now() else null end,
    bloqueado_por = case when p_bloquear then (select auth.uid()) else null end,
    bloqueo_motivo = case when p_bloquear then p_motivo else null end
  where id = p_usuario;
  perform public.registrar_actividad(case when p_bloquear then 'usuario.bloqueado' else 'usuario.desbloqueado' end, 'perfiles', p_usuario::text, null, jsonb_build_object('motivo', p_motivo));
end;
$$;


ALTER FUNCTION "public"."equipo_bloquear"("p_usuario" "uuid", "p_bloquear" boolean, "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equipo_dar_de_baja"("p_usuario" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_activo boolean; v_nombre text; v_terminada boolean; v_baja public.equipo_bajas;
begin
  perform public.assert_permiso('equipo.usuarios.gestionar');
  if p_usuario = (select auth.uid()) then raise exception 'No puedes darte de baja a ti mismo.' using errcode = '42501'; end if;
  select activo, coalesce(nullif(nombre, ''), email::text) into v_activo, v_nombre
  from public.perfiles where id = p_usuario for update;
  if not found then raise exception 'Esa persona ya no está en el equipo.' using errcode = 'PT409'; end if;
  if not v_activo then raise exception '% ya no forma parte del equipo.', v_nombre using errcode = 'PT409'; end if;
  update public.perfiles set activo = false, baja_en = now(), baja_por = (select auth.uid()), publico_web = false where id = p_usuario;
  update public.cola_web_asesores set habilitado = false, disponible = false where usuario_id = p_usuario;
  insert into public.equipo_bajas (usuario_id, por) values (p_usuario, (select auth.uid()))
  on conflict (usuario_id) do update set por = excluded.por, empezada_en = now(), terminada_en = null,
    leads_al_limbo = 0, oportunidades_canceladas = 0;
  -- El primer lote, en esta misma llamada: una cartera chica termina acá.
  v_terminada := public._baja_lote(p_usuario, 5000);
  select * into v_baja from public.equipo_bajas where usuario_id = p_usuario;
  perform public.registrar_actividad('usuario.baja', 'perfiles', p_usuario::text, null,
    jsonb_build_object('leads_al_limbo', v_baja.leads_al_limbo, 'terminada', v_terminada));
  return jsonb_build_object('terminada', v_terminada, 'leads_al_limbo', v_baja.leads_al_limbo);
end;
$$;


ALTER FUNCTION "public"."equipo_dar_de_baja"("p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equipo_lista"("p_texto" "text" DEFAULT NULL::"text", "p_estado" "text" DEFAULT 'vigentes'::"text", "p_limite" integer DEFAULT 101) RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limite int := public._acotar_pagina(p_limite, 101, 101);  -- el tope de la lista, 100, y una más para saber si hay otras
  v_texto text := left(btrim(coalesce(p_texto, '')), 100);
  v_ids uuid[];
begin
  perform public.assert_activo();
  if not (public.tiene_permiso('equipo.usuarios.ver') or public.tiene_permiso('equipo.usuarios.gestionar')) then
    raise exception 'No tienes el permiso «equipo.usuarios.ver».' using errcode = '42501';
  end if;
  -- Sin texto, o con uno de menos de 3 letras o dígitos seguidos: la lista sin filtro de texto (5a-31).
  if v_texto = '' or not public._equipo_lista_indexable(v_texto) then
    return query execute public._equipo_lista_sql(null, p_estado, v_limite, 'todo');
    return;
  end if;
  execute public._equipo_lista_sql(v_texto, p_estado, v_limite, 'recorrer') into v_ids;
  -- Juntó el límite: no hay nada más que buscar.
  if cardinality(v_ids) >= v_limite then
    return query select unnest(v_ids);
    return;
  end if;
  -- El texto tiene un tramo indexable: lo que no apareció en las primeras S, por el trigram.
  return query execute public._equipo_lista_sql(v_texto, p_estado, v_limite, 'indice');
end;
$$;


ALTER FUNCTION "public"."equipo_lista"("p_texto" "text", "p_estado" "text", "p_limite" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equipo_vista_previa_baja"("p_usuario" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('equipo.usuarios.gestionar');
  -- Hasta 1.001 cada uno: la pantalla dice «más de 1.000» (conteoAcotado).
  return jsonb_build_object(
    'leads_al_limbo', public._leads_al_limbo_de(p_usuario, 1000),
    'oportunidades_abiertas', (select count(*) from (select 1 from public.oportunidades o
                                                       where o.usuario_id = p_usuario and o.estado = 'abierta' limit 1001) x));
end;
$$;


