CREATE OR REPLACE FUNCTION "public"."flujo_regla_apagar_validar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int;
begin
  if tg_op = 'DELETE' or (tg_op = 'UPDATE' and old.activa and not new.activa) then
    select count(*) into n from public.fases f where f.flujo_id = old.flujo_id and (
      (old.regla = 'vitrina_web' and f.publica_web) or (old.regla = 'portal_cliente' and f.visible_portal)
      or (old.regla = 'aduana' and f.permite_aduana) or (old.regla = 'logistica' and f.es_logistica));
    if n > 0 then
      raise exception 'No se puede apagar «%»: % fase(s) la tienen marcada.', old.regla, n using errcode = '23514';
    end if;
  end if;
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."flujo_regla_apagar_validar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."formula_auditar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id text;
begin
  v_id := coalesce(to_jsonb(coalesce(new, old)) ->> 'id', '');
  insert into public.actividad (accion, actor_id, tabla, registro_id, antes, despues)
  values (tg_table_name || '.' || lower(tg_op), (select auth.uid()), tg_table_name, v_id,
          case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) - 'definicion' - 'params' - 'diseno' - 'visibilidad' end,
          case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) - 'definicion' - 'params' - 'diseno' - 'visibilidad' end);
  return null;
end;
$$;


ALTER FUNCTION "public"."formula_auditar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."formula_cambiar_constante"("p_origen" "uuid", "p_nodo" "text", "p_valor" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_pub public.formulas; v_anterior numeric;
begin
  perform public.assert_permiso('cotizaciones.configurar', p_origen);
  select * into v_pub from public.formulas where origen_id = p_origen and estado = 'publicada';
  if v_pub.id is null then raise exception 'El origen no tiene fórmula publicada.' using errcode = '22023'; end if;
  v_anterior := (v_pub.params ->> p_nodo)::numeric;
  if v_anterior is null then raise exception 'La fórmula publicada no tiene la constante «%».', p_nodo using errcode = '22023'; end if;
  perform public.formula_guardar_borrador(p_origen, v_pub.definicion, v_pub.params || jsonb_build_object(p_nodo, p_valor), v_pub.diseno, null);
  return public._publicar_formula(p_origen, format('%s: %s → %s, desde el cotizador', p_nodo, v_anterior, p_valor), v_pub.id, true);
end;
$$;


ALTER FUNCTION "public"."formula_cambiar_constante"("p_origen" "uuid", "p_nodo" "text", "p_valor" numeric) OWNER TO "postgres";


