    AS $$
begin
  perform public.assert_permiso('cotizaciones.configurar', p_origen);
  delete from public.formulas where origen_id = p_origen and estado = 'borrador';
end;
$$;


ALTER FUNCTION "public"."formula_descartar_borrador"("p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."formula_guardar_borrador"("p_origen" "uuid", "p_def" "jsonb", "p_params" "jsonb", "p_diseno" "jsonb", "p_nota" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  perform public.assert_permiso('cotizaciones.configurar', p_origen);
  perform public.validar_formula(p_def, p_params);
  if p_diseno is not null then
    perform public._diseno_forma(p_diseno);   -- sólo la forma: cruzarlo con la fórmula es de publicar
  end if;
  insert into public.formulas (origen_id, estado, definicion, params, diseno, nota, creado_por)
  values (p_origen, 'borrador', p_def, p_params, p_diseno, p_nota, (select auth.uid()))
  on conflict (origen_id) where estado = 'borrador' do update
    set definicion = excluded.definicion, params = excluded.params, diseno = excluded.diseno, nota = excluded.nota, visibilidad = null
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."formula_guardar_borrador"("p_origen" "uuid", "p_def" "jsonb", "p_params" "jsonb", "p_diseno" "jsonb", "p_nota" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."formula_para_cotizar"("p_origen" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  f public.formulas;
begin
  perform public.assert_permiso('cotizaciones.configurar', p_origen);
  if p_origen is null then
    raise exception 'Falta el origen.' using errcode = '22023';
  end if;
  select * into f from public.formulas x where x.origen_id = p_origen and x.estado = 'publicada';   -- formulas_publicada_unica
  if f.id is null then
    raise exception 'Este origen no tiene una fórmula publicada.' using errcode = '22023';
  end if;
  return jsonb_build_object('id', f.id, 'version', f.version, 'nota', f.nota, 'publicado_en', f.publicado_en,
                            'definicion', f.definicion, 'params', f.params, 'diseno', f.diseno, 'visibilidad', f.visibilidad);
end $$;


