    AS $$
  select not exists (select 1 from public.leads_asesores la
                      where la.lead_id = p_lead and la.revocado_en is null
                        and la.usuario_id <> all ((select public._bajas_en_curso())::uuid[]));
$$;


ALTER FUNCTION "public"."lead_en_limbo"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_etiquetas_poner"("p_lead" "uuid", "p_etiquetas" "uuid"[], "p_valor" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int;
begin
  perform public._lead_visible(p_lead);
  if p_valor is null then
    raise exception 'Falta decir si va o no.' using errcode = '22023';
  end if;
  if p_etiquetas is null or cardinality(p_etiquetas) not between 1 and 20 or array_position(p_etiquetas, null) is not null then
    raise exception 'Elige entre 1 y 20 etiquetas.' using errcode = '22023', hint = 'etiquetas';
  end if;
  perform public._etiquetas_candado();
  -- Ajena o inexistente: lo mismo. No se dice que existe.
  if exists (select 1 from unnest(p_etiquetas) x (id)
              where not exists (select 1 from public.etiquetas e where e.id = x.id and e.usuario_id = (select auth.uid()))) then
    raise exception 'No encontramos esa etiqueta. Recarga para ver las tuyas.' using errcode = '22023', hint = 'etiquetas';
  end if;
  if p_valor then
    insert into public.leads_etiquetas (lead_id, etiqueta_id)
    select distinct p_lead, x.id from unnest(p_etiquetas) x (id)
    on conflict do nothing;
    get diagnostics n = row_count;
    if (select count(*) from public.leads_etiquetas le join public.etiquetas e on e.id = le.etiqueta_id
         where le.lead_id = p_lead and e.usuario_id = (select auth.uid())) > 20 then
      raise exception 'Un lead admite hasta 20 de tus etiquetas. Quita una para poner otra.' using errcode = '22023', hint = 'etiquetas';
    end if;
  else
    delete from public.leads_etiquetas le where le.lead_id = p_lead and le.etiqueta_id = any (p_etiquetas);
    get diagnostics n = row_count;
  end if;
  return jsonb_build_object('resultado', case when n = 0 then 'sin_cambios' when p_valor then 'puesto' else 'quitado' end,
                            'etiquetas', public._lead_mis_etiquetas(p_lead));
end;
$$;


ALTER FUNCTION "public"."lead_etiquetas_poner"("p_lead" "uuid", "p_etiquetas" "uuid"[], "p_valor" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_favorito_poner"("p_lead" "uuid", "p_valor" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int;
begin
  perform public._lead_visible(p_lead);
  if p_valor is null then
    raise exception 'Falta decir si va o no.' using errcode = '22023';
  end if;
  if p_valor then
    insert into public.leads_favoritos (lead_id, usuario_id) values (p_lead, (select auth.uid())) on conflict do nothing;
  else
    delete from public.leads_favoritos f where f.lead_id = p_lead and f.usuario_id = (select auth.uid());
  end if;
  get diagnostics n = row_count;
  return jsonb_build_object('resultado', case when n = 0 then 'sin_cambios' when p_valor then 'puesto' else 'quitado' end,
                            'valor', p_valor);
end;
$$;


ALTER FUNCTION "public"."lead_favorito_poner"("p_lead" "uuid", "p_valor" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_ficha"("p_lead" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare v record; t record;
begin
  select * into v from public.leads_vista lv where lv.id = p_lead;
  if not found then
    return null;
  end if;
  select la.usuario_id as id, nullif(btrim(p.nombre), '') as nombre into t
    from public.leads_asesores la join public.perfiles p on p.id = la.usuario_id
   where la.lead_id = p_lead and la.revocado_en is null
     and la.usuario_id <> all ((select public._bajas_en_curso())::uuid[])
   order by (la.tipo_acceso = 'dueno') desc, la.desde
   limit 1;
  return jsonb_build_object(
    'id', v.id, 'numero', v.numero, 'numero_propio', v.numero_propio, 'numero_propio_de', v.numero_propio_de,
    'numero_propio_creador', v.numero_propio_creador,
    'nombre', v.nombre,
    'telefono_cc', v.telefono_cc, 'telefono', v.telefono_principal, 'en_cartera', v.en_cartera,
    'tipo_lead_id', v.tipo_lead_id, 'origen_lead_id', v.origen_lead_id,
    'atributos', coalesce(v.atributos, '{}'::jsonb),
    'creado_en', v.creado_en, 'actualizado_en', v.actualizado_en,
    'tiene_id', t.id, 'tiene_nombre', t.nombre,
    'telefonos', coalesce((
      select jsonb_agg(jsonb_build_object('id', x.id, 'telefono', x.telefono, 'etiqueta', x.etiqueta)
                       order by x.creado_en, x.id)
        from public.lead_telefonos(p_lead) x), '[]'::jsonb),
    'recordatorios_vencidos', (
      select count(*) from (
        select 1 from public.recordatorios r
         where r.usuario_id = (select auth.uid()) and r.lead_id = p_lead
           and r.completado_en is null and r.eliminado_en is null and r.recordar_en <= now()
         order by r.recordar_en limit 21) x),
    -- Hasta 101 (el aviso dice «más de 100»); índice `vehiculos_lead_idx`.
    'vehiculos_vinculados', (select count(*) from (select 1 from public.vehiculos x where x.lead_id = p_lead limit 101) q),
    'es_favorito', v.es_favorito, 'esta_tachado', v.esta_tachado,
    'etiquetas', to_jsonb(v.etiquetas));
end;
$$;


ALTER FUNCTION "public"."lead_ficha"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_guardar"("p_lead" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_permitidas constant text[] := array['nombre', 'tipo_lead_id', 'origen_lead_id', 'atributos'];
  v_k text;
  l public.leads;
  n public.leads;
  v_nombre text;
  v_tipo uuid;
  v_origen uuid;
  v_atributos jsonb;
  e record;
begin
  perform public.assert_activo();
  if p_cambios is null or jsonb_typeof(p_cambios) <> 'object' then
    raise exception 'Los cambios de un lead tienen que ser un objeto.' using errcode = '22023';
  end if;
  for v_k in select jsonb_object_keys(p_cambios) loop
    if not (v_k = any (v_permitidas)) then
      raise exception 'El dato «%» no va suelto: los campos del lead se mandan dentro de «atributos».', v_k
        using errcode = '22023', hint = v_k;
    end if;
  end loop;

  -- Inexistente, limbo, papelera, ajeno y «lo veo pero no es mío»: la misma respuesta.
  l := public._lead_mio(p_lead, 'leads.editar', true);
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;

  v_nombre := l.nombre;
  v_tipo := l.tipo_lead_id;
  v_origen := l.origen_lead_id;
  v_atributos := l.atributos;

  if p_cambios ? 'nombre' then
    if jsonb_typeof(p_cambios -> 'nombre') <> 'string' then
      raise exception 'Escribe el nombre.' using errcode = '22023', hint = 'nombre';
    end if;
    v_nombre := btrim(p_cambios ->> 'nombre');
    if v_nombre = '' then
      raise exception 'Escribe el nombre.' using errcode = '22023', hint = 'nombre';
    end if;
    if char_length(v_nombre) > 120 then
      raise exception 'El nombre admite hasta 120 caracteres.' using errcode = '22023', hint = 'nombre';
    end if;
  end if;

  if p_cambios ? 'tipo_lead_id' then
    begin
      v_tipo := nullif(p_cambios ->> 'tipo_lead_id', '')::uuid;
    exception when invalid_text_representation then
      raise exception 'Ese tipo de lead no existe.' using errcode = '22023', hint = 'tipo_lead_id';
    end;
    if v_tipo is null then
      raise exception 'Elige el tipo de lead.' using errcode = '22023', hint = 'tipo_lead_id';
    end if;
    -- Sólo si cambia: uno desactivado que el lead ya tiene se conserva.
    if v_tipo is distinct from l.tipo_lead_id then
      perform public._tipo_lead_exigir_activo(v_tipo);
    end if;
  end if;

  if p_cambios ? 'origen_lead_id' then
    begin
      v_origen := nullif(p_cambios ->> 'origen_lead_id', '')::uuid;
    exception when invalid_text_representation then
      raise exception 'Ese origen del lead no existe.' using errcode = '22023', hint = 'origen_lead_id';
    end;
    -- Sólo si cambia: uno desactivado que el lead ya tiene se conserva.
    if v_origen is distinct from l.origen_lead_id then
      if v_origen is not null then
        if not exists (select 1 from public.origenes_lead o where o.id = v_origen and o.activo) then
          raise exception 'Ese origen del lead está desactivado o ya no existe.' using errcode = '22023', hint = 'origen_lead_id';
        end if;
      elsif exists (select 1 from public.origenes_lead o where o.activo) then
        raise exception 'Elige de dónde viene el lead.' using errcode = '22023', hint = 'origen_lead_id';
      end if;
    end if;
  end if;

  if p_cambios ? 'atributos' then
    if jsonb_typeof(p_cambios -> 'atributos') <> 'object' then
      raise exception 'Los atributos de un lead tienen que ser un objeto.' using errcode = '22023';
    end if;
    for e in select x.key, x.value from jsonb_each(p_cambios -> 'atributos') x loop
      if e.value = 'null'::jsonb then
        v_atributos := v_atributos - e.key;
      else
        v_atributos := v_atributos || jsonb_build_object(e.key, e.value);
      end if;
    end loop;
  end if;

  -- Guardar lo que ya está guardado no es un conflicto: un reintento tras perder la respuesta no
  -- choca consigo mismo, y quien no cambió nada no pisa a nadie.
  if (v_nombre, v_tipo, v_origen, v_atributos) is not distinct from (l.nombre, l.tipo_lead_id, l.origen_lead_id, l.atributos) then
    return jsonb_build_object('actualizado_en', l.actualizado_en);
  end if;
  if l.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._lead_conflicto(l.id, l.actualizado_en);
  end if;

  -- `atributos` va siempre en el SET: el trigger que valida el layout se dispara por columna
  -- nombrada, así que un lead al que le falta un requerido nuevo no se guarda ni cambiándole
  -- sólo el tipo.
  update public.leads x set
    nombre = v_nombre, tipo_lead_id = v_tipo, origen_lead_id = v_origen, atributos = v_atributos
  where x.id = l.id
  returning * into n;
  return jsonb_build_object('actualizado_en', n.actualizado_en);
end;
$$;


ALTER FUNCTION "public"."lead_guardar"("p_lead" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_numero_propio_asignar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.creado_por is null then
    new.numero_propio := null;
  else
    insert into public.leads_contadores as c (usuario_id, ultimo) values (new.creado_por, 1)
    on conflict (usuario_id) do update set ultimo = c.ultimo + 1
    returning c.ultimo into new.numero_propio;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."lead_numero_propio_asignar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_numeros_inmutables"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.numero_propio is distinct from old.numero_propio
     and coalesce(current_setting('importadora.numerar_lote', true), 'no') <> 'si' then
    raise exception 'El número de un lead no cambia.' using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."lead_numeros_inmutables"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_numeros_proyectar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    insert into public.leads_numeros_globales (lead_id, numero) values (new.id, new.numero);
    if new.numero_propio is not null then
      insert into public.leads_numeros_propios (lead_id, creado_por, numero) values (new.id, new.creado_por, new.numero_propio);
    end if;
  else
    update public.leads_numeros_propios p set numero = new.numero_propio where p.lead_id = new.id;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."lead_numeros_proyectar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_oportunidades"("p_lead" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with leidas as (
    select public._oportunidad_json(o) || jsonb_build_object(
             'etapa', jsonb_build_object('id', s.id, 'nombre', s.nombre, 'color', s.color,
                        'es_ganada', s.es_ganada, 'es_perdida', s.es_perdida),
             'embudo', jsonb_build_object('id', e.id, 'nombre', e.nombre)) as json,
           (o.estado = 'abierta') as abierta, o.ultima_actividad_en as en, o.id,
           row_number() over (order by (o.estado = 'abierta') desc, o.ultima_actividad_en desc, o.id desc) as k
      from public.oportunidades o
      join public.embudos e on e.id = o.embudo_id
      join public.embudos_etapas s on s.id = o.etapa_id
     where o.lead_id = p_lead
     order by (o.estado = 'abierta') desc, o.ultima_actividad_en desc, o.id desc
     limit 101)
  select jsonb_build_object(
    'puedo_crear', public.puede_actuar_lead(p_lead, 'leads.editar'),
    'hay_mas', coalesce(bool_or(l.k > 100), false),
    'oportunidades', coalesce(jsonb_agg(l.json order by l.abierta desc, l.en desc, l.id desc) filter (where l.k <= 100), '[]'::jsonb))
  from leidas l;
$$;


ALTER FUNCTION "public"."lead_oportunidades"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_origen_vigente"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_activo boolean;
begin
  if new.origen_lead_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.origen_lead_id is not distinct from old.origen_lead_id then
    return new;
  end if;
  select o.activo into v_activo from public.origenes_lead o where o.id = new.origen_lead_id for share;
  if not found then
    raise exception 'Ese origen del lead ya no existe: elige otro.' using errcode = '22023', hint = 'origen_lead_id';
  end if;
  if not v_activo then
    raise exception 'Ese origen del lead se desactivó: elige otro.' using errcode = '22023', hint = 'origen_lead_id';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."lead_origen_vigente"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_recordatorios"("p_lead" "uuid", "p_completados" boolean DEFAULT false, "p_desde_en" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_desde_id" "uuid" DEFAULT NULL::"uuid", "p_tamano" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_tamano int := public._acotar_pagina(p_tamano, 20, 50);
  v_yo uuid := (select auth.uid());
  v_lead record;
  v_filas public.recordatorios[];
  v_json jsonb;
  v_hay_completados boolean;
begin
  select l.id, l.nombre, g.numero, np.numero as numero_propio into v_lead
    from public.leads l
    left join public.leads_numeros_globales g on g.lead_id = l.id
    left join public.leads_numeros_propios np on np.lead_id = l.id
   where l.id = p_lead;
  if not found then
    return jsonb_build_object('recordatorios', '[]'::jsonb, 'hay_mas', false, 'hay_completados', false,
                              'puedo_agendar', false);
  end if;
  if coalesce(p_completados, false) then
    if p_desde_en is null then
      select array_agg(x.r order by (x.r).completado_en desc, (x.r).id desc) into v_filas from (
        select r from public.recordatorios r
         where r.usuario_id = v_yo and r.lead_id = p_lead and r.completado_en is not null and r.eliminado_en is null
         order by r.completado_en desc, r.id desc limit v_tamano + 1) x;
    else
      select array_agg(x.r order by (x.r).completado_en desc, (x.r).id desc) into v_filas from (
        select r from public.recordatorios r
         where r.usuario_id = v_yo and r.lead_id = p_lead and r.completado_en is not null and r.eliminado_en is null
           and (r.completado_en, r.id) < (p_desde_en, p_desde_id)
         order by r.completado_en desc, r.id desc limit v_tamano + 1) x;
    end if;
    v_hay_completados := true;
  else
    if p_desde_en is null then
      select array_agg(x.r order by (x.r).recordar_en, (x.r).id) into v_filas from (
        select r from public.recordatorios r
         where r.usuario_id = v_yo and r.lead_id = p_lead and r.completado_en is null and r.eliminado_en is null
         order by r.recordar_en, r.id limit v_tamano + 1) x;
    else
      select array_agg(x.r order by (x.r).recordar_en, (x.r).id) into v_filas from (
        select r from public.recordatorios r
         where r.usuario_id = v_yo and r.lead_id = p_lead and r.completado_en is null and r.eliminado_en is null
           and (r.recordar_en, r.id) > (p_desde_en, p_desde_id)
         order by r.recordar_en, r.id limit v_tamano + 1) x;
    end if;
    v_hay_completados := exists (
      select 1 from public.recordatorios r
       where r.usuario_id = v_yo and r.lead_id = p_lead and r.completado_en is not null and r.eliminado_en is null);
  end if;
  -- La forma de `recordatorios_vista`; la RLS de `vehiculos` vacía el join si quien mira no lo ve.
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', u.id, 'titulo', u.titulo, 'recordar_en', u.recordar_en, 'notificado_en', u.notificado_en,
           'completado_en', u.completado_en, 'creado_en', u.creado_en, 'actualizado_en', u.actualizado_en,
           'lead_id', v_lead.id, 'lead_nombre', v_lead.nombre, 'lead_numero', v_lead.numero, 'lead_numero_propio', v_lead.numero_propio,
           'vehiculo_id', v.id, 'vehiculo_titulo', v.titulo, 'vehiculo_numero', v.numero,
           'vehiculo_oculto', u.vehiculo_id is not null and v.id is null) order by u.ordinality), '[]'::jsonb)
    into v_json
    from unnest(v_filas[1:v_tamano]) with ordinality as u
    left join public.vehiculos v on v.id = u.vehiculo_id;
  return jsonb_build_object(
    'recordatorios', v_json, 'hay_mas', coalesce(cardinality(v_filas), 0) > v_tamano,
    'hay_completados', v_hay_completados,
    'puedo_agendar', public.en_cartera(p_lead) and public.puede_lead(p_lead, 'leads.editar'));
end;
$$;


ALTER FUNCTION "public"."lead_recordatorios"("p_lead" "uuid", "p_completados" boolean, "p_desde_en" timestamp with time zone, "p_desde_id" "uuid", "p_tamano" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_revocar_acceso"("p_lead" "uuid", "p_usuario" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l public.leads; v_dueno uuid; v_alcance public.alcance_permiso; v_yo uuid := (select auth.uid());
begin
  l := public._lead_para_mover(p_lead);
  v_dueno := public._lead_dueno(l.id);
  v_alcance := public.alcance_de('leads.compartir');
  if v_alcance is null then
    raise exception 'No tienes permiso para quitar el acceso a este lead.' using errcode = '42501';
  end if;
  if p_usuario is not null and p_usuario = v_dueno then
    raise exception 'Al dueño no se le quita el acceso: transfiere el lead.' using errcode = '23514', hint = 'usuario';
  end if;
  if p_usuario = v_yo then
    raise exception 'Para dejar este lead usa «Salir de este lead».' using errcode = '23514', hint = 'usuario';
  end if;
  if v_alcance <> 'todos' and v_dueno is distinct from v_yo then
    raise exception 'Sólo quien es dueño del lead quita accesos.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.leads_asesores a where a.lead_id = l.id and a.usuario_id = p_usuario and a.revocado_en is null) then
    return jsonb_build_object('resultado', 'sin_cambios', 'cartera', public._lead_cartera_json(l.id));
  end if;
  -- El limbo sólo nace de una baja: nadie deja un lead sin ninguna persona.
  if not exists (select 1 from public.leads_asesores a where a.lead_id = l.id and a.usuario_id <> p_usuario and a.revocado_en is null) then
    raise exception 'Es la única persona que lo tiene: transfiérelo antes de quitarle el acceso.'
      using errcode = '23514', hint = 'usuario';
  end if;
  update public.leads_asesores set revocado_en = now(), revocado_por = v_yo
  where lead_id = l.id and usuario_id = p_usuario and revocado_en is null;
  perform public.registrar_actividad('lead.acceso_revocado', 'leads', l.id::text, jsonb_build_object('a', p_usuario), null);
  return jsonb_build_object('resultado', 'revocado', 'cartera', public._lead_cartera_json(l.id));
end;
$$;


ALTER FUNCTION "public"."lead_revocar_acceso"("p_lead" "uuid", "p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_salir"("p_lead" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l public.leads; v_yo uuid := (select auth.uid()); a public.leads_asesores;
begin
  perform public.assert_activo();
  if p_lead is null then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  select * into l from public.leads x
   where x.id = p_lead and x.eliminado_en is null and public.en_cartera(x.id) and not public.lead_en_limbo(x.id)
   for update;
  if not found then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  perform public._lead_aplicar_bajas(l.id);
  select * into a from public.leads_asesores x where x.lead_id = l.id and x.usuario_id = v_yo and x.revocado_en is null;
  if a.tipo_acceso = 'dueno' then
    raise exception 'Eres quien tiene este lead: transfiérelo para dejarlo.' using errcode = '23514';
  end if;
  if not exists (select 1 from public.leads_asesores x where x.lead_id = l.id and x.usuario_id <> v_yo and x.revocado_en is null) then
    raise exception 'Eres la única persona que lo tiene: transfiérelo antes de salir.' using errcode = '23514';
  end if;
  update public.leads_asesores set revocado_en = now(), revocado_por = v_yo
  where lead_id = l.id and usuario_id = v_yo and revocado_en is null;
  perform public.registrar_actividad('lead.salio', 'leads', l.id::text, null, null);
  return jsonb_build_object('resultado', 'salio');
end;
$$;


ALTER FUNCTION "public"."lead_salir"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_seguimiento"("p_lead" "uuid", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare v_yo uuid := (select auth.uid()); v_json jsonb;
begin
  select jsonb_build_object(
           'id', s.id, 'lead_id', s.lead_id,
           'tipo_id', s.tipo_id, 'tipo_nombre', t.nombre, 'tipo_icono', t.icono,
           'titulo', s.titulo, 'detalle_doc', s.detalle_doc, 'detalle_texto', s.detalle_texto,
           'visibilidad', s.visibilidad, 'ocurrido_en', s.ocurrido_en, 'actualizado_en', s.actualizado_en,
           'eliminado', false,
           'autor_id', s.usuario_id, 'autor_nombre', nullif(btrim(p.nombre), ''),
           'es_mio', s.usuario_id = v_yo,
           'vehiculo', case when v.id is not null then
                         jsonb_build_object('id', v.id, 'titulo', v.titulo, 'numero', v.numero) end,
           'vehiculo_oculto', s.vehiculo_id is not null and v.id is null and s.usuario_id = v_yo)
    into v_json
    from public.seguimientos s
    join public.tipos_seguimiento t on t.id = s.tipo_id
    left join public.perfiles p on p.id = s.usuario_id
    left join public.vehiculos v on v.id = s.vehiculo_id
   where s.id = p_id and s.lead_id = p_lead and s.eliminado_en is null;
  return v_json;
end;
$$;


ALTER FUNCTION "public"."lead_seguimiento"("p_lead" "uuid", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_seguimientos"("p_lead" "uuid", "p_antes_en" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_antes_id" "uuid" DEFAULT NULL::"uuid", "p_tamano" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_tamano int := public._acotar_pagina(p_tamano, 20, 50);
  v_yo uuid := (select auth.uid());
  v_filas public.seguimientos[];
  v_json jsonb;
begin
  -- `union` (no `all`): uno mío y público llega por las dos ramas.
  if p_antes_en is null then
    select array_agg(x.s order by (x.s).ocurrido_en desc, (x.s).id desc) into v_filas from (
      select u.s from (
        (select s from public.seguimientos s
          where s.lead_id = p_lead and s.usuario_id = v_yo and s.eliminado_en is null
          order by s.ocurrido_en desc, s.id desc limit v_tamano + 1)
        union
        (select s from public.seguimientos s
          where s.lead_id = p_lead and s.visibilidad = 'publico' and s.eliminado_en is null
          order by s.ocurrido_en desc, s.id desc limit v_tamano + 1)) u
      order by (u.s).ocurrido_en desc, (u.s).id desc limit v_tamano + 1) x;
  else
    select array_agg(x.s order by (x.s).ocurrido_en desc, (x.s).id desc) into v_filas from (
      select u.s from (
        (select s from public.seguimientos s
          where s.lead_id = p_lead and s.usuario_id = v_yo and s.eliminado_en is null
            and (s.ocurrido_en, s.id) < (p_antes_en, p_antes_id)
          order by s.ocurrido_en desc, s.id desc limit v_tamano + 1)
        union
        (select s from public.seguimientos s
          where s.lead_id = p_lead and s.visibilidad = 'publico' and s.eliminado_en is null
            and (s.ocurrido_en, s.id) < (p_antes_en, p_antes_id)
          order by s.ocurrido_en desc, s.id desc limit v_tamano + 1)) u
      order by (u.s).ocurrido_en desc, (u.s).id desc limit v_tamano + 1) x;
  end if;
  -- La forma de siempre (la misma que `lead_seguimiento()`). La RLS de `vehiculos` vacía el join si
  -- quien mira no ve ese vehículo.
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', u.id, 'lead_id', u.lead_id,
           'tipo_id', u.tipo_id, 'tipo_nombre', t.nombre, 'tipo_icono', t.icono,
           'titulo', u.titulo, 'detalle_doc', u.detalle_doc, 'detalle_texto', u.detalle_texto,
           'visibilidad', u.visibilidad, 'ocurrido_en', u.ocurrido_en, 'actualizado_en', u.actualizado_en,
           'eliminado', false,
           'autor_id', u.usuario_id, 'autor_nombre', nullif(btrim(p.nombre), ''),
           'es_mio', u.usuario_id = v_yo,
           'vehiculo', case when v.id is not null then
                         jsonb_build_object('id', v.id, 'titulo', v.titulo, 'numero', v.numero) end,
           'vehiculo_oculto', u.vehiculo_id is not null and v.id is null and u.usuario_id = v_yo)
           order by u.ordinality), '[]'::jsonb)
    into v_json
    from unnest(v_filas[1:v_tamano]) with ordinality as u
    join public.tipos_seguimiento t on t.id = u.tipo_id
    left join public.perfiles p on p.id = u.usuario_id
    left join public.vehiculos v on v.id = u.vehiculo_id;
  return jsonb_build_object(
    'seguimientos', v_json, 'hay_mas', coalesce(cardinality(v_filas), 0) > v_tamano,
    'puedo_anotar', public.en_cartera(p_lead) and public.puede_lead(p_lead, 'leads.editar'));
end;
$$;


ALTER FUNCTION "public"."lead_seguimientos"("p_lead" "uuid", "p_antes_en" timestamp with time zone, "p_antes_id" "uuid", "p_tamano" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_tachado_poner"("p_lead" "uuid", "p_valor" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int;
begin
  perform public._lead_visible(p_lead);
  if p_valor is null then
    raise exception 'Falta decir si va o no.' using errcode = '22023';
  end if;
  if p_valor then
    insert into public.leads_tachados (lead_id, usuario_id) values (p_lead, (select auth.uid())) on conflict do nothing;
  else
    delete from public.leads_tachados t where t.lead_id = p_lead and t.usuario_id = (select auth.uid());
  end if;
  get diagnostics n = row_count;
  return jsonb_build_object('resultado', case when n = 0 then 'sin_cambios' when p_valor then 'puesto' else 'quitado' end,
                            'valor', p_valor);
end;
$$;


ALTER FUNCTION "public"."lead_tachado_poner"("p_lead" "uuid", "p_valor" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_telefono_guardar"("p_lead" "uuid", "p_id" "uuid", "p_cc" "text", "p_tel" "text", "p_etiqueta" "text" DEFAULT NULL::"text", "p_creado_en" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  l public.leads;
  t public.leads_telefonos;
  v_cc text;
  v_tel text;
  v_etiqueta text;
  v_msg text;
begin
  l := public._lead_mio(p_lead, 'leads.editar', true);
  if p_id is null then
    raise exception 'Falta el identificador del teléfono.' using errcode = '22023';
  end if;
  v_etiqueta := nullif(btrim(coalesce(p_etiqueta, '')), '');
  if char_length(v_etiqueta) > 40 then
    raise exception 'La etiqueta admite hasta 40 caracteres.' using errcode = '22023', hint = 'etiqueta';
  end if;
  v_cc := coalesce(nullif(btrim(p_cc), ''), (select e.telefono_cc from public.ajustes_empresa e where e.id = 1));
  begin
    v_tel := public.normalizar_telefono(v_cc, p_tel);
  exception when sqlstate '22023' then
    get stacked diagnostics v_msg = message_text;
    raise exception '%', v_msg using errcode = '22023', hint = 'telefono';
  end;

  select * into t from public.leads_telefonos x where x.id = p_id;
  if found then
    if t.lead_id <> l.id then
      raise exception 'No pudimos guardar este teléfono. Vuelve a intentarlo.' using errcode = '22023';
    end if;
    if t.telefono <> v_tel then
      raise exception 'Para cambiar el número, quita este teléfono y agrega el nuevo.'
        using errcode = '22023', hint = 'telefono';
    end if;
    if t.etiqueta is distinct from v_etiqueta then
      update public.leads_telefonos x set etiqueta = v_etiqueta where x.id = t.id;
      perform public.registrar_actividad('lead.telefono_extra_rotulado', 'leads', l.id::text, null, null,
        jsonb_build_object('telefono', public.enmascarar_telefono(v_tel)));
      return public._lead_telefonos_estado(l.id, 'rotulado');
    end if;
    return public._lead_telefonos_estado(l.id, 'sin_cambios');
  end if;

  if v_tel = l.telefono_principal
     or exists (select 1 from public.leads_telefonos x where x.lead_id = l.id and x.telefono = v_tel) then
    raise exception 'Ese número ya está en este lead.' using errcode = '22023', hint = 'telefono';
  end if;
  if (select count(*) from public.leads_telefonos x where x.lead_id = l.id) >= 10 then
    raise exception 'Un lead admite hasta 10 teléfonos extra. Quita uno para agregar otro.'
      using errcode = '22023', hint = 'telefono';
  end if;
  insert into public.leads_telefonos (id, lead_id, telefono, etiqueta, creado_en)
  values (p_id, l.id, v_tel, v_etiqueta, least(coalesce(p_creado_en, now()), now()));
  perform public.registrar_actividad('lead.telefono_extra_agregado', 'leads', l.id::text, null, null,
    jsonb_build_object('telefono', public.enmascarar_telefono(v_tel)));
  return public._lead_telefonos_estado(l.id, 'agregado');
end;
$$;


ALTER FUNCTION "public"."lead_telefono_guardar"("p_lead" "uuid", "p_id" "uuid", "p_cc" "text", "p_tel" "text", "p_etiqueta" "text", "p_creado_en" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_telefono_quitar"("p_lead" "uuid", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  l public.leads;
  t public.leads_telefonos;
begin
  l := public._lead_mio(p_lead, 'leads.editar', true);
  delete from public.leads_telefonos x where x.id = p_id and x.lead_id = l.id returning * into t;
  if not found then
    return public._lead_telefonos_estado(l.id, 'sin_cambios') || jsonb_build_object('quitado', null);
  end if;
  perform public.registrar_actividad('lead.telefono_extra_quitado', 'leads', l.id::text, null, null,
    jsonb_build_object('telefono', public.enmascarar_telefono(t.telefono)));
  return public._lead_telefonos_estado(l.id, 'quitado') || jsonb_build_object('quitado',
    jsonb_build_object('id', t.id, 'telefono', t.telefono, 'etiqueta', t.etiqueta, 'creado_en', t.creado_en));
end;
$$;


ALTER FUNCTION "public"."lead_telefono_quitar"("p_lead" "uuid", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_telefonos"("p_lead" "uuid") RETURNS TABLE("id" "uuid", "telefono" "text", "etiqueta" "text", "creado_en" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cartera boolean;
begin
  if not public.puede_lead(p_lead, 'leads.ver') then
    return;
  end if;
  v_cartera := public.en_cartera(p_lead);
  return query
    select t.id,
           case when v_cartera then t.telefono else public.enmascarar_telefono(t.telefono) end,
           t.etiqueta, t.creado_en
      from public.leads_telefonos t
     where t.lead_id = p_lead
     order by t.creado_en, t.id;
end;
$$;


ALTER FUNCTION "public"."lead_telefonos"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_tipo_por_defecto"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.tipo_lead_id is null then
    new.tipo_lead_id := public._tipo_lead_por_defecto();
    if new.tipo_lead_id is null then
      raise exception 'No hay un tipo de lead activo de la clase prospecto: activa uno en Configuración.' using errcode = '22023', hint = 'tipo_lead_id';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."lead_tipo_por_defecto"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_tipo_vigente"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_activo boolean;
begin
  if new.tipo_lead_id is null then
    raise exception 'Elige el tipo de lead.' using errcode = '22023', hint = 'tipo_lead_id';
  end if;
  if tg_op = 'UPDATE' and new.tipo_lead_id is not distinct from old.tipo_lead_id then
    return new;
  end if;
  select t.activo into v_activo from public.tipos_lead t where t.id = new.tipo_lead_id for share;
  if not found then
    raise exception 'Ese tipo de lead ya no existe: elige otro.' using errcode = '22023', hint = 'tipo_lead_id';
  end if;
  if not v_activo then
    raise exception 'Ese tipo de lead se desactivó: elige otro.' using errcode = '22023', hint = 'tipo_lead_id';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."lead_tipo_vigente"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_transferir"("p_lead" "uuid", "p_destino" "uuid", "p_dueno_esperado" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  l public.leads; v_dueno uuid; v_alcance public.alcance_permiso; v_yo uuid := (select auth.uid()); v_nombre text;
  o public.oportunidades; v_embudo uuid; v_etapa uuid; v_movidas int := 0;
begin
  l := public._lead_para_mover(p_lead);
  v_dueno := public._lead_dueno(l.id);
  v_alcance := public.alcance_de('leads.transferir');
  if v_alcance is null then
    raise exception 'No tienes permiso para transferir este lead.' using errcode = '42501';
  end if;
  -- Ya está como se pidió: un reintento tras perder la respuesta no choca consigo mismo.
  if v_dueno is not null and v_dueno = p_destino then
    return jsonb_build_object('resultado', 'sin_cambios', 'dueno', v_dueno, 'cartera', public._lead_cartera_json(l.id),
      'oportunidades', 0);
  end if;
  if v_alcance <> 'todos' and v_dueno is distinct from v_yo then
    raise exception 'Sólo quien es dueño del lead lo transfiere.' using errcode = '42501';
  end if;
  -- Nadie se concede un lead que no es suyo, ni como destino: ni la supervisión ni un compartido.
  if p_destino = v_yo then
    raise exception 'No puedes transferirte un lead que no es tuyo.' using errcode = '42501', hint = 'usuario';
  end if;
  perform public._lead_destino_validar(p_destino);
  if p_dueno_esperado is distinct from v_dueno then
    select nullif(btrim(p.nombre), '') into v_nombre from public.perfiles p where p.id = v_dueno;
    raise exception 'Este lead cambió de dueño: ahora lo tiene %. Recarga para ver quién lo tiene.',
      case when v_dueno = v_yo then 'tú' else coalesce(v_nombre, 'otra persona') end
      using errcode = 'PT409';
  end if;

  -- El saliente conserva acceso compartido.
  update public.leads_asesores set tipo_acceso = 'compartido'
  where lead_id = l.id and tipo_acceso = 'dueno' and revocado_en is null;
  insert into public.leads_asesores (lead_id, usuario_id, tipo_acceso) values (l.id, p_destino, 'dueno')
  on conflict (lead_id, usuario_id) do update set tipo_acceso = 'dueno', revocado_en = null, revocado_por = null, desde = now();

  -- Las abiertas del saliente pasan al embudo por defecto del destino.
  if v_dueno is not null then
    for o in
      select * from public.oportunidades x
       where x.lead_id = l.id and x.usuario_id = v_dueno and x.estado = 'abierta' and x.eliminado_en is null
       order by x.id for update
    loop
      if v_embudo is null then
        v_embudo := public._embudo_defecto_de(p_destino);
      end if;
      select s.id into v_etapa
        from public.embudos_etapas s join public.embudos_etapas a on a.id = o.etapa_id
       where s.embudo_id = v_embudo and lower(s.nombre) = lower(a.nombre) and not s.es_ganada and not s.es_perdida;
      if v_etapa is null then
        select s.id into v_etapa from public.embudos_etapas s where s.embudo_id = v_embudo and s.es_inicial;
      end if;
      update public.oportunidades x set usuario_id = p_destino, embudo_id = v_embudo, etapa_id = v_etapa,
        actualizado_en = greatest(clock_timestamp(), o.actualizado_en + interval '1 microsecond')
      where x.id = o.id;
      v_movidas := v_movidas + 1;
    end loop;
    if v_movidas > 0 then
      perform public.registrar_actividad('oportunidad.transferida', 'leads', l.id::text,
        jsonb_build_object('de', v_dueno), jsonb_build_object('a', p_destino), jsonb_build_object('cantidad', v_movidas));
    end if;
  end if;

  perform public.registrar_actividad('lead.transferido', 'leads', l.id::text,
    jsonb_build_object('de', v_dueno), jsonb_build_object('a', p_destino));
  return jsonb_build_object('resultado', 'transferido', 'dueno', p_destino, 'cartera', public._lead_cartera_json(l.id),
    'oportunidades', v_movidas);
end;
$$;


ALTER FUNCTION "public"."lead_transferir"("p_lead" "uuid", "p_destino" "uuid", "p_dueno_esperado" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_validar_atributos"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_anteriores jsonb := '{}'::jsonb; v_fuera boolean; v_todos jsonb; v_activos jsonb; c record;
begin
  if jsonb_typeof(new.atributos) <> 'object' then
    raise exception 'Los atributos de un lead tienen que ser un objeto.' using errcode = '22023';
  end if;
  if tg_op = 'UPDATE' then
    v_anteriores := old.atributos;
  end if;
  v_fuera := tg_op = 'UPDATE' and (select auth.uid()) is not null and not public.en_cartera(new.id);
  if v_fuera then
    for c in select k.clave, k.etiqueta from public.leads_campos k where k.solo_cartera loop
      if new.atributos -> c.clave is distinct from v_anteriores -> c.clave then
        raise exception 'No tienes acceso a «%».', c.etiqueta using errcode = '42501', hint = 'atributos.' || c.clave;
      end if;
    end loop;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('clave', k.clave, 'etiqueta', k.etiqueta, 'tipo', k.tipo,
                                               'opciones', k.opciones, 'activo', k.activo)), '[]'::jsonb),
         coalesce(jsonb_agg(jsonb_build_object('clave', k.clave, 'etiqueta', k.etiqueta, 'tipo', k.tipo,
                                               'requerido', k.requerido and not (v_fuera and k.solo_cartera)))
                  filter (where k.activo), '[]'::jsonb)
    into v_todos, v_activos
  from public.leads_campos k;

  perform public._atributos_validar(new.atributos, v_activos, 'Los atributos de un lead tienen que ser un objeto.');
  perform public._lead_atributos_formato(new.atributos, v_anteriores, v_todos);
  return new;
end;
$$;


ALTER FUNCTION "public"."lead_validar_atributos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_vehiculos"("p_lead" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  if not public.puede_lead(p_lead, 'leads.ver') then
    return jsonb_build_object('vinculados', '[]'::jsonb, 'interesados', '[]'::jsonb, 'historial', '[]'::jsonb,
                              'puedo_actuar', false);
  end if;
  return jsonb_build_object(
    'vinculados', coalesce((
      select jsonb_agg(public._vehiculo_resumen(v) || jsonb_build_object(
               'desde', (select k.desde from public.vehiculos_vinculos k where k.vehiculo_id = v.id and k.hasta is null))
             order by v.numero desc)
        from (select * from public.vehiculos x where x.lead_id = p_lead order by x.numero desc limit 101) v), '[]'::jsonb),
    'interesados', coalesce((
      select jsonb_agg(public._vehiculo_resumen(v) || jsonb_build_object(
               'nota', i.nota, 'marcado_en', i.creado_en, 'vinculado_aqui', v.lead_id is not distinct from p_lead)
             order by i.creado_en desc, v.id)
        from (select * from public.vehiculos_interesados y where y.lead_id = p_lead order by y.creado_en desc limit 101) i
        join public.vehiculos v on v.id = i.vehiculo_id), '[]'::jsonb),
    'historial', coalesce((
      select jsonb_agg(jsonb_build_object('vehiculo_id', v.id, 'titulo', v.titulo, 'numero', v.numero,
                                          'desde', k.desde, 'hasta', k.hasta)
             order by k.hasta desc, k.id desc)
        from (select * from public.vehiculos_vinculos z where z.lead_id = p_lead and z.hasta is not null
               order by z.hasta desc, z.id desc limit 51) k
        join public.vehiculos v on v.id = k.vehiculo_id), '[]'::jsonb),
    'puedo_actuar', public.puede_actuar_lead(p_lead, 'leads.editar'));
end;
$$;


ALTER FUNCTION "public"."lead_vehiculos"("p_lead" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."lead_vehiculos"("p_lead" "uuid") IS 'Los vehículos de un lead que quien mira ve (vinculados, interesados y vínculos cerrados), y si puede actuar sobre el lead. De invocador: lo que no se ve no llega ni se cuenta.';



CREATE OR REPLACE FUNCTION "public"."lead_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if (new.nombre, new.tipo_lead_id, new.origen_lead_id, new.atributos, new.telefono_principal,
      new.telefono_cc, new.eliminado_en, new.lote_papelera_id)
     is distinct from
     (old.nombre, old.tipo_lead_id, old.origen_lead_id, old.atributos, old.telefono_principal,
      old.telefono_cc, old.eliminado_en, old.lote_papelera_id) then
    new.actualizado_en := greatest(clock_timestamp(), old.actualizado_en + interval '1 microsecond');
  else
    new.actualizado_en := old.actualizado_en;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."lead_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_visible_al_escribir"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.lead_id is not null and (select auth.uid()) is not null
     and (tg_op = 'INSERT' or new.lead_id is distinct from old.lead_id)
     and not public.puede_lead(new.lead_id, 'leads.ver') then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501', hint = 'lead_id';
  end if;
  return new;
end;
$$;


