CREATE OR REPLACE FUNCTION "public"."origen_apibara_agregar"("p_origen" "uuid", "p_rutas" "text"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_n int := 0; v_clave text; v_orden int; v_sufijo int;
begin
  perform public.assert_permiso('origenes.gestionar');
  perform 1 from public.origenes o where o.id = p_origen and o.tipo = 'subasta' for update;
  if not found then raise exception 'Ese origen no es de subasta o ya no existe.' using errcode = 'PT409'; end if;
  if p_rutas is null or cardinality(p_rutas) = 0 then return 0; end if;
  for r in select * from public.origen_apibara_rutas_sin_campo(p_origen) x where x.ruta = any (p_rutas) loop
    v_clave := left('apibara_' || regexp_replace(lower(r.ruta), '[^a-z0-9]+', '_', 'g'), 41);
    v_sufijo := 1;
    while exists (select 1 from public.origenes_campos c where c.origen_id = p_origen and c.clave = v_clave) loop
      v_sufijo := v_sufijo + 1;
      v_clave := left('apibara_' || regexp_replace(lower(r.ruta), '[^a-z0-9]+', '_', 'g'), 38) || '_' || v_sufijo;
    end loop;
    select coalesce(max(c.orden) + 10, 10) into v_orden from public.origenes_campos c where c.origen_id = p_origen;
    insert into public.origenes_campos (origen_id, clave, etiqueta, tipo, grupo, orden, clave_apibara, es_sistema)
    values (p_origen, v_clave, left(r.ruta, 60),
            case r.tipo when 'number' then 'numero' when 'boolean' then 'booleano' else 'texto' end::public.tipo_campo,
            'Otros datos de apibara', v_orden, r.ruta, false);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;


ALTER FUNCTION "public"."origen_apibara_agregar"("p_origen" "uuid", "p_rutas" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_apibara_completar"("p_origen" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int;
begin
  if not exists (select 1 from public.origenes o where o.id = p_origen and o.tipo = 'subasta') then
    return 0;
  end if;
  insert into public.origenes_campos (origen_id, clave, etiqueta, tipo, requerido, grupo, orden, en_tarjeta, filtrable, publico_web, clave_apibara, es_sistema)
  select p_origen, c.clave, c.etiqueta, c.tipo, false, c.grupo, c.orden, c.en_tarjeta, c.filtrable, c.publico_web, c.clave_apibara, c.es_sistema
  from public._apibara_catalogo() c
  where not exists (select 1 from public.origenes_campos x where x.origen_id = p_origen and x.clave = c.clave)
    and (c.clave_apibara is null or not exists (
      select 1 from public.origenes_campos x where x.origen_id = p_origen and x.clave_apibara = c.clave_apibara));
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


ALTER FUNCTION "public"."origen_apibara_completar"("p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_apibara_rutas_sin_campo"("p_origen" "uuid") RETURNS TABLE("ruta" "text", "tipo" "text", "ejemplo" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('origenes.gestionar');
  if not exists (select 1 from public.origenes o where o.id = p_origen and o.tipo = 'subasta') then
    return;
  end if;
  return query
  with ultimos as (
    select v.apibara_raw from public.vehiculos v
    where v.origen_id = p_origen and v.eliminado_en is null and v.apibara_raw is not null
    order by v.apibara_sync_en desc nulls last limit 200
  ), hojas as (
    select h.ruta, h.tipo, h.valor from ultimos u cross join lateral public._apibara_hojas(u.apibara_raw) h
  ), conocidas as (
    select c.clave_apibara as ruta from public.origenes_campos c where c.origen_id = p_origen and c.clave_apibara is not null
    union select k.clave_apibara from public._apibara_catalogo() k where k.clave_apibara is not null
  )
  select h.ruta, min(h.tipo), min(left(h.valor #>> '{}', 80))
  from hojas h
  where h.tipo not in ('array', 'null') and not public._apibara_ruta_ignorada(h.ruta)
    and not exists (select 1 from conocidas c where c.ruta = h.ruta)
  group by h.ruta
  order by h.ruta;
end;
$$;


ALTER FUNCTION "public"."origen_apibara_rutas_sin_campo"("p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_campo_crear"("p_origen" "uuid", "p_clave" "text", "p_etiqueta" "text", "p_tipo" "public"."tipo_campo", "p_opciones" "jsonb" DEFAULT '[]'::"jsonb", "p_requerido" boolean DEFAULT false, "p_grupo" "text" DEFAULT NULL::"text", "p_en_tarjeta" boolean DEFAULT false, "p_filtrable" boolean DEFAULT false, "p_publico_web" boolean DEFAULT false, "p_clave_apibara" "text" DEFAULT NULL::"text", "p_valor_defecto" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_origen public.origenes; v_etiqueta text; v_grupo text := nullif(btrim(p_grupo), '');
  v_apibara text := nullif(btrim(p_clave_apibara), ''); v_id uuid; v_version timestamptz; v_defecto jsonb;
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into v_origen from public.origenes o where o.id = p_origen for update;
  if not found then raise exception 'Ese origen ya no existe.' using errcode = 'PT409'; end if;
  if p_clave is null or p_clave !~ '^[a-z][a-z0-9_]{1,40}$' then
    raise exception 'La clave del campo usa minúsculas, números y guion bajo, y empieza con una letra.';
  end if;
  if public._origen_clave_reservada(p_clave) then
    raise exception '«%» ya es un dato común de todos los vehículos: no se crea como campo propio.', p_clave;
  end if;
  v_etiqueta := public._origen_nombre_valido(p_etiqueta, 'el nombre del campo', 60);
  perform public._origen_opciones_validas(coalesce(p_opciones, '[]'::jsonb));
  if p_tipo in ('opcion', 'multi_opcion') and jsonb_array_length(coalesce(p_opciones, '[]'::jsonb)) = 0 then
    raise exception 'Un campo de opciones necesita al menos una opción.';
  end if;
  if p_tipo not in ('opcion', 'multi_opcion') and jsonb_array_length(coalesce(p_opciones, '[]'::jsonb)) > 0 then
    raise exception 'Sólo un campo de opciones lleva opciones.';
  end if;
  if v_apibara is not null and v_origen.tipo <> 'subasta' then
    raise exception 'La clave de apibara sólo se usa en orígenes de subasta.';
  end if;
  if v_grupo is not null and length(v_grupo) > 40 then raise exception 'El nombre del grupo no puede pasar de 40 caracteres.'; end if;
  v_defecto := public._origen_valor_defecto(p_tipo, coalesce(p_opciones, '[]'::jsonb), p_valor_defecto);
  begin
    insert into public.origenes_campos (origen_id, clave, etiqueta, tipo, opciones, requerido, grupo, orden, en_tarjeta, filtrable, publico_web, clave_apibara, es_sistema, valor_defecto)
    values (p_origen, p_clave, v_etiqueta, p_tipo, coalesce(p_opciones, '[]'::jsonb), coalesce(p_requerido, false), v_grupo,
            coalesce((select max(c.orden) + 10 from public.origenes_campos c where c.origen_id = p_origen), 10),
            coalesce(p_en_tarjeta, false), coalesce(p_filtrable, false), coalesce(p_publico_web, false), v_apibara, false, v_defecto)
    returning id, actualizado_en into v_id, v_version;
  exception when unique_violation then
    raise exception 'Ya hay un campo con la clave «%» en este origen.', p_clave using errcode = '23505';
  end;
  return jsonb_build_object('id', v_id, 'actualizado_en', v_version);
end;
$_$;


ALTER FUNCTION "public"."origen_campo_crear"("p_origen" "uuid", "p_clave" "text", "p_etiqueta" "text", "p_tipo" "public"."tipo_campo", "p_opciones" "jsonb", "p_requerido" boolean, "p_grupo" "text", "p_en_tarjeta" boolean, "p_filtrable" boolean, "p_publico_web" boolean, "p_clave_apibara" "text", "p_valor_defecto" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_campo_eliminar"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.origenes_campos; v_con int;
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into c from public.origenes_campos x where x.id = p_campo for update;
  if not found then raise exception 'Ese campo ya no existe.' using errcode = 'PT409'; end if;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este campo mientras lo editabas.');
  if c.es_sistema then
    raise exception '«%» es un campo de fábrica: no se elimina. Puedes desactivarlo.', c.etiqueta using errcode = '23503';
  end if;
  v_con := public._origen_vehiculos_con_valor(c.origen_id, c.clave);
  if v_con > 0 then
    raise exception '% % tienen un valor en «%». Desactívalo para conservarlo.',
      v_con, case when v_con = 1 then 'vehículo' else 'vehículos' end, c.etiqueta using errcode = '23503';
  end if;
  delete from public.origenes_campos where id = p_campo;
end;
$$;


ALTER FUNCTION "public"."origen_campo_eliminar"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_campo_guardar"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.origenes_campos; v_origen public.origenes; v_clave text; v_nueva timestamptz;
  v_editables constant text[] := array['etiqueta', 'tipo', 'opciones', 'requerido', 'grupo', 'en_tarjeta', 'filtrable', 'publico_web', 'clave_apibara', 'activo', 'valor_defecto'];
  v_tipo public.tipo_campo; v_opciones jsonb; v_grupo text; v_apibara text; v_con int; v_orden smallint; v_defecto jsonb;
begin
  perform public.assert_permiso('origenes.gestionar');
  if p_cambios is null or jsonb_typeof(p_cambios) <> 'object' then
    raise exception 'Faltan los cambios a guardar.';
  end if;
  for v_clave in select jsonb_object_keys(p_cambios) loop
    if not (v_clave = any (v_editables)) then
      raise exception 'El dato «%» no se cambia desde el layout de campos.', v_clave;
    end if;
    if v_clave in ('etiqueta', 'tipo', 'opciones', 'requerido', 'en_tarjeta', 'filtrable', 'publico_web', 'activo') and p_cambios -> v_clave = 'null'::jsonb then
      raise exception 'El dato «%» no puede quedar vacío.', v_clave;
    end if;
  end loop;

  select * into c from public.origenes_campos x where x.id = p_campo for update;
  if not found then raise exception 'Ese campo ya no existe.' using errcode = 'PT409'; end if;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este campo mientras lo editabas.');
  select * into v_origen from public.origenes o where o.id = c.origen_id;

  v_tipo := coalesce((p_cambios ->> 'tipo')::public.tipo_campo, c.tipo);
  if v_tipo is distinct from c.tipo then
    if c.es_sistema then
      raise exception 'El tipo de «%» no cambia: es un campo de fábrica.', c.etiqueta;
    end if;
    v_con := public._origen_vehiculos_con_valor(c.origen_id, c.clave);
    if v_con > 0 then
      raise exception '% % ya tienen un valor en «%»: no se puede cambiar su tipo. Desactívalo y crea otro campo.',
        v_con, case when v_con = 1 then 'vehículo' else 'vehículos' end, c.etiqueta;
    end if;
  end if;

  v_opciones := coalesce(p_cambios -> 'opciones', c.opciones);
  if v_tipo not in ('opcion', 'multi_opcion') then
    v_opciones := '[]'::jsonb;
  else
    perform public._origen_opciones_validas(v_opciones);
  end if;

  if p_cambios ? 'valor_defecto' then
    v_defecto := public._origen_valor_defecto(v_tipo, v_opciones, p_cambios -> 'valor_defecto');
  elsif v_tipo is distinct from c.tipo then
    v_defecto := null;
  else
    begin
      v_defecto := public._origen_valor_defecto(v_tipo, v_opciones, c.valor_defecto);
    exception when invalid_parameter_value then
      v_defecto := null;
    end;
  end if;

  v_grupo := case when p_cambios ? 'grupo' then nullif(btrim(p_cambios ->> 'grupo'), '') else c.grupo end;
  if v_grupo is not null and length(v_grupo) > 40 then raise exception 'El nombre del grupo no puede pasar de 40 caracteres.'; end if;
  v_apibara := case when p_cambios ? 'clave_apibara' then nullif(btrim(p_cambios ->> 'clave_apibara'), '') else c.clave_apibara end;
  if v_apibara is not null and v_origen.tipo <> 'subasta' then
    raise exception 'La clave de apibara sólo se usa en orígenes de subasta.';
  end if;

  -- Cambiar de grupo lo manda al final del grupo nuevo.
  v_orden := c.orden;
  if v_grupo is distinct from c.grupo then
    select max(x.orden) + 1 into v_orden from public.origenes_campos x
    where x.origen_id = c.origen_id and x.id <> c.id and x.grupo is not distinct from v_grupo;
    v_orden := coalesce(v_orden, (select coalesce(max(x.orden), 0) + 10 from public.origenes_campos x where x.origen_id = c.origen_id));
  end if;

  update public.origenes_campos x set
    etiqueta = case when p_cambios ? 'etiqueta' then public._origen_nombre_valido(p_cambios ->> 'etiqueta', 'el nombre del campo', 60) else x.etiqueta end,
    tipo = v_tipo,
    opciones = v_opciones,
    requerido = coalesce((p_cambios ->> 'requerido')::boolean, x.requerido),
    grupo = v_grupo,
    en_tarjeta = coalesce((p_cambios ->> 'en_tarjeta')::boolean, x.en_tarjeta),
    filtrable = coalesce((p_cambios ->> 'filtrable')::boolean, x.filtrable),
    publico_web = coalesce((p_cambios ->> 'publico_web')::boolean, x.publico_web),
    clave_apibara = v_apibara,
    activo = coalesce((p_cambios ->> 'activo')::boolean, x.activo),
    valor_defecto = v_defecto,
    orden = v_orden
  where x.id = p_campo
  returning x.actualizado_en into v_nueva;
  if v_orden is distinct from c.orden then
    perform public._origen_campos_renumerar(c.origen_id);
  end if;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."origen_campo_guardar"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_campo_impacto"("p_campo" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.origenes_campos;
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into c from public.origenes_campos x where x.id = p_campo;
  if not found then raise exception 'Ese campo ya no existe.' using errcode = 'PT409'; end if;
  return public._campo_impacto(
    array(select v.atributos -> c.clave from public.vehiculos v where v.origen_id = c.origen_id), c.tipo);
end;
$$;


