CREATE OR REPLACE FUNCTION "public"."permisos_efectivos"("p_perspectiva" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("clave" "text", "origen_id" "uuid", "alcance" "public"."alcance_permiso")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with usa as (
    select (p_perspectiva is not null
            and public.tiene_permiso('equipo.roles.gestionar')
            and exists (select 1 from public.roles r where r.id = p_perspectiva)) as si
  )
  select m.clave, m.origen_id, m.alcance
  from public.mis_permisos() m cross join usa
  where not usa.si
  union
  select m.clave,
         coalesce(rp.origen_id, m.origen_id),
         (case when m.alcance = 'todos' and rp.alcance = 'todos' then 'todos' else 'propios' end)::public.alcance_permiso
  from public.mis_permisos() m
  join public.roles_permisos rp
    on rp.rol_id = p_perspectiva and rp.permiso_clave = m.clave
   and (m.origen_id is null or rp.origen_id is null or m.origen_id = rp.origen_id)
  cross join usa
  where usa.si;
$$;


ALTER FUNCTION "public"."permisos_efectivos"("p_perspectiva" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."plantilla_guardar_borrador"("p_origen" "uuid", "p_def" "jsonb", "p_nota" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  perform public.assert_permiso('cotizaciones.configurar', p_origen);
  if jsonb_typeof(p_def -> 'columnas') <> 'array' or jsonb_typeof(p_def -> 'grupos') <> 'array' then raise exception 'La plantilla necesita columnas y grupos.' using errcode = '22023'; end if;
  insert into public.plantillas_tarjeta (origen_id, estado, definicion, nota, creado_por) values (p_origen, 'borrador', p_def, p_nota, (select auth.uid()))
  on conflict (origen_id) where estado = 'borrador' do update set definicion = excluded.definicion, nota = excluded.nota returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."plantilla_guardar_borrador"("p_origen" "uuid", "p_def" "jsonb", "p_nota" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."plantilla_publicar"("p_origen" "uuid", "p_nota" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_borrador uuid; v_pub uuid; v_ver int;
begin
  perform public.assert_permiso('cotizaciones.configurar', p_origen);
  select id into v_pub from public.plantillas_tarjeta where origen_id = p_origen and estado = 'publicada';
  select id into v_borrador from public.plantillas_tarjeta where origen_id = p_origen and estado = 'borrador';
  if v_borrador is null then raise exception 'No hay borrador para publicar.' using errcode = '22023'; end if;
  select coalesce(max(version), 0) + 1 into v_ver from public.plantillas_tarjeta where origen_id = p_origen;
  update public.plantillas_tarjeta set estado = 'archivada' where id = v_pub;
  update public.plantillas_tarjeta set estado = 'publicada', version = v_ver, nota = p_nota, publicado_en = now() where id = v_borrador;
  return v_borrador;
end;
$$;


ALTER FUNCTION "public"."plantilla_publicar"("p_origen" "uuid", "p_nota" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_desbloquear"("p_lead" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_codigo text;
begin
  perform public._lead_mio(p_lead, 'leads.portal.gestionar', true);
  update public.accesos_portal x set intentos_fallidos = 0, bloqueado_hasta = null
  where x.lead_id = p_lead and x.habilitado and (x.intentos_fallidos > 0 or x.bloqueado_hasta is not null)
  returning x.codigo into v_codigo;
  if v_codigo is not null then
    perform public.registrar_actividad('portal.desbloqueado', 'accesos_portal', p_lead::text, null, null,
      jsonb_build_object('codigo', v_codigo));
  end if;
end;
$$;


ALTER FUNCTION "public"."portal_desbloquear"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_estado"("p_lead" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a public.accesos_portal;
begin
  perform public._lead_mio(p_lead, 'leads.portal.gestionar', false);
  select * into a from public.accesos_portal x where x.lead_id = p_lead;
  if not found then
    return jsonb_build_object('estado', 'sin_acceso');
  end if;
  return jsonb_build_object(
    'estado', case when not a.habilitado then 'revocado'
                   when a.bloqueado_hasta > now() then 'bloqueado'
                   else 'activo' end,
    'codigo', a.codigo,
    'otorgado_en', a.otorgado_en,
    'otorgado_por', public._portal_persona(a.otorgado_por),
    'ultimo_ingreso_en', a.ultimo_ingreso_en,
    'debe_cambiar_clave', a.debe_cambiar_clave,
    'bloqueado_hasta', case when a.habilitado and a.bloqueado_hasta > now() then a.bloqueado_hasta end,
    'revocado_en', case when not a.habilitado then a.revocado_en end,
    'revocado_por', case when not a.habilitado then public._portal_persona(a.revocado_por) end);
end;
$$;


ALTER FUNCTION "public"."portal_estado"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."previsualizar_cambio_fase"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_fase_destino" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_flujo uuid; v_actual uuid; v_destino public.fases; motivos text[] := '{}'; req jsonb; faltan jsonb;
begin
  if num_nonnulls(p_vehiculo, p_repuesto) <> 1 then raise exception 'Una unidad por vez.' using errcode = '22023'; end if;
  if p_vehiculo is not null then
    select f.id, v.fase_id into v_flujo, v_actual from public.vehiculos v join public.flujos f on f.origen_id = v.origen_id where v.id = p_vehiculo and v.eliminado_en is null;
    if v_flujo is null then return jsonb_build_object('ok', false, 'motivos', array['El vehículo no existe o está en la papelera.']); end if;
    if not public.puede_vehiculo(p_vehiculo, 'logistica.ver') then return jsonb_build_object('ok', false, 'motivos', array['Sin acceso a la logística de este vehículo.']); end if;
  else
    select f.id, i.fase_id into v_flujo, v_actual from public.repuestos_items i join public.flujos f on f.ambito = 'repuestos' where i.id = p_repuesto and i.eliminado_en is null;
    if v_flujo is null then return jsonb_build_object('ok', false, 'motivos', array['El repuesto no existe o no hay flujo de repuestos.']); end if;
  end if;
  select * into v_destino from public.fases where id = p_fase_destino;
  if v_destino.id is null or v_destino.flujo_id <> v_flujo then motivos := array_append(motivos, 'La fase destino no pertenece a este flujo.'); end if;
  if v_destino.id is not null and not v_destino.activa then motivos := array_append(motivos, 'La fase destino está jubilada.'); end if;
  if v_actual is null and v_destino.id is not null and not v_destino.es_inicial then motivos := array_append(motivos, 'La primera fase tiene que ser una inicial.'); end if;
  if v_actual is not null and v_destino.id is not null and not exists (select 1 from public.fases_transiciones where de_fase_id = v_actual and a_fase_id = v_destino.id) then
    motivos := array_append(motivos, 'No hay transición desde la fase actual.');
  end if;
  if v_destino.id is not null and not public._puede_mover(v_flujo, v_actual, v_destino.id) then motivos := array_append(motivos, 'Tu rol no puede mover a esta fase.'); end if;
  select jsonb_agg(to_jsonb(e)), jsonb_agg(to_jsonb(e)) filter (where e.bloqueante and not e.cumplido)
    into req, faltan from public.evaluar_requisitos(p_vehiculo, p_repuesto, p_fase_destino) e;
  if faltan is not null then motivos := array_append(motivos, ('Faltan ' || jsonb_array_length(faltan) || ' requisito(s) bloqueante(s).')); end if;
  return jsonb_build_object('ok', coalesce(array_length(motivos, 1), 0) = 0, 'motivos', motivos, 'fase_actual', v_actual, 'requisitos', coalesce(req, '[]'::jsonb), 'faltan', coalesce(faltan, '[]'::jsonb), 'nota_obligatoria', coalesce(v_destino.nota_obligatoria, false));
end;
$$;


ALTER FUNCTION "public"."previsualizar_cambio_fase"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_fase_destino" "uuid") OWNER TO "postgres";


