CREATE OR REPLACE FUNCTION "public"."puede_configurar_flujo"("p_flujo" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from public.flujos f where f.id = p_flujo
      and case when f.ambito = 'repuestos' then public.tiene_permiso('repuestos.configurar')
               else public.tiene_permiso('flujos.configurar', f.origen_id) end
  );
$$;


ALTER FUNCTION "public"."puede_configurar_flujo"("p_flujo" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."puede_cotizacion"("p_cot" "uuid", "p_clave" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((
    select a.alcance = 'todos'
        or (a.alcance = 'propios' and (c.creado_por = (select auth.uid()) or public.en_cartera(c.lead_id)))
      from public.cotizaciones c
     cross join lateral (select public.alcance_de(p_clave, c.origen_id) as alcance) a
     where c.id = p_cot and c.eliminado_en is null
  ), false);
$$;


ALTER FUNCTION "public"."puede_cotizacion"("p_cot" "uuid", "p_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."puede_estar_en_la_rueda"("p_usuario" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from public.perfiles p where p.id = p_usuario and p.activo and not p.bloqueado)
     and exists (select 1 from public.usuarios_roles ur
                   join public.roles_permisos rp on rp.rol_id = ur.rol_id and rp.permiso_clave = 'web.cola.participar'
                  where ur.usuario_id = p_usuario);
$$;


ALTER FUNCTION "public"."puede_estar_en_la_rueda"("p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."puede_evento"("p_evento" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from public.eventos e
    where e.id = p_evento and e.eliminado_en is null
      and (e.creado_por = (select auth.uid()) or e.visibilidad = 'publico'
        or exists (select 1 from public.eventos_destinatarios d where d.evento_id = e.id and d.usuario_id = (select auth.uid()))
        or public.tiene_permiso('agenda.ver_todo'))
  );
$$;


ALTER FUNCTION "public"."puede_evento"("p_evento" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."puede_lead"("p_lead" "uuid", "p_clave" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from public.leads l
     where l.id = p_lead
       and public._lead_visible_para(l.eliminado_en, l.cartera, public.alcance_de(p_clave), (select auth.uid()),
                                     (select public._bajas_en_curso()))
  );
$$;


ALTER FUNCTION "public"."puede_lead"("p_lead" "uuid", "p_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."puede_objeto_de_vehiculo"("p_nombre" "text", "p_clave" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  select case
    when split_part(p_nombre, '/', 1) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then public.puede_vehiculo(split_part(p_nombre, '/', 1)::uuid, p_clave)
    else false
  end;
$_$;


ALTER FUNCTION "public"."puede_objeto_de_vehiculo"("p_nombre" "text", "p_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."puede_repuesto"("p_item" "uuid", "p_clave" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from public.repuestos_items i where i.id = p_item and i.eliminado_en is null and public.tiene_permiso(p_clave));
$$;


ALTER FUNCTION "public"."puede_repuesto"("p_item" "uuid", "p_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."puede_unidad"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_clave_v" "text", "p_clave_r" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when p_vehiculo is not null then public.puede_vehiculo(p_vehiculo, p_clave_v)
              when p_repuesto is not null then public.puede_repuesto(p_repuesto, p_clave_r)
              else false end;
$$;


ALTER FUNCTION "public"."puede_unidad"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_clave_v" "text", "p_clave_r" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."puede_vehiculo"("p_vehiculo" "uuid", "p_clave" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((
    select case public.alcance_de(p_clave, v.origen_id)
             when 'todos' then true
             when 'propios' then v.creado_por = (select auth.uid()) or (v.lead_id is not null and public.en_cartera(v.lead_id))
             else false
           end
      from public.vehiculos v
     where v.id = p_vehiculo and v.eliminado_en is null
  ), false);
$$;


ALTER FUNCTION "public"."puede_vehiculo"("p_vehiculo" "uuid", "p_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rbac_asignar_rol"("p_usuario" "uuid", "p_rol" "uuid", "p_principal" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('equipo.usuarios.gestionar');
  if not public.rol_dominado(p_rol) then raise exception 'No puedes asignar un rol con permisos que no tienes.' using errcode = '42501'; end if;
  insert into public.usuarios_roles (usuario_id, rol_id, es_principal, asignado_por) values (p_usuario, p_rol, p_principal, (select auth.uid()))
  on conflict (usuario_id, rol_id) do update set es_principal = excluded.es_principal;
  if p_principal then update public.usuarios_roles set es_principal = false where usuario_id = p_usuario and rol_id <> p_rol; end if;
  perform public.registrar_actividad('usuario.rol_asignado', 'usuarios_roles', p_usuario::text, null, jsonb_build_object('rol', p_rol));
end;
$$;


ALTER FUNCTION "public"."rbac_asignar_rol"("p_usuario" "uuid", "p_rol" "uuid", "p_principal" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rbac_crear_rol"("p_clave" "text", "p_nombre" "text", "p_color" "text" DEFAULT NULL::"text", "p_descripcion" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  perform public.assert_permiso('equipo.roles.gestionar');
  begin
    insert into public.roles (clave, nombre, color, descripcion) values (p_clave, p_nombre, p_color, p_descripcion) returning id into v_id;
  exception when unique_violation then
    raise exception 'Ya existe un rol con ese nombre.' using errcode = '23505';
  end;
  perform public.registrar_actividad('rol.creado', 'roles', v_id::text, null, jsonb_build_object('clave', p_clave, 'nombre', p_nombre));
  return v_id;
end;
$$;


ALTER FUNCTION "public"."rbac_crear_rol"("p_clave" "text", "p_nombre" "text", "p_color" "text", "p_descripcion" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rbac_eliminar_rol"("p_rol" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_sistema boolean; v_personas int;
begin
  perform public.assert_permiso('equipo.roles.gestionar');
  perform public._rol_para_editar(p_rol, p_actualizado_en_esperado);
  select es_sistema into v_sistema from public.roles where id = p_rol;
  if v_sistema then raise exception 'Un rol de sistema no se elimina.' using errcode = '42501'; end if;
  if not public.rol_dominado(p_rol) then raise exception 'No puedes eliminar un rol con permisos que no tienes.' using errcode = '42501'; end if;
  select count(*) into v_personas from public.usuarios_roles where rol_id = p_rol;
  if v_personas = 1 then raise exception 'Una persona tiene este rol: quítaselo antes de eliminarlo.' using errcode = '23503'; end if;
  if v_personas > 1 then raise exception '% personas tienen este rol: quítaselo antes de eliminarlo.', v_personas using errcode = '23503'; end if;
  delete from public.roles where id = p_rol;
  perform public.registrar_actividad('rol.eliminado', 'roles', p_rol::text, null, null);
end;
$$;


ALTER FUNCTION "public"."rbac_eliminar_rol"("p_rol" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rbac_guardian"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.perfiles) and not exists (
    select 1 from public.perfiles p
    where p.activo and not p.bloqueado
      and (p.invitado_en is null or p.invitacion_aceptada_en is not null)
      and exists (
        select 1 from public.usuarios_roles ur join public.roles_permisos rp on rp.rol_id = ur.rol_id
        where ur.usuario_id = p.id and rp.permiso_clave = 'equipo.roles.gestionar' and rp.origen_id is null)
      and exists (
        select 1 from public.usuarios_roles ur join public.roles_permisos rp on rp.rol_id = ur.rol_id
        where ur.usuario_id = p.id and rp.permiso_clave = 'equipo.usuarios.gestionar' and rp.origen_id is null)
  ) then
    raise exception 'Siempre tiene que quedar alguien activo que gestione los roles y las personas del equipo.' using errcode = '23514';
  end if;
  if exists (select 1 from public.roles where clave = 'dueno') and exists (
    select 1 from public.permisos pe
    where pe.modulo = 'equipo'
      and not exists (
        select 1 from public.roles r join public.roles_permisos rp on rp.rol_id = r.id
        where r.clave = 'dueno' and rp.permiso_clave = pe.clave and rp.origen_id is null and rp.alcance = 'todos')
  ) then
    raise exception 'El rol dueño no puede perder los permisos de equipo.' using errcode = '23514';
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."rbac_guardian"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rbac_otorgar"("p_rol" "uuid", "p_clave" "text", "p_actualizado_en_esperado" timestamp with time zone, "p_origen" "uuid" DEFAULT NULL::"uuid", "p_alcance" "public"."alcance_permiso" DEFAULT 'todos'::"public"."alcance_permiso") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_por_origen boolean; v_con_alcance boolean;
begin
  perform public.assert_permiso('equipo.roles.gestionar');
  perform public._rol_para_editar(p_rol, p_actualizado_en_esperado);
  select por_origen, con_alcance into v_por_origen, v_con_alcance from public.permisos where clave = p_clave;
  if not found then raise exception 'Permiso desconocido: %', p_clave using errcode = '22023'; end if;
  if p_origen is not null and not v_por_origen then raise exception 'El permiso % no se acota por origen.', p_clave using errcode = '22023'; end if;
  if p_alcance = 'propios' and not v_con_alcance then raise exception 'El permiso % no distingue entre lo propio y todo.', p_clave using errcode = '22023'; end if;
  if not public.rol_dominado(p_rol) then raise exception 'No puedes editar un rol con permisos que no tienes.' using errcode = '42501'; end if;
  if not public.concesion_dominada(p_clave, p_origen, p_alcance) then raise exception 'No puedes otorgar «%» con ese origen y alcance: no lo tienes.', p_clave using errcode = '42501'; end if;
  insert into public.roles_permisos (rol_id, permiso_clave, origen_id, alcance) values (p_rol, p_clave, p_origen, p_alcance)
  on conflict (rol_id, permiso_clave, origen_id) do update set alcance = excluded.alcance;
  perform public.registrar_actividad('rol.permiso_otorgado', 'roles_permisos', p_rol::text, null, jsonb_build_object('clave', p_clave, 'origen', p_origen, 'alcance', p_alcance));
  return public._rol_tocar(p_rol);
end;
$$;


ALTER FUNCTION "public"."rbac_otorgar"("p_rol" "uuid", "p_clave" "text", "p_actualizado_en_esperado" timestamp with time zone, "p_origen" "uuid", "p_alcance" "public"."alcance_permiso") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rbac_quitar_rol"("p_usuario" "uuid", "p_rol" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('equipo.usuarios.gestionar');
  if not public.rol_dominado(p_rol) then raise exception 'No puedes quitar un rol con permisos que no tienes.' using errcode = '42501'; end if;
  delete from public.usuarios_roles where usuario_id = p_usuario and rol_id = p_rol;
  perform public.registrar_actividad('usuario.rol_quitado', 'usuarios_roles', p_usuario::text, jsonb_build_object('rol', p_rol), null);
end;
$$;


ALTER FUNCTION "public"."rbac_quitar_rol"("p_usuario" "uuid", "p_rol" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rbac_revocar"("p_rol" "uuid", "p_clave" "text", "p_actualizado_en_esperado" timestamp with time zone, "p_origen" "uuid" DEFAULT NULL::"uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('equipo.roles.gestionar');
  perform public._rol_para_editar(p_rol, p_actualizado_en_esperado);
  if not public.rol_dominado(p_rol) then raise exception 'No puedes editar un rol con permisos que no tienes.' using errcode = '42501'; end if;
  delete from public.roles_permisos where rol_id = p_rol and permiso_clave = p_clave and origen_id is not distinct from p_origen;
  perform public.registrar_actividad('rol.permiso_revocado', 'roles_permisos', p_rol::text, jsonb_build_object('clave', p_clave, 'origen', p_origen), null);
  return public._rol_tocar(p_rol);
end;
$$;


ALTER FUNCTION "public"."rbac_revocar"("p_rol" "uuid", "p_clave" "text", "p_actualizado_en_esperado" timestamp with time zone, "p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reasignar_tarea"("p_tarea" "uuid", "p_responsable" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('agenda.tareas.asignar');
  if not exists (select 1 from public.tareas where id = p_tarea and (creado_por = (select auth.uid()) or responsable_id = (select auth.uid()))) then raise exception 'Sin acceso a la tarea.' using errcode = '42501'; end if;
  if not public.usuario_tiene_permiso(p_responsable, 'agenda.tareas.recibir') then raise exception 'Esa persona no puede recibir tareas.' using errcode = '23514'; end if;
  update public.tareas set responsable_id = p_responsable where id = p_tarea;
end;
$$;


ALTER FUNCTION "public"."reasignar_tarea"("p_tarea" "uuid", "p_responsable" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recordatorio_completar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_completado" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.recordatorios; n public.recordatorios;
begin
  r := public._recordatorio_mio(p_id);
  if r.eliminado_en is not null then
    raise exception 'No encontramos este recordatorio.' using errcode = '42501';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if p_completado is null then
    raise exception 'Falta decir si se completa o se reabre.' using errcode = '22023';
  end if;
  if (r.completado_en is not null) = p_completado then
    return jsonb_build_object('resultado', 'sin_cambios', 'recordatorio', public._recordatorio_json(r));
  end if;
  if r.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._recordatorio_conflicto(r.actualizado_en);
  end if;
  update public.recordatorios x set
    completado_en = case when p_completado then now() end,
    actualizado_en = greatest(clock_timestamp(), r.actualizado_en + interval '1 microsecond')
  where x.id = r.id
  returning * into n;
  return jsonb_build_object('resultado', case when p_completado then 'completado' else 'reabierto' end,
                            'recordatorio', public._recordatorio_json(n));
end;
$$;


ALTER FUNCTION "public"."recordatorio_completar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_completado" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recordatorio_crear"("p_id" "uuid", "p_lead" "uuid", "p_titulo" "text", "p_recordar_en" timestamp with time zone, "p_vehiculo" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.recordatorios; v_lead uuid; v_titulo text; v_cuando timestamptz; v_vehiculo uuid;
begin
  perform public.assert_activo();
  if p_lead is not null then
    v_lead := (public._lead_mio(p_lead)).id;
  end if;
  if p_id is null then
    raise exception 'Falta el identificador del recordatorio.' using errcode = '22023';
  end if;
  select * into r from public.recordatorios x where x.id = p_id;
  if found then
    if r.usuario_id = (select auth.uid()) and r.lead_id is not distinct from v_lead then
      return jsonb_build_object('resultado', 'repetido', 'recordatorio', public._recordatorio_json(r));
    end if;
    raise exception 'No pudimos guardar este recordatorio. Vuelve a intentarlo.' using errcode = '22023';
  end if;
  v_titulo := public._recordatorio_titulo(p_titulo, 'titulo');
  v_cuando := public._recordatorio_cuando(p_recordar_en, 'recordar_en');
  v_vehiculo := public._vehiculo_para_nota(p_vehiculo);
  begin
    insert into public.recordatorios (id, usuario_id, lead_id, vehiculo_id, titulo, recordar_en, actualizado_en)
    values (p_id, (select auth.uid()), v_lead, v_vehiculo, v_titulo, v_cuando, clock_timestamp())
    returning * into r;
  exception when unique_violation then
    select * into r from public.recordatorios x where x.id = p_id;
    if r.usuario_id = (select auth.uid()) and r.lead_id is not distinct from v_lead then
      return jsonb_build_object('resultado', 'repetido', 'recordatorio', public._recordatorio_json(r));
    end if;
    raise exception 'No pudimos guardar este recordatorio. Vuelve a intentarlo.' using errcode = '22023';
  end;
  return jsonb_build_object('resultado', 'creado', 'recordatorio', public._recordatorio_json(r));
end;
$$;


ALTER FUNCTION "public"."recordatorio_crear"("p_id" "uuid", "p_lead" "uuid", "p_titulo" "text", "p_recordar_en" timestamp with time zone, "p_vehiculo" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recordatorio_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.recordatorios; n public.recordatorios;
begin
  r := public._recordatorio_mio(p_id);
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if r.eliminado_en is not null then
    return jsonb_build_object('resultado', 'sin_cambios', 'recordatorio', public._recordatorio_json(r));
  end if;
  if r.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._recordatorio_conflicto(r.actualizado_en);
  end if;
  update public.recordatorios x set
    eliminado_en = now(),
    actualizado_en = greatest(clock_timestamp(), r.actualizado_en + interval '1 microsecond')
  where x.id = r.id
  returning * into n;
  return jsonb_build_object('resultado', 'eliminado', 'recordatorio', public._recordatorio_json(n));
end;
$$;


ALTER FUNCTION "public"."recordatorio_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recordatorio_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.recordatorios; n public.recordatorios; v_titulo text; v_cuando timestamptz; v_vehiculo uuid; v_k text;
begin
  r := public._recordatorio_mio(p_id);
  if r.eliminado_en is not null then
    raise exception 'No encontramos este recordatorio.' using errcode = '42501';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if p_cambios is null or jsonb_typeof(p_cambios) <> 'object' then
    raise exception 'Los cambios de un recordatorio tienen que ser un objeto.' using errcode = '22023';
  end if;
  for v_k in select jsonb_object_keys(p_cambios) loop
    if v_k not in ('titulo', 'recordar_en', 'vehiculo_id') then
      raise exception 'El dato «%» no es de un recordatorio.', v_k using errcode = '22023', hint = v_k;
    end if;
  end loop;
  v_titulo := r.titulo;
  v_cuando := r.recordar_en;
  v_vehiculo := r.vehiculo_id;
  if p_cambios ? 'titulo' then
    v_titulo := public._recordatorio_titulo(p_cambios ->> 'titulo', 'titulo');
  end if;
  if p_cambios ? 'recordar_en' then
    begin
      v_cuando := (p_cambios ->> 'recordar_en')::timestamptz;
    exception when others then
      v_cuando := null;
    end;
    if v_cuando is distinct from r.recordar_en then
      v_cuando := public._recordatorio_cuando(v_cuando, 'recordar_en');
    end if;
  end if;
  -- Como en los seguimientos: el vehículo sólo se mira si cambia.
  if p_cambios ? 'vehiculo_id' then
    v_vehiculo := public._uuid_de(p_cambios -> 'vehiculo_id', 'vehiculo_id');
    if v_vehiculo is distinct from r.vehiculo_id then
      v_vehiculo := public._vehiculo_para_nota(v_vehiculo);
    end if;
  end if;
  if (v_titulo, v_cuando, v_vehiculo) is not distinct from (r.titulo, r.recordar_en, r.vehiculo_id) then
    return jsonb_build_object('resultado', 'sin_cambios', 'recordatorio', public._recordatorio_json(r));
  end if;
  if r.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._recordatorio_conflicto(r.actualizado_en);
  end if;
  update public.recordatorios x set
    titulo = v_titulo, recordar_en = v_cuando, vehiculo_id = v_vehiculo,
    notificado_en = case when v_cuando is distinct from r.recordar_en then null else r.notificado_en end,
    actualizado_en = greatest(clock_timestamp(), r.actualizado_en + interval '1 microsecond')
  where x.id = r.id
  returning * into n;
  return jsonb_build_object('resultado', 'guardado', 'recordatorio', public._recordatorio_json(n));
end;
$$;


ALTER FUNCTION "public"."recordatorio_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recordatorio_restaurar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.recordatorios; n public.recordatorios;
begin
  r := public._recordatorio_mio(p_id);
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if r.eliminado_en is null then
    return jsonb_build_object('resultado', 'sin_cambios', 'recordatorio', public._recordatorio_json(r));
  end if;
  if r.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._recordatorio_conflicto(r.actualizado_en);
  end if;
  update public.recordatorios x set
    eliminado_en = null,
    actualizado_en = greatest(clock_timestamp(), r.actualizado_en + interval '1 microsecond')
  where x.id = r.id
  returning * into n;
  return jsonb_build_object('resultado', 'restaurado', 'recordatorio', public._recordatorio_json(n));
end;
$$;


ALTER FUNCTION "public"."recordatorio_restaurar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recordatorios_notificar"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; n int := 0;
begin
  for r in select * from public.recordatorios where notificado_en is null and completado_en is null and recordar_en <= now() limit 200 loop
    perform public.notificar(r.usuario_id, 'recordatorio', r.titulo, null, 'recordatorio', r.id, case when r.lead_id is not null then '/leads/' || r.lead_id else '/agenda' end, true);
    update public.recordatorios set notificado_en = now() where id = r.id;
    n := n + 1;
  end loop;
  return n;
end;
$$;


