CREATE OR REPLACE FUNCTION "public"."tipo_cambio_crear"("p_clave" "text", "p_nombre" "text", "p_moneda_de" "text", "p_moneda_a" "text", "p_valor" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_clave text := lower(btrim(coalesce(p_clave, '')));
  v_de text := upper(btrim(coalesce(p_moneda_de, '')));
  v_a text := upper(btrim(coalesce(p_moneda_a, '')));
  v_id uuid;
begin
  perform public.assert_permiso('empresa.tipos_cambio.gestionar');
  if v_clave !~ '^[a-z][a-z0-9_]{1,30}$' then
    raise exception 'La clave va en minúsculas, sin espacios y empieza con una letra.';
  end if;
  if nullif(btrim(p_nombre), '') is null then
    raise exception 'El tipo de cambio necesita un nombre.';
  end if;
  -- NaN es mayor que cualquier número para Postgres: pasaría el `<= 0` y el CHECK de la tabla.
  if p_valor is null or p_valor = 'NaN'::numeric or p_valor <= 0 then
    raise exception 'El valor tiene que ser mayor que cero.';
  end if;
  if v_de = v_a then
    raise exception 'Un tipo de cambio va entre dos monedas distintas.';
  end if;
  if (select count(*) from public.monedas m where m.activa and m.codigo::text in (v_de, v_a)) <> 2 then
    raise exception 'Las dos monedas tienen que estar activas.';
  end if;
  if exists (select 1 from public.tipos_cambio t where t.clave = v_clave) then
    raise exception 'Ya existe un tipo de cambio con la clave «%».', v_clave using errcode = '23505';
  end if;
  insert into public.tipos_cambio (clave, nombre, moneda_de, moneda_a, valor, es_default, orden)
  values (v_clave, btrim(p_nombre), v_de, v_a, p_valor,
          not exists (select 1 from public.tipos_cambio t where t.moneda_de::text = v_de and t.moneda_a::text = v_a and t.es_default),
          (select coalesce(max(t.orden), -1) + 1 from public.tipos_cambio t))
  returning id into v_id;
  return v_id;
end;
$_$;


ALTER FUNCTION "public"."tipo_cambio_crear"("p_clave" "text", "p_nombre" "text", "p_moneda_de" "text", "p_moneda_a" "text", "p_valor" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tipo_cambio_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text" DEFAULT NULL::"text", "p_valor" numeric DEFAULT NULL::numeric, "p_activo" boolean DEFAULT NULL::boolean, "p_es_default" boolean DEFAULT NULL::boolean) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.tipos_cambio;
  v_nueva timestamptz;
begin
  perform public.assert_permiso('empresa.tipos_cambio.gestionar');
  select * into v from public.tipos_cambio t where t.id = p_id for update;
  if not found then
    raise exception 'Ese tipo de cambio ya no existe.' using errcode = 'PT409';
  end if;
  perform public._exigir_version(v.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este tipo de cambio mientras lo editabas.');
  if p_valor is not null and (p_valor = 'NaN'::numeric or p_valor <= 0) then
    raise exception 'El valor tiene que ser mayor que cero.';
  end if;
  if v.es_default and p_es_default = false then
    raise exception 'Siempre hay un tipo de cambio por defecto entre dos monedas: marca otro para cambiarlo.';
  end if;
  if coalesce(p_es_default, v.es_default) and not coalesce(p_activo, v.activo) then
    raise exception 'El tipo de cambio por defecto no se desactiva: marca otro por defecto antes.';
  end if;
  if p_activo and not v.activo
     and (select count(*) from public.monedas m where m.activa and m.codigo in (v.moneda_de, v.moneda_a)) <> 2 then
    raise exception 'Para activarlo, las dos monedas tienen que estar activas.';
  end if;
  if p_es_default and not v.es_default then
    update public.tipos_cambio t set es_default = false
    where t.moneda_de = v.moneda_de and t.moneda_a = v.moneda_a and t.es_default and t.id <> v.id;
  end if;
  update public.tipos_cambio t set
    nombre = coalesce(nullif(btrim(p_nombre), ''), t.nombre),
    valor = coalesce(p_valor, t.valor),
    activo = coalesce(p_activo, t.activo),
    es_default = coalesce(p_es_default, t.es_default)
  where t.id = v.id
  returning t.actualizado_en into v_nueva;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."tipo_cambio_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text", "p_valor" numeric, "p_activo" boolean, "p_es_default" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tipo_lead_auditar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and new.actualizado_en is not distinct from old.actualizado_en then
    return null;
  end if;
  insert into public.actividad (accion, actor_id, tabla, registro_id, antes, despues)
  values ('tipos_lead.' || lower(tg_op), (select auth.uid()), 'tipos_lead', coalesce(new.id, old.id)::text,
          case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end,
          case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end);
  return null;
end;
$$;


ALTER FUNCTION "public"."tipo_lead_auditar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tipo_lead_clase_vigente"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and new.clase is distinct from old.clase then
    raise exception 'La clase de un tipo no cambia: crea otro de la clase que necesitas.' using errcode = '22023', hint = 'clase';
  end if;
  if old.activo and (tg_op = 'DELETE' or not new.activo) then
    perform pg_advisory_xact_lock(hashtextextended('tipos_lead:' || old.clase::text, 0));
    if not exists (select 1 from public.tipos_lead t where t.clase = old.clase and t.activo and t.id <> old.id) then
      raise exception 'Es el único tipo activo de la clase «%»: activa o crea otro antes.', old.clase
        using errcode = '22023', hint = 'activo';
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."tipo_lead_clase_vigente"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tipo_lead_crear"("p_id" "uuid", "p_nombre" "text", "p_clase" "text", "p_icono" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_nombre text; v_version timestamptz; v_clase public.clase_tipo_lead; v_icono text; v_tope integer := public._tipos_lead_tope();
begin
  perform public.assert_permiso('leads.configurar');
  lock table public.tipos_lead in share row exclusive mode;
  if p_id is null then
    raise exception 'Falta el identificador del intento.' using errcode = '22023';
  end if;
  select t.actualizado_en into v_version from public.tipos_lead t where t.id = p_id;
  if found then
    return jsonb_build_object('id', p_id, 'actualizado_en', v_version, 'repetido', true, 'lista', public._tipos_lead_lista());
  end if;
  v_nombre := public._tipo_lead_nombre(p_nombre);
  v_icono := public._icono_del_catalogo(p_icono);
  if p_clase is null or p_clase not in ('prospecto', 'cliente') then
    raise exception 'Elige la clase del tipo: prospecto o cliente.' using errcode = '22023', hint = 'clase';
  end if;
  v_clase := p_clase::public.clase_tipo_lead;
  if (select count(*) from (select 1 from public.tipos_lead limit v_tope) t) >= v_tope then
    raise exception 'Ya hay % tipos de lead, que es el máximo. Elimina uno sin leads o desactiva los que no uses.', v_tope
      using errcode = '22023', hint = 'nombre';
  end if;
  if exists (select 1 from public.tipos_lead t where lower(btrim(t.nombre)) = lower(v_nombre)) then
    raise exception 'Ya hay un tipo «%».', v_nombre using errcode = '23505', hint = 'nombre';
  end if;
  insert into public.tipos_lead (id, clave, nombre, clase, icono, orden)
  values (p_id, public._tipo_lead_clave(v_nombre), v_nombre, v_clase, v_icono,
          coalesce((select max(t.orden) + 10 from public.tipos_lead t), 10))
  returning actualizado_en into v_version;
  return jsonb_build_object('id', p_id, 'actualizado_en', v_version, 'repetido', false, 'lista', public._tipos_lead_lista());
end;
$$;


ALTER FUNCTION "public"."tipo_lead_crear"("p_id" "uuid", "p_nombre" "text", "p_clase" "text", "p_icono" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tipo_lead_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.tipos_lead; v_mensaje text;
begin
  perform public.assert_permiso('leads.configurar');
  lock table public.tipos_lead in share row exclusive mode;
  select * into o from public.tipos_lead x where x.id = p_id for update;
  if not found then
    raise exception 'Ese tipo ya no existe.' using errcode = 'PT409';
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este tipo mientras lo editabas.');
  v_mensaje := format('«%s» ya tiene leads: no se elimina. Desactívalo para que no se ofrezca a los nuevos.', o.nombre);
  if exists (select 1 from public.leads l where l.tipo_lead_id >= p_id and l.tipo_lead_id <= p_id) then
    raise exception '%', v_mensaje using errcode = '23503';
  end if;
  begin
    delete from public.tipos_lead x where x.id = p_id;
  exception when foreign_key_violation then
    raise exception '%', v_mensaje using errcode = '23503';
  end;
  return jsonb_build_object('lista', public._tipos_lead_lista());
end;
$$;


