CREATE OR REPLACE FUNCTION "web"."portal_cambiar_clave"("p_lead" "uuid", "p_otorgado_en" timestamp with time zone, "p_actual" "text", "p_nueva" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a public.accesos_portal; v_ok boolean;
begin
  select x.* into a from public.accesos_portal x join public.leads l on l.id = x.lead_id
  where x.lead_id = p_lead and x.habilitado and x.otorgado_en = p_otorgado_en and l.eliminado_en is null
  for update of x;
  v_ok := coalesce(a.clave_hash, public._portal_hash_falso())
          = extensions.crypt(coalesce(p_actual, ''), coalesce(a.clave_hash, public._portal_hash_falso()));
  if a.lead_id is null or a.bloqueado_hasta > now() then
    return false;
  end if;
  if not v_ok then
    update public.accesos_portal x
    set intentos_fallidos = case when x.intentos_fallidos + 1 >= 5 then 0 else x.intentos_fallidos + 1 end,
        bloqueado_hasta = case when x.intentos_fallidos + 1 >= 5 then now() + interval '15 minutes' end
    where x.lead_id = a.lead_id;
    return false;
  end if;
  perform public._portal_clave_validar(p_nueva);
  update public.accesos_portal x
  set clave_hash = extensions.crypt(p_nueva, extensions.gen_salt('bf', 10)), debe_cambiar_clave = false,
      intentos_fallidos = 0, bloqueado_hasta = null
  where x.lead_id = a.lead_id;
  return true;
end;
$$;


ALTER FUNCTION "web"."portal_cambiar_clave"("p_lead" "uuid", "p_otorgado_en" timestamp with time zone, "p_actual" "text", "p_nueva" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "web"."portal_documento_ruta"("p_lead" "uuid", "p_otorgado_en" timestamp with time zone, "p_documento" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select d.ruta from public.documentos d join public.vehiculos v on v.id = d.vehiculo_id
  where d.id = p_documento and v.lead_id = p_lead and d.visible_portal and d.estado <> 'rechazado'
    and d.eliminado_en is null and v.eliminado_en is null
    and (public._portal_vigente(p_lead, p_otorgado_en)).lead_id is not null;
$$;


ALTER FUNCTION "web"."portal_documento_ruta"("p_lead" "uuid", "p_otorgado_en" timestamp with time zone, "p_documento" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "web"."portal_login"("p_codigo" "text", "p_clave" "text") RETURNS TABLE("lead_id" "uuid", "nombre" "text", "debe_cambiar_clave" boolean, "otorgado_en" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_codigo text := public._portal_codigo_normal(left(p_codigo, 40));
  a public.accesos_portal; v_nombre text; v_ok boolean;
begin
  if length(v_codigo) between 7 and 9 then
    select * into a from public.accesos_portal x where replace(x.codigo, '-', '') = v_codigo for update;
  end if;
  v_ok := coalesce(a.clave_hash, public._portal_hash_falso())
          = extensions.crypt(coalesce(p_clave, ''), coalesce(a.clave_hash, public._portal_hash_falso()));
  if a.lead_id is null or not a.habilitado or a.bloqueado_hasta > now() then
    return;
  end if;
  select l.nombre into v_nombre from public.leads l where l.id = a.lead_id and l.eliminado_en is null;
  if not found then
    return;
  end if;
  if not v_ok then
    update public.accesos_portal x
    set intentos_fallidos = case when x.intentos_fallidos + 1 >= 5 then 0 else x.intentos_fallidos + 1 end,
        bloqueado_hasta = case when x.intentos_fallidos + 1 >= 5 then now() + interval '15 minutes' end
    where x.lead_id = a.lead_id;
    return;
  end if;
  update public.accesos_portal x set intentos_fallidos = 0, bloqueado_hasta = null, ultimo_ingreso_en = now()
  where x.lead_id = a.lead_id;
  return query select a.lead_id, v_nombre, a.debe_cambiar_clave, a.otorgado_en;
end;
$$;


ALTER FUNCTION "web"."portal_login"("p_codigo" "text", "p_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "web"."portal_snapshot"("p_lead" "uuid", "p_otorgado_en" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (public._portal_vigente(p_lead, p_otorgado_en)).lead_id is null then
    return null;
  end if;
  return jsonb_build_object(
    'cliente', (select jsonb_build_object('nombre', l.nombre) from public.leads l where l.id = p_lead),
    'asesor', (select jsonb_build_object('nombre', p.nombre, 'whatsapp', p.whatsapp_web, 'avatar', p.avatar_ruta) from public.leads_asesores la join public.perfiles p on p.id = la.usuario_id where la.lead_id = p_lead and la.tipo_acceso = 'dueno' and la.revocado_en is null and la.usuario_id <> all ((select public._bajas_en_curso())::uuid[])),
    'vehiculos', coalesce((select jsonb_agg(jsonb_build_object(
        'id', v.id, 'titulo', v.titulo, 'anio', v.anio, 'vin_parcial', case when v.vin is not null then left(v.vin, 3) || '•••••' || right(v.vin, 4) end,
        'imagenes', (select coalesce(jsonb_agg(i.ruta order by i.es_portada desc, i.orden), '[]'::jsonb) from public.vehiculos_imagenes i where i.vehiculo_id = v.id),
        'fase', case when f.visible_portal then jsonb_build_object('nombre', f.alias_portal, 'descripcion', f.descripcion_portal, 'desde', v.fase_desde) end,
        'linea_tiempo', (select coalesce(jsonb_agg(jsonb_build_object('nombre', fz.alias_portal, 'en', h.creado_en) order by h.creado_en), '[]'::jsonb) from public.historial_fases h join public.fases fz on fz.id = h.a_fase_id where h.vehiculo_id = v.id and fz.visible_portal),
        'embarque', (select jsonb_build_object('zarpe', t.zarpe_el, 'eta', t.eta_el, 'arribo', t.arribo_el) from public.transportes t where t.vehiculo_id = v.id),
        'documentos', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'tipo', td.nombre, 'estado', d.estado, 'fecha', d.creado_en)), '[]'::jsonb) from public.documentos d join public.tipos_documento td on td.id = d.tipo_documento_id where d.vehiculo_id = v.id and d.visible_portal and d.estado <> 'rechazado' and d.eliminado_en is null),
        'seguimientos', (select coalesce(jsonb_agg(jsonb_build_object('titulo', s.titulo, 'detalle', s.detalle_texto, 'en', s.ocurrido_en) order by s.ocurrido_en desc), '[]'::jsonb) from public.seguimientos s where s.lead_id = p_lead and s.vehiculo_id = v.id and s.visibilidad = 'publico' and s.eliminado_en is null),
        'pagos', (select coalesce(jsonb_agg(jsonb_build_object('concepto', pg.concepto, 'monto', pg.monto, 'moneda', pg.moneda, 'fecha', pg.fecha, 'confirmado', pg.confirmado) order by pg.fecha), '[]'::jsonb) from public.pagos pg where pg.vehiculo_id = v.id and pg.eliminado_en is null)
      )) from public.vehiculos v left join public.fases f on f.id = v.fase_id where v.lead_id = p_lead and v.eliminado_en is null), '[]'::jsonb),
    -- Lo «Visible para el cliente» que no sale con un vehículo suyo: sin vehículo, o de uno que no está
    -- vinculado a este lead (un interés, uno que se desvinculó). No se nombra el vehículo. Las 30 más nuevas.
    'novedades', coalesce((select jsonb_agg(jsonb_build_object('titulo', n.titulo, 'detalle', n.detalle_texto, 'en', n.ocurrido_en) order by n.ocurrido_en desc, n.id)
      from (select s.id, s.titulo, s.detalle_texto, s.ocurrido_en from public.seguimientos s
            where s.lead_id = p_lead and s.visibilidad = 'publico' and s.eliminado_en is null
              and (s.vehiculo_id is null or not exists (
                select 1 from public.vehiculos v where v.id = s.vehiculo_id and v.lead_id = p_lead and v.eliminado_en is null))
            order by s.ocurrido_en desc, s.id limit 30) n), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "web"."portal_snapshot"("p_lead" "uuid", "p_otorgado_en" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "web"."registrar_evento"("p_token" "text", "p_evento" "text", "p_ruta" "text" DEFAULT NULL::"text", "p_referencia_id" "uuid" DEFAULT NULL::"uuid", "p_utm" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
begin
  if p_token !~ '^[A-Za-z0-9_-]{16,64}$' or p_evento not in ('page_view', 'vehiculo_view', 'contacto_click', 'guia_view', 'filtro_uso', 'asesor_view') then return; end if;
  insert into public.eventos_web (token, evento, ruta, referencia_id, utm) values (p_token, p_evento, left(p_ruta, 300), p_referencia_id, p_utm);
end;
$_$;


ALTER FUNCTION "web"."registrar_evento"("p_token" "text", "p_evento" "text", "p_ruta" "text", "p_referencia_id" "uuid", "p_utm" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "web"."solicitar_asesor"("p_token" "text", "p_fuente" "text", "p_ruta" "text" DEFAULT NULL::"text", "p_vehiculo_id" "uuid" DEFAULT NULL::"uuid", "p_handle" "text" DEFAULT NULL::"text", "p_utm" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare w public.ajustes_web; e public.ajustes_empresa; cand uuid; s public.solicitudes_contacto_web; p public.perfiles; ttl interval; v_titulo text; v_codigo text; abiertas int;
begin
  if p_token !~ '^[A-Za-z0-9_-]{16,64}$' then raise exception 'token inválido' using errcode = '22023'; end if;
  select * into w from public.ajustes_web where id = 1;
  select * into e from public.ajustes_empresa where id = 1;
  ttl := make_interval(mins => w.ttl_contacto_minutos);
  perform public.web_expirar_solicitudes(20);
  select titulo into v_titulo from web.vehiculos where id = p_vehiculo_id;
  -- 1) contacto directo por handle: sin sorteo, sin vencimiento, no mueve el puntero
  if p_handle is not null then
    select pf.* into p from public.perfiles pf where pf.handle = p_handle and pf.publico_web and pf.activo and not pf.bloqueado and pf.whatsapp_web is not null;
    if p.id is not null then
      v_codigo := '#WEB-' || public.codigo_dictable(4);
      insert into public.solicitudes_contacto_web (codigo, token_visitante, usuario_id, estado, es_directa, fuente, ruta, vehiculo_id, utm)
      values (v_codigo, p_token, p.id, 'asignada', true, p_fuente, p_ruta, p_vehiculo_id, p_utm) returning * into s;
      insert into public.notificaciones (usuario_id, tipo, titulo, cuerpo, referencia_tipo, referencia_id, ruta, requiere_accion)
      values (p.id, 'turno_web', 'Contacto directo desde la web', coalesce(v_titulo, v_codigo), 'solicitud_web', s.id, '/notificaciones', true) on conflict do nothing;
      return jsonb_build_object('ref', v_codigo, 'handle', p.handle, 'nombre', p.nombre, 'avatar', p.avatar_ruta, 'cargo', p.cargo_web, 'whatsapp', p.whatsapp_web, 'es_directo', true, 'es_respaldo', false, 'mensaje', 'Hola ' || split_part(p.nombre, ' ', 1) || ', vi ' || coalesce(v_titulo, 'la web') || ' y quiero más información. (Ref: ' || v_codigo || ')');
    end if;
  end if;
  -- 2) anti-abuso
  if (select count(*) from public.solicitudes_contacto_web x where x.token_visitante = p_token and x.creado_en > now() - interval '1 hour') >= 12 then
    return jsonb_build_object('es_respaldo', true, 'whatsapp', w.whatsapp_respaldo, 'mensaje', 'Hola, quiero más información.');
  end if;
  -- 3) ya tiene una abierta: la misma. El reloj vuelve a cero sólo si quien la tiene puede estar en la rueda: si no, vence a su hora y se reasigna. `returning * into s`: la respuesta lleva el vencimiento nuevo.
  select x.* into s from public.solicitudes_contacto_web x where x.token_visitante = p_token and x.estado = 'asignada' and not x.es_directa order by x.creado_en desc limit 1;
  if s.id is not null then
    if public.puede_estar_en_la_rueda(s.usuario_id) then
      update public.solicitudes_contacto_web set vence_en = now() + ttl where id = s.id returning * into s;
    end if;
    cand := s.usuario_id;
  end if;
  -- 4) pegajoso: su último asesor dentro del plazo, si sigue elegible
  if cand is null and w.dias_pegajoso > 0 then
    select x.usuario_id into cand from public.solicitudes_contacto_web x join public.cola_web_asesores q on q.usuario_id = x.usuario_id join public.perfiles pf on pf.id = q.usuario_id
    where x.token_visitante = p_token and x.estado in ('asignada', 'contactada') and x.creado_en > now() - make_interval(days => w.dias_pegajoso)
      and q.habilitado and pf.whatsapp_web is not null and public.puede_estar_en_la_rueda(q.usuario_id)
    order by x.creado_en desc limit 1;
  end if;
  -- 5) ruleta, serializada
  if cand is null and w.cola_activa then
    perform pg_advisory_xact_lock(hashtext('cola_web'));
    select q.usuario_id into cand
    from public.cola_web_asesores q join public.perfiles pf on pf.id = q.usuario_id
    where q.habilitado and q.disponible and pf.whatsapp_web is not null and public.puede_estar_en_la_rueda(q.usuario_id)
    order by ((select count(*) from public.solicitudes_contacto_web a where a.usuario_id = q.usuario_id and a.estado = 'asignada' and not a.es_directa) >= coalesce(q.max_abiertas, w.max_abiertas_default)),
             (select count(*) from public.solicitudes_contacto_web a where a.usuario_id = q.usuario_id and a.estado = 'asignada' and not a.es_directa) / greatest(q.prioridad + 1, 1),
             q.ultima_asignacion_en asc nulls first, q.orden, q.usuario_id
    limit 1;
  end if;
  if cand is null then
    insert into public.solicitudes_contacto_web (codigo, token_visitante, estado, fuente, ruta, vehiculo_id, utm) values ('#WEB-' || public.codigo_dictable(4), p_token, 'sin_asignar', p_fuente, p_ruta, p_vehiculo_id, p_utm);
    return jsonb_build_object('es_respaldo', true, 'whatsapp', w.whatsapp_respaldo, 'mensaje', 'Hola, vi ' || coalesce(v_titulo, 'la web') || ' y quiero más información.');
  end if;
  if s.id is null then
    v_codigo := '#WEB-' || public.codigo_dictable(4);
    insert into public.solicitudes_contacto_web (codigo, token_visitante, usuario_id, estado, fuente, ruta, vehiculo_id, utm, vence_en)
    values (v_codigo, p_token, cand, 'asignada', p_fuente, p_ruta, p_vehiculo_id, p_utm, now() + ttl) returning * into s;
    update public.cola_web_asesores set ultima_asignacion_en = now(), asignadas_total = asignadas_total + 1 where usuario_id = cand;
    insert into public.notificaciones (usuario_id, tipo, titulo, cuerpo, referencia_tipo, referencia_id, ruta, requiere_accion)
    values (cand, 'turno_web', 'Turno de la web', coalesce(v_titulo, v_codigo), 'solicitud_web', s.id, '/notificaciones', true) on conflict do nothing;
  end if;
  select * into p from public.perfiles where id = cand;
  return jsonb_build_object('ref', s.codigo, 'handle', p.handle, 'nombre', p.nombre, 'avatar', p.avatar_ruta, 'cargo', p.cargo_web, 'whatsapp', p.whatsapp_web, 'expira_en', s.vence_en, 'es_directo', false, 'es_respaldo', false,
    'mensaje', 'Hola ' || split_part(p.nombre, ' ', 1) || ', vi ' || coalesce(v_titulo, 'la web') || ' y quiero más información. (Ref: ' || s.codigo || ')');
end;
$_$;


ALTER FUNCTION "web"."solicitar_asesor"("p_token" "text", "p_fuente" "text", "p_ruta" "text", "p_vehiculo_id" "uuid", "p_handle" "text", "p_utm" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."ajustes_web" (
    "id" integer DEFAULT 1 NOT NULL,
    "nombre_sitio" "text",
    "lema" "text",
    "whatsapp_respaldo" "text",
    "horario" "text",
    "redes" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "mostrar_moneda_secundaria" boolean DEFAULT true NOT NULL,
    "origenes_visibles" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "cola_activa" boolean DEFAULT true NOT NULL,
    "ttl_contacto_minutos" integer DEFAULT 30 NOT NULL,
    "dias_pegajoso" integer DEFAULT 30 NOT NULL,
    "max_abiertas_default" integer DEFAULT 3 NOT NULL,
    "max_intentos" integer DEFAULT 3 NOT NULL,
    "legales" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "seo" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "direccion_publica" "text",
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_por" "uuid",
    CONSTRAINT "ajustes_web_dias_pegajoso_check" CHECK ((("dias_pegajoso" >= 0) AND ("dias_pegajoso" <= 365))),
    CONSTRAINT "ajustes_web_direccion_publica_check" CHECK ((("direccion_publica" IS NULL) OR ("direccion_publica" ~ '^https://[^[:space:]]+$'::"text"))),
    CONSTRAINT "ajustes_web_id_check" CHECK (("id" = 1)),
    CONSTRAINT "ajustes_web_max_abiertas_default_check" CHECK ((("max_abiertas_default" >= 1) AND ("max_abiertas_default" <= 50))),
    CONSTRAINT "ajustes_web_max_intentos_check" CHECK ((("max_intentos" >= 1) AND ("max_intentos" <= 10))),
    CONSTRAINT "ajustes_web_ttl_contacto_minutos_check" CHECK ((("ttl_contacto_minutos" >= 5) AND ("ttl_contacto_minutos" <= 1440))),
    CONSTRAINT "ajustes_web_whatsapp_respaldo_check" CHECK ((("whatsapp_respaldo" IS NULL) OR ("whatsapp_respaldo" ~ '^\+[1-9][0-9]{6,14}$'::"text")))
);


ALTER TABLE "public"."ajustes_web" OWNER TO "postgres";


COMMENT ON TABLE "public"."ajustes_web" IS 'Fila única. Contenido y política de la web pública. Separado de ajustes_empresa a propósito.';



CREATE TABLE IF NOT EXISTS "public"."categorias" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "origen_id" "uuid" NOT NULL,
    "padre_id" "uuid",
    "nombre" "text" NOT NULL,
    "orden" smallint DEFAULT 0 NOT NULL,
    "activa" boolean DEFAULT true NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."categorias" OWNER TO "postgres";


COMMENT ON TABLE "public"."categorias" IS 'Categorías dentro de un origen (marcas, «vehículos medio uso», segmentos). Un nivel de anidado opcional.';



CREATE TABLE IF NOT EXISTS "public"."fases" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "flujo_id" "uuid" NOT NULL,
    "nombre" "text" NOT NULL,
    "descripcion" "text",
    "color" "text" DEFAULT '#717c93'::"text" NOT NULL,
    "icono" "text",
    "orden" smallint DEFAULT 0 NOT NULL,
    "es_inicial" boolean DEFAULT false NOT NULL,
    "es_final" boolean DEFAULT false NOT NULL,
    "activa" boolean DEFAULT true NOT NULL,
    "es_logistica" boolean DEFAULT true NOT NULL,
    "demora_dias" integer,
    "alerta_cada_horas" integer,
    "nota_obligatoria" boolean DEFAULT false NOT NULL,
    "permite_contenedor" boolean DEFAULT true NOT NULL,
    "permite_aduana" boolean DEFAULT false NOT NULL,
    "cuenta_llegada_repuestos" boolean DEFAULT false NOT NULL,
    "publica_web" boolean DEFAULT false NOT NULL,
    "visible_portal" boolean DEFAULT false NOT NULL,
    "alias_portal" "text",
    "descripcion_portal" "text",
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "fases_alerta_cada_horas_check" CHECK ((("alerta_cada_horas" IS NULL) OR (("alerta_cada_horas" >= 1) AND ("alerta_cada_horas" <= 720)))),
    CONSTRAINT "fases_check" CHECK ((NOT ("es_inicial" AND "es_final"))),
    CONSTRAINT "fases_check1" CHECK (((NOT "visible_portal") OR ("alias_portal" IS NOT NULL))),
    CONSTRAINT "fases_color_check" CHECK (("color" ~ '^#[0-9a-fA-F]{6}$'::"text")),
    CONSTRAINT "fases_demora_dias_check" CHECK ((("demora_dias" IS NULL) OR ("demora_dias" >= 0)))
);


ALTER TABLE "public"."fases" OWNER TO "postgres";


COMMENT ON TABLE "public"."fases" IS 'Fase de un flujo. Nombre único POR FLUJO. Jubilar (activa=false) la saca de los destinos sin romper el historial; borrar sólo sin historial ni unidades paradas (RPC).';



CREATE TABLE IF NOT EXISTS "public"."integraciones" (
    "clave" "text" NOT NULL,
    "activa" boolean DEFAULT false NOT NULL,
    "config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "secreto_guardado_en" timestamp with time zone,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_por" "uuid"
);


ALTER TABLE "public"."integraciones" OWNER TO "postgres";


COMMENT ON TABLE "public"."integraciones" IS 'Interruptor y configuración no secreta de cada integración. Las claves de API viven en Vault (vault.secrets, nombre integracion:<clave>) y se escriben con integracion_guardar_secreto(); acá sólo queda cuándo se guardaron.';



CREATE TABLE IF NOT EXISTS "public"."origenes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "clave" "text" NOT NULL,
    "nombre" "text" NOT NULL,
    "sustantivo" "text" DEFAULT 'vehículo'::"text" NOT NULL,
    "genero" "public"."genero_gramatical" DEFAULT 'm'::"public"."genero_gramatical" NOT NULL,
    "tipo" "public"."tipo_origen" DEFAULT 'manual'::"public"."tipo_origen" NOT NULL,
    "color" "text" DEFAULT '#465fff'::"text" NOT NULL,
    "icono" "text",
    "activo" boolean DEFAULT true NOT NULL,
    "orden" smallint DEFAULT 0 NOT NULL,
    "apibara_plataformas" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "origenes_clave_check" CHECK (("clave" ~ '^[a-z][a-z0-9_]{1,30}$'::"text")),
    CONSTRAINT "origenes_color_check" CHECK (("color" ~ '^#[0-9a-fA-F]{6}$'::"text"))
);


ALTER TABLE "public"."origenes" OWNER TO "postgres";


COMMENT ON TABLE "public"."origenes" IS 'Origen configurable de vehículos. tipo=subasta usa la preconfiguración apibara (lote, link, plataforma…); tipo=manual la preconfiguración de venta directa. Cada origen tiene exactamente un flujo de logística (flujos.origen_id) y una serie de fórmulas de cotización.';



CREATE TABLE IF NOT EXISTS "public"."origenes_campos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "origen_id" "uuid" NOT NULL,
    "clave" "text" NOT NULL,
    "etiqueta" "text" NOT NULL,
    "tipo" "public"."tipo_campo" NOT NULL,
    "opciones" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "requerido" boolean DEFAULT false NOT NULL,
    "valor_defecto" "jsonb",
    "grupo" "text",
    "orden" smallint DEFAULT 0 NOT NULL,
    "en_tarjeta" boolean DEFAULT false NOT NULL,
    "filtrable" boolean DEFAULT false NOT NULL,
    "publico_web" boolean DEFAULT false NOT NULL,
    "clave_apibara" "text",
    "es_sistema" boolean DEFAULT false NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "origenes_campos_clave_check" CHECK (("clave" ~ '^[a-z][a-z0-9_]{1,40}$'::"text")),
    CONSTRAINT "origenes_campos_tipo_de_vehiculo" CHECK (("tipo" <> ALL (ARRAY['correo'::"public"."tipo_campo", 'documento'::"public"."tipo_campo"])))
);


ALTER TABLE "public"."origenes_campos" OWNER TO "postgres";


COMMENT ON TABLE "public"."origenes_campos" IS 'Layout de campos de un origen. Los campos comunes (marca, modelo, año, vin, lote, precio) viven como columnas de vehiculos; el resto en vehiculos.atributos, validado contra esta tabla por trigger. valor_defecto sólo precarga el formulario de alta: la base nunca lo aplica sola.';



CREATE TABLE IF NOT EXISTS "public"."vehiculos_imagenes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "vehiculo_id" "uuid" NOT NULL,
    "hash" "text" NOT NULL,
    "ruta" "text" NOT NULL,
    "ruta_miniatura" "text" NOT NULL,
    "orden" smallint DEFAULT 0 NOT NULL,
    "es_portada" boolean DEFAULT false NOT NULL,
    "ancho" integer NOT NULL,
    "alto" integer NOT NULL,
    "bytes" integer NOT NULL,
    "origen_url" "text",
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "vehiculos_imagenes_alto_check" CHECK (("alto" > 0)),
    CONSTRAINT "vehiculos_imagenes_ancho_check" CHECK (("ancho" > 0)),
    CONSTRAINT "vehiculos_imagenes_bytes_check" CHECK (("bytes" > 0)),
    CONSTRAINT "vehiculos_imagenes_hash_check" CHECK (("hash" ~ '^[0-9a-f]{64}$'::"text"))
);


ALTER TABLE "public"."vehiculos_imagenes" OWNER TO "postgres";


COMMENT ON TABLE "public"."vehiculos_imagenes" IS 'Las fotos de un vehículo: hasta 24, una sola portada. De sólo lectura para la app: se escriben por vehiculo_fotos_agregar(), vehiculo_foto_mover(), vehiculo_foto_portada() y vehiculo_foto_eliminar(). Cada foto son dos objetos del bucket público `vehiculos`, generados en el navegador y nombrados por el hash de su contenido, siempre en la carpeta de su vehículo. `hash` es el del archivo original: la misma foto no entra dos veces al mismo vehículo.';



CREATE OR REPLACE VIEW "interno"."vitrina_vehiculos" AS
 SELECT "v"."id",
    "v"."numero",
    "v"."origen_id",
    "o"."clave" AS "origen",
    "o"."nombre" AS "origen_nombre",
    "v"."titulo",
    "v"."marca",
    "v"."modelo",
    "v"."anio",
    "c"."nombre" AS "categoria",
    "v"."precio_web" AS "precio",
    "v"."precio_web_hasta" AS "precio_hasta",
    "v"."precio_web_nota" AS "precio_nota",
    "v"."destacado_web" AS "destacado",
    COALESCE(( SELECT "jsonb_object_agg"("oc"."clave", ("v"."atributos" -> "oc"."clave")) AS "jsonb_object_agg"
           FROM "public"."origenes_campos" "oc"
          WHERE (("oc"."origen_id" = "v"."origen_id") AND "oc"."publico_web" AND "oc"."activo" AND ("v"."atributos" ? "oc"."clave"))), '{}'::"jsonb") AS "atributos",
    "p"."ruta" AS "imagen",
    "p"."ruta_miniatura" AS "miniatura",
    "v"."actualizado_en",
    "v"."publicado_web" AS "publicado",
    ("v"."fase_id" IS NOT NULL) AS "con_fase",
    COALESCE(("f"."publica_web" AND "f"."activa"), false) AS "fase_publica",
    "o"."activo" AS "origen_activo",
    ("v"."origen_id" = ANY ("w"."origenes_visibles")) AS "origen_visible",
    (EXISTS ( SELECT 1
           FROM "public"."integraciones" "i"
          WHERE (("i"."clave" = 'web_publica'::"text") AND "i"."activa"))) AS "web_activa",
    ("v"."publicado_web" AND COALESCE(("f"."publica_web" AND "f"."activa"), false) AND "o"."activo" AND ("v"."origen_id" = ANY ("w"."origenes_visibles")) AND (EXISTS ( SELECT 1
           FROM "public"."integraciones" "i"
          WHERE (("i"."clave" = 'web_publica'::"text") AND "i"."activa")))) AS "visible"
   FROM ((((("public"."vehiculos" "v"
     JOIN "public"."origenes" "o" ON (("o"."id" = "v"."origen_id")))
     LEFT JOIN "public"."fases" "f" ON (("f"."id" = "v"."fase_id")))
     LEFT JOIN "public"."categorias" "c" ON (("c"."id" = "v"."categoria_id")))
     LEFT JOIN "public"."vehiculos_imagenes" "p" ON ((("p"."vehiculo_id" = "v"."id") AND "p"."es_portada")))
     CROSS JOIN "public"."ajustes_web" "w")
  WHERE (("w"."id" = 1) AND ("v"."eliminado_en" IS NULL));


ALTER VIEW "interno"."vitrina_vehiculos" OWNER TO "postgres";


COMMENT ON VIEW "interno"."vitrina_vehiculos" IS 'Lo que la web pública puede mostrar de cada vehículo vivo, y las cinco condiciones para que se vea. Única definición: de acá salen web.vehiculos y la vista previa del CRM. Una columna nueva acá es una columna nueva a la vista de cualquiera.';



