CREATE TABLE IF NOT EXISTS "public"."ajustes_empresa" (
    "id" integer DEFAULT 1 NOT NULL,
    "nombre" "text" DEFAULT 'Mi importadora'::"text" NOT NULL,
    "razon_social" "text",
    "nit" "text",
    "direccion" "text",
    "ciudad" "text",
    "pais" "text" DEFAULT 'Bolivia'::"text" NOT NULL,
    "telefono" "text",
    "telefono_cc" "text",
    "whatsapp" "text",
    "email" "text",
    "logo_ruta" "text",
    "logo_oscuro_ruta" "text",
    "iconos" "jsonb",
    "color_acento" "text",
    "locale" "text" DEFAULT 'es-BO'::"text" NOT NULL,
    "zona_horaria" "text" DEFAULT 'America/La_Paz'::"text" NOT NULL,
    "moneda_base" character(3) DEFAULT 'USD'::"bpchar" NOT NULL,
    "registro_abierto" boolean DEFAULT false NOT NULL,
    "papelera_dias" integer DEFAULT 30 NOT NULL,
    "actividad_dias" integer DEFAULT 14 NOT NULL,
    "demora_dias_default" integer DEFAULT 7 NOT NULL,
    "lead_dormido_meses" integer DEFAULT 3 NOT NULL,
    "limpieza_automatica" boolean DEFAULT true NOT NULL,
    "limpieza_dias_gracia" integer DEFAULT 7 NOT NULL,
    "vehiculo_obligatorio_al_cotizar" boolean DEFAULT true NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_por" "uuid",
    CONSTRAINT "ajustes_empresa_actividad_dias_check" CHECK ((("actividad_dias" >= 1) AND ("actividad_dias" <= 365))),
    CONSTRAINT "ajustes_empresa_color_acento_check" CHECK (("color_acento" ~ '^#[0-9a-fA-F]{6}$'::"text")),
    CONSTRAINT "ajustes_empresa_demora_dias_default_check" CHECK (("demora_dias_default" >= 0)),
    CONSTRAINT "ajustes_empresa_id_check" CHECK (("id" = 1)),
    CONSTRAINT "ajustes_empresa_lead_dormido_meses_check" CHECK ((("lead_dormido_meses" >= 1) AND ("lead_dormido_meses" <= 24))),
    CONSTRAINT "ajustes_empresa_limpieza_dias_gracia_check" CHECK ((("limpieza_dias_gracia" >= 1) AND ("limpieza_dias_gracia" <= 90))),
    CONSTRAINT "ajustes_empresa_papelera_dias_check" CHECK ((("papelera_dias" >= 1) AND ("papelera_dias" <= 365))),
    CONSTRAINT "ajustes_empresa_telefono_cc_check" CHECK (("telefono_cc" ~ '^\+[1-9][0-9]{0,2}$'::"text"))
);


ALTER TABLE "public"."ajustes_empresa" OWNER TO "postgres";


COMMENT ON TABLE "public"."ajustes_empresa" IS 'Fila única (id = 1). Marca, país, locale, zona horaria, moneda base y políticas globales. Del cotizador sólo vive acá el ajuste «Vehículo obligatorio al cotizar»: lo demás (fórmulas, tablas, plantillas) es de formulas y tablas_referencia.';



COMMENT ON COLUMN "public"."ajustes_empresa"."telefono_cc" IS 'Código de país de los teléfonos de los leads (+ y 1 a 3 dígitos). Con él se completa un número escrito sin «+» ni «00».';



COMMENT ON COLUMN "public"."ajustes_empresa"."iconos" IS 'Objeto {"32","180","192","512","512m"} → ruta en el bucket marca. Lo escribe «Regenerar íconos»; lo lee manifest.ts.';



COMMENT ON COLUMN "public"."ajustes_empresa"."limpieza_automatica" IS 'Interruptor general de la limpieza automática de vehículos de subasta. Apagado: no hay job, filtro ni banner.';



COMMENT ON COLUMN "public"."ajustes_empresa"."limpieza_dias_gracia" IS 'Días que pasan desde que terminó la subasta hasta que un vehículo sin ancla va a la papelera (1 a 90).';



COMMENT ON COLUMN "public"."ajustes_empresa"."vehiculo_obligatorio_al_cotizar" IS 'D3 (Fase 4): sí por defecto. Con no, cotizacion_crear acepta una preventa sin vehículo; una final siempre lo exige. Sin pantalla hasta el 4.20 (Configuración › Cotización); lo cambia quien tiene cotizaciones.configurar.';



