    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "fase_id" "uuid" NOT NULL,
    "tipo" "public"."tipo_requisito" NOT NULL,
    "bloqueante" boolean DEFAULT true NOT NULL,
    "orden" smallint DEFAULT 0 NOT NULL,
    "notas" "text",
    "tipo_documento_id" "uuid",
    "min_archivos" integer,
    "max_archivos" integer,
    "formatos" "text"[],
    "clave_dato" "text",
    "config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "espera_fase_id" "uuid",
    "espera_ambito" "public"."ambito_espera",
    CONSTRAINT "fases_requisitos_check" CHECK (((("tipo" = 'documento'::"public"."tipo_requisito") AND ("tipo_documento_id" IS NOT NULL) AND ("clave_dato" IS NULL) AND ("espera_fase_id" IS NULL)) OR (("tipo" = 'dato'::"public"."tipo_requisito") AND ("clave_dato" IS NOT NULL) AND ("tipo_documento_id" IS NULL) AND ("espera_fase_id" IS NULL)) OR (("tipo" = 'espera'::"public"."tipo_requisito") AND ("espera_fase_id" IS NOT NULL) AND ("espera_ambito" IS NOT NULL) AND ("tipo_documento_id" IS NULL) AND ("clave_dato" IS NULL)))),
    CONSTRAINT "fases_requisitos_check1" CHECK ((("max_archivos" IS NULL) OR ("min_archivos" IS NULL) OR ("max_archivos" >= "min_archivos"))),
    CONSTRAINT "fases_requisitos_max_archivos_check" CHECK ((("max_archivos" IS NULL) OR ("max_archivos" >= 1))),
    CONSTRAINT "fases_requisitos_min_archivos_check" CHECK ((("min_archivos" IS NULL) OR ("min_archivos" >= 1)))
);


