CREATE TABLE IF NOT EXISTS "public"."permisos" (
    "clave" "text" NOT NULL,
    "modulo" "text" NOT NULL,
    "nombre" "text" NOT NULL,
    "descripcion" "text" NOT NULL,
    "por_origen" boolean DEFAULT false NOT NULL,
    "con_alcance" boolean DEFAULT false NOT NULL,
    "aplicado_en" "text" NOT NULL,
    "orden" smallint DEFAULT 0 NOT NULL,
    "nivel_clave" "text",
    CONSTRAINT "permisos_clave_check" CHECK (("clave" ~ '^[a-z]+(\.[a-z0-9_]+){1,3}$'::"text")),
    CONSTRAINT "permisos_nivel_check" CHECK (((("clave" ~~ 'cotizaciones.nivel.%'::"text") = ("nivel_clave" IS NOT NULL)) AND (("nivel_clave" IS NULL) OR (("nivel_clave" <> 'todos'::"text") AND (("clave" = (('cotizaciones.nivel.'::"text" || "nivel_clave") || '.ver'::"text")) OR ("clave" = (('cotizaciones.nivel.'::"text" || "nivel_clave") || '.editar'::"text")))))))
);


ALTER TABLE "public"."permisos" OWNER TO "postgres";


COMMENT ON TABLE "public"."permisos" IS 'CATÁLOGO FIJO POR CÓDIGO, salvo los `cotizaciones.nivel.*`, que los genera `nivel_crear()` al crear un nivel de acceso. Un permiso existe sólo si hay un punto de enforcement (policy o RPC) que lo consulta. Se siembra por migración; la UI lo lee y lo asigna, nunca lo crea. Sin política de escritura para nadie: la ausencia de política ES el enforcement.';



