CREATE OR REPLACE VIEW "web"."ajustes" WITH ("security_invoker"='false') AS
 SELECT "e"."nombre",
    "e"."razon_social",
    "e"."nit",
    "e"."direccion",
    "e"."ciudad",
    "e"."pais",
    "e"."whatsapp",
    "e"."logo_ruta",
    "e"."locale",
    "e"."moneda_base",
    "w"."nombre_sitio",
    "w"."lema",
    "w"."whatsapp_respaldo",
    "w"."horario",
    "w"."redes",
    "w"."mostrar_moneda_secundaria",
    "w"."legales",
    "w"."seo"
   FROM ("public"."ajustes_empresa" "e"
     CROSS JOIN "public"."ajustes_web" "w")
  WHERE (("e"."id" = 1) AND ("w"."id" = 1));


ALTER VIEW "web"."ajustes" OWNER TO "postgres";


CREATE OR REPLACE VIEW "web"."asesores" WITH ("security_invoker"='false') AS
 SELECT "p"."id",
    "p"."handle",
    "p"."nombre",
    "p"."avatar_ruta" AS "avatar",
    "p"."cargo_web" AS "cargo",
    "p"."bio_web" AS "bio",
    "p"."whatsapp_web" AS "whatsapp",
    "p"."especialidades",
    "p"."creado_en" AS "desde",
    "q"."orden"
   FROM ("public"."perfiles" "p"
     LEFT JOIN "public"."cola_web_asesores" "q" ON (("q"."usuario_id" = "p"."id")))
  WHERE ("p"."publico_web" AND "p"."activo" AND (NOT "p"."bloqueado") AND ("p"."handle" IS NOT NULL) AND ("p"."whatsapp_web" IS NOT NULL));


ALTER VIEW "web"."asesores" OWNER TO "postgres";


CREATE OR REPLACE VIEW "web"."faqs" WITH ("security_invoker"='false') AS
 SELECT "pregunta",
    "respuesta",
    "categoria",
    "orden"
   FROM "public"."web_faqs"
  WHERE "publicada";


ALTER VIEW "web"."faqs" OWNER TO "postgres";


CREATE OR REPLACE VIEW "web"."guias" WITH ("security_invoker"='false') AS
 SELECT "g"."slug",
    "g"."titulo",
    "g"."resumen",
    "g"."cuerpo_html",
    "g"."portada_ruta" AS "portada",
    "c"."slug" AS "categoria",
    "c"."nombre" AS "categoria_etiqueta",
    "g"."minutos_lectura",
    "g"."seo_titulo",
    "g"."seo_descripcion",
    "g"."publicada_en",
    "g"."orden",
        CASE
            WHEN "p"."publico_web" THEN "p"."nombre"
            ELSE NULL::"text"
        END AS "autor",
        CASE
            WHEN "p"."publico_web" THEN "p"."avatar_ruta"
            ELSE NULL::"text"
        END AS "autor_avatar",
        CASE
            WHEN "p"."publico_web" THEN "p"."handle"
            ELSE NULL::"extensions"."citext"
        END AS "autor_handle"
   FROM (("public"."web_guias" "g"
     LEFT JOIN "public"."web_categorias_guias" "c" ON (("c"."id" = "g"."categoria_id")))
     LEFT JOIN "public"."perfiles" "p" ON (("p"."id" = "g"."autor_id")))
  WHERE (("g"."publicada_en" IS NOT NULL) AND ("g"."publicada_en" <= "now"()));


ALTER VIEW "web"."guias" OWNER TO "postgres";


CREATE OR REPLACE VIEW "web"."testimonios" WITH ("security_invoker"='false') AS
 SELECT "cliente",
        CASE
            WHEN "consent_ciudad" THEN "ciudad"
            ELSE NULL::"text"
        END AS "ciudad",
    "texto",
        CASE
            WHEN "consent_vehiculo" THEN "vehiculo"
            ELSE NULL::"text"
        END AS "vehiculo",
        CASE
            WHEN "consent_foto" THEN "foto_ruta"
            ELSE NULL::"text"
        END AS "foto",
    "orden"
   FROM "public"."web_testimonios"
  WHERE ("publicado" AND ("consent_por" IS NOT NULL) AND ("consent_en" IS NOT NULL) AND ("consent_canal" IS NOT NULL) AND ("consent_retirado_en" IS NULL));


ALTER VIEW "web"."testimonios" OWNER TO "postgres";


CREATE OR REPLACE VIEW "web"."vehiculos" WITH ("security_invoker"='false') AS
 SELECT "id",
    "numero",
    "origen",
    "origen_nombre",
    "titulo",
    "marca",
    "modelo",
    "anio",
    "categoria",
    "precio",
    "precio_hasta",
    "precio_nota",
    "destacado",
    "atributos",
    "imagen",
    "miniatura",
    "actualizado_en"
   FROM "interno"."vitrina_vehiculos" "t"
  WHERE "visible";


ALTER VIEW "web"."vehiculos" OWNER TO "postgres";


