-- 3. Lo que el volcado no lleva: triggers de auth.users y policies de storage.objects
create policy "avatares: borrar propio" on storage.objects as permissive for delete to authenticated
  using (((bucket_id = 'avatares'::text) AND ((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text)));
create policy "avatares: propio" on storage.objects as permissive for insert to authenticated
  with check (((bucket_id = 'avatares'::text) AND ((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text)));
create policy "comprobantes: leer" on storage.objects as permissive for select to authenticated
  using (((bucket_id = 'comprobantes'::text) AND (( SELECT public.tiene_permiso('logistica.gastos.ver'::text) AS tiene_permiso) OR ( SELECT public.tiene_permiso('logistica.pagos.ver'::text) AS tiene_permiso) OR ( SELECT public.tiene_permiso('repuestos.costos.ver'::text) AS tiene_permiso))));
create policy "comprobantes: subir" on storage.objects as permissive for insert to authenticated
  with check (((bucket_id = 'comprobantes'::text) AND (( SELECT public.tiene_permiso('logistica.gastos.editar'::text) AS tiene_permiso) OR ( SELECT public.tiene_permiso('logistica.pagos.editar'::text) AS tiene_permiso) OR ( SELECT public.tiene_permiso('repuestos.costos.editar'::text) AS tiene_permiso))));
create policy "cotizaciones: leer" on storage.objects as permissive for select to authenticated
  using (((bucket_id = 'cotizaciones'::text) AND ( SELECT public.puede_cotizacion(((storage.foldername(objects.name))[1])::uuid, 'cotizaciones.ver'::text) AS puede_cotizacion)));
create policy "cotizaciones: subir" on storage.objects as permissive for insert to authenticated
  with check (((bucket_id = 'cotizaciones'::text) AND ( SELECT public.puede_cotizacion(((storage.foldername(objects.name))[1])::uuid, 'cotizaciones.editar'::text) AS puede_cotizacion)));
create policy "documentos: leer" on storage.objects as permissive for select to authenticated
  using (((bucket_id = 'documentos'::text) AND (( SELECT public.puede_vehiculo(((storage.foldername(objects.name))[1])::uuid, 'logistica.ver'::text) AS puede_vehiculo) OR ( SELECT public.puede_repuesto(((storage.foldername(objects.name))[1])::uuid, 'repuestos.ver'::text) AS puede_repuesto))));
create policy "documentos: subir" on storage.objects as permissive for insert to authenticated
  with check (((bucket_id = 'documentos'::text) AND (( SELECT public.puede_vehiculo(((storage.foldername(objects.name))[1])::uuid, 'logistica.documentos.subir'::text) AS puede_vehiculo) OR ( SELECT public.puede_repuesto(((storage.foldername(objects.name))[1])::uuid, 'repuestos.documentos.subir'::text) AS puede_repuesto))));
create policy "importaciones: propio" on storage.objects as permissive for all to authenticated
  using (((bucket_id = 'importaciones'::text) AND ((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text)))
  with check (((bucket_id = 'importaciones'::text) AND ((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text)));
create policy "marca: borrar" on storage.objects as permissive for delete to authenticated
  using (((bucket_id = 'marca'::text) AND ( SELECT public.tiene_permiso('empresa.ajustes.gestionar'::text) AS tiene_permiso)));
create policy "marca: escribir" on storage.objects as permissive for insert to authenticated
  with check (((bucket_id = 'marca'::text) AND ( SELECT public.tiene_permiso('empresa.ajustes.gestionar'::text) AS tiene_permiso)));
create policy "marca: leer" on storage.objects as permissive for select to anon, authenticated
  using ((bucket_id = ANY (ARRAY['marca'::text, 'avatares'::text, 'web'::text, 'repuestos'::text])));
create policy "repuestos: borrar" on storage.objects as permissive for delete to authenticated
  using (((bucket_id = 'repuestos'::text) AND ( SELECT public.tiene_permiso('repuestos.editar'::text) AS tiene_permiso)));
create policy "repuestos: escribir" on storage.objects as permissive for insert to authenticated
  with check (((bucket_id = 'repuestos'::text) AND ( SELECT public.tiene_permiso('repuestos.editar'::text) AS tiene_permiso)));
create policy "vehiculos: listar" on storage.objects as permissive for select to authenticated
  using (((bucket_id = 'vehiculos'::text) AND ( SELECT public.puede_objeto_de_vehiculo(objects.name, 'vehiculos.ver'::text) AS puede_objeto_de_vehiculo)));
create policy "vehiculos: subir" on storage.objects as permissive for insert to authenticated
  with check (((bucket_id = 'vehiculos'::text) AND ( SELECT public.puede_objeto_de_vehiculo(objects.name, 'vehiculos.editar'::text) AS puede_objeto_de_vehiculo)));
create policy "web: borrar" on storage.objects as permissive for delete to authenticated
  using (((bucket_id = 'web'::text) AND ( SELECT public.tiene_permiso('web.contenido.gestionar'::text) AS tiene_permiso)));
create policy "web: escribir" on storage.objects as permissive for insert to authenticated
  with check (((bucket_id = 'web'::text) AND ( SELECT public.tiene_permiso('web.contenido.gestionar'::text) AS tiene_permiso)));
CREATE TRIGGER trg_auth_crear_perfil AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.auth_crear_perfil();
CREATE CONSTRAINT TRIGGER trg_auth_registro_permitido AFTER INSERT ON auth.users DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.auth_registro_permitido();
CREATE TRIGGER trg_auth_sellar_invitacion AFTER INSERT OR UPDATE OF raw_app_meta_data ON auth.users FOR EACH ROW EXECUTE FUNCTION public.auth_sellar_invitacion();

