select cron.schedule('apibara-consultas-purgar', '40 4 * * *', 'select public.apibara_consultas_purgar()');
select cron.schedule('limpieza-automatica', '7 * * * *', 'select public.limpieza_automatica_correr()');
select cron.schedule('importaciones-vinculos-purgar', '35 3 * * *', 'select public.importaciones_vinculos_purgar()');
select cron.schedule('leads-campos-privacidad', '* * * * *', 'select public.leads_campos_privacidad_aplicar()');
select cron.schedule('equipo-bajas', '* * * * *', 'select public.equipo_bajas_continuar()');
